  const std::vector<double>& ppg12Fig7TurnonEdges()
  {
    static const std::vector<double> edges = []()
    {
      std::vector<double> e;
      e.reserve(51);
      for (int i = 0; i <= 30; ++i) e.push_back(5.0 + 0.5 * static_cast<double>(i));
      for (int i = 1; i <= 20; ++i) e.push_back(20.0 + static_cast<double>(i));
      return e;
    }();
    return edges;
  }

  struct PPG12TableQAVarDef
  {
    const char* key;
    const char* axis;
    int nbins;
    double xmin;
    double xmax;
  };

  const std::array<PPG12TableQAVarDef, 12>& ppg12TableQAVars()
  {
    static const std::array<PPG12TableQAVarDef, 12> vars{{
      {"weta_cogx",   "w_{#eta}^{cogX}",      100, 0.0, 2.0},
      {"wphi_cogx",   "w_{#phi}^{cogX}",      100, 0.0, 2.0},
      {"wr",          "w_{#phi}^{cogX}/w_{#eta}^{cogX}", 100, 0.0, 2.0},
      {"et1",         "E_{T}^{1}/E_{T}^{cluster}", 100, 0.0, 1.2},
      {"et2",         "E_{T}^{2}/E_{T}^{cluster}", 100, 0.0, 1.2},
      {"et3",         "E_{T}^{3}/E_{T}^{cluster}", 100, 0.0, 1.2},
      {"et4",         "E_{T}^{4}/E_{T}^{cluster}", 100, 0.0, 0.3},
      {"e11_to_e33",  "E_{11}/E_{33}",        100, 0.0, 1.0},
      {"e17_to_e77",  "E_{17}/E_{77}",        100, 0.0, 1.2},
      {"e32_to_e35",  "E_{32}/E_{35}",        100, 0.0, 1.2},
      {"bdt",         "BDT score",            100, 0.0, 1.0},
      {"npb_score",   "NPB score",            100, 0.0, 1.0}
    }};
    return vars;
  }

  const PPG12TableQAVarDef* findPPG12TableQAVar(const std::string& key)
  {
    for (const auto& var : ppg12TableQAVars())
    {
      if (key == var.key) return &var;
    }
    return nullptr;
  }

  struct PPG12TableQA2DXAxisDef
  {
    int nbins;
    double xmin;
    double xmax;
  };

  PPG12TableQA2DXAxisDef ppg12TableQA2DXAxis(const std::string& key)
  {
    // Match PPG12 efficiencytool/ShowerShapeCheck.C h2d_all booking.
    // The compact 1D h1d_* outputs keep their slide-facing per-variable axes.
    if (key == "npb_score") return {100, 0.0, 1.0};
    return {300, -1.0, 2.0};
  }

  std::vector<std::string> ppg12TableQAPtTokens(double pt)
  {
    std::vector<std::string> out;
    if (!std::isfinite(pt)) return out;
    if (pt > 10.0 && pt < 14.0) out.emplace_back("0");
    if (pt > 14.0 && pt < 18.0) out.emplace_back("1");
    if (pt > 18.0 && pt < 22.0) out.emplace_back("2");
    if (pt > 22.0 && pt < 28.0) out.emplace_back("3");
    if (pt > 28.0 && pt < 30.0) out.emplace_back("4");
    if (pt > 15.0 && pt < 35.0) out.emplace_back("1535");
    return out;
  }

  const std::array<const char*, 6>& ppg12TableQAAllPtTokens()
  {
    static const std::array<const char*, 6> tokens{{"0", "1", "2", "3", "4", "1535"}};
    return tokens;
  }

  inline bool preselectionUsesNPB(const std::string& preselectionVariant)
  {
    return preselectionVariant == "newPPG12" ||
           preselectionVariant == "onlyNPB" ||
           preselectionVariant == "refPlusNPB" ||
           preselectionVariant == "variantA" ||
           preselectionVariant == "variantC" ||
           preselectionVariant == "variantD";
  }

  inline std::string normalizePreselectionVariantName(const std::string& preselectionVariant)
  {
    if (preselectionVariant == "variantA" || preselectionVariant == "VariantA" || preselectionVariant == "varianta") return "newPPG12";
    if (preselectionVariant == "variantB" || preselectionVariant == "VariantB" || preselectionVariant == "variantb") return "noPreCriteria";
    if (preselectionVariant == "variantC" || preselectionVariant == "VariantC" || preselectionVariant == "variantc") return "onlyNPB";
    if (preselectionVariant == "variantD" || preselectionVariant == "VariantD" || preselectionVariant == "variantd") return "refPlusNPB";
    if (preselectionVariant == "variantE" || preselectionVariant == "VariantE" || preselectionVariant == "variante") return "auauOnlyNPB";
    return preselectionVariant;
  }

  inline std::string normalizeTightVariantName(const std::string& tightVariant)
  {
    if (tightVariant == "variantA" || tightVariant == "VariantA" || tightVariant == "varianta") return "newPPG12";
    return tightVariant;
  }

  inline std::string normalizeNonTightVariantName(const std::string& nonTightVariant)
  {
    if (nonTightVariant == "variantA" || nonTightVariant == "VariantA" || nonTightVariant == "varianta" ||
        nonTightVariant == "bdtSideband" || nonTightVariant == "BDTSideband" || nonTightVariant == "bdtsideband")
    {
      return "newPPG12";
    }
    return nonTightVariant;
  }

  inline bool preselectionIsNoPreCriteria(const std::string& preselectionVariant)
  {
    return preselectionVariant == "noPreCriteria" || preselectionVariant == "variantB";
  }

  inline bool preselectionIsOnlyNPB(const std::string& preselectionVariant)
  {
    return preselectionVariant == "onlyNPB" || preselectionVariant == "variantC";
  }

  inline bool preselectionIsNewPPG12(const std::string& preselectionVariant)
  {
    return preselectionVariant == "newPPG12" || preselectionVariant == "variantA";
  }

  inline bool preselectionIsRefPlusNPB(const std::string& preselectionVariant)
  {
    return preselectionVariant == "refPlusNPB" || preselectionVariant == "variantD";
  }

  struct DoNotScalePairConfig
  {
    uint64_t runMin;
    uint64_t runMax;
    int baselineBit;
    int probeBit;
    const char* probeHistKey;
  };

  inline bool doNotScaleRunMatch(const uint64_t runNumber,
                                 const DoNotScalePairConfig& cfg)
  {
    return (runNumber >= cfg.runMin && runNumber <= cfg.runMax);
  }

  inline bool doNotScaleBitIsSet(const uint64_t vec, const int bit)
  {
    return (bit >= 0 && bit < 64) ? (((vec >> bit) & 0x1ULL) != 0ULL) : false;
  }

  inline std::string doNotScaleBaselineHistKey(const DoNotScalePairConfig& cfg)
  {
    return std::string("baseline_") + cfg.probeHistKey;
  }

  inline std::string doNotScaleHistName(const std::string& histKey)
  {
    return std::string("h_maxEnergyClus_NewTriggerFilling_doNotScale_") + histKey;
  }

