  inline bool ppg12WindowContains(const double value,
                                  const double lo,
                                  const double hi)
  {
    if (!std::isfinite(value) || !std::isfinite(lo)) return false;
    if (value < lo) return false;
    if (std::isinf(hi)) return true;
    return value <= hi;
  }

  inline std::pair<JetContainer*, std::string>
  ppg12FindTruthJetsR04(PHCompositeNode* topNode)
  {
    if (!topNode) return {nullptr, {}};

    auto trim = [](std::string value) -> std::string
    {
      const char* whitespace = " \t\r\n";
      const auto first = value.find_first_not_of(whitespace);
      if (first == std::string::npos) return {};
      const auto last = value.find_last_not_of(whitespace);
      return value.substr(first, last - first + 1);
    };

    const char* truthNodeEnvRaw = std::getenv("RJ_TRUTH_JETS_NODE");
    const std::string truthNodeEnv =
        truthNodeEnvRaw ? trim(std::string(truthNodeEnvRaw)) : std::string{};
    std::vector<std::string> candidates;
    if (!truthNodeEnv.empty())
    {
      const std::string placeholder = "{rKey}";
      if (truthNodeEnv.find(placeholder) != std::string::npos)
      {
        std::string expanded = truthNodeEnv;
        expanded.replace(expanded.find(placeholder), placeholder.size(), "r04");
        candidates.push_back(expanded);
      }
      else
      {
        candidates.push_back(truthNodeEnv);
        if (truthNodeEnv.find("_r04") == std::string::npos)
        {
          candidates.push_back(truthNodeEnv + "_r04");
        }
      }
    }
    candidates.push_back("AntiKt_Truth_r04");
    candidates.push_back("AntiKt_TruthFromParticles_r04");

    for (const auto& node : candidates)
    {
      if (node.empty()) continue;
      if (auto* truthJets = findNode::getClass<JetContainer>(topNode, node))
      {
        return {truthJets, node};
      }
    }
    return {nullptr, {}};
  }

  inline double ppg12InclusiveJetClusterEtUpper(const PPG12InclusiveJetSlice slice)
  {
    if (const char* raw = std::getenv("RJ_PP_INCLUSIVE_CLUSTER_ET_MAX_OVERRIDE"))
    {
      std::string value = lowerCopy(raw);
      value.erase(std::remove_if(value.begin(), value.end(), ::isspace), value.end());
      if (value == "off" || value == "none" || value == "inf" || value == "infinity")
      {
        return std::numeric_limits<double>::infinity();
      }
      try
      {
        const double override = std::stod(value);
        if (std::isfinite(override) && override > 0.0) return override;
      }
      catch (...) {}
    }
    switch (slice)
    {
      case PPG12InclusiveJetSlice::kJet5:  return 10.0;
      case PPG12InclusiveJetSlice::kJet8:  return 15.0;
      case PPG12InclusiveJetSlice::kJet12: return 23.0;
      case PPG12InclusiveJetSlice::kJet20: return 35.0;
      case PPG12InclusiveJetSlice::kJet30: return 45.0;
      case PPG12InclusiveJetSlice::kJet40: return 100.0;
      default:                             return std::numeric_limits<double>::infinity();
    }
  }

  constexpr double kPPG12TruthVtxSentinelThreshold = -9000.0;

  inline double ppg12TruthVertexWeight(TH1* h, const double z)
  {
    if (!h) return 0.0;
    if (!std::isfinite(z) || z <= kPPG12TruthVtxSentinelThreshold) return 1.0;
    if (z < h->GetXaxis()->GetXmin() || z > h->GetXaxis()->GetXmax()) return 0.0;

    const double w = h->Interpolate(z);
    return (std::isfinite(w) && w > 0.0) ? w : 0.0;
  }

  struct PPG12PeriodContract
  {
    const char* key;
    const char* label;
    int runMin;
    int runMaxExclusive;
    double lumiPbInv;
    double lumiTargetPbInv;
    double doubleFraction;
    double closureZCutCm;
    const char* vertexReweightFile;
  };

  constexpr PPG12PeriodContract kPPG12Period0mrad = {
      "0mrad",
      "0 mrad",
      47289,
      51274,
      47.2076,
      64.3718,
      0.224,
      144.0,
      "/sphenix/user/shuhangli/ppg12/efficiencytool/truth_vertex_reweight/output/0mrad/reweight.root"};

  constexpr PPG12PeriodContract kPPG12Period1p5mrad = {
      "1p5mrad",
      "1.5 mrad",
      51274,
      54000,
      17.1642,
      64.3718,
      0.079,
      83.0,
      "/sphenix/user/shuhangli/ppg12/efficiencytool/truth_vertex_reweight/output/1p5mrad/reweight.root"};

  inline std::string compactPPG12PeriodKey(std::string raw)
  {
    raw.erase(std::remove_if(raw.begin(), raw.end(),
                             [](unsigned char c){ return std::isspace(c); }),
              raw.end());
    raw = lowerCopy(raw);
    std::replace(raw.begin(), raw.end(), '.', 'p');
    raw.erase(std::remove(raw.begin(), raw.end(), '_'), raw.end());
    raw.erase(std::remove(raw.begin(), raw.end(), '-'), raw.end());
    return raw;
  }

  inline const PPG12PeriodContract* ppg12PeriodContractFromText(const std::string& raw)
  {
    const std::string key = compactPPG12PeriodKey(raw);
    if (key == "0" || key == "0mrad" || key == "zeromrad") return &kPPG12Period0mrad;
    if (key == "1p5" || key == "15" || key == "1p5mrad" || key == "15mrad") return &kPPG12Period1p5mrad;
    return nullptr;
  }

  inline const char* ppg12PeriodLabelForRun(const int runNumber)
  {
    if (runNumber >= kPPG12Period0mrad.runMin &&
        runNumber < kPPG12Period0mrad.runMaxExclusive)
    {
      return kPPG12Period0mrad.key;
    }
    if (runNumber >= kPPG12Period1p5mrad.runMin &&
        runNumber < kPPG12Period1p5mrad.runMaxExclusive)
    {
      return kPPG12Period1p5mrad.key;
    }
    return "other";
  }

  inline double safeEtaFromMomentum(const double px,
                                    const double py,
                                    const double pz)
  {
    const double p2 = px * px + py * py + pz * pz;
    if (!std::isfinite(p2) || p2 <= 0.0) return std::numeric_limits<double>::quiet_NaN();

    const double p = std::sqrt(p2);
    const double denom = p - pz;
    const double numer = p + pz;
    if (denom <= 0.0 || numer <= 0.0)
    {
      return (pz >= 0.0 ? 1.0 : -1.0) * std::numeric_limits<double>::infinity();
    }

    return 0.5 * std::log(numer / denom);
  }

  double ppg12MaxStoredTruthPhotonPt(PHCompositeNode* topNode,
                                     PHG4TruthInfoContainer* truthInfo,
                                     const bool requireEmbed = true,
                                     const double etaAbsMax = 1.5)
  {
    if (!truthInfo && topNode)
    {
      truthInfo = findNode::getClass<PHG4TruthInfoContainer>(topNode, "G4TruthInfo");
    }
    if (!truthInfo) return -1.0;

      // Use -1 as "no valid truth photon found" so missing-photon events
      // are rejected instead of being assigned to the PhotonJet5 slice.
      double maxPt = -1.0;

    auto primaryRange = truthInfo->GetPrimaryParticleRange();
    for (auto truthItr = primaryRange.first; truthItr != primaryRange.second; ++truthItr)
    {
      const PHG4Particle* p = truthItr->second;
      if (!p) continue;
      if (requireEmbed && truthInfo->isEmbeded(p->get_track_id()) < 1) continue;
      if (p->get_pid() != 22) continue;

      const double px = p->get_px();
      const double py = p->get_py();
      const double pz = p->get_pz();
      const double e  = p->get_e();
      const double pt = std::hypot(px, py);
      const double eta = safeEtaFromMomentum(px, py, pz);

      // Default mirrors the CaloAna particle array used by the production
      // stitch gate. Fig. 5 parity histograms pass etaAbsMax=0.7 below.
      if (!std::isfinite(pt) || pt <= 1.0) continue;
      if (!std::isfinite(e) || e <= 1.0) continue;
      if (!std::isfinite(eta) || std::fabs(eta) > etaAbsMax) continue;

      if (pt > maxPt) maxPt = pt;
    }

    return maxPt;
  }

  double ppHepMCFilterPhotonPt(PHCompositeNode* topNode,
                               const bool requireParent,
                               const bool requireStable)
  {
    PHHepMCGenEventMap* hepmcmap = findNode::getClass<PHHepMCGenEventMap>(topNode, "PHHepMCGenEventMap");
    PHHepMCGenEvent* hepmc = nullptr;
    HepMC::GenEvent* evt = nullptr;

    if (hepmcmap)
    {
      hepmc = hepmcmap->get(0);
      if (!hepmc) hepmc = hepmcmap->get(1);
      if (!hepmc && !hepmcmap->empty()) hepmc = hepmcmap->begin()->second;
      if (hepmc) evt = hepmc->getEvent();
    }
    if (!evt) return -1.0;

    double maxPt = -1.0;
    for (auto it = evt->particles_begin(); it != evt->particles_end(); ++it)
    {
      const HepMC::GenParticle* p = *it;
      if (!p) continue;
      if (p->pdg_id() != 22) continue;
      if (requireStable && p->status() != 1) continue;

      const double pt = std::hypot(p->momentum().px(), p->momentum().py());
      const double eta = p->momentum().pseudoRapidity();
      if (!std::isfinite(pt) || !std::isfinite(eta) || pt <= 0.0) continue;
      if (eta < -1.5 || eta > 1.5) continue;

      if (requireParent)
      {
        const HepMC::GenVertex* vtx = p->production_vertex();
        if (!vtx) continue;

        bool parentOk = false;
        for (auto inItr = vtx->particles_in_const_begin(); inItr != vtx->particles_in_const_end(); ++inItr)
        {
          const HepMC::GenParticle* parent = *inItr;
          if (!parent) continue;

          const int absParentId = std::abs(parent->pdg_id());
          if (absParentId >= 1 && absParentId <= 22)
          {
            parentOk = true;
            break;
          }
        }
        if (!parentOk) continue;
      }

      if (pt > maxPt) maxPt = pt;
    }

    return maxPt;
  }

  double ppStitchDiagPhotonPt(PHCompositeNode* topNode,
                              PHG4TruthInfoContainer* truthInfo,
                              const PPStitchDiagVariant variant)
  {
    switch (variant)
    {
      case PPStitchDiagVariant::kG4Stored:
        return ppg12MaxStoredTruthPhotonPt(topNode, truthInfo, true);
      case PPStitchDiagVariant::kHepMCParent:
        return ppHepMCFilterPhotonPt(topNode, true, false);
      case PPStitchDiagVariant::kHepMCParentStable:
        return ppHepMCFilterPhotonPt(topNode, true, true);
      case PPStitchDiagVariant::kHepMCAnyPhoton:
        return ppHepMCFilterPhotonPt(topNode, false, false);
      case PPStitchDiagVariant::kG4NoEmbed:
        return ppg12MaxStoredTruthPhotonPt(topNode, truthInfo, false);
      default:
        return -1.0;
    }
  }

  inline void getDoNotScaleEventVectors(const Gl1Packet* gl1Packet,
                                        uint64_t& rawVector,
                                        uint64_t& liveVector)
  {
    rawVector = 0;
    liveVector = 0;

    if (!gl1Packet)
    {
      return;
    }

    // IMPORTANT:
    //   Use the explicit getter interface from Gl1Packet instead of the
    //   string-dispatch lValue("TriggerVector") compatibility path.
    //   The attached GL1 variants show that the string path can alias
    //   deprecated compatibility behavior, while these getters are the
    //   cleanest available accessors without changing coresoftware.
    rawVector  = static_cast<uint64_t>(gl1Packet->getTriggerVector());
    liveVector = static_cast<uint64_t>(gl1Packet->getLiveVector());
  }

