void RecoilJets::fillPPPhotonIDTrainingTree(const SSVars& v,
                                            double eta,
                                            double phi,
                                            int clusterIndex,
                                            double scoreInputEt,
                                            double responseEt,
                                            double eiso,
                                            double ppg12RawEiso,
                                            double ppg12RecoEiso,
                                            double ppg12IsoThreshold,
                                            double ppg12NonIsoThreshold,
                                            bool ppg12Iso,
                                            bool ppg12NonIso,
                                            bool ppg12CommonPass,
                                            int ppg12TightTag,
                                            int ptIdx,
                                            bool isSignal,
                                            int truthClass,
                                            int ppg12AnalysisWindowPass,
                                            int ppg12ResponseWindowPass,
                                            int ppg12LogicalABCDRegion,
                                            int ppg12SignalFillA,
                                            int ppg12SignalFillB,
                                            int ppg12SignalFillC,
                                            int ppg12SignalFillD,
                                            int ppg12SignalFillMultiplicity,
                                            int truthTrackId,
                                            int truthBarcode,
                                            float truthEnergyContribution,
                                            int ppg12SampleBin,
                                            float ppg12XsecPb,
                                            float ppg12XsecWeight,
                                            float ppg12WindowLow,
                                            float ppg12WindowHigh,
                                            float maxTruthJetPtR04,
                                            int ppg12TruthWindowPassR04,
                                            double truthIsoEtR03,
                                            double truthIsoEtR04,
                                            int truthIsoValid,
                                            int truthHepMCAssociationValid)
{
  if (!m_ppPhotonIDTrainingTreeEnabled || m_isAuAu) return;
  if (!m_ppPhotonIDTrainingTree) initPPPhotonIDTrainingTree();
  if (!m_ppPhotonIDTrainingTreeEnabled || !m_ppPhotonIDTrainingTree) return;
  if (m_ppPhotonIDTrainingTreeMaxEntries > 0 &&
      m_ppPhotonIDTrainingTreeEntries >= m_ppPhotonIDTrainingTreeMaxEntries) return;

  auto featureValue = [](double x) -> float
  {
    return std::isfinite(x) ? static_cast<float>(x) : 0.0f;
  };

  m_bdtTrain_run = currentRunNumber();
  m_bdtTrain_evt = event_count;
  m_bdtTrain_eventnumber = (m_evtHeader ? m_evtHeader->get_EvtSequence() : event_count);
  m_bdtTrain_cluster_index = clusterIndex;
  m_bdtTrain_is_signal = isSignal ? 1 : 0;
  m_bdtTrain_pt_bin = ptIdx;
  m_bdtTrain_cent_bin = -1;
  m_bdtTrain_pt = featureValue(v.pt_gamma);
  m_bdtTrain_score_input_et = featureValue(scoreInputEt);
  m_bdtTrain_response_et = featureValue(responseEt);
  m_bdtTrain_eta = featureValue(eta);
  m_bdtTrain_phi = featureValue(phi);
  m_bdtTrain_cent = -1.0f;
  m_bdtTrain_vz = featureValue(m_vz);
  m_bdtTrain_ppg12_kin_vertexz = featureValue(ppg12PhotonYieldKinematicVertexZ());
  // m_mcEventWeight is the canonical full PPG12 SIM weight in pp-SIM lanes.
  m_bdtTrain_weight = featureValue(m_mcEventWeight);
  m_bdtTrain_eiso = featureValue(eiso);
  m_bdtTrain_ppg12_raw_eiso = featureValue(ppg12RawEiso);
  m_bdtTrain_ppg12_reco_eiso = featureValue(ppg12RecoEiso);
  m_bdtTrain_ppg12_iso_threshold = featureValue(ppg12IsoThreshold);
  m_bdtTrain_ppg12_noniso_threshold = featureValue(ppg12NonIsoThreshold);
  m_bdtTrain_ppg12_is_iso = ppg12Iso ? 1 : 0;
  m_bdtTrain_ppg12_is_noniso = ppg12NonIso ? 1 : 0;
  m_bdtTrain_ppg12_common_pass = ppg12CommonPass ? 1 : 0;
  m_bdtTrain_ppg12_tight_tag = ppg12TightTag;
  m_bdtTrain_ppg12_logical_abcd_region = ppg12LogicalABCDRegion;
  m_bdtTrain_ppg12_analysis_window_pass = ppg12AnalysisWindowPass;
  m_bdtTrain_ppg12_response_window_pass = ppg12ResponseWindowPass;
  m_bdtTrain_ppg12_signal_fill_a = ppg12SignalFillA;
  m_bdtTrain_ppg12_signal_fill_b = ppg12SignalFillB;
  m_bdtTrain_ppg12_signal_fill_c = ppg12SignalFillC;
  m_bdtTrain_ppg12_signal_fill_d = ppg12SignalFillD;
  m_bdtTrain_ppg12_signal_fill_multiplicity = ppg12SignalFillMultiplicity;
  m_bdtTrain_ppg12_sample_bin = ppg12SampleBin;
  m_bdtTrain_ppg12_xsec_pb = featureValue(ppg12XsecPb);
  m_bdtTrain_ppg12_xsec_weight = featureValue(ppg12XsecWeight);
  m_bdtTrain_ppg12_window_low = featureValue(ppg12WindowLow);
  m_bdtTrain_ppg12_window_high = featureValue(ppg12WindowHigh);
  m_bdtTrain_max_truth_jet_pt_r04 = featureValue(maxTruthJetPtR04);
  m_bdtTrain_ppg12_truth_window_pass_r04 = ppg12TruthWindowPassR04;
  m_bdtTrain_truth_track_id = truthTrackId;
  m_bdtTrain_truth_barcode = truthBarcode;
  m_bdtTrain_truth_class = truthClass;
  m_bdtTrain_truth_energy_contribution =
      std::isfinite(truthEnergyContribution) ? truthEnergyContribution : -999.0f;
  m_bdtTrain_ppg12_weight_lane_code = m_ppg12SimWeightLaneCode;
  m_bdtTrain_ppg12_weight_component_code = m_ppg12SimWeightLaneComponentCode;
  m_bdtTrain_ppg12_weight_slice = featureValue(m_ppg12SimWeightFactorSlice);
  m_bdtTrain_ppg12_weight_vertex = featureValue(m_ppg12SimWeightFactorVertex);
  m_bdtTrain_ppg12_weight_mix = featureValue(m_ppg12SimWeightFactorMix);
  m_bdtTrain_ppg12_weight_period = featureValue(m_ppg12SimWeightFactorPeriod);
  m_bdtTrain_ppg12_weight_final = featureValue(m_ppg12SimWeightFactorFinal);

  m_bdtTrain_weta = featureValue(v.weta_cogx);
  m_bdtTrain_wphi = featureValue(v.wphi_cogx);
  m_bdtTrain_weta33 = featureValue(v.weta33_cogx);
  m_bdtTrain_wphi33 = featureValue(v.wphi33_cogx);
  m_bdtTrain_weta35 = featureValue(v.weta35_cogx);
  m_bdtTrain_wphi53 = featureValue(v.wphi53_cogx);
  m_bdtTrain_et1 = featureValue(v.et1);
  m_bdtTrain_et2 = featureValue(v.et2);
  m_bdtTrain_et3 = featureValue(v.et3);
  m_bdtTrain_et4 = featureValue(v.et4);
  m_bdtTrain_e11e33 = featureValue(v.e11_over_e33);
  m_bdtTrain_e32e35 = featureValue(v.e32_over_e35);
  m_bdtTrain_e11e22 = featureValue(v.e11_over_e22);
  m_bdtTrain_e11e13 = featureValue(v.e11_over_e13);
  m_bdtTrain_e11e15 = featureValue(v.e11_over_e15);
  m_bdtTrain_e11e17 = featureValue(v.e11_over_e17);
  m_bdtTrain_e11e31 = featureValue(v.e11_over_e31);
  m_bdtTrain_e11e51 = featureValue(v.e11_over_e51);
  m_bdtTrain_e11e71 = featureValue(v.e11_over_e71);
  m_bdtTrain_e22e33 = featureValue(v.e22_over_e33);
  m_bdtTrain_e22e35 = featureValue(v.e22_over_e35);
  m_bdtTrain_e22e37 = featureValue(v.e22_over_e37);
  m_bdtTrain_e22e53 = featureValue(v.e22_over_e53);
  m_bdtTrain_w32 = featureValue(v.w32);
  m_bdtTrain_w52 = featureValue(v.w52);
  m_bdtTrain_w72 = featureValue(v.w72);
  m_bdtTrain_cluster_prob = std::isfinite(v.cluster_prob) ? static_cast<float>(v.cluster_prob) : -2.0f;
  m_bdtTrain_npb_score = std::isfinite(v.npb_score) ? static_cast<float>(v.npb_score) : -2.0f;
  m_bdtTrain_tight_bdt_score = std::isfinite(v.tight_bdt_score) ? static_cast<float>(v.tight_bdt_score) : -2.0f;
  m_bdtTrain_ppg12_shape_n_owned = featureValue(v.ppg12_shape_n_owned);
  m_bdtTrain_ppg12_shape_owned_e = featureValue(v.ppg12_shape_owned_e);
  m_bdtTrain_ppg12_shape_all_e = featureValue(v.ppg12_shape_all_e);
  m_bdtTrain_ppg12_shape_den_e = featureValue(v.ppg12_shape_den_e);
  m_bdtTrain_ppg12_shape_weta_cogx_num = featureValue(v.ppg12_shape_weta_cogx_num);
  m_bdtTrain_ppg12_shape_wphi_cogx_num = featureValue(v.ppg12_shape_wphi_cogx_num);
  m_bdtTrain_ppg12_shape_cog_eta = featureValue(v.ppg12_shape_cog_eta);
  m_bdtTrain_ppg12_shape_cog_phi = featureValue(v.ppg12_shape_cog_phi);
  m_bdtTrain_ppg12_shape_center_ieta = featureValue(v.ppg12_shape_center_ieta);
  m_bdtTrain_ppg12_shape_center_iphi = featureValue(v.ppg12_shape_center_iphi);

  // THE134_FAST_EXTRACTION_V1 preserves the legacy calculation and label
  // authority above, but the broad extraction artifact owns only the
  // normalized seven-view sidecar.  Do not serialize the redundant legacy
  // tree in that explicitly gated mode.
  if (!m_the134FastExtraction)
  {
    m_ppPhotonIDTrainingTree->Fill();
    ++m_ppPhotonIDTrainingTreeEntries;
  }

  if (m_photonTrainingViewRuntime)
  {
    RJPhotonTrainingViewV1::Label label;
    label.cluster_index = clusterIndex;
    label.training_label = isSignal ? 1 : 0;
    label.is_signal = isSignal ? 1 : 0;
    label.label_authority = "PPG12_SOURCE_ROLE";
    label.truth_match_found = truthTrackId >= 0 ? 1 : 0;
    label.truth_hepmc_association_valid = truthHepMCAssociationValid;
    label.truth_photon_class = truthClass;
    label.truth_is_prompt =
        (truthClass == 1 || truthClass == 2) ? 1 : (truthClass >= 0 ? 0 : -1);
    label.truth_iso_et = truthIsoEtR03;
    label.truth_iso_et_r03 = truthIsoEtR03;
    label.truth_iso_et_r04 = truthIsoEtR04;
    label.truth_iso_valid = truthIsoValid;
    label.truth_iso_pass = truthIsoValid == 1 ? (truthIsoEtR03 < m_truthIsoMaxGeV ? 1 : 0) : -1;
    label.cluster_truth_track_id = truthTrackId;
    label.cluster_truth_pid = truthTrackId >= 0 ? 22 : 0;
    label.cluster_truth_barcode = truthBarcode;
    label.truth_energy_contribution = truthEnergyContribution;
    label.source_role = isSignal ? 1 : 2;
    // The legacy PPG12 branch stores a compact ordinal in
    // ppg12_sample_bin.  The normalized source identity instead owns the
    // physical generator threshold (Photon5/10/20 or Jet8/12/20/30).
    label.source_sample_code = m_photonTrainingViewRuntime->sourceSampleCode();
    label.ppg12_source_role_label = isSignal ? 1 : 0;
    label.ppg12_analysis_window_pass = ppg12AnalysisWindowPass;
    label.ppg12_response_window_pass = ppg12ResponseWindowPass;
    label.ppg12_truth_window_pass_r04 = ppg12TruthWindowPassR04;
    label.ppg12_sample_bin = ppg12SampleBin;
    label.ppg12_xsec_pb = ppg12XsecPb;
    label.ppg12_xsec_weight = ppg12XsecWeight;
    label.ppg12_window_low = ppg12WindowLow;
    label.ppg12_window_high = ppg12WindowHigh;
    label.max_truth_jet_pt_r04 = maxTruthJetPtR04;
    label.weight_slice = m_ppg12SimWeightFactorSlice;
    // Match the accepted replay ledger: cross_section and exposure are
    // provenance aliases, while the physical slice and period factors are
    // applied exactly once when reconstructing the final weight.
    label.weight_cross_section = m_ppg12SimWeightFactorSlice;
    label.weight_vertex = m_ppg12SimWeightFactorVertex;
    label.weight_si_di = m_ppg12SimWeightFactorMix;
    label.weight_period = m_ppg12SimWeightFactorPeriod;
    label.weight_exposure = m_ppg12SimWeightFactorPeriod;
    label.weight_final = m_ppg12SimWeightFactorFinal;
    label.weight_application_count = 1;
    std::string trainingError;
    if (!m_photonTrainingViewRuntime->recordLabel(
            event_count,clusterIndex,label,&trainingError))
    {
      m_replayWriteFailed = true;
      LOG(0, CLR_RED, "[RJPhotonTrainingViewV1][FATAL] label capture failed: " << trainingError);
    }
  }
}


int RecoilJets::InitRun(PHCompositeNode* /*topNode*/)
{
  const uint64_t run = recoConsts::instance()->get_uint64Flag("TIMESTAMP", 0);
  LOG(1, CLR_BLUE, "[InitRun] ------------------------------------------------------------");
  LOG(1, CLR_BLUE, "[InitRun] Starting InitRun  –  TIMESTAMP = " << run);

  // Dataset flag + configured binning
  LOG(1, CLR_GREEN, "[InitRun] Dataset      : " << (m_isAuAu ? "Au+Au" : "p+p"));
      {
        std::ostringstream os;
        os << "[InitRun] gamma-pT bins: {";
        for (std::size_t i = 0; i+1 < m_gammaPtBins.size(); ++i)
          os << (i? ", ":" ") << m_gammaPtBins[i] << "–" << m_gammaPtBins[i+1];
        os << " }";
        LOG(1, CLR_GREEN, os.str());
  }

  // ------------------------------------------------------------------
  // reset per-pT negative-isolation accounting (SS-independent)
  // ------------------------------------------------------------------
  const std::size_t nPtBins = (m_gammaPtBins.size() > 1 ? (m_gammaPtBins.size() - 1) : 0);
  m_nIsoBuilderByPt.assign(nPtBins, 0ULL);
  m_nIsoBuilderNegByPt.assign(nPtBins, 0ULL);

  if (m_isAuAu)
  {
    if (m_centEdges.empty())
      LOG(0, CLR_YELLOW, "[InitRun] WARNING: centrality edges vector is EMPTY");
    else
    {
      bool mono = std::is_sorted(m_centEdges.begin(), m_centEdges.end());
      if (!mono)
        LOG(0, CLR_YELLOW, "[InitRun] WARNING: centrality edges not monotonic");
      std::ostringstream oc;
      oc << "[InitRun] centrality bins: {";
      for (std::size_t i = 0; i+1 < m_centEdges.size(); ++i)
        oc << (i? ", ":" ") << m_centEdges[i] << "–" << m_centEdges[i+1];
      oc << " }";
      LOG(1, CLR_GREEN, oc.str());
    }
  }

  if (m_vertexReweightH)
  {
    delete m_vertexReweightH;
    m_vertexReweightH = nullptr;
  }

  const bool initPPPhotonVertexWeight =
      m_isSim && !m_isAuAu && m_vertexReweightOn &&
      (ppg12PhotonSliceFromContext(Outfile) != PPG12PhotonSlice::kNone ||
       (m_ppg12PhotonYieldEnabled &&
        ppg12InclusiveJetSliceFromContext(Outfile) != PPG12InclusiveJetSlice::kNone));

  if (initPPPhotonVertexWeight)
  {
    TFile* fvtx = TFile::Open(m_vertexReweightFile.c_str(), "READ");
    if (!fvtx || fvtx->IsZombie())
    {
      LOG(0, CLR_RED, "[InitRun] pp vertex reweight file open failed: " << m_vertexReweightFile);
      if (fvtx)
      {
        fvtx->Close();
        delete fvtx;
      }
      return Fun4AllReturnCodes::ABORTRUN;
    }

    TH1* htmp = dynamic_cast<TH1*>(fvtx->Get(m_vertexReweightHist.c_str()));
    if (!htmp)
    {
      LOG(0, CLR_RED, "[InitRun] pp vertex reweight histogram missing: "
                       << m_vertexReweightHist << " in " << m_vertexReweightFile);
      fvtx->Close();
      delete fvtx;
      return Fun4AllReturnCodes::ABORTRUN;
    }

    m_vertexReweightH = dynamic_cast<TH1*>(htmp->Clone("h_truth_vtx_reweight_clone"));
    if (!m_vertexReweightH)
    {
      LOG(0, CLR_RED, "[InitRun] pp vertex reweight histogram clone failed: " << m_vertexReweightHist);
      fvtx->Close();
      delete fvtx;
      return Fun4AllReturnCodes::ABORTRUN;
    }

    m_vertexReweightH->SetDirectory(nullptr);
    for (const char* k : {"period", "run_min", "run_max", "z_cut"})
    {
      if (auto* tn = dynamic_cast<TNamed*>(fvtx->Get(k)))
      {
        LOG(1, CLR_GREEN, "[TruthVertexReweight] " << k << "=" << tn->GetTitle());
      }
    }
    fvtx->Close();
    delete fvtx;

    LOG(1, CLR_GREEN, "[TruthVertexReweight] loaded " << m_vertexReweightHist
                         << " from " << m_vertexReweightFile
                         << " (" << m_vertexReweightH->GetNbinsX() << " bins, "
                         << m_vertexReweightH->GetBinWidth(1) << " cm/bin)");
  }

    // -------------------------------------------------------------------------
    // EventDisplay diagnostics payload (offline rendering; independent of Verbosity()).
    //
    // Enable via either:
    //   - RecoilJets::enableEventDisplayDiagnostics(true), or
    //   - environment: RJ_ENABLE_EVENTDISPLAY_DIAGNOSTICS=1
    //
    // Optional cap (per rKey × pTγ bin × {NUM,MissA,MissB}):
    //   - environment: RJ_EVTDIAG_MAX_PER_BIN=N   (0 => unlimited)
    // -------------------------------------------------------------------------
    if (const char* e = gSystem->Getenv("RJ_ENABLE_EVENTDISPLAY_DIAGNOSTICS"))
    {
      m_evtDiagEnabled = (std::atoi(e) != 0);
    }

    if (const char* n = gSystem->Getenv("RJ_EVTDIAG_MAX_PER_BIN"))
    {
      m_evtDiagMaxPerBin = std::max(0, std::atoi(n));
    }

    m_evtDiagSavedPerBin.clear();

    if (m_evtDiagEnabled)
    {
      initEventDisplayDiagnosticsTree();
    }

    // -------------------------------------------------------------------------
    // Pre-book the EXACT doNotScale pair histograms that are valid for this run.
    //   - numerator   : <probeHistKey>
    //   - denominator : baseline_<probeHistKey>
    // This keeps the output schema aligned with the run-resolved pair table and
    // removes the old family-level pp-only doNotScale bookkeeping.
    // -------------------------------------------------------------------------
    if (!m_isSim && out && out->IsOpen())
    {
      auto bookDoNotScaleHist = [&](const std::string& histKey)
      {
        TDirectory* dir = out->GetDirectory(histKey.c_str());
        if (!dir) dir = out->mkdir(histKey.c_str());
        if (!dir) return;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        HistMap& H = qaHistogramsByTrigger[histKey];
        const std::string histName = doNotScaleHistName(histKey);
        if (H.find(histName) == H.end())
        {
          TH1F* hist = RJMCWeighting::RJNewTH1F(histName.c_str(),
                                "Max Cluster Energy; Cluster Energy [GeV]",
                                40, 0, 20);
          hist->SetDirectory(dir);
          H[histName] = hist;
        }

        if (prevDir) prevDir->cd();
      };

      for (const auto& cfg : getDoNotScalePairConfigs())
      {
        if (!doNotScaleRunMatch(run, cfg)) continue;

        bookDoNotScaleHist(doNotScaleBaselineHistKey(cfg));
        bookDoNotScaleHist(cfg.probeHistKey);
      }

      out->cd();
    }

    LOG(1, CLR_BLUE, "[InitRun] InitRun completed successfully");
    return Fun4AllReturnCodes::EVENT_OK;
}



void RecoilJets::createHistos_Data()
{
  // Vertex histogram binning tied to your configured vz cut (m_vzCut).
  // Keep the same resolution as before: ~0.5 cm per bin.
  const double vzAbs    = std::max(1.0, std::fabs(static_cast<double>(m_vzCut)));
  const double vzBinW   = 0.5; // cm/bin
  const int    nbVz     = std::max(1, static_cast<int>(std::lround((2.0 * vzAbs) / vzBinW)));
  const double vzMin    = -vzAbs;
  const double vzMax    =  vzAbs;

  // ------------------------------------------------------------------
  // SIMULATION MODE: do NOT depend on trigger names.
  // Everything goes under a single directory: /SIM/
  // ------------------------------------------------------------------
  if (m_isSim)
  {
    const std::string trig = "SIM";

    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    dir->cd();

    HistMap& H = qaHistogramsByTrigger[trig];

    // 1) per-job event counter (SIM)
    const std::string hcnt = "cnt_" + trig;
    if (H.find(hcnt) == H.end())
    {
      auto* h = RJMCWeighting::RJNewTH1I(hcnt.c_str(), (hcnt + ";count;entries").c_str(), 1, 0.5, 1.5);
      h->GetXaxis()->SetBinLabel(1, "count");
      H[hcnt] = h;
    }

    // 2) vertex-z QA
    if (H.find("h_vertexZ") == H.end())
    {
      auto* hvz = RJMCWeighting::RJNewTH1F("h_vertexZ", "h_vertexZ;v_{z} [cm];Entries", nbVz, vzMin, vzMax);
      H["h_vertexZ"] = hvz;
    }

    // 3) SIM ONLY: truth-vs-reco vertex comparison (filled BEFORE |vz| cut)
    if (H.find("h_vzTruthVsReco") == H.end())
    {
      auto* h2 = RJMCWeighting::RJNewTH2F("h_vzTruthVsReco",
                           "h_vzTruthVsReco;v_{z}^{truth} [cm];v_{z}^{reco-used} [cm]",
                           nbVz, vzMin, vzMax,
                           nbVz, vzMin, vzMax);
      H["h_vzTruthVsReco"] = h2;
    }

    // Optional: if you ever run a HI-like sim with centrality available
    if (m_isAuAu && H.find("h_centrality") == H.end())
    {
      auto* hc = RJMCWeighting::RJNewTH1F("h_centrality", "h_centrality;Centrality [%];Entries", 100, 0.0, 100.0);
      H["h_centrality"] = hc;
    }

    // SIM pi0 analysis: book pi0 TH2s under the SIM directory itself
    // so that AnalyzeRecoilJets RunPi0QA can find them via ds.topDir ("SIM").
    if (m_doPi0Analysis)
    {
      dir->cd();
      HistMap& Hpi0 = H;

      if (Hpi0.find("h2_pi0_mass_vs_pi0pt_corr") == Hpi0.end())
      {
        TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_pi0pt_corr",
                               "h2_pi0_mass_vs_pi0pt_corr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{#pi^{0}} [GeV/c]",
                               240, 0, 0.6,
                               240, 0, 60);
        hist->SetDirectory(out);
        Hpi0["h2_pi0_mass_vs_pi0pt_corr"] = hist;
      }

      if (Hpi0.find("h2_pi0_mass_vs_pi0pt_nocorr") == Hpi0.end())
      {
        TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_pi0pt_nocorr",
                               "h2_pi0_mass_vs_pi0pt_nocorr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{#pi^{0}} [GeV/c]",
                               240, 0, 0.6,
                               240, 0, 60);
        hist->SetDirectory(out);
        Hpi0["h2_pi0_mass_vs_pi0pt_nocorr"] = hist;
      }

      if (Hpi0.find("h2_pi0_mass_vs_leadcluspt_corr") == Hpi0.end())
      {
        TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_leadcluspt_corr",
                               "h2_pi0_mass_vs_leadcluspt_corr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{lead cluster} [GeV/c]",
                               240, 0, 0.6,
                               240, 0, 60);
        hist->SetDirectory(out);
        Hpi0["h2_pi0_mass_vs_leadcluspt_corr"] = hist;
      }

      if (Hpi0.find("h2_pi0_mass_vs_leadcluspt_nocorr") == Hpi0.end())
      {
        TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_leadcluspt_nocorr",
                               "h2_pi0_mass_vs_leadcluspt_nocorr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{lead cluster} [GeV/c]",
                               240, 0, 0.6,
                               240, 0, 60);
        hist->SetDirectory(out);
        Hpi0["h2_pi0_mass_vs_leadcluspt_nocorr"] = hist;
      }

      out->cd();
    }

    out->cd();
    return;
  }

  // ------------------------------------------------------------------
  // DATA MODE: per-trigger directories
  // ------------------------------------------------------------------
  if (m_isAuAu)
  {
    for (const auto& kv : triggerNameMapAuAu) // kv: std::pair<int,std::string>
    {
      const std::string trig = kv.second;

      // Make sure the trigger directory exists
      TDirectory* dir = out->GetDirectory(trig.c_str());
      if (!dir) dir = out->mkdir(trig.c_str());
      dir->cd();

      HistMap& H = qaHistogramsByTrigger[trig];

      // 1) per-trigger event counter
      const std::string hcnt = "cnt_" + trig;
      if (H.find(hcnt) == H.end())
      {
        auto* h = RJMCWeighting::RJNewTH1I(hcnt.c_str(), (hcnt + ";count;entries").c_str(), 1, 0.5, 1.5);
        h->GetXaxis()->SetBinLabel(1, "count");
        H[hcnt] = h;
      }

      // 2) vertex-z QA
      if (H.find("h_vertexZ") == H.end())
      {
        auto* hvz = RJMCWeighting::RJNewTH1F("h_vertexZ", "h_vertexZ;v_{z} [cm];Entries", nbVz, vzMin, vzMax);
        H["h_vertexZ"] = hvz;
      }

      // 3) centrality QA (Au+Au only)
      if (H.find("h_centrality") == H.end())
      {
        auto* hc = RJMCWeighting::RJNewTH1F("h_centrality", "h_centrality;Centrality [%];Entries", 100, 0.0, 100.0);
        H["h_centrality"] = hc;
      }

      out->cd();
    }
  }
  else
  {
    {
      const std::string trig = "MBD_NandS_geq_1";

      TDirectory* dir = out->GetDirectory(trig.c_str());
      if (!dir) dir = out->mkdir(trig.c_str());
      dir->cd();

      HistMap& H = qaHistogramsByTrigger[trig];

      if (m_doPi0Analysis)
      {
        if (H.find("h2_pi0_mass_vs_pi0pt_corr") == H.end())
        {
          TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_pi0pt_corr",
                                "h2_pi0_mass_vs_pi0pt_corr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{#pi^{0}} [GeV/c]",
                                240, 0, 0.6,
                                240, 0, 60);
          hist->SetDirectory(out);
          H["h2_pi0_mass_vs_pi0pt_corr"] = hist;
        }

        if (H.find("h2_pi0_mass_vs_pi0pt_nocorr") == H.end())
        {
          TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_pi0pt_nocorr",
                                "h2_pi0_mass_vs_pi0pt_nocorr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{#pi^{0}} [GeV/c]",
                                240, 0, 0.6,
                                240, 0, 60);
          hist->SetDirectory(out);
          H["h2_pi0_mass_vs_pi0pt_nocorr"] = hist;
        }

        if (H.find("h2_pi0_mass_vs_leadcluspt_corr") == H.end())
        {
          TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_leadcluspt_corr",
                                "h2_pi0_mass_vs_leadcluspt_corr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{lead cluster} [GeV/c]",
                                240, 0, 0.6,
                                240, 0, 60);
          hist->SetDirectory(out);
          H["h2_pi0_mass_vs_leadcluspt_corr"] = hist;
        }

        if (H.find("h2_pi0_mass_vs_leadcluspt_nocorr") == H.end())
        {
          TH2F* hist = RJMCWeighting::RJNewTH2F("h2_pi0_mass_vs_leadcluspt_nocorr",
                                "h2_pi0_mass_vs_leadcluspt_nocorr;M_{#gamma#gamma} [GeV/c^{2}];p_{T}^{lead cluster} [GeV/c]",
                                240, 0, 0.6,
                                240, 0, 60);
          hist->SetDirectory(out);
          H["h2_pi0_mass_vs_leadcluspt_nocorr"] = hist;
        }
      }

      out->cd();
    }

    // ------------------------------------------------------------------
    // Existing pp per-trigger QA booking (unchanged; still uses triggerNameMap_pp)
    // ------------------------------------------------------------------
    for (const auto& kv : triggerNameMap_pp) // kv: std::pair<std::string,std::string>
    {
      const std::string trig = kv.second;

      // Make sure the trigger directory exists
      TDirectory* dir = out->GetDirectory(trig.c_str());
      if (!dir) dir = out->mkdir(trig.c_str());
      dir->cd();

      HistMap& H = qaHistogramsByTrigger[trig];

      // 1) per-trigger event counter
      const std::string hcnt = "cnt_" + trig;
      if (H.find(hcnt) == H.end())
      {
        auto* h = RJMCWeighting::RJNewTH1I(hcnt.c_str(), (hcnt + ";count;entries").c_str(), 1, 0.5, 1.5);
        h->GetXaxis()->SetBinLabel(1, "count");
        H[hcnt] = h;
      }

      // 2) vertex-z QA
      if (H.find("h_vertexZ") == H.end())
      {
        auto* hvz = RJMCWeighting::RJNewTH1F("h_vertexZ", "h_vertexZ;v_{z} [cm];Entries", nbVz, vzMin, vzMax);
        H["h_vertexZ"] = hvz;
      }

      out->cd();
    }
  }
}



bool RecoilJets::firstEventCuts(PHCompositeNode* topNode,
                                std::vector<std::string>& activeTrig)
{
  m_lastReject = EventReject::None;
  activeTrig.clear();

  // Small helper for printing lists
  auto joinList = [](const std::vector<std::string>& v, const char* sep) -> std::string
  {
    std::ostringstream os;
    for (std::size_t i = 0; i < v.size(); ++i)
    {
      if (i) os << sep;
      os << v[i];
    }
    return os.str();
  };

  // Grab GL1 scaled vector for diagnostics (works for pp & Au+Au if node exists)
  uint64_t gl1Scaled = 0;
  {
    Gl1Packet* gl1 = findNode::getClass<Gl1Packet>(topNode, "GL1Packet");
    if (!gl1) gl1 = findNode::getClass<Gl1Packet>(topNode, "14001");
    if (gl1) gl1Scaled = gl1->lValue(0, "ScaledVector");
  }

  // ------------------------------------------------------------------
  // SIMULATION MODE:
  //   - skip trigger logic
  //   - still apply global |vz| cut if enabled
  // ------------------------------------------------------------------
  if (m_isSim)
  {
    activeTrig.emplace_back("SIM");

    if (m_ppg12PhotonYieldEnabled && !m_isAuAu)
    {
      fillPPG12VertexContractQA(activeTrig, true);
    }

    if (m_useVzCut && std::fabs(m_vz) >= m_vzCut)
    {
      m_lastReject = EventReject::Vz;
      if (Verbosity() >= 4)
      {
        std::ostringstream os;
        os << "    [firstEventCuts] REJECT (SIM |vz| cut)"
           << " | vz=" << std::fixed << std::setprecision(3) << m_vz
           << " | |vz|cut=" << m_vzCut;
        LOG(4, CLR_YELLOW, os.str());
      }
      return false;
    }

    if (Verbosity() >= 4)
    {
      std::ostringstream os;
      os << "    [firstEventCuts] ACCEPT (SIM)"
         << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
      if (m_useVzCut) os << " (|vz|cut=" << m_vzCut << ")";
      LOG(4, CLR_GREEN, os.str());
    }

    if (m_ppg12PhotonYieldEnabled && !m_isAuAu)
    {
      fillPPG12VertexContractQA(activeTrig, false);
    }

    m_lastReject = EventReject::None;
    return true;
  }

  // ------------------------------------------------------------------
  // DATA MODE
  // ------------------------------------------------------------------
  if (!m_isAuAu)
  {
    // ---------- p+p: accept if ANY configured pp trigger fired ----------
    auto* directGl1Packet=findNode::getClass<Gl1Packet>(topNode,"GL1Packet");
    if(!directGl1Packet) directGl1Packet=findNode::getClass<Gl1Packet>(topNode,"14001");
    const auto* directRunInfo=findNode::getClass<TriggerRunInfo>(topNode,"TriggerRunInfo");

    std::vector<std::string> firedDb;
    std::vector<std::string> checkedLines;
    firedDb.reserve(triggerNameMap_pp.size());
    checkedLines.reserve(triggerNameMap_pp.size());

    uint64_t ppg12ScaledVector = 0;
    bool havePPG12ScaledVector = false;
    bool ppg12ScaledBit30Fired = false;
    if (m_ppg12Fig13Bit30Diagnostic)
    {
      Gl1Packet* ppg12Gl1 = findNode::getClass<Gl1Packet>(topNode, "14001");
      if (!ppg12Gl1) ppg12Gl1 = findNode::getClass<Gl1Packet>(topNode, "GL1Packet");
      if (ppg12Gl1)
      {
        ppg12ScaledVector = static_cast<uint64_t>(ppg12Gl1->lValue(0, "ScaledVector"));
        havePPG12ScaledVector = true;
        ppg12ScaledBit30Fired = ((ppg12ScaledVector & (1ULL << 30U)) != 0ULL);
      }
    }

    bool photon4DbFired = false;
    for (const auto& kv : triggerNameMap_pp)
    {
      const std::string& dbName   = kv.first;   // GL1/DB name
      const std::string& shortKey = kv.second;  // friendly key

      const bool fired = RJGl1TriggerContract::firedByName(directGl1Packet,directRunInfo,dbName);
      checkedLines.push_back(dbName + "->" + (fired ? "1" : "0") + " (" + shortKey + ")");
      if (fired) activeTrig.push_back(shortKey);
      if (fired) firedDb.push_back(dbName);
      if (shortKey == "Photon_4_GeV_plus_MBD_NS_geq_1") photon4DbFired = fired;

      if (Verbosity() >= 6)
      {
        LOG(6, CLR_CYAN,
            "      [pp trigger] " << dbName
            << " fired=" << (fired ? 1 : 0)
            << "  shortKey=\"" << shortKey << "\"");
      }
    }

    if (m_ppg12Fig13Bit30Diagnostic)
    {
      const bool passVzForAudit = (!m_useVzCut || std::fabs(m_vz) < m_vzCut);
      auto& H = qaHistogramsByTrigger[kPPG12Fig13Bit30TriggerKey];

      auto getAuditCount = [&](const std::string& name,
                               const std::string& title,
                               const std::vector<std::string>& labels) -> TH1I*
      {
        if (auto it = H.find(name); it != H.end())
        {
          if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
          H.erase(it);
        }
        if (!out || !out->IsOpen()) return nullptr;
        TDirectory* const prevDir = gDirectory;
        TDirectory* dir = out->GetDirectory(kPPG12Fig13Bit30TriggerKey);
        if (!dir) dir = out->mkdir(kPPG12Fig13Bit30TriggerKey);
        if (!dir)
        {
          if (prevDir) prevDir->cd();
          return nullptr;
        }
        dir->cd();
        auto* h = RJMCWeighting::RJNewTH1I(name.c_str(), title.c_str(),
                                           static_cast<int>(labels.size()), 0.5,
                                           static_cast<double>(labels.size()) + 0.5);
        if (h)
        {
          for (std::size_t i = 0; i < labels.size(); ++i)
          {
            h->GetXaxis()->SetBinLabel(static_cast<int>(i) + 1, labels[i].c_str());
          }
          H[name] = h;
        }
        if (prevDir) prevDir->cd();
        return h;
      };

      auto getAuditFloat = [&](const std::string& name,
                               const std::string& title,
                               int nbins,
                               double xmin,
                               double xmax) -> TH1F*
      {
        if (auto it = H.find(name); it != H.end())
        {
          if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
          H.erase(it);
        }
        if (!out || !out->IsOpen()) return nullptr;
        TDirectory* const prevDir = gDirectory;
        TDirectory* dir = out->GetDirectory(kPPG12Fig13Bit30TriggerKey);
        if (!dir) dir = out->mkdir(kPPG12Fig13Bit30TriggerKey);
        if (!dir)
        {
          if (prevDir) prevDir->cd();
          return nullptr;
        }
        dir->cd();
        auto* h = RJMCWeighting::RJNewRawTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
        if (h) H[name] = h;
        if (prevDir) prevDir->cd();
        return h;
      };

      const std::vector<std::string> overlapLabels = {
          "all_pp_events_seen",
          "scaled_bit30",
          "db_photon4",
          "both",
          "bit30_only",
          "db_only",
          "bit30_vz_pass",
          "db_vz_pass",
          "gl1_packet_missing"
      };
      if (auto* h = getAuditCount("h_ppg12_fig13_trigger_overlap",
                                  "PPG12 Fig.13 pp trigger audit;category;events",
                                  overlapLabels))
      {
        h->Fill(1);
        if (ppg12ScaledBit30Fired) h->Fill(2);
        if (photon4DbFired) h->Fill(3);
        if (ppg12ScaledBit30Fired && photon4DbFired) h->Fill(4);
        if (ppg12ScaledBit30Fired && !photon4DbFired) h->Fill(5);
        if (!ppg12ScaledBit30Fired && photon4DbFired) h->Fill(6);
        if (ppg12ScaledBit30Fired && passVzForAudit) h->Fill(7);
        if (photon4DbFired && passVzForAudit) h->Fill(8);
        if (!havePPG12ScaledVector) h->Fill(9);
        bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
      }

      const int runNumber = currentRunNumber();
      if (runNumber > 0)
      {
        if (ppg12ScaledBit30Fired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_run_scaled_bit30",
                                      "PPG12 Fig.13 scaled bit 30 accepted;run number;events",
                                      20000, 40000.0, 60000.0))
          {
            h->Fill(runNumber);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
        if (photon4DbFired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_run_db_photon4",
                                      "RecoilJets DB Photon 4 accepted;run number;events",
                                      20000, 40000.0, 60000.0))
          {
            h->Fill(runNumber);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
        if (ppg12ScaledBit30Fired && !photon4DbFired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_run_bit30_only",
                                      "PPG12 scaled bit 30 only;run number;events",
                                      20000, 40000.0, 60000.0))
          {
            h->Fill(runNumber);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
        if (!ppg12ScaledBit30Fired && photon4DbFired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_run_db_only",
                                      "RecoilJets DB Photon 4 only;run number;events",
                                      20000, 40000.0, 60000.0))
          {
            h->Fill(runNumber);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
      }

      if (std::isfinite(m_vz))
      {
        if (ppg12ScaledBit30Fired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_vz_scaled_bit30",
                                      "PPG12 scaled bit 30 vertex;v_{z} [cm];events",
                                      240, -120.0, 120.0))
          {
            h->Fill(m_vz);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
        if (photon4DbFired)
        {
          if (auto* h = getAuditFloat("h_ppg12_fig13_vz_db_photon4",
                                      "RecoilJets DB Photon 4 vertex;v_{z} [cm];events",
                                      240, -120.0, 120.0))
          {
            h->Fill(m_vz);
            bumpHistFill(kPPG12Fig13Bit30TriggerKey, h->GetName());
          }
        }
      }

      if (ppg12ScaledBit30Fired &&
          std::find(activeTrig.begin(), activeTrig.end(), kPPG12Fig13Bit30TriggerKey) == activeTrig.end())
      {
        activeTrig.emplace_back(kPPG12Fig13Bit30TriggerKey);
      }
    }

    if (activeTrig.empty())
    {
      m_lastReject = EventReject::Trigger;

      if (Verbosity() >= 4)
      {
        std::ostringstream os;
        os << "    [firstEventCuts] REJECT (p+p Trigger): no configured pp triggers fired"
           << " | checked={" << joinList(checkedLines, ", ") << "}"
           << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
        if (m_useVzCut) os << " (|vz|cut=" << m_vzCut << ")";
        if (gl1Scaled) os << " | GL1Scaled=0x" << std::hex << gl1Scaled << std::dec;
        if (m_ppg12Fig13Bit30Diagnostic)
          os << " | ppg12Scaled30=" << (ppg12ScaledBit30Fired ? 1 : 0);
        LOG(4, CLR_YELLOW, os.str());
      }
      return false;
    }

    if (Verbosity() >= 4)
    {
      std::ostringstream os;
      os << "    [firstEventCuts] Trigger PASS (p+p)"
         << " | activeTrig={" << joinList(activeTrig, ", ") << "}"
         << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
      if (gl1Scaled) os << " | GL1Scaled=0x" << std::hex << gl1Scaled << std::dec;
      if (m_ppg12Fig13Bit30Diagnostic)
        os << " | ppg12Scaled30=" << (ppg12ScaledBit30Fired ? 1 : 0)
           << " | dbPhoton4=" << (photon4DbFired ? 1 : 0);
      LOG(4, CLR_GREEN, os.str());
    }

    if (m_ppg12PhotonYieldEnabled)
    {
      fillPPG12VertexContractQA(activeTrig, true);

      if (m_ppg12PeriodFilterData)
      {
        const int runNumber = currentRunNumber();
        if (!ppg12PeriodRunContains(runNumber))
        {
          m_lastReject = EventReject::Period;
          if (Verbosity() >= 4)
          {
            LOG(4, CLR_YELLOW,
                "    [firstEventCuts] REJECT (PPG12 period filter)"
                << " | run=" << runNumber
                << " | required=" << m_ppg12PeriodKey
                << " run=[" << m_ppg12PeriodRunMin << "," << m_ppg12PeriodRunMaxExclusive << ")"
                << " | triggers={" << joinList(activeTrig, ", ") << "}");
          }
          return false;
        }
      }
    }
  }
  else
  {
    // ---------- Au+Au: scaled GL1 bits only ----------
    uint64_t wScaled = 0;
    if (auto* gl1 = findNode::getClass<Gl1Packet>(topNode, "GL1Packet"))
      wScaled = gl1->lValue(0, "ScaledVector");
    else if (auto* gl1b = findNode::getClass<Gl1Packet>(topNode, "14001"))
      wScaled = gl1b->lValue(0, "ScaledVector");

    if (Verbosity() >= 6)
    {
      std::ostringstream os;
      os << "    [AuAu trigger] ScaledVector="
         << "0x" << std::hex << wScaled << std::dec
         << " (event_count=" << event_count << ")";
      LOG(6, CLR_CYAN, os.str());
    }

    if (wScaled)
    {
      const auto bits = extractTriggerBits(wScaled, static_cast<int>(event_count));
      for (const auto& [bit, key] : triggerNameMapAuAu)
        if (checkTriggerCondition(bits, bit))
          activeTrig.push_back(key);
    }

    if (activeTrig.empty())
    {
      m_lastReject = EventReject::Trigger;

      if (Verbosity() >= 4)
      {
        std::ostringstream os;
        os << "    [firstEventCuts] REJECT (Au+Au Trigger): no configured scaled triggers fired"
           << " | ScaledVector=0x" << std::hex << wScaled << std::dec
           << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
        if (m_useVzCut) os << " (|vz|cut=" << m_vzCut << ")";
        LOG(4, CLR_YELLOW, os.str());
      }
      return false;
    }

    if (Verbosity() >= 4)
    {
      std::ostringstream os;
      os << "    [firstEventCuts] Trigger PASS (Au+Au)"
         << " | activeTrig={" << joinList(activeTrig, ", ") << "}"
         << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
      LOG(4, CLR_GREEN, os.str());
    }
  }

  // ---------- Global |vz| veto ----------
  if (m_useVzCut && std::fabs(m_vz) >= m_vzCut)
  {
    m_lastReject = EventReject::Vz;

    if (Verbosity() >= 4)
    {
      std::ostringstream os;
      os << "    [firstEventCuts] REJECT (|vz| cut)"
         << " | vz=" << std::fixed << std::setprecision(3) << m_vz
         << " | |vz|cut=" << m_vzCut
         << " | triggers={" << joinList(activeTrig, ", ") << "}";
      LOG(4, CLR_YELLOW, os.str());
    }
    return false;
  }

  // Uniform downstream behavior
  if (activeTrig.empty()) activeTrig.emplace_back("ALL");

  if (m_ppg12PhotonYieldEnabled && !m_isAuAu)
  {
    fillPPG12VertexContractQA(activeTrig, false);
  }

  m_lastReject = EventReject::None;

  if (Verbosity() >= 4)
  {
    std::ostringstream os;
    os << "    [firstEventCuts] ACCEPT"
       << " | triggers={" << joinList(activeTrig, ", ") << "}"
       << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
    if (m_useVzCut) os << " (|vz|cut=" << m_vzCut << ")";
    LOG(4, CLR_GREEN, os.str());
  }

  return true;
}


void RecoilJets::fillPPG12Fig7TriggerQA(PHCompositeNode* topNode)
{
  if (!m_ppg12Fig7TriggerDiagnostic || m_isSim || m_isAuAu) return;
  if (!out || !out->IsOpen()) return;

  auto& H = qaHistogramsByTrigger[kPPG12Fig7TriggerKey];

  auto ensureDir = [&]() -> TDirectory*
  {
    TDirectory* dir = out->GetDirectory(kPPG12Fig7TriggerKey);
    if (!dir) dir = out->mkdir(kPPG12Fig7TriggerKey);
    return dir;
  };

  auto book1D = [&](const std::string& name,
                    const std::string& title,
                    int nbins,
                    double xmin,
                    double xmax) -> TH1D*
  {
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1D*>(it->second)) return h;
      H.erase(it);
    }
    TDirectory* dir = ensureDir();
    if (!dir) return nullptr;
    TDirectory* const prevDir = gDirectory;
    dir->cd();
    TH1D* h = RJMCWeighting::RJNewTH1D(name.c_str(), title.c_str(), nbins, xmin, xmax);
    if (h)
    {
      h->SetDirectory(dir);
      h->Sumw2();
      H[name] = h;
    }
    if (prevDir) prevDir->cd();
    return h;
  };

  auto book1DVar = [&](const std::string& name,
                       const std::string& title) -> TH1D*
  {
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1D*>(it->second)) return h;
      H.erase(it);
    }
    const auto& edges = ppg12Fig7TurnonEdges();
    if (edges.size() < 2) return nullptr;
    TDirectory* dir = ensureDir();
    if (!dir) return nullptr;
    TDirectory* const prevDir = gDirectory;
    dir->cd();
    TH1D* h = RJMCWeighting::RJNewTH1D(name.c_str(), title.c_str(),
                                       static_cast<int>(edges.size()) - 1,
                                       edges.data());
    if (h)
    {
      h->SetDirectory(dir);
      h->Sumw2();
      H[name] = h;
    }
    if (prevDir) prevDir->cd();
    return h;
  };

  auto bookCounter = [&](const std::string& name,
                         const std::string& title,
                         const std::vector<std::string>& labels) -> TH1D*
  {
    TH1D* h = book1D(name, title,
                     static_cast<int>(labels.size()), 0.5,
                     static_cast<double>(labels.size()) + 0.5);
    if (h)
    {
      for (std::size_t i = 0; i < labels.size(); ++i)
      {
        h->GetXaxis()->SetBinLabel(static_cast<int>(i) + 1, labels[i].c_str());
      }
    }
    return h;
  };

  const std::vector<std::string> counterLabels = {
      "all_pp_events_seen",
      "gl1_packet_missing",
      "vz200_pass",
      "scaled10",
      "scaled10_vz200",
      "scaled10_live29_vz200",
      "scaled10_live30_vz200",
      "scaled10_live31_vz200",
      "clusters_scaled10_vz200",
      "clusters_live29_vz200",
      "clusters_live30_vz200",
      "clusters_live31_vz200",
      "clusters_eta_reject",
      "clusters_et_range_reject",
      "live10",
      "live10_vz200",
      "live10_live29_vz200",
      "live10_live30_vz200",
      "live10_live31_vz200",
      "clusters_live10_vz200",
      "clusters_live10_live29_vz200",
      "clusters_live10_live30_vz200",
      "clusters_live10_live31_vz200"
  };

  TH1D* hCounts = bookCounter("h_ppg12_fig7_event_and_cluster_counts",
                              "PPG12 Fig.7 trigger definition audit;category;count",
                              counterLabels);
  auto fillCount = [&](int labelIndex)
  {
    if (hCounts) hCounts->Fill(static_cast<double>(labelIndex));
  };

  fillCount(1);

  Gl1Packet* gl1Packet = findNode::getClass<Gl1Packet>(topNode, "GL1Packet");
  if (!gl1Packet) gl1Packet = findNode::getClass<Gl1Packet>(topNode, "14001");
  if (!gl1Packet)
  {
    fillCount(2);
    return;
  }

  const uint64_t scaledVector = static_cast<uint64_t>(gl1Packet->getScaledVector());
  const uint64_t liveVector = static_cast<uint64_t>(gl1Packet->getLiveVector());
  const bool passVz200 = std::isfinite(m_vz) && (std::fabs(m_vz) <= 200.0);
  const bool scaled10 = ((scaledVector & (1ULL << 10U)) != 0ULL);
  const bool live10 = ((liveVector & (1ULL << 10U)) != 0ULL);
  const bool live29 = ((liveVector & (1ULL << 29U)) != 0ULL);
  const bool live30 = ((liveVector & (1ULL << 30U)) != 0ULL);
  const bool live31 = ((liveVector & (1ULL << 31U)) != 0ULL);

  const int runNumber = currentRunNumber();

  TH1D* hRunSeen = book1D("h_ppg12_fig7_run_all_seen",
                          "PPG12 Fig.7 run coverage, all seen;run number;events",
                          20000, 40000.0, 60000.0);
  TH1D* hRunScaled10 = book1D("h_ppg12_fig7_run_scaled10",
                              "PPG12 Fig.7 run coverage, scaled[10];run number;events",
                              20000, 40000.0, 60000.0);
  TH1D* hRunScaled10Vz = book1D("h_ppg12_fig7_run_scaled10_vz200",
                                "PPG12 Fig.7 run coverage, scaled[10] and |vz|<200;run number;events",
                                20000, 40000.0, 60000.0);
  TH1D* hRunLive10 = book1D("h_ppg12_fig7_run_live10",
                            "PPG12 Fig.7 run coverage, live[10];run number;events",
                            20000, 40000.0, 60000.0);
  TH1D* hRunLive10Vz = book1D("h_ppg12_fig7_run_live10_vz200",
                              "PPG12 Fig.7 run coverage, live[10] and |vz|<200;run number;events",
                              20000, 40000.0, 60000.0);
  TH1D* hRunLive29 = book1D("h_ppg12_fig7_run_scaled10_live29_vz200",
                            "PPG12 Fig.7 run coverage, scaled[10] and live[29];run number;events",
                            20000, 40000.0, 60000.0);
  TH1D* hRunLive30 = book1D("h_ppg12_fig7_run_scaled10_live30_vz200",
                            "PPG12 Fig.7 run coverage, scaled[10] and live[30];run number;events",
                            20000, 40000.0, 60000.0);
  TH1D* hRunLive31 = book1D("h_ppg12_fig7_run_scaled10_live31_vz200",
                            "PPG12 Fig.7 run coverage, scaled[10] and live[31];run number;events",
                            20000, 40000.0, 60000.0);
  TH1D* hRunLive10Live29 = book1D("h_ppg12_fig7_run_live10_live29_vz200",
                                  "PPG12 Fig.7 run coverage, live[10] and live[29];run number;events",
                                  20000, 40000.0, 60000.0);
  TH1D* hRunLive10Live30 = book1D("h_ppg12_fig7_run_live10_live30_vz200",
                                  "PPG12 Fig.7 run coverage, live[10] and live[30];run number;events",
                                  20000, 40000.0, 60000.0);
  TH1D* hRunLive10Live31 = book1D("h_ppg12_fig7_run_live10_live31_vz200",
                                  "PPG12 Fig.7 run coverage, live[10] and live[31];run number;events",
                                  20000, 40000.0, 60000.0);

  if (runNumber > 0 && hRunSeen) hRunSeen->Fill(runNumber);
  if (passVz200) fillCount(3);
  if (scaled10)
  {
    fillCount(4);
    if (runNumber > 0 && hRunScaled10) hRunScaled10->Fill(runNumber);
  }
  if (live10)
  {
    fillCount(15);
    if (runNumber > 0 && hRunLive10) hRunLive10->Fill(runNumber);
  }
  if (scaled10 && passVz200)
  {
    fillCount(5);
    if (runNumber > 0 && hRunScaled10Vz) hRunScaled10Vz->Fill(runNumber);
    if (live29)
    {
      fillCount(6);
      if (runNumber > 0 && hRunLive29) hRunLive29->Fill(runNumber);
    }
    if (live30)
    {
      fillCount(7);
      if (runNumber > 0 && hRunLive30) hRunLive30->Fill(runNumber);
    }
    if (live31)
    {
      fillCount(8);
      if (runNumber > 0 && hRunLive31) hRunLive31->Fill(runNumber);
    }
  }
  if (live10 && passVz200)
  {
    fillCount(16);
    if (runNumber > 0 && hRunLive10Vz) hRunLive10Vz->Fill(runNumber);
    if (live29)
    {
      fillCount(17);
      if (runNumber > 0 && hRunLive10Live29) hRunLive10Live29->Fill(runNumber);
    }
    if (live30)
    {
      fillCount(18);
      if (runNumber > 0 && hRunLive10Live30) hRunLive10Live30->Fill(runNumber);
    }
    if (live31)
    {
      fillCount(19);
      if (runNumber > 0 && hRunLive10Live31) hRunLive10Live31->Fill(runNumber);
    }
  }

  if (TH1D* hVzAll = book1D("h_ppg12_fig7_vz_all_seen",
                            "PPG12 Fig.7 vertex distribution, all seen;vertex z [cm];events",
                            500, -250.0, 250.0))
  {
    if (std::isfinite(m_vz)) hVzAll->Fill(m_vz);
  }
  if (scaled10)
  {
    if (TH1D* hVzScaled10 = book1D("h_ppg12_fig7_vz_scaled10",
                                   "PPG12 Fig.7 vertex distribution, scaled[10];vertex z [cm];events",
                                   500, -250.0, 250.0))
    {
      if (std::isfinite(m_vz)) hVzScaled10->Fill(m_vz);
    }
    if (live30)
    {
      if (TH1D* hVzLive30 = book1D("h_ppg12_fig7_vz_scaled10_live30",
                                   "PPG12 Fig.7 vertex distribution, scaled[10] and live[30];vertex z [cm];events",
                                   500, -250.0, 250.0))
      {
        if (std::isfinite(m_vz)) hVzLive30->Fill(m_vz);
      }
    }
  }

  TH1D* hScaledBits = book1D("h_ppg12_fig7_scaled_bit_occupancy_vz200",
                             "PPG12 Fig.7 scaled bit occupancy after |vz|<200;GL1 bit;events",
                             64, -0.5, 63.5);
  TH1D* hLiveBits = book1D("h_ppg12_fig7_live_bit_occupancy_scaled10_vz200",
                           "PPG12 Fig.7 live bit occupancy for scaled[10] events after |vz|<200;GL1 bit;events",
                           64, -0.5, 63.5);
  TH1D* hLiveBitsLive10 = book1D("h_ppg12_fig7_live_bit_occupancy_live10_vz200",
                                 "PPG12 Fig.7 live bit occupancy for live[10] events after |vz|<200;GL1 bit;events",
                                 64, -0.5, 63.5);
  if (passVz200 && hScaledBits)
  {
    for (int bit = 0; bit < 64; ++bit)
    {
      if ((scaledVector & (1ULL << static_cast<unsigned>(bit))) != 0ULL)
      {
        hScaledBits->Fill(bit);
      }
    }
  }
  if (passVz200 && scaled10 && hLiveBits)
  {
    for (int bit = 0; bit < 64; ++bit)
    {
      if ((liveVector & (1ULL << static_cast<unsigned>(bit))) != 0ULL)
      {
        hLiveBits->Fill(bit);
      }
    }
  }
  if (passVz200 && live10 && hLiveBitsLive10)
  {
    for (int bit = 0; bit < 64; ++bit)
    {
      if ((liveVector & (1ULL << static_cast<unsigned>(bit))) != 0ULL)
      {
        hLiveBitsLive10->Fill(bit);
      }
    }
  }

  if (!passVz200 || (!scaled10 && !live10)) return;

  TH1D* hDen = book1DVar("h_ppg12_fig7_cluster_et_scaled10",
                         "PPG12 Fig.7 denominator: scaled[10];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive29Et = book1DVar("h_ppg12_fig7_cluster_et_scaled10_live29",
                              "PPG12 Fig.7 numerator: scaled[10] and live[29];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive30Et = book1DVar("h_ppg12_fig7_cluster_et_scaled10_live30",
                              "PPG12 Fig.7 numerator: scaled[10] and live[30];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive31Et = book1DVar("h_ppg12_fig7_cluster_et_scaled10_live31",
                              "PPG12 Fig.7 numerator: scaled[10] and live[31];E_{T}^{cluster} [GeV];clusters");
  TH1D* hTot29 = book1DVar("h_ppg12_fig7_eff_total_bit29",
                           "PPG12 Fig.7 TEff total for bit 29;E_{T}^{cluster} [GeV];clusters");
  TH1D* hPass29 = book1DVar("h_ppg12_fig7_eff_pass_bit29",
                            "PPG12 Fig.7 TEff pass for bit 29;E_{T}^{cluster} [GeV];clusters");
  TH1D* hTot30 = book1DVar("h_ppg12_fig7_eff_total_bit30",
                           "PPG12 Fig.7 TEff total for bit 30;E_{T}^{cluster} [GeV];clusters");
  TH1D* hPass30 = book1DVar("h_ppg12_fig7_eff_pass_bit30",
                            "PPG12 Fig.7 TEff pass for bit 30;E_{T}^{cluster} [GeV];clusters");
  TH1D* hTot31 = book1DVar("h_ppg12_fig7_eff_total_bit31",
                           "PPG12 Fig.7 TEff total for bit 31;E_{T}^{cluster} [GeV];clusters");
  TH1D* hPass31 = book1DVar("h_ppg12_fig7_eff_pass_bit31",
                            "PPG12 Fig.7 TEff pass for bit 31;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Den = book1DVar("h_ppg12_fig7_cluster_et_live10",
                               "PPG12 Fig.7 denominator: live[10];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Live29Et = book1DVar("h_ppg12_fig7_cluster_et_live10_live29",
                                    "PPG12 Fig.7 numerator: live[10] and live[29];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Live30Et = book1DVar("h_ppg12_fig7_cluster_et_live10_live30",
                                    "PPG12 Fig.7 numerator: live[10] and live[30];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Live31Et = book1DVar("h_ppg12_fig7_cluster_et_live10_live31",
                                    "PPG12 Fig.7 numerator: live[10] and live[31];E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Tot29 = book1DVar("h_ppg12_fig7_eff_total_live10_bit29",
                                 "PPG12 Fig.7 TEff total for bit 29 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Pass29 = book1DVar("h_ppg12_fig7_eff_pass_live10_bit29",
                                  "PPG12 Fig.7 TEff pass for bit 29 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Tot30 = book1DVar("h_ppg12_fig7_eff_total_live10_bit30",
                                 "PPG12 Fig.7 TEff total for bit 30 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Pass30 = book1DVar("h_ppg12_fig7_eff_pass_live10_bit30",
                                  "PPG12 Fig.7 TEff pass for bit 30 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Tot31 = book1DVar("h_ppg12_fig7_eff_total_live10_bit31",
                                 "PPG12 Fig.7 TEff total for bit 31 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");
  TH1D* hLive10Pass31 = book1DVar("h_ppg12_fig7_eff_pass_live10_bit31",
                                  "PPG12 Fig.7 TEff pass for bit 31 with live[10] denominator;E_{T}^{cluster} [GeV];clusters");

  if (!m_clus) return;

  const auto& edges = ppg12Fig7TurnonEdges();
  const double etMin = edges.front();
  const double etMax = edges.back();
  const CLHEP::Hep3Vector vertex(0.0, 0.0, m_vz);
  const auto range = m_clus->getClusters();
  for (auto it = range.first; it != range.second; ++it)
  {
    const RawCluster* cl = it->second;
    if (!cl) continue;
    const double eta = RawClusterUtility::GetPseudorapidity(*cl, vertex);
    if (!std::isfinite(eta) || std::fabs(eta) >= 0.7)
    {
      fillCount(13);
      continue;
    }
    const double energy = cl->get_energy();
    const double et = std::isfinite(eta) ? energy / std::cosh(eta)
                                         : std::numeric_limits<double>::quiet_NaN();
    if (!std::isfinite(energy) || energy <= 0.0 || !std::isfinite(et) || et < etMin || et >= etMax)
    {
      fillCount(14);
      continue;
    }

    if (scaled10)
    {
      if (hDen) hDen->Fill(et);
      if (hTot29) hTot29->Fill(et);
      if (hTot30) hTot30->Fill(et);
      if (hTot31) hTot31->Fill(et);
      fillCount(9);

      if (live29)
      {
        if (hLive29Et) hLive29Et->Fill(et);
        if (hPass29) hPass29->Fill(et);
        fillCount(10);
      }
      if (live30)
      {
        if (hLive30Et) hLive30Et->Fill(et);
        if (hPass30) hPass30->Fill(et);
        fillCount(11);
      }
      if (live31)
      {
        if (hLive31Et) hLive31Et->Fill(et);
        if (hPass31) hPass31->Fill(et);
        fillCount(12);
      }
    }

    if (live10)
    {
      if (hLive10Den) hLive10Den->Fill(et);
      if (hLive10Tot29) hLive10Tot29->Fill(et);
      if (hLive10Tot30) hLive10Tot30->Fill(et);
      if (hLive10Tot31) hLive10Tot31->Fill(et);
      fillCount(20);

      if (live29)
      {
        if (hLive10Live29Et) hLive10Live29Et->Fill(et);
        if (hLive10Pass29) hLive10Pass29->Fill(et);
        fillCount(21);
      }
      if (live30)
      {
        if (hLive10Live30Et) hLive10Live30Et->Fill(et);
        if (hLive10Pass30) hLive10Pass30->Fill(et);
        fillCount(22);
      }
      if (live31)
      {
        if (hLive10Live31Et) hLive10Live31Et->Fill(et);
        if (hLive10Pass31) hLive10Pass31->Fill(et);
        fillCount(23);
      }
    }
  }
}




bool RecoilJets::initReplayFoundation()
{
  m_replayFoundationEnabled = RJReplayRuntimeV1::envEnabled("RJ_REPLAY_FOUNDATION_V1");
  const bool multiviewTrainingEnabled =
      RJReplayRuntimeV1::envEnabled("RJ_THE134_MULTIVIEW_TRAINING_V1");
  m_the134MultiviewSidecarOnly =
      RJReplayRuntimeV1::envEnabled("RJ_THE134_MULTIVIEW_SIDECAR_ONLY_V1");
  m_the134FastExtraction =
      RJReplayRuntimeV1::envEnabled("RJ_THE134_FAST_EXTRACTION_V1");
  if (multiviewTrainingEnabled && !m_replayFoundationEnabled)
  {
    LOG(0, CLR_RED, "[RJPhotonTrainingViewV1][FATAL] the multiview training artifact requires RJ_REPLAY_FOUNDATION_V1=1");
    return false;
  }
  if (m_the134MultiviewSidecarOnly &&
      (!m_replayFoundationEnabled || !multiviewTrainingEnabled ||
       !m_ppPhotonIDExtractOnly || !m_ppPhotonIDTrainingTreeEnabled ||
       m_isAuAu))
  {
    LOG(0, CLR_RED,
        "[RJPhotonTrainingViewV1][FATAL] "
        "RJ_THE134_MULTIVIEW_SIDECAR_ONLY_V1=1 requires p+p replay, "
        "multiview training, extract-only mode, and the legacy training tree");
    return false;
  }
  if (m_the134FastExtraction && !m_the134MultiviewSidecarOnly)
  {
    LOG(0, CLR_RED,
        "[RJPhotonTrainingViewV1][FATAL] "
        "RJ_THE134_FAST_EXTRACTION_V1=1 requires the complete "
        "RJ_THE134_MULTIVIEW_SIDECAR_ONLY_V1 extraction contract");
    return false;
  }
  if (!m_replayFoundationEnabled) return true;

  const std::string lane = RJReplayRuntimeV1::env("RJ_REPLAY_LANE");
  const std::string dataset = RJReplayRuntimeV1::env("RJ_REPLAY_DATASET");
  const std::string sample = RJReplayRuntimeV1::env("RJ_REPLAY_SAMPLE");
  const std::string manifestHash = RJReplayRuntimeV1::env("RJ_REPLAY_SOURCE_MANIFEST_SHA256");
  const std::string analysisJetNodeSuffix =
      RJReplayRuntimeV1::env("RJ_ANALYSIS_JET_NODE_SUFFIX");
  if (lane.empty() || dataset.empty() || sample.empty() || manifestHash.empty() ||
      analysisJetNodeSuffix.empty() ||
      !RJReplayFoundationV1::validAnalysisJetNodeSuffix(analysisJetNodeSuffix))
  {
    LOG(0, CLR_RED, "[ReplayFoundationV1][FATAL] lane, dataset, sample, source-manifest hash, and a valid analysis-owned jet-node suffix are required");
    return false;
  }

  RJReplayFoundationV1::SourceOccurrenceRow source;
  source.lane = lane;
  source.dataset = dataset;
  source.sample = sample;
  source.period = RJReplayRuntimeV1::env("RJ_REPLAY_PERIOD");
  source.si_di_role = RJReplayRuntimeV1::env("RJ_REPLAY_SI_DI_ROLE");
  source.ownership_state = RJReplayRuntimeV1::env("RJ_REPLAY_OWNERSHIP_STATE");
  source.run = RJReplayRuntimeV1::envInt("RJ_REPLAY_RUN", 0);
  source.segment = RJReplayRuntimeV1::envInt("RJ_REPLAY_SEGMENT", 0);
  source.input_uri_hash = RJReplayRuntimeV1::env("RJ_REPLAY_INPUT_URI_SHA256");
  source.input_file_sha256 = RJReplayRuntimeV1::env("RJ_REPLAY_INPUT_FILE_SHA256");
  source.source_manifest_sha256 = manifestHash;
  source.id = RJReplayFoundationV1::makeScopedIdentity(
      RJReplayFoundationV1::CompactIdentityDomain::SOURCE,0,0);

  m_replayRuntime = std::make_unique<RJReplayRuntimeV1::Runtime>();
  std::string error;
  const bool replayInitialized = m_the134MultiviewSidecarOnly
      ? m_replayRuntime->initialize(
            out,source,RJReplayFoundationV1::WriterMode::VALIDATE_ONLY,&error)
      : m_replayRuntime->initialize(out,source,&error);
  if (!replayInitialized)
  {
    LOG(0, CLR_RED, "[ReplayFoundationV1][FATAL] initialization failed: " << error);
    m_replayRuntime.reset();
    return false;
  }
  // DATA counters are captured before sparse event/candidate retention. SIM
  // GL1 words are not measured DATA exposure and have no scaler companion.
  if (!m_isSim)
  {
    m_triggerScalerWriter=std::make_unique<RJTriggerScalersV1::Writer>();
    if (!m_triggerScalerWriter->initialize(out,source.run,source.segment,
                                           source.input_uri_hash,manifestHash))
    {
      LOG(0, CLR_RED, "[RJTriggerScalersV1][FATAL] missing source binding");
      return false;
    }
    m_triggerRunInfoWriter=std::make_unique<RJTriggerRunInfoV1::Writer>();
    if(!m_triggerRunInfoWriter->initialize(out,source.run,source.segment,
                                          source.input_uri_hash,manifestHash)) return false;
  }
  if (multiviewTrainingEnabled)
  {
    if (!m_ppPhotonIDTrainingTreeEnabled || m_isAuAu)
    {
      LOG(0, CLR_RED, "[RJPhotonTrainingViewV1][FATAL] p+p multiview extraction requires the legacy p+p photon-ID training tree");
      return false;
    }
    const std::string trainingPath =
        RJReplayRuntimeV1::env("RJ_THE134_MULTIVIEW_TRAINING_FILE");
    if (trainingPath.empty() || trainingPath == Outfile)
    {
      LOG(0, CLR_RED, "[RJPhotonTrainingViewV1][FATAL] RJ_THE134_MULTIVIEW_TRAINING_FILE must name a separate ROOT artifact");
      return false;
    }
    m_photonTrainingViewRuntime =
        std::make_unique<RJPhotonTrainingViewV1::Runtime>();
    if (!m_photonTrainingViewRuntime->initialize(
            trainingPath,RJPhotonTrainingViewV1::kSystemPP,source,
            RJReplayRuntimeV1::env("RJ_REPLAY_CONFIG_SHA256"),
            RJReplayRuntimeV1::env("RJ_REPLAY_CODE_SHA256"),&error))
    {
      LOG(0, CLR_RED, "[RJPhotonTrainingViewV1][FATAL] initialization failed: " << error);
      m_photonTrainingViewRuntime.reset();
      return false;
    }
    LOG(1, CLR_GREEN, "[RJPhotonTrainingViewV1] enabled at " << trainingPath);
  }
  LOG(1, CLR_GREEN, "[ReplayFoundationV1] enabled for lane=" << lane << " sample=" << sample);
  return true;
}

bool RecoilJets::captureReplayTrigger(PHCompositeNode* topNode)
{
  m_replayTriggerSnapshotId=0;
  auto* packet=findNode::getClass<Gl1Packet>(topNode,"GL1Packet");
  if(!packet) packet=findNode::getClass<Gl1Packet>(topNode,"14001");
  m_replayGl1Decisions=RJGl1TriggerContract::read(packet,m_isSim);
  if(!m_replayFoundationEnabled || m_isSim) return true;
  const auto* info=findNode::getClass<TriggerRunInfo>(topNode,"TriggerRunInfo");
  if(!m_triggerScalerWriter || !m_triggerRunInfoWriter ||
     !m_triggerScalerWriter->observe(RJGl1ScalerContract::read(packet),event_count,
                                    m_replayTriggerSnapshotId) ||
     !m_triggerRunInfoWriter->observe(info))
  {
    m_replayWriteFailed=true;
    LOG(0, CLR_RED, "[DirectGL1][FATAL] source-bound trigger capture failed");
    return false;
  }
  return true;
}

void RecoilJets::writeReplayFoundationEvent(PHCompositeNode* topNode, int terminalStatus)
{
  if (!m_replayFoundationEnabled || !m_replayRuntime || m_replayWriteFailed) return;

  using namespace RJReplayFoundationV1;
  RJReplayRuntimeV1::EventBundle bundle;
  captureTruthVertices(bundle.event,m_isSim,
      findNode::getClass<PHG4TruthInfoContainer>(topNode,"G4TruthInfo"));
  // Version 1 describes raw capture, not an AuAu calibration for pp. Do not
  // assign an AuAu MB/native centrality decision; missing nodes stay explicit.
  auto* replayPmts=findNode::getClass<MbdPmtContainer>(topNode,"MbdPmtContainer");
  auto* replayMbdOut=findNode::getClass<MbdOut>(topNode,"MbdOut");
  RJCentralityReplayV1::capture(bundle.event,replayPmts,replayMbdOut,
      static_cast<MinimumBiasInfo*>(nullptr));
  RJCollaboratorMbdV1::capture(bundle.event,replayPmts,
      findNode::getClass<MbdGeom>(topNode,"MbdGeom"));
  bundle.event.trigger_scaler_snapshot_id=m_replayTriggerSnapshotId;
  Schema10DataRetentionContractV1::Decision retentionDecision;
  bool retentionDecisionRecorded = false;
  const bool replayTrace = RJReplayRuntimeV1::envEnabled("RJ_REPLAY_TRACE");
  auto replayMark = [&](const char* stage)
  {
    if (replayTrace)
      std::cerr << "RJ_REPLAY_BUILD_TRACE event=" << event_count
                << " stage=" << stage << std::endl;
  };
  replayMark("begin");
  const std::uint64_t eventScope=event_count>=0
      ? static_cast<std::uint64_t>(event_count):0ULL;
  std::uint64_t candidateIdentityOrdinal=0,jetIdentityOrdinal=0,
      pairIdentityOrdinal=0,truthPhotonIdentityOrdinal=0,
      truthJetIdentityOrdinal=0,linkIdentityOrdinal=0,
      isolationWitnessIdentityOrdinal=0,occurrenceIdentityOrdinal=0;
  bundle.event.id = makeScopedIdentity(
      CompactIdentityDomain::EVENT,0,eventScope);
  bundle.event.run = RJReplayRuntimeV1::envInt("RJ_REPLAY_RUN", static_cast<int>(currentRunNumber()));
  bundle.event.event_sequence = event_count;
  capturePhysicalEventSequence(bundle.event,
      findNode::getClass<EventHeader>(topNode,"EventHeader"));
  bundle.event.vertex_z = m_vz;
  bundle.event.centrality = m_isAuAu ? static_cast<double>(m_centBin) : -1.0;
  bundle.event.event_weight = m_mcEventWeight;
  bundle.event.truth_vertex_z = m_truthVz;
  bundle.event.truth_mb_vertex_z = m_truthVzMB;
  bundle.event.nodes_ready = m_replayNodesReady ? 1 : 0;
  bundle.event.reco_vertex_valid = m_collaboratorRecoVertexValid ? 1 : 0;
  if (!m_collaboratorRecoVertexValid)
    bundle.event.vertex_z = std::numeric_limits<double>::quiet_NaN();
  bundle.event.legacy_event_weight = bundle.event.event_weight;
  // DATA producer factors are unity, not exposure. Mere node availability
  // does not certify SIM normalization or complete truth denominators.
  bundle.event.sample_weight_valid = m_isSim ? -1 : 1;
  bundle.event.vertex_weight_valid = m_isSim ? -1 : 1;
  bundle.event.truth_denominator_complete = m_isSim ? 0 : 1;
  bundle.event.truth_photon_inventory.capture_state = m_isSim ? 0 : -1;
  bundle.event.ppg12_weight_active_state = m_ppg12SimWeightActive ? 1 : 0;
  bundle.event.ppg12_weight_lane_component_code = m_ppg12SimWeightLaneComponentCode;
  const auto& fullFillCounts = RJMCWeighting::FullFillCounts();
  const auto& rawFillCounts = RJMCWeighting::RawFillCounts();
  for (std::size_t code = 1; code < fullFillCounts.size(); ++code)
  {
    if (fullFillCounts[code] >= m_replayFullFillCountsAtEventStart[code])
    {
      bundle.event.ppg12_weighted_fill_count_by_code[code] = static_cast<std::int64_t>(
          fullFillCounts[code] - m_replayFullFillCountsAtEventStart[code]);
      bundle.event.ppg12_weighted_fill_count +=
          bundle.event.ppg12_weighted_fill_count_by_code[code];
    }
    if (rawFillCounts[code] >= m_replayRawFillCountsAtEventStart[code])
    {
      bundle.event.ppg12_raw_fill_count_by_code[code] = static_cast<std::int64_t>(
          rawFillCounts[code] - m_replayRawFillCountsAtEventStart[code]);
      bundle.event.ppg12_raw_fill_count +=
          bundle.event.ppg12_raw_fill_count_by_code[code];
    }
  }
  bundle.event.terminal_status = terminalStatus;
  RJGl1TriggerContract::capture(bundle.event,m_replayGl1Decisions);

  // Preserve the exact raw-cluster maximum used by the existing data-only
  // do-not-scale trigger histograms.  This is a selection-neutral observable:
  // the direct histogram keeps the same run, vertex, and GL1 gates.
  bundle.event.max_cluster_energy = 0.0;
  auto retainMaxClusterEnergy = [&](const auto* clusters)
  {
    if (!clusters) return;
    const auto range = clusters->getClusters();
    for (auto it = range.first; it != range.second; ++it)
    {
      const RawCluster* cluster = it->second;
      if (!cluster) continue;
      const double energy = cluster->get_energy();
      if (!std::isfinite(energy) || energy < 1.0) continue;
      bundle.event.max_cluster_energy =
          std::max(bundle.event.max_cluster_energy, energy);
    }
  };
  if (m_clus) retainMaxClusterEnergy(m_clus);
  else if (m_photons) retainMaxClusterEnergy(m_photons);

  std::vector<std::pair<Identity128,std::array<double,3>>> recoKinematics;
  std::vector<JetMatchObject> recoJetKinematics;
  if (m_replayNodesReady && m_photons &&
      m_replayRuntime->captureObjectDomain(m_isSim, bundle.event.vertex_z))
  {
    const std::string modelHash = RJReplayRuntimeV1::env("RJ_REPLAY_MODEL_SHA256");
    const std::string modelScoreName = RJReplayRuntimeV1::env("RJ_REPLAY_MODEL_SCORE_NAME").empty()
        ? "tight_bdt_score" : RJReplayRuntimeV1::env("RJ_REPLAY_MODEL_SCORE_NAME");
    const std::string referenceHash = RJReplayRuntimeV1::env("RJ_REPLAY_REFERENCE_MODEL_SHA256");
    const std::string referenceScoreName = RJReplayRuntimeV1::env("RJ_REPLAY_REFERENCE_SCORE_NAME").empty()
        ? "ppg12_reference_bdt_score" : RJReplayRuntimeV1::env("RJ_REPLAY_REFERENCE_SCORE_NAME");
    const std::array<double,9> ptEdges{{15,17,19,21,23,25,28,32,35}};
    auto thresholdList = [](const std::string& text)
    {
      std::vector<double> values;
      std::istringstream input(text);
      std::string token;
      while (std::getline(input, token, ','))
      {
        try { values.push_back(std::stod(token)); }
        catch (...) { values.clear(); break; }
      }
      return values;
    };
    const auto wp70 = thresholdList(RJReplayRuntimeV1::env("RJ_REPLAY_WP70_BINS"));
    const auto wp80 = thresholdList(RJReplayRuntimeV1::env("RJ_REPLAY_WP80_BINS"));
    const auto wp90 = thresholdList(RJReplayRuntimeV1::env("RJ_REPLAY_WP90_BINS"));
    auto wpAt = [&](const std::vector<double>& values, double pt)
    {
      if (values.size() != 8) return std::numeric_limits<double>::quiet_NaN();
      for (std::size_t i=0;i+1<ptEdges.size();++i) if (pt>=ptEdges[i] && pt<ptEdges[i+1]) return values[i];
      return std::numeric_limits<double>::quiet_NaN();
    };

    TruthSignalPhotonMap replayTruthSignalByTrackId;
    std::unique_ptr<CaloRawClusterEval> replayClusterEval;
    bool replayTruthClassificationReady = false;
    auto replayTruthEvaluatorMode=RJDominantTruthWitnessV1::UNAVAILABLE;
    if (m_isSim)
    {
      replayTruthSignalByTrackId = buildPPG12TruthSignalPhotonMap(topNode);
      replayClusterEval = std::make_unique<CaloRawClusterEval>(topNode, "CEMC");
      replayClusterEval->set_usetowerinfo(true);
      replayTruthEvaluatorMode=RJDominantTruthWitnessV1::TOWERINFO;
      replayClusterEval->next_event(topNode);
      if (!replayClusterEval->has_reduced_node_pointers())
      {
        replayClusterEval->set_usetowerinfo(false);
        replayTruthEvaluatorMode=RJDominantTruthWitnessV1::LEGACY_RAWTOWER;
        replayClusterEval->next_event(topNode);
      }
      replayTruthClassificationReady = replayClusterEval->has_reduced_node_pointers();
    }

    if (!m_isAuAu && m_ppg12PhotonYieldEnabled)
    {
      bundle.event.ppg12_source_arbitration_state = 1;
      const auto sourceRange = m_photons->getClusters();
      int sourceOrdinal = 0;
      for (auto sourceIt=sourceRange.first;
           sourceIt!=sourceRange.second; ++sourceIt,++sourceOrdinal)
      {
        const auto* sourcePhoton =
            dynamic_cast<const PhotonClusterv1*>(sourceIt->second);
        if (!sourcePhoton || ppg12PhotonYieldTowerMasked(sourcePhoton)) continue;
        double sourceEt =
            sourcePhoton->get_shower_shape_parameter("cluster_pt");
        sourceEt = ppg12PhotonYieldClusterEtForCuts(sourceEt,sourceOrdinal);
        if (!std::isfinite(sourceEt) || sourceEt < 5.0) continue;
        if (std::isfinite(bundle.event.ppg12_leading_source_et) &&
            sourceEt <= bundle.event.ppg12_leading_source_et)
          continue;
        bundle.event.ppg12_leading_source_cluster_key =
            static_cast<std::uint32_t>(sourceIt->first);
        bundle.event.ppg12_leading_source_encounter_ordinal = sourceOrdinal;
        bundle.event.ppg12_leading_source_et = sourceEt;
        bundle.event.ppg12_leading_source_eta =
            sourcePhoton->get_shower_shape_parameter("cluster_eta");
        bundle.event.ppg12_leading_source_phi =
            sourcePhoton->get_shower_shape_parameter("cluster_phi");
      }
    }

    const auto range = m_photons->getClusters();
    int ordinal = 0;
    for (auto it=range.first; it!=range.second; ++it,++ordinal)
    {
      const auto* photon = dynamic_cast<const PhotonClusterv1*>(it->second);
      if (!photon) continue;
      const double pt = photon->get_shower_shape_parameter("cluster_pt");
      const double eta = photon->get_shower_shape_parameter("cluster_eta");
      const double phi = photon->get_shower_shape_parameter("cluster_phi");
      if (!std::isfinite(pt)||!std::isfinite(eta)||!std::isfinite(phi)||pt<5.0||pt>=40.0||std::fabs(eta)>=0.7) continue;
      struct FactorialShapeState
      {
        bool valid=false;
        double raw_eta=std::numeric_limits<double>::quiet_NaN();
        double raw_phi=std::numeric_limits<double>::quiet_NaN();
        std::array<double,4> native_et{{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::quiet_NaN()}};
      };
      auto factorialShape=[&](double floor)
      {
        FactorialShapeState result;
        const auto values=photon->get_shower_shapes(floor);
        if(values.size()<6)return result;
        result.raw_eta=static_cast<double>(values[4])+0.5;
        result.raw_phi=static_cast<double>(values[5])+0.5;
        for(std::size_t i=0;i<4;++i)result.native_et[i]=values[i];
        result.valid=std::isfinite(result.raw_eta)&&std::isfinite(result.raw_phi)&&
            std::all_of(result.native_et.begin(),result.native_et.end(),[](double item){return std::isfinite(item);});
        return result;
      };
      const auto shape0=factorialShape(0.0);
      const auto shape70=factorialShape(0.070);
      const SSVars v = makeSSFromPhoton(photon,pt);
      PhotonCandidateRow candidate;
      candidate.id = makeScopedIdentity(
          CompactIdentityDomain::CANDIDATE,eventScope,candidateIdentityOrdinal++);
      candidate.event_id = bundle.event.id;
      candidate.native_cluster_key = static_cast<std::uint32_t>(it->first);
      candidate.encounter_ordinal = ordinal;
      candidate.rank_keys = {pt,-std::fabs(eta),static_cast<double>(ordinal)};
      candidate.cluster_et=pt; candidate.eta=eta; candidate.phi=phi;
      candidate.native_weta_cogx=v.weta_cogx;
      candidate.native_wphi_cogx=v.wphi_cogx;
      candidate.native_weta33_cogx=v.weta33_cogx;
      candidate.native_wphi33_cogx=v.wphi33_cogx;
      candidate.native_weta35_cogx=v.weta35_cogx;
      candidate.native_wphi53_cogx=v.wphi53_cogx;
      candidate.native_et1=v.et1;
      candidate.native_e11_over_e33=v.e11_over_e33;
      candidate.native_e32_over_e35=v.e32_over_e35;
      candidate.npb_score=v.npb_score;
      candidate.reference_preselection_state=
          v.e11_over_e33<PRE_E11E33_MAX&&
          v.et1>PRE_ET1_MIN&&v.et1<PRE_ET1_MAX&&
          v.e32_over_e35>PRE_E32E35_MIN&&v.e32_over_e35<PRE_E32E35_MAX&&
          v.weta_cogx<PRE_WETA_MAX;
      candidate.active_preselection_state=passesPhotonPreselection(v);
      candidate.ppg12_tower_mask_state =
          (!m_isAuAu && m_ppg12PhotonYieldEnabled)
              ? (ppg12PhotonYieldTowerMasked(photon) ? 1 : 0)
              : -1;
      candidate.ppg12_source_eligible_state =
          candidate.ppg12_tower_mask_state == 0 ? 1 : 0;
      candidate.dominant_truth=RJDominantTruthWitnessV1::capture(
          m_isSim,replayClusterEval.get(),const_cast<PhotonClusterv1*>(photon),
          m_truthInfo,replayTruthEvaluatorMode);
      if (replayTruthClassificationReady)
      {
        TruthSignalPhotonInfo matchedTruth;
        int clusterTruthTrackId = -1;
        float energyContribution = std::numeric_limits<float>::lowest();
        const bool matched = classifyRecoPhotonWithPPG12TruthTrack(
            photon, *replayClusterEval, replayTruthSignalByTrackId,
            matchedTruth, clusterTruthTrackId, energyContribution);
        candidate.truth_signal_match_state = matched ? 1 : 0;
        candidate.truth_signal_match_barcode = matched ? matchedTruth.barcode : -1;
      }
      ShowerFeatureViewRow runtimeFeatureView;
      runtimeFeatureView.weta_cogx=v.weta_cogx;
      runtimeFeatureView.wphi_cogx=v.wphi_cogx;
      runtimeFeatureView.weta33_cogx=v.weta33_cogx;
      runtimeFeatureView.wphi33_cogx=v.wphi33_cogx;
      runtimeFeatureView.e11_over_e33=v.e11_over_e33;
      runtimeFeatureView.native_et1=v.et1;
      runtimeFeatureView.native_et2=v.et2;
      runtimeFeatureView.native_et3=v.et3;
      runtimeFeatureView.native_et4=v.et4;
      runtimeFeatureView.e32_over_e35=v.e32_over_e35;
      candidate.ordered_features=RJShowerFactorialV1::modelFeatures(
          runtimeFeatureView,pt,m_vz,eta,-1.0,false);
      if(shape70.valid)candidate.shower_definition_views={"H70","G70","O70","R70"};
      if(shape0.valid)candidate.shower_definition_views.insert(candidate.shower_definition_views.end(),{"H0","G0","O0"});
      candidate.finite_feature_state = std::all_of(candidate.ordered_features.begin(),candidate.ordered_features.end(),[](double x){return std::isfinite(x);}) ? 1:0;
      candidate.below15_retention_state = pt<15.0 ? 1:0;
      candidate.preselection_bitmask = 1ULL|2ULL|4ULL|(candidate.finite_feature_state?8ULL:0ULL);
      bundle.candidates.push_back(candidate);
      recoKinematics.push_back({candidate.id,{pt,eta,phi}});
      replayMark("candidate_retained");

      auto appendModel = [&](const std::string& hash,const std::string& scoreName,bool isReference)
      {
        if (hash.empty()) return;
        ModelEvaluationRow model;
        model.candidate_id=candidate.id; model.model_id=identityFromSha256(hash); model.model_sha256=hash;
        model.shower_definition_id=RJReplayRuntimeV1::env(isReference?"RJ_REPLAY_REFERENCE_MODEL_SHOWER_DEFINITION":"RJ_REPLAY_MODEL_SHOWER_DEFINITION");
        if(!model.shower_definition_id.empty())
        {
          try{model.shower_semantic_sha256=RJShowerFactorialV1::semanticSha256(RJShowerFactorialV1::definition(model.shower_definition_id));}
          catch(const std::exception&){model.shower_semantic_sha256.clear();}
        }
        model.ordered_input_witnesses.assign(candidate.ordered_features.begin(),candidate.ordered_features.end());
        model.raw_score=photon->get_shower_shape_parameter(scoreName);
        model.finite_score=std::isfinite(model.raw_score) ? 1:0;
        if (!candidate.finite_feature_state) model.applicability_state=static_cast<int>(ModelApplicability::INPUT_INVALID);
        else if (pt>=15.0&&pt<35.0) model.applicability_state=static_cast<int>(ModelApplicability::VALIDATED_DOMAIN);
        else model.applicability_state=static_cast<int>(ModelApplicability::DIAGNOSTIC_EXTRAPOLATION);
        if (!isReference && model.applicability_state==static_cast<int>(ModelApplicability::VALIDATED_DOMAIN))
        {
          model.wp70=wpAt(wp70,pt); model.wp80=wpAt(wp80,pt); model.wp90=wpAt(wp90,pt);
          model.delta_wp70=model.raw_score-model.wp70; model.delta_wp80=model.raw_score-model.wp80; model.delta_wp90=model.raw_score-model.wp90;
        }
        bundle.models.push_back(model);
      };
      appendModel(modelHash,modelScoreName,false);
      if (!referenceHash.empty() && referenceHash == modelHash)
      {
        // The harmonized p+p lane intentionally maps the current and PPG12
        // reference score names to the same immutable model artifact.  The
        // normalized model table is keyed by candidate plus model identity,
        // so serializing that artifact twice is a duplicate row, not a second
        // model evaluation.  Require the two score aliases to agree before
        // retaining the single canonical row.
        const double modelScore = photon->get_shower_shape_parameter(modelScoreName);
        const double referenceScore = photon->get_shower_shape_parameter(referenceScoreName);
        const bool scoresAgree =
            (std::isnan(modelScore) && std::isnan(referenceScore)) ||
            modelScore == referenceScore;
        if (!scoresAgree)
        {
          m_replayWriteFailed=true;
          LOG(0,CLR_RED,
              "[ReplayFoundationV1][FATAL] identical model hashes carry "
              "different current/reference score witnesses");
          return;
        }
      }
      else
      {
        appendModel(referenceHash,referenceScoreName,true);
      }
      replayMark("candidate_models_built");

      auto* cemcTowers=findNode::getClass<TowerInfoContainer>(topNode,"TOWERINFO_CALIB_CEMC");
      std::vector<ShowerCellRow> candidateCells;
      std::vector<ShowerFeatureViewRow> candidateViews;
      if (cemcTowers && (shape0.valid||shape70.valid))
      {
        std::map<std::pair<int,int>,int> gridCells;
        auto addGrid=[&](const FactorialShapeState& state,int bit)
        {
          if(!state.valid)return;
          const int centerEta=static_cast<int>(std::floor(state.raw_eta));
          int centerPhi=static_cast<int>(std::floor(state.raw_phi));
          while(centerPhi<0)centerPhi+=256;
          while(centerPhi>=256)centerPhi-=256;
          for(int de=-3;de<=3;++de)for(int dp=-3;dp<=3;++dp)
          {
            const int towerEta=centerEta+de;
            const int towerPhi=(centerPhi+dp+256)%256;
            if(towerEta<0||towerEta>=96)continue;
            gridCells[{towerEta,towerPhi}]|=bit;
          }
        };
        addGrid(shape0,1);addGrid(shape70,2);
        const auto& rawTowerMap=photon->get_towermap();
        // RawClusterv1::get_shower_shapes derives its maximum tower,
        // thresholded denominator, centroid, and native et1-et4 from the
        // complete RawCluster TowerMap, not only the 7x7 rectangular-sum
        // neighborhood.  Retain every owned map cell so an offline validator
        // can reproduce that authority independently.  A zero grid bit means
        // the cell is provenance-only for native-shape replay; buildView()
        // still excludes it from the frozen 7x7 sums and moments.
        for(const auto& rawItem:rawTowerMap)
        {
          const int rawEta=RawTowerDefs::decode_index1(rawItem.first);
          int rawPhi=RawTowerDefs::decode_index2(rawItem.first);
          while(rawPhi<0)rawPhi+=256;
          while(rawPhi>=256)rawPhi-=256;
          if(rawEta<0||rawEta>=96)continue;
          gridCells.try_emplace({rawEta,rawPhi},0);
        }
        const int nominalCenterEta=static_cast<int>(std::floor(shape70.valid?shape70.raw_eta:shape0.raw_eta));
        int nominalCenterPhi=static_cast<int>(std::floor(shape70.valid?shape70.raw_phi:shape0.raw_phi));
        while(nominalCenterPhi<0)nominalCenterPhi+=256;
        while(nominalCenterPhi>=256)nominalCenterPhi-=256;
        for(const auto& item:gridCells)
        {
          const int ie=item.first.first,ip=item.first.second;
          ShowerCellRow cell;cell.candidate_id=candidate.id;
          cell.tower_eta_index=ie;cell.tower_phi_index=ip;
          cell.local_eta_index=ie-nominalCenterEta;
          int dphi=ip-nominalCenterPhi;
          while(dphi<-128)dphi+=256;
          while(dphi>127)dphi-=256;
          cell.local_phi_index=dphi;cell.grid_membership_bitmask=item.second;
          cell.tower_key=TowerInfoDefs::encode_emcal(ie,ip);
          TowerInfo* tower=cemcTowers->get_tower_at_key(static_cast<unsigned int>(cell.tower_key));
          cell.calibrated_energy=tower?tower->get_energy():std::numeric_limits<double>::quiet_NaN();
          cell.is_good=tower&&tower->get_isGood(); cell.is_zero=tower&&cell.calibrated_energy==0.0;
          cell.is_negative=tower&&cell.calibrated_energy<0.0; cell.is_nonfinite=!tower||!std::isfinite(cell.calibrated_energy);
          cell.seed_state=(ie==nominalCenterEta&&ip==nominalCenterPhi);
          cell.denominator_membership=cell.is_good&&std::isfinite(cell.calibrated_energy)&&cell.calibrated_energy>0.0;
          cell.floor0_membership=cell.denominator_membership;
          cell.floor70_membership=cell.is_good&&std::isfinite(cell.calibrated_energy)&&cell.calibrated_energy>0.070;
          const auto rawKey=RawTowerDefs::encode_towerid(RawTowerDefs::CalorimeterId::CEMC,ie,ip);
          const auto rawIt=rawTowerMap.find(rawKey);
          cell.rawcluster_owned=rawIt!=rawTowerMap.end();cell.rawcluster_value_present=cell.rawcluster_owned;
          if(rawIt!=rawTowerMap.end())cell.rawcluster_map_value=rawIt->second;
          candidateCells.push_back(cell);bundle.shower_cells.push_back(cell);
        }
        for(const auto& def:RJShowerFactorialV1::definitions())
        {
          const auto& state=def.floor_gev==0.0?shape0:shape70;
          if(!state.valid)continue;
          auto view=RJShowerFactorialV1::buildView(candidate.id,def,candidateCells,state.raw_eta,state.raw_phi,state.native_et);
          view.ordered_features=RJShowerFactorialV1::modelFeatures(view,pt,m_vz,eta,-1.0,false);
          candidateViews.push_back(view);
          bundle.shower_feature_views.push_back(std::move(view));
        }
      }

      if (m_photonTrainingViewRuntime)
      {
        RJPhotonTrainingViewV1::CandidateContext context;
        context.source_occurrence_id=m_photonTrainingViewRuntime->sourceOccurrenceId();
        context.event_id=bundle.event.id;
        context.candidate_id=candidate.id;
        context.run=bundle.event.run;
        context.event_sequence=bundle.event.event_sequence;
        context.encounter_ordinal=candidate.encounter_ordinal;
        context.cluster_map_key=static_cast<std::uint64_t>(it->first);
        context.cluster_et=pt;
        context.eta=eta;
        context.phi=phi;
        context.vertex_z=m_vz;
        context.centrality=-1.0;
        context.event_weight=m_mcEventWeight;
        std::string trainingError;
        if(!m_photonTrainingViewRuntime->appendCandidate(context,candidateViews,&trainingError))
        {
          m_replayWriteFailed=true;
          LOG(0,CLR_RED,"[RJPhotonTrainingViewV1][FATAL] candidate capture failed: "<<trainingError);
          return;
        }
      }

      if (m_the134FastExtraction) continue;

      for (double radius : {0.3,0.4})
      {
        IsolationWitnessRow witness; witness.candidate_id=candidate.id;
        witness.isolation_id=makeScopedIdentity(
            CompactIdentityDomain::ISOLATION_WITNESS,eventScope,
            isolationWitnessIdentityOrdinal++);
        witness.radius=radius; witness.subtraction_method=1; witness.reconstructed_or_truth=0;
        const char* key=radius<0.35?"ppg12_topo_raw_eiso_03":"ppg12_topo_raw_eiso_04";
        witness.cone_sum=photon->get_shower_shape_parameter(key);
        double isoA=m_isoA,isoB=m_isoB,sideGap=m_isoGap;
        getPPIsoParamsForCone(radius,isoA,isoB,sideGap);
        witness.threshold=m_isSlidingIso?(isoA+isoB*pt):m_isoFixed;
        witness.sideband_threshold=witness.threshold+sideGap;
        witness.pass_state=std::isfinite(witness.cone_sum)&&witness.cone_sum<witness.threshold;
        bundle.isolation_witnesses.push_back(witness);
      }
      if (m_ppg12TopoClusters)
      {
        replayMark("pp_topocluster_loop_begin");
        const CLHEP::Hep3Vector vertex(0.0,0.0,m_vz);
        const auto topoRange=m_ppg12TopoClusters->getClusters();
        int topoOrdinal=0;
        for(auto jt=topoRange.first;jt!=topoRange.second;++jt,++topoOrdinal)
        {
          const RawCluster* topo=jt->second; if(!topo) continue;
          const double topoEta=RawClusterUtility::GetPseudorapidity(*topo,vertex);
          const double topoPhi=RawClusterUtility::GetAzimuthAngle(*topo,vertex);
          const double dEta=topoEta-eta,dPhi=TVector2::Phi_mpi_pi(topoPhi-phi),dR=std::hypot(dEta,dPhi);
          if(!std::isfinite(dR)||dR>=0.4) continue;
          IsolationConstituentRow row; row.candidate_id=candidate.id;
          row.native_source=10;
          row.native_key=static_cast<std::uint32_t>(jt->first);
          row.delta_eta=dEta; row.delta_phi=dPhi; row.delta_r=dR; row.subsystem=10;
          row.raw_energy=topo->get_energy(); row.calibrated_energy=topo->get_energy()/std::cosh(topoEta);
          row.sub1_energy=row.calibrated_energy; row.phosub_residual=std::numeric_limits<double>::quiet_NaN();
          row.quality_state=std::isfinite(row.calibrated_energy); row.mask_state=0; row.candidate_removal_state=dR<0.02;
          bundle.isolation_constituents.push_back(row);
        }
        replayMark("pp_topocluster_loop_complete");
      }
    }

    replayMark("candidate_loop_complete");

    retentionDecision = m_replayRuntime->classifyAndRecord(
        m_isSim,m_isAuAu,m_vz,bundle.event.centrality,bundle.candidates);
    retentionDecisionRecorded = true;
    bundle.retention_class = retentionDecision.event_class;
    bundle.is_data = !m_isSim;
    if (!retentionDecision.retainEvent())
    {
      replayMark("data_event_omitted_after_histograms");
      return;
    }

    if (m_the134FastExtraction)
    {
      // The sidecar depends only on the accepted label ledger, stable
      // event/candidate identities, retained shower cells, and the seven
      // feature views constructed above.  Validate exactly that dependency
      // slice, then stop before isolation, reco-jet, pair, response, and
      // normalized-replay row assembly that cannot affect a sidecar branch.
      bundle.event.candidate_count =
          static_cast<int>(bundle.candidates.size());
      bundle.event.tag_count = static_cast<int>(std::count_if(
          bundle.models.begin(),bundle.models.end(),
          [](const ModelEvaluationRow& row)
          {
            return std::isfinite(row.wp80) && std::isfinite(row.raw_score) &&
                   row.raw_score > row.wp80;
          }));
      bundle.event.recoil_count = 0;
      std::string error;
      if (m_photonTrainingViewRuntime &&
          !m_photonTrainingViewRuntime->finishEvent(
              bundle.event.event_sequence,&error))
      {
        m_replayWriteFailed = true;
        LOG(0,CLR_RED,
            "[RJPhotonTrainingViewV1][FATAL] fast-extraction event "
            "transaction failed: " << error);
        return;
      }
      if (!m_replayRuntime->write(bundle,&error))
      {
        m_replayWriteFailed = true;
        LOG(0,CLR_RED,
            "[ReplayFoundationV1][FATAL] fast-extraction dependency-slice "
            "validation failed: " << error);
      }
      return;
    }

    if (retentionDecision.retainJetPayload())
    {
    auto appendJetConstituents = [&](const Jet* jet, const JetRow& parent)
    {
      if (!jet) return;
      int constituentOrdinal = 0;
      auto append = [&](Jet::SRC source, unsigned int channel)
      {
        const char* towerNode = nullptr;
        const char* geometryNode = nullptr;
        RawTowerDefs::CalorimeterId calorimeter = RawTowerDefs::CalorimeterId::CEMC;
        int subsystem = -1;
        const std::string configuredPrefix = RJReplayRuntimeV1::env("RJ_TOWERINFO_PREFIX");
        const std::string towerPrefix = configuredPrefix.empty() ? "TOWERINFO_CALIB" : configuredPrefix;
        std::string resolvedTowerNode;
        if (source == Jet::CEMC_TOWERINFO)
        { resolvedTowerNode=towerPrefix+"_CEMC"; geometryNode="TOWERGEOM_CEMC"; calorimeter=RawTowerDefs::CalorimeterId::CEMC; subsystem=0; }
        else if (source == Jet::CEMC_TOWERINFO_RETOWER)
        { resolvedTowerNode=towerPrefix+"_CEMC_RETOWER"; geometryNode="TOWERGEOM_HCALIN"; calorimeter=RawTowerDefs::CalorimeterId::HCALIN; subsystem=0; }
        else if (source == Jet::CEMC_TOWERINFO_SUB1)
        { resolvedTowerNode=towerPrefix+"_CEMC_RETOWER_SUB1"; geometryNode="TOWERGEOM_HCALIN"; calorimeter=RawTowerDefs::CalorimeterId::HCALIN; subsystem=0; }
        else if (source == Jet::HCALIN_TOWERINFO)
        { resolvedTowerNode=towerPrefix+"_HCALIN"; geometryNode="TOWERGEOM_HCALIN"; calorimeter=RawTowerDefs::CalorimeterId::HCALIN; subsystem=1; }
        else if (source == Jet::HCALIN_TOWERINFO_SUB1)
        { resolvedTowerNode=towerPrefix+"_HCALIN_SUB1"; geometryNode="TOWERGEOM_HCALIN"; calorimeter=RawTowerDefs::CalorimeterId::HCALIN; subsystem=1; }
        else if (source == Jet::HCALOUT_TOWERINFO)
        { resolvedTowerNode=towerPrefix+"_HCALOUT"; geometryNode="TOWERGEOM_HCALOUT"; calorimeter=RawTowerDefs::CalorimeterId::HCALOUT; subsystem=2; }
        else if (source == Jet::HCALOUT_TOWERINFO_SUB1)
        { resolvedTowerNode=towerPrefix+"_HCALOUT_SUB1"; geometryNode="TOWERGEOM_HCALOUT"; calorimeter=RawTowerDefs::CalorimeterId::HCALOUT; subsystem=2; }
        else return;
        towerNode=resolvedTowerNode.c_str();
        auto* towers=findNode::getClass<TowerInfoContainer>(topNode,towerNode);
        auto* geometry=findNode::getClass<RawTowerGeomContainer>(topNode,geometryNode);
        if(!towers||!geometry||channel>=towers->size())return;
        TowerInfo* tower=towers->get_tower_at_channel(channel);if(!tower)return;
        const unsigned int key=towers->encode_key(channel);
        const int ie=towers->getTowerEtaBin(key),ip=towers->getTowerPhiBin(key);
        JetConstituentRow row;row.jet_id=parent.id;row.constituent_ordinal=constituentOrdinal++;row.subsystem=subsystem;
        row.native_source=static_cast<std::int32_t>(source);
        row.native_key=static_cast<std::uint32_t>(channel);
        row.energy=tower->get_energy();
        row.eta=std::numeric_limits<double>::quiet_NaN();
        row.phi=std::numeric_limits<double>::quiet_NaN();
        const bool isCemc = calorimeter==RawTowerDefs::CalorimeterId::CEMC;
        const int etaBins=isCemc?96:24, phiBins=isCemc?256:64;
        if(ie<0||ie>=etaBins||ip<0||ip>=phiBins)
        {
          // Preserve the constituent and its energy, but never pass a TowerInfo
          // sentinel (commonly 65535) into RawTowerDefs::encode_towerid.
          row.quality_state=-2;
          bundle.jet_constituents.push_back(row);
          return;
        }
        RawTowerGeom* geom=geometry->get_tower_geometry(RawTowerDefs::encode_towerid(calorimeter,ie,ip));
        if(!geom)
        {
          row.quality_state=-1;
          bundle.jet_constituents.push_back(row);
          return;
        }
        const double radius=std::hypot(geom->get_center_x(),geom->get_center_y());
        if(!(radius>0))
        {
          row.quality_state=-3;
          bundle.jet_constituents.push_back(row);
          return;
        }
        row.eta=std::asinh((std::sinh(geom->get_eta())*radius-m_vz)/radius);
        row.phi=geom->get_phi();row.quality_state=tower->get_isGood();
        bundle.jet_constituents.push_back(row);
      };
      Jet* mutableJet=const_cast<Jet*>(jet);Jet::TYPE_comp_vec& components=mutableJet->get_comp_vec();
      if(!components.empty())for(const auto& component:components)append(component.first,component.second);
      else for(auto it=jet->begin_comp();it!=jet->end_comp();++it)append(it->first,it->second);
    };

    // Constituent payload is opt-in for source-linked event-display augmentation.
    // Default production keeps every jet and pair, but no per-tower jet rows.
    // RJJetV1 quality bit 0 explicitly records retained constituent payload.
    constexpr std::uint64_t kJetConstituentPayloadRetained = 1ULL << 0;
    const bool saveJetConstituents =
        RJReplayRuntimeV1::envEnabled("RJ_REPLAY_SAVE_JET_CONSTITUENTS");
    double jetConstituentPtMin = 5.0;
    const std::string configuredJetConstituentPtMin = RJReplayRuntimeV1::env("RJ_REPLAY_JET_CONSTITUENT_PT_MIN");
    if (!configuredJetConstituentPtMin.empty())
    {
      try
      {
        jetConstituentPtMin = std::stod(configuredJetConstituentPtMin);
      }
      catch (const std::exception&)
      {
        std::cerr << "RJ_REPLAY_FOUNDATION_FATAL invalid RJ_REPLAY_JET_CONSTITUENT_PT_MIN="
                  << configuredJetConstituentPtMin << std::endl;
        m_replayWriteFailed = true;
        return;
      }
    }
    if (!std::isfinite(jetConstituentPtMin) || jetConstituentPtMin < 0.0 || jetConstituentPtMin >= 15.0)
    {
      std::cerr << "RJ_REPLAY_FOUNDATION_FATAL RJ_REPLAY_JET_CONSTITUENT_PT_MIN must satisfy 0 <= pT < 15 GeV"
                << std::endl;
      m_replayWriteFailed = true;
      return;
    }

    auto appendRecoJetView = [&](const std::map<std::string, JetContainer*>& calibratedByRadius,
                                 const std::map<std::string, JetContainer*>& rawByRadius,
                                 const std::string& inputIdentity,
                                 const std::string& subtractionIdentity) -> bool
    {
      for (const auto& item : calibratedByRadius)
      {
        const std::string& rkey = item.first;
        JetContainer* calibrated = item.second;
        if (!calibrated)
        {
          LOG(0, CLR_RED,
              "[ReplayFoundationV1][FATAL] missing calibrated jet container for "
              << subtractionIdentity << " " << rkey);
          return false;
        }

        const auto rawIt = rawByRadius.find(rkey);
        JetContainer* raw =
            rawIt == rawByRadius.end() ? nullptr : rawIt->second;
        if (!raw)
        {
          LOG(0, CLR_RED,
              "[ReplayFoundationV1][FATAL] missing pre-JES jet container for "
              << subtractionIdentity << " " << rkey);
          return false;
        }
        if (!raw->has_property(Jet::PROPERTY::prop_area))
        {
          LOG(0, CLR_RED,
              "[ReplayFoundationV1][FATAL] missing FastJet area property for "
              << subtractionIdentity << " " << rkey);
          return false;
        }
        const Jet::PROPERTY areaIndex =
            raw->property_index(Jet::PROPERTY::prop_area);

        std::vector<const Jet*> rawByOrdinal;
        for (const Jet* rawJet : *raw)
        {
          rawByOrdinal.push_back(rawJet);
        }

        const double radius =
            (rkey.size() >= 3 && rkey[0] == 'r')
                ? std::stod(rkey.substr(1)) / 10.0
                : 0.0;
        bundle.event.reco_jet_view_radius_code.push_back(
            static_cast<int>(std::lround(radius * 10.0)));
        bundle.event.reco_jet_view_input_identity.push_back(inputIdentity);
        bundle.event.reco_jet_view_subtraction_identity.push_back(subtractionIdentity);
        bundle.event.reco_jet_view_available.push_back(1);
        int calibratedOrdinal = 0;
        int retainedOrdinal = 0;
        for (const Jet* jet : *calibrated)
        {
          const int sourceOrdinal = calibratedOrdinal++;
          if (!jet || !std::isfinite(jet->get_pt()) || jet->get_pt() < 0.0)
            continue;

          const int calibratedId = static_cast<int>(jet->get_id());
          std::size_t rawOrdinal = 0;
          if (!jetCalibRawOrdinal(calibrated->size(),rawByOrdinal.size(),
                                  sourceOrdinal,calibratedId,rawOrdinal))
          {
            LOG(0, CLR_RED,
                "[ReplayFoundationV1][FATAL] JetCalib output-id/raw-ordinal "
                "contract failure for " << subtractionIdentity << " " << rkey
                << " calibrated_size=" << calibrated->size()
                << " raw_size=" << rawByOrdinal.size()
                << " ordinal=" << sourceOrdinal
                << " calibrated_id=" << calibratedId);
            return false;
          }
          const Jet* rawJet = rawByOrdinal[rawOrdinal];

          if (!rawJet || !std::isfinite(rawJet->get_pt()) || rawJet->get_pt() < 0.0)
          {
            LOG(0, CLR_RED,
                "[ReplayFoundationV1][FATAL] unable to bind calibrated jet to "
                "a finite pre-JES partner for " << subtractionIdentity << " "
                << rkey << " ordinal=" << sourceOrdinal);
            return false;
          }

          JetRow row;
          row.id = makeScopedIdentity(
              CompactIdentityDomain::JET,eventScope,jetIdentityOrdinal++);
          row.event_id = bundle.event.id;
          row.native_jet_key = static_cast<std::uint32_t>(jet->get_id());
          row.native_raw_jet_key = static_cast<std::uint32_t>(rawJet->get_id());
          row.algorithm = "antikt";
          row.radius = radius;
          row.input_identity = inputIdentity;
          row.subtraction_identity = subtractionIdentity;
          row.raw_pt = rawJet->get_pt();
          row.corrected_pt = jet->get_pt();
          row.eta = jet->get_eta();
          row.phi = jet->get_phi();
          row.mass = jet->get_mass();
          row.area = rawJet->get_property(areaIndex);
          if (!std::isfinite(row.area) || row.area < 0.0)
          {
            LOG(0, CLR_RED,
                "[ReplayFoundationV1][FATAL] invalid FastJet active area for "
                << subtractionIdentity << " " << rkey
                << " ordinal=" << sourceOrdinal << " area=" << row.area);
            return false;
          }
          row.quality_bitmask |= kJetFastJetAreaValid;
          row.quality_bitmask |= kJetCalibRawOrdinalLinked;
          row.deterministic_order = retainedOrdinal++;
          const bool retainConstituents =
              saveJetConstituents && row.corrected_pt >= jetConstituentPtMin;
          if (retainConstituents)
            row.quality_bitmask |= kJetConstituentPayloadRetained;
          bundle.jets.push_back(row);
          recoJetKinematics.push_back(
              {row.id,row.corrected_pt,row.eta,row.phi,row.radius});
          if (retainConstituents) appendJetConstituents(rawJet,row);
          for (const auto& cand : recoKinematics)
          {
            PhotonJetPairRow pair;
            pair.id = makeScopedIdentity(
                CompactIdentityDomain::PAIR,eventScope,pairIdentityOrdinal++);
            pair.event_id = bundle.event.id;
            pair.candidate_id = cand.first;
            pair.jet_id = row.id;
            pair.delta_phi =
                std::fabs(TVector2::Phi_mpi_pi(row.phi-cand.second[2]));
            pair.xjgamma = cand.second[0] > 0
                               ? row.corrected_pt/cand.second[0]
                               : std::numeric_limits<double>::quiet_NaN();
            pair.recoil_state = pair.delta_phi >= 7.0*M_PI/8.0;
            pair.photon_rank = 0;
            pair.jet_rank = row.deterministic_order;
            bundle.pairs.push_back(pair);
          }
        }
      }
      return true;
    };

    const std::string primaryInputIdentity =
        m_isAuAu ? "towerinfo_sub1" : "towerinfo_calib";
    const std::string primarySubtractionIdentity = m_isAuAu ? "SUB1" : "none";
    if (!appendRecoJetView(
            m_jets,m_jetsRaw,primaryInputIdentity,primarySubtractionIdentity))
    {
      m_replayWriteFailed = true;
      return;
    }
    if (m_isAuAu &&
        !appendRecoJetView(
            m_jetsNoSub,m_jetsNoSubRaw,
            "towerinfo_retower_unsubtracted","none"))
    {
      m_replayWriteFailed = true;
      return;
    }
    replayMark("jet_loop_complete");
    }
  }

    // Truth denominators survive reconstructed-vertex/object rejection.
    if(m_isSim)
    {
      std::vector<std::string> truthKeys=m_activeJetRKeys;
      if(truthKeys.empty())for(const auto& radius:kJetRadii)truthKeys.push_back(radius.key);
      const auto replayTruthJetsByRKey=captureTruthJetContainers(
          truthKeys,RJReplayRuntimeV1::env("RJ_TRUTH_JETS_NODE"),
          [&](const std::string& node){return findNode::getClass<JetContainer>(topNode,node);});
      recordTruthJetAvailability(bundle.event,replayTruthJetsByRKey);
      std::vector<std::pair<Identity128,std::array<double,3>>> truthPhotonKinematics;
      const TruthSignalPhotonMap replayPPG12TruthByTrackId =
          buildPPG12TruthSignalPhotonMap(topNode);
      const TruthSignalPhotonMap replayTruthWitnessByTrackId =
          buildPPG12TruthPhotonWitnessMap(
              topNode,&bundle.event.truth_photon_inventory);
      for(const auto& truthEntry:replayTruthWitnessByTrackId)
      {
        const auto& info=truthEntry.second;
        if(!std::isfinite(info.pt)||!std::isfinite(info.eta)||
           !std::isfinite(info.phi)||!info.truthIsolationValid||info.pt<=0.0)
        {
          bundle.event.truth_photon_inventory.rejectInvalidKinematics();
          continue;
        }
        const bool analysisSignal =
            replayPPG12TruthByTrackId.count(info.trackId) != 0;
        TruthPhotonRow row;
        row.id=makeScopedIdentity(
            CompactIdentityDomain::TRUTH_PHOTON,eventScope,
            truthPhotonIdentityOrdinal++);
        row.event_id=bundle.event.id;
        row.pt=info.pt;row.eta=info.eta;row.phi=info.phi;
        row.prompt_class=info.photonClass;
        // Preserve the established analysis-signal field; family role is separate.
        row.source_role=analysisSignal?1:0;
        row.sample_source_role=(m_ppPhotonIDSourceRole=="signal")?1:
            ((m_ppPhotonIDSourceRole=="background"||m_ppPhotonIDSourceRole=="bkg")?2:0);
        row.g4_photon_valid=info.g4PhotonValid?1:0;
        row.hepmc_association_valid=info.hepmcAssociationValid?1:0;
        row.truth_isolation_valid=info.truthIsolationValid?1:0;
        row.analysis_signal_r03=analysisSignal?1:0;
        row.generator_barcode=info.barcode;
        row.native_track_id=info.trackId;
        row.native_vertex_id=info.g4 ? info.g4->get_vtx_id() : -1;
        row.embedding_id=info.embedId;
        row.generator_occurrence_embedding_id=info.embedId;
        row.truth_isolation_witness=info.isoEtR03;
        row.truth_isolation_r03=info.isoEtR03;
        row.truth_isolation_r04=info.isoEtR04;
        row.reporting_guard_state=info.pt<15?1:(info.pt>=35?2:0);
        bundle.truth_photons.push_back(row);
        ++bundle.event.truth_photon_inventory.serialized_raw_count;
        if(analysisSignal)
          ++bundle.event.truth_photon_inventory.analysis_signal_count;
        // Persist every raw witness, but nominal links use the same signal and
        // hard-scattering population as the accepted PPG12 response.
        if (analysisSignal && (!m_ppg12PhotonYieldDoubleInteraction || info.embedId==2))
          truthPhotonKinematics.push_back({row.id,{info.pt,info.eta,info.phi}});
      }
      bundle.event.truth_denominator_complete=
          bundle.event.truth_photon_inventory.denominatorComplete()?1:0;
      std::unordered_set<Identity128,IdentityHash> matchedTruth;
      for(const auto& reco:recoKinematics)
      {
        double best=0.1; Identity128 bestId;
        for(const auto& truth:truthPhotonKinematics){const double dr=std::hypot(reco.second[1]-truth.second[1],TVector2::Phi_mpi_pi(reco.second[2]-truth.second[2]));if(dr<best){best=dr;bestId=truth.first;}}
        RecoTruthLinkRow link;link.id=makeScopedIdentity(CompactIdentityDomain::LINK,eventScope,linkIdentityOrdinal++);link.reco_type=static_cast<int>(RecoTruthType::PHOTON);link.reco_id=reco.first;link.match_metric=best;
        if(bestId.isNull()){link.truth_type=static_cast<int>(RecoTruthType::NONE);link.link_class=static_cast<int>(LinkClass::RECO_FAKE);}else{link.truth_type=static_cast<int>(RecoTruthType::PHOTON);link.truth_id=bestId;link.link_class=static_cast<int>(LinkClass::MATCH);matchedTruth.insert(bestId);}
        bundle.links.push_back(link);
      }
      for(const auto& truth:truthPhotonKinematics) if(!matchedTruth.count(truth.first))
      {RecoTruthLinkRow link;link.id=makeScopedIdentity(CompactIdentityDomain::LINK,eventScope,linkIdentityOrdinal++);link.reco_type=static_cast<int>(RecoTruthType::NONE);link.truth_type=static_cast<int>(RecoTruthType::PHOTON);link.truth_id=truth.first;link.link_class=static_cast<int>(LinkClass::TRUTH_MISS);bundle.links.push_back(link);}
      std::vector<JetMatchObject> truthJetKinematics;
      for(const auto& item:replayTruthJetsByRKey)
      {
        if(!item.second)continue;
        const std::string& rkey=item.first;
        const double radius=(rkey.size()>=3&&rkey[0]=='r')?std::stod(rkey.substr(1))/10.0:0.0;
        for(const Jet* jet:*item.second)
        {
          if(!jet||!std::isfinite(jet->get_pt())||jet->get_pt()<0.0)continue;
          TruthJetRow row;
          row.id=makeScopedIdentity(
              CompactIdentityDomain::TRUTH_JET,eventScope,
              truthJetIdentityOrdinal++);
          row.event_id=bundle.event.id;
          row.native_jet_key=static_cast<std::uint32_t>(jet->get_id());
          row.algorithm="antikt";row.radius=radius;row.pt=jet->get_pt();
          row.eta=jet->get_eta();row.phi=jet->get_phi();
          row.ownership_state="source_owned";
          row.reporting_guard_state=row.pt<5?1:(row.pt>=35?2:0);
          bundle.truth_jets.push_back(row);
          truthJetKinematics.push_back({row.id,row.pt,row.eta,row.phi,row.radius});
        }
      }
      const auto jetLinks=buildDeterministicJetLinks(
          recoJetKinematics,truthJetKinematics,0.3,eventScope,
          linkIdentityOrdinal);
      linkIdentityOrdinal+=jetLinks.size();
      bundle.links.insert(bundle.links.end(),jetLinks.begin(),jetLinks.end());
    }
    replayMark("truth_loop_complete");

  if (!retentionDecisionRecorded)
  {
    retentionDecision = m_replayRuntime->classifyAndRecord(
        m_isSim,m_isAuAu,m_vz,bundle.event.centrality,bundle.candidates);
    bundle.retention_class = retentionDecision.event_class;
    bundle.is_data = !m_isSim;
    if (!retentionDecision.retainEvent())
    {
      replayMark("data_event_omitted_after_histograms");
      return;
    }
  }

  for (std::size_t ordinal = 0;
       ordinal < m_replayPPG12DiagnosticOccurrences.size(); ++ordinal)
  {
    const auto& source = m_replayPPG12DiagnosticOccurrences[ordinal];
    PPG12DiagnosticOccurrenceRow row;
    row.id = makeScopedIdentity(
        CompactIdentityDomain::OCCURRENCE,eventScope,
        occurrenceIdentityOrdinal++);
    row.event_id = bundle.event.id;
    row.trigger = source.trigger;
    row.occurrence_kind = source.occurrence_kind;
    row.stage_code = source.stage_code;
    row.source_code = source.source_code;
    row.sample_code = source.sample_code;
    row.decision = source.decision;
    row.cluster_ordinal = source.cluster_ordinal;
    row.truth_track_id = source.truth_track_id;
    row.generator_barcode = source.generator_barcode;
    row.source_photon_pt = source.source_photon_pt;
    row.flow_value = source.flow_value;
    row.reco_photon_pt = source.reco_photon_pt;
    row.response_photon_pt = source.response_photon_pt;
    row.truth_photon_pt = source.truth_photon_pt;
    row.truth_prior_weight = source.truth_prior_weight;
    row.reco_vertex_z = source.reco_vertex_z;
    row.hard_truth_vertex_z = source.hard_truth_vertex_z;
    row.mb_truth_vertex_z = source.mb_truth_vertex_z;
    row.vertex_weight = source.vertex_weight;
    row.period_event_weight = source.period_event_weight;
    row.cluster_energy = source.cluster_energy;
    row.cluster_eta = source.cluster_eta;
    row.cluster_et = source.cluster_et;
    row.truth_energy = source.truth_energy;
    row.truth_eta = source.truth_eta;
    row.truth_et = source.truth_et;
    row.energy_contribution = source.energy_contribution;
    row.occurrence_weight = source.occurrence_weight;
    row.selection_bitmask = source.selection_bitmask;
    row.occurrence_ordinal = static_cast<int>(ordinal);
    bundle.ppg12_diagnostic_occurrences.push_back(row);
  }

  bundle.event.candidate_count=static_cast<int>(bundle.candidates.size());
  bundle.event.tag_count=static_cast<int>(std::count_if(bundle.models.begin(),bundle.models.end(),[](const ModelEvaluationRow& row){return std::isfinite(row.wp80)&&std::isfinite(row.raw_score)&&row.raw_score>row.wp80;}));
  bundle.event.recoil_count=static_cast<int>(std::count_if(bundle.pairs.begin(),bundle.pairs.end(),[](const PhotonJetPairRow& row){return row.recoil_state!=0;}));
  WeightComponentRow eventWeight;
  eventWeight.target_id = bundle.event.id;
  eventWeight.component_type = "event";
  eventWeight.slice_weight = m_ppg12SimWeightFactorSlice;
  eventWeight.cross_section_weight = m_ppg12SimWeightFactorSlice;
  eventWeight.vertex_weight = m_ppg12SimWeightFactorVertex;
  eventWeight.si_di_weight = m_ppg12SimWeightFactorMix;
  eventWeight.period_weight = m_ppg12SimWeightFactorPeriod;
  eventWeight.exposure_weight = m_ppg12SimWeightFactorPeriod;
  eventWeight.final_weight = m_mcEventWeight;
  eventWeight.application_count = 1;
  bundle.weights.push_back(eventWeight);

  std::string error;
  const std::int64_t localSourceEntryOffset =
      event_count>0 ? static_cast<std::int64_t>(event_count-1) : -1;
  if(!m_replayRuntime->applyLegacyOrderCoordinates(
         bundle.event,localSourceEntryOffset,&error))
  {
    m_replayWriteFailed=true;
    LOG(0,CLR_RED,"[ReplayFoundationV1][FATAL] source-order coordinate failure: "<<error);
    return;
  }
  if(m_photonTrainingViewRuntime &&
     !m_photonTrainingViewRuntime->finishEvent(bundle.event.event_sequence,&error))
  {
    m_replayWriteFailed=true;
    LOG(0,CLR_RED,"[RJPhotonTrainingViewV1][FATAL] event transaction failed: "<<error);
    return;
  }
  replayMark("runtime_write_begin");
  if(!m_replayRuntime->write(bundle,&error))
  {
    m_replayWriteFailed=true;
    LOG(0,CLR_RED,"[ReplayFoundationV1][FATAL] event transaction failed: "<<error);
  }
  replayMark("runtime_write_complete");
}

void RecoilJets::fillReplayFoundationCaptureWitness()
{
  if (!m_replayFoundationCaptureWitnessEnabled || !m_photons) return;

  // This directory is intentionally not a nominal trigger or analysis view.
  // It proves that direct and writer arms see the same loose detector
  // candidates, including diagnostic-only candidates below 15 GeV.
  static const std::string kWitnessDir = "REPLAY_FOUNDATION_CAPTURE_DIAGNOSTIC";
  HistMap& H = qaHistogramsByTrigger[kWitnessDir];

  auto book1 = [&](const std::string& name,
                   const std::string& title,
                   int bins, double lo, double hi) -> TH1F*
  {
    auto it = H.find(name);
    if (it != H.end()) return dynamic_cast<TH1F*>(it->second);
    auto* hist = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), bins, lo, hi);
    hist->SetDirectory(nullptr);
    H[name] = hist;
    return hist;
  };
  auto book2 = [&](const std::string& name,
                   const std::string& title,
                   int xBins, double xLo, double xHi,
                   int yBins, double yLo, double yHi) -> TH2F*
  {
    auto it = H.find(name);
    if (it != H.end()) return dynamic_cast<TH2F*>(it->second);
    auto* hist = RJMCWeighting::RJNewTH2F(
        name.c_str(), title.c_str(), xBins, xLo, xHi, yBins, yLo, yHi);
    hist->SetDirectory(nullptr);
    H[name] = hist;
    return hist;
  };

  auto* hCount = book1(
      "h_the119_capture_diagnostic_candidate_count_per_event",
      "THE-119 loose-capture candidates per delivered event;N_{candidate};Events",
      128, -0.5, 127.5);
  auto* hEt = book1(
      "h_the119_capture_diagnostic_cluster_et",
      "THE-119 loose-capture candidate E_{T};E_{T}^{candidate} [GeV];Candidates",
      350, 5.0, 40.0);
  auto* hEta = book1(
      "h_the119_capture_diagnostic_cluster_eta",
      "THE-119 loose-capture candidate #eta;#eta^{candidate};Candidates",
      280, -0.7, 0.7);
  auto* hPhi = book1(
      "h_the119_capture_diagnostic_cluster_phi",
      "THE-119 loose-capture candidate #phi;#phi^{candidate};Candidates",
      256, -M_PI, M_PI);
  auto* hDomain = book2(
      "h_the119_capture_diagnostic_model_domain_state_vs_et",
      "THE-119 model-domain witness;E_{T}^{candidate} [GeV];Domain state",
      350, 5.0, 40.0, 3, 0.5, 3.5);
  hDomain->GetYaxis()->SetBinLabel(1, "diagnostic below 15");
  hDomain->GetYaxis()->SetBinLabel(2, "validated 15-35");
  hDomain->GetYaxis()->SetBinLabel(3, "diagnostic above 35");
  auto* hNonfinite = book2(
      "h_the119_capture_diagnostic_nonfinite_feature_vs_et",
      "THE-119 nonfinite ordered-feature witness;E_{T}^{candidate} [GeV];Feature index",
      350, 5.0, 40.0, 11, -0.5, 10.5);

  struct FeatureSpec
  {
    const char* name;
    const char* axis;
    int bins;
    double lo;
    double hi;
  };
  static const std::array<FeatureSpec,11> specs{{
      {"cluster_et", "E_{T}^{candidate} [GeV]", 350, 5.0, 40.0},
      {"weta_cogx", "w_{#eta}^{COGX}", 240, 0.0, 1.2},
      {"wphi_cogx", "w_{#phi}^{COGX}", 240, 0.0, 1.2},
      {"vertex_z", "v_{z} [cm]", 240, -60.0, 60.0},
      {"cluster_eta", "#eta^{candidate}", 280, -0.7, 0.7},
      {"e11_over_e33", "E_{11}/E_{33}", 240, -0.2, 1.2},
      {"cluster_et1", "e_{T1}", 240, -0.2, 1.2},
      {"cluster_et2", "e_{T2}", 240, -0.2, 1.2},
      {"cluster_et3", "e_{T3}", 240, -0.2, 1.2},
      {"cluster_et4", "e_{T4}", 240, -0.2, 1.2},
      {"e32_over_e35", "E_{32}/E_{35}", 240, -0.2, 1.2}
  }};

  std::array<TH2F*,11> featureHists{};
  for (std::size_t i = 0; i < specs.size(); ++i)
  {
    const auto& spec = specs[i];
    const std::string name =
        std::string("h_the119_capture_diagnostic_") + spec.name + "_vs_et";
    const std::string title =
        std::string("THE-119 loose-capture ") + spec.axis +
        ";E_{T}^{candidate} [GeV];" + spec.axis;
    featureHists[i] = book2(name, title, 350, 5.0, 40.0,
                            spec.bins, spec.lo, spec.hi);
  }
  auto* hMatchedScore = book2(
      "h_the119_capture_diagnostic_matched_bdt_score_vs_et",
      "THE-119 matched-model raw score diagnostic;E_{T}^{candidate} [GeV];Raw BDT score",
      350, 5.0, 40.0, 250, 0.0, 1.0);
  auto* hReferenceScore = book2(
      "h_the119_capture_diagnostic_ppg12_bdt_score_vs_et",
      "THE-119 PPG12-reference raw score diagnostic;E_{T}^{candidate} [GeV];Raw BDT score",
      350, 5.0, 40.0, 250, 0.0, 1.0);
  auto* hTopoRawR03 = book2(
      "h_the119_capture_diagnostic_topocluster_raw_eiso_r03_vs_et",
      "THE-119 p+p topocluster isolation witness, R=0.3;E_{T}^{candidate} [GeV];E_{T}^{iso,raw}(R=0.3) [GeV]",
      350, 5.0, 40.0, 400, -10.0, 30.0);
  auto* hTopoRawR04 = book2(
      "h_the119_capture_diagnostic_topocluster_raw_eiso_r04_vs_et",
      "THE-119 p+p topocluster isolation witness, R=0.4;E_{T}^{candidate} [GeV];E_{T}^{iso,raw}(R=0.4) [GeV]",
      350, 5.0, 40.0, 400, -10.0, 30.0);
  auto* hTopoAnnulus = book2(
      "h_the119_capture_diagnostic_topocluster_raw_eiso_annulus_r03_r04_vs_et",
      "THE-119 p+p topocluster isolation annulus witness;E_{T}^{candidate} [GeV];E_{T}^{iso,raw}(R=0.4)-E_{T}^{iso,raw}(R=0.3) [GeV]",
      350, 5.0, 40.0, 400, -10.0, 30.0);
  auto* hTopoR04Delta = book2(
      "h_the119_capture_diagnostic_topocluster_r04_delta_nominal_threshold_vs_et",
      "THE-119 p+p nominal R=0.4 isolation-threshold witness;E_{T}^{candidate} [GeV];E_{T}^{iso,raw}-(0.490+0.037E_{T}^{candidate}) [GeV]",
      350, 5.0, 40.0, 400, -20.0, 20.0);
  auto* hTopoR04State = book2(
      "h_the119_capture_diagnostic_topocluster_r04_nominal_state_vs_et",
      "THE-119 p+p nominal R=0.4 isolation state;E_{T}^{candidate} [GeV];State",
      350, 5.0, 40.0, 3, -0.5, 2.5);
  hTopoR04State->GetYaxis()->SetBinLabel(1, "invalid");
  hTopoR04State->GetYaxis()->SetBinLabel(2, "finite fail");
  hTopoR04State->GetYaxis()->SetBinLabel(3, "finite pass");
  auto* hTopoR03Finite = book2(
      "h_the119_capture_diagnostic_topocluster_r03_finite_state_vs_et",
      "THE-119 p+p R=0.3 isolation finite-state witness;E_{T}^{candidate} [GeV];State",
      350, 5.0, 40.0, 2, -0.5, 1.5);
  hTopoR03Finite->GetYaxis()->SetBinLabel(1, "invalid");
  hTopoR03Finite->GetYaxis()->SetBinLabel(2, "finite");

  int retained = 0;
  const auto range = m_photons->getClusters();
  for (auto it = range.first; it != range.second; ++it)
  {
    const auto* photon = dynamic_cast<const PhotonClusterv1*>(it->second);
    if (!photon) continue;
    const double et = photon->get_shower_shape_parameter("cluster_pt");
    const double eta = photon->get_shower_shape_parameter("cluster_eta");
    const double phi = photon->get_shower_shape_parameter("cluster_phi");
    if (!std::isfinite(et) || !std::isfinite(eta) || !std::isfinite(phi) ||
        et < 5.0 || et >= 40.0 || std::fabs(eta) >= 0.7)
      continue;

    const SSVars v = makeSSFromPhoton(photon, et);
    const std::array<double,11> values{{
        et, v.weta_cogx, v.wphi_cogx, m_vz, eta, v.e11_over_e33,
        v.et1, v.et2, v.et3, v.et4, v.e32_over_e35
    }};
    ++retained;
    hEt->Fill(et);
    hEta->Fill(eta);
    hPhi->Fill(phi);
    hDomain->Fill(et, et < 15.0 ? 1.0 : (et < 35.0 ? 2.0 : 3.0));
    for (std::size_t i = 0; i < values.size(); ++i)
    {
      if (std::isfinite(values[i])) featureHists[i]->Fill(et, values[i]);
      else hNonfinite->Fill(et, static_cast<double>(i));
    }
    if (std::isfinite(v.tight_bdt_score)) hMatchedScore->Fill(et, v.tight_bdt_score);
    const double referenceScore =
        photon->get_shower_shape_parameter("ppg12_reference_bdt_score");
    if (std::isfinite(referenceScore)) hReferenceScore->Fill(et, referenceScore);

    const double topoRawR03 =
        photon->get_shower_shape_parameter("ppg12_topo_raw_eiso_03");
    const double topoRawR04 =
        photon->get_shower_shape_parameter("ppg12_topo_raw_eiso_04");
    const bool finiteR03 = std::isfinite(topoRawR03);
    const bool finiteR04 = std::isfinite(topoRawR04);
    hTopoR03Finite->Fill(et, finiteR03 ? 1.0 : 0.0);
    if (finiteR03) hTopoRawR03->Fill(et, topoRawR03);
    if (finiteR04)
    {
      const double nominalThreshold = 0.490 + 0.037 * et;
      hTopoRawR04->Fill(et, topoRawR04);
      hTopoR04Delta->Fill(et, topoRawR04 - nominalThreshold);
      hTopoR04State->Fill(et, topoRawR04 < nominalThreshold ? 2.0 : 1.0);
    }
    else
    {
      hTopoR04State->Fill(et, 0.0);
    }
    if (finiteR03 && finiteR04)
      hTopoAnnulus->Fill(et, topoRawR04 - topoRawR03);
  }
  hCount->Fill(retained);
}

int RecoilJets::process_event(PHCompositeNode* topNode)
{
  const bool replayTrace = RJReplayRuntimeV1::envEnabled("RJ_REPLAY_TRACE");
  auto replayProcessMark = [&](const char* stage)
  {
    if (replayTrace)
      std::cerr << "RJ_REPLAY_PROCESS_TRACE event=" << (event_count + 1)
                << " stage=" << stage << std::endl;
  };
  replayProcessMark("begin");
  m_replayNodesReady = false;
  m_collaboratorRecoVertexValid = false;
  m_lastReject = EventReject::None;
  m_replayPPG12DiagnosticOccurrences.clear();
  m_replayFullFillCountsAtEventStart = RJMCWeighting::FullFillCounts();
  m_replayRawFillCountsAtEventStart = RJMCWeighting::RawFillCounts();
  auto replayScope = RJReplayRuntimeV1::onScopeExit([this, topNode]()
  {
    if (m_replayFoundationEnabled)
      writeReplayFoundationEvent(topNode, static_cast<int>(m_lastReject));
  });
  RJMCWeighting::CurrentWeight() = 1.0;
  RJMCWeighting::CurrentLaneComponentCode() = 0;
  m_mcVertexWeight = 1.0;
  m_mcEventWeight = 1.0;
  m_ppg12SimWeightActive = false;
  m_ppg12SimWeightLaneCode = 0;
  m_ppg12SimWeightLaneComponentCode = 0;
  m_ppg12SimWeightFactorSlice = 1.0;
  m_ppg12SimWeightFactorVertex = 1.0;
  m_ppg12SimWeightFactorMix = 1.0;
  m_ppg12SimWeightFactorPeriod = 1.0;
  m_ppg12SimWeightFactorFinal = 1.0;
  m_ppg12Fig6FilledThisEvent = false;

  /* ------------------------------------------------------------------ */
  /* 0) Banner & counter                                                */
  /* ------------------------------------------------------------------ */
  ++event_count;
  if(!captureReplayTrigger(topNode)) return Fun4AllReturnCodes::ABORTRUN;
  ++m_bk.evt_seen;
  if (Verbosity() >= 4)
  {
    std::cout << "==================== processing event "
              << std::setw(6) << event_count
              << " ====================" << std::endl;
  }

  if (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu &&
      ppg12InclusiveJetSliceFromContext(Outfile) != PPG12InclusiveJetSlice::kNone)
  {
    m_ppg12Fig6FilledThisEvent = fillPPG12InclusiveJetTruthSpectrumQA(topNode);
  }

  /* ------------------------------------------------------------------ */
  /* 1) Mandatory nodes                                                 */
  /* ------------------------------------------------------------------ */
  LOG(4, CLR_BLUE, "  [process_event] – node sanity");
  if (!fetchNodes(topNode))
  {
    LOG(4, CLR_YELLOW, "    mandatory node(s) missing → ABORTEVENT");
    return Fun4AllReturnCodes::ABORTEVENT;
  }
  replayProcessMark("fetch_nodes_complete");
  m_replayNodesReady = true;
  fillReplayFoundationCaptureWitness();

  // PPG12 Fig.81 data h_D reference contract. This must be filled before
  // firstEventCuts()/vz60 and before cluster requirements: PPG12's
  // truth_vertex_reweight h_D uses only data scaled bit 30, run period, and
  // finite MBD vertex z within |z| <= 200 cm.
  fillPPG12Fig81DataHDReferenceVertexQA(topNode);

  // PPG12 Fig. 6 parity fallback: the strict truth-spectrum fill normally
  // happens before fetchNodes() so reco/MBD vertex failures cannot bias it.
  // This post-fetch fallback is only for unexpected missing truth nodes in the
  // pre-fetch path; the per-event guard prevents double counting.
  if (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu &&
      ppg12InclusiveJetSliceFromContext(Outfile) != PPG12InclusiveJetSlice::kNone &&
      !m_ppg12Fig6FilledThisEvent)
  {
    m_ppg12Fig6FilledThisEvent = fillPPG12InclusiveJetTruthSpectrumQA();
  }

  // PPG12 inclusive-jet production assigns each event to exactly one source
  // sample using the maximum truth anti-kT R=0.4 jet pT.  This is an event
  // ownership contract, not a histogram-specific cut: reject out-of-window
  // events here so every downstream physics consumer (photon ID, isolation,
  // ABCD/purity, recoil jets, and xJgamma) sees the same stitched population.
  //
  // The all/kept/rejected Fig. 6 audit above deliberately runs before this
  // decision.  Historical PPG12 BDT row extraction is the one documented
  // exception: RJ_PP_PHOTONID_EXTRACT_ONLY preserves its ungated candidate
  // population while still storing the ownership decision on each row.
  const PPG12InclusiveJetSlice ppInclusivePhysicsSlice =
      (m_isSim && !m_isAuAu)
          ? ppg12InclusiveJetSliceFromContext(Outfile)
          : PPG12InclusiveJetSlice::kNone;
  if (ppInclusivePhysicsSlice != PPG12InclusiveJetSlice::kNone &&
      !m_ppPhotonIDExtractOnly)
  {
    double ownershipLo = std::numeric_limits<double>::quiet_NaN();
    double ownershipHi = std::numeric_limits<double>::quiet_NaN();
    const bool haveOwnershipWindow =
        ppg12InclusiveJetSliceWindow(ppInclusivePhysicsSlice,
                                     ownershipLo,
                                     ownershipHi);

    JetContainer* ownershipTruthJetsR04 = nullptr;
    if (auto itR04 = m_truthJetsByRKey.find("r04");
        itR04 != m_truthJetsByRKey.end())
    {
      ownershipTruthJetsR04 = itR04->second;
    }
    if (!ownershipTruthJetsR04)
    {
      ownershipTruthJetsR04 = ppg12FindTruthJetsR04(topNode).first;
    }

    double maxTruthJetPtR04 = -1.0;
    if (ownershipTruthJetsR04)
    {
      for (const Jet* truthJet : *ownershipTruthJetsR04)
      {
        if (!truthJet) continue;
        const double truthJetPt = truthJet->get_pt();
        if (std::isfinite(truthJetPt) && truthJetPt > maxTruthJetPtR04)
        {
          maxTruthJetPtR04 = truthJetPt;
        }
      }
    }

    const bool haveTruthJetR04 = (maxTruthJetPtR04 >= 0.0);
    const bool passInclusivePhysicsOwnership =
        haveOwnershipWindow && haveTruthJetR04 &&
        ppg12WindowContains(maxTruthJetPtR04, ownershipLo, ownershipHi);
    if (!passInclusivePhysicsOwnership)
    {
      m_lastReject = EventReject::Ownership;
      LOG(5, CLR_YELLOW,
          "    [PPG12_INCLUSIVE_OWNERSHIP] reject event before physics fills"
          << " | sample=" << ppg12InclusiveJetSliceName(ppInclusivePhysicsSlice)
          << " | maxTruthJetPtR04=" << maxTruthJetPtR04
          << " | window=[" << ownershipLo << "," << ownershipHi << "]"
          << " | haveR04=" << (haveTruthJetR04 ? "true" : "false"));
      return Fun4AllReturnCodes::ABORTEVENT;
    }
  }

  // Strict PPG12 IAN Fig. 5 source-stage diagnostic. This is intentionally
  // before firstEventCuts()/vz so the next photon5/10/20 canary can test the
  // PPG12 source-plot contract separately from the existing post-vz stitch QA.
  if (m_isSim && !m_isAuAu)
  {
    const PPG12PhotonSlice fig5PreVzSlice = ppg12PhotonSliceFromContext(Outfile);
    if (fig5PreVzSlice != PPG12PhotonSlice::kNone)
    {
      double fig5PreVzLo = std::numeric_limits<double>::quiet_NaN();
      double fig5PreVzHi = std::numeric_limits<double>::quiet_NaN();
      const bool fig5PreVzHaveWindow =
          ppg12PhotonSliceWindow(fig5PreVzSlice, fig5PreVzLo, fig5PreVzHi);
      const double fig5PreVzPhotonPt =
          ppg12MaxStoredTruthPhotonPt(topNode, m_truthInfo, true, 0.7);
      const bool fig5PreVzHaveTruth = (fig5PreVzPhotonPt >= 0.0);
      const bool fig5PreVzPass =
          fig5PreVzHaveWindow && fig5PreVzHaveTruth &&
          ppg12WindowContains(fig5PreVzPhotonPt, fig5PreVzLo, fig5PreVzHi);

      auto bookFig5PreVz1F = [&](const std::string& name,
                                 const std::string& title,
                                 int nbins,
                                 double xmin,
                                 double xmax) -> TH1F*
      {
        HistMap& H = qaHistogramsByTrigger["SIM"];
        if (auto it = H.find(name); it != H.end())
        {
          return dynamic_cast<TH1F*>(it->second);
        }

        TDirectory* dir = (out ? out->GetDirectory("SIM") : nullptr);
        if (!dir && out) dir = out->mkdir("SIM");
        if (!dir) return nullptr;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        auto* h = RJMCWeighting::RJNewRawTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
        h->Sumw2();
        h->SetDirectory(dir);
        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
      };

      auto bookFig5PreVz1I = [&](const std::string& name,
                                 const std::string& title,
                                 int nbins,
                                 double xmin,
                                 double xmax) -> TH1I*
      {
        HistMap& H = qaHistogramsByTrigger["SIM"];
        if (auto it = H.find(name); it != H.end())
        {
          return dynamic_cast<TH1I*>(it->second);
        }

        TDirectory* dir = (out ? out->GetDirectory("SIM") : nullptr);
        if (!dir && out) dir = out->mkdir("SIM");
        if (!dir) return nullptr;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        auto* h = RJMCWeighting::RJNewRawTH1I(name.c_str(), title.c_str(), nbins, xmin, xmax);
        h->SetDirectory(dir);
        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
      };

      if (auto* hMeta = bookFig5PreVz1F(
              "h_ppPhotonStitch_ppg12Fig5PreVz_metadata",
              "h_ppPhotonStitch_ppg12Fig5PreVz_metadata;metadata;value",
              10, 0.5, 10.5))
      {
        hMeta->GetXaxis()->SetBinLabel(1, "events_pre_firstEventCuts");
        hMeta->GetXaxis()->SetBinLabel(2, "window_low_GeV");
        hMeta->GetXaxis()->SetBinLabel(3, "window_high_GeV");
        hMeta->GetXaxis()->SetBinLabel(4, "upper_edge_inclusive");
        hMeta->GetXaxis()->SetBinLabel(5, "bin_width_GeV");
        hMeta->GetXaxis()->SetBinLabel(6, "xsec_pb");
        hMeta->GetXaxis()->SetBinLabel(7, "truth_def_code");
        hMeta->GetXaxis()->SetBinLabel(8, "sample_bin");
        hMeta->GetXaxis()->SetBinLabel(9, "stage_code_pre_firstEventCuts");
        hMeta->GetXaxis()->SetBinLabel(10, "uses_current_event_weight");
        hMeta->Fill(1.0);
        hMeta->SetBinContent(2, fig5PreVzLo);
        hMeta->SetBinContent(3, std::isinf(fig5PreVzHi) ? 200.0 : fig5PreVzHi);
        hMeta->SetBinContent(4, 1.0);
        hMeta->SetBinContent(5, 0.5);
        hMeta->SetBinContent(6, ppg12PhotonSliceXsecPb(fig5PreVzSlice));
        hMeta->SetBinContent(7, 5.0);
        hMeta->SetBinContent(8, static_cast<double>(ppg12PhotonSliceBin(fig5PreVzSlice)));
        hMeta->SetBinContent(9, 1.0);
        hMeta->SetBinContent(10, 0.0);
        bumpHistFill("SIM", hMeta->GetName());
      }

      if (auto* hAll = bookFig5PreVz1F(
              "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_all",
              "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_all;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
              120, 0.0, 60.0))
      {
        if (fig5PreVzHaveTruth)
        {
          hAll->Fill(fig5PreVzPhotonPt);
          bumpHistFill("SIM", hAll->GetName());
        }
      }
      if (fig5PreVzPass)
      {
        if (auto* hKept = bookFig5PreVz1F(
                "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_kept",
                "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_kept;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
                120, 0.0, 60.0))
        {
          hKept->Fill(fig5PreVzPhotonPt);
          bumpHistFill("SIM", hKept->GetName());
        }
      }
      else if (auto* hRejected = bookFig5PreVz1F(
                   "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_rejected",
                   "h_ppPhotonStitch_ppg12Fig5PreVz_maxPhotonPt_rejected;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
                   120, 0.0, 60.0))
      {
        if (fig5PreVzHaveTruth)
        {
          hRejected->Fill(fig5PreVzPhotonPt);
          bumpHistFill("SIM", hRejected->GetName());
        }
      }

      if (auto* hDecision = bookFig5PreVz1I(
              "h_ppPhotonStitch_ppg12Fig5PreVz_decision",
              "h_ppPhotonStitch_ppg12Fig5PreVz_decision;decision;Events",
              4, 0.5, 4.5))
      {
        hDecision->GetXaxis()->SetBinLabel(1, "kept");
        hDecision->GetXaxis()->SetBinLabel(2, "rejected");
        hDecision->GetXaxis()->SetBinLabel(3, "missing truth");
        hDecision->GetXaxis()->SetBinLabel(4, "unknown sample");
        hDecision->Fill(fig5PreVzPass ? 1 : (fig5PreVzHaveTruth ? 2 : 3));
        bumpHistFill("SIM", hDecision->GetName());
      }
      if (m_replayFoundationEnabled)
      {
        ReplayPPG12DiagnosticOccurrence row;
        row.trigger = "SIM";
        row.occurrence_kind = "PP_STITCH_SOURCE";
        row.source_code = 7;  // PPG12 eta<0.7 source before firstEventCuts.
        row.sample_code = ppg12PhotonSliceBin(fig5PreVzSlice);
        row.decision = fig5PreVzPass ? 1 : (fig5PreVzHaveTruth ? 2 : 3);
        if (fig5PreVzHaveTruth) row.source_photon_pt = fig5PreVzPhotonPt;
        m_replayPPG12DiagnosticOccurrences.push_back(row);
      }
    }
  }

  /* ------------------------------------------------------------------ */
  /* 2) Trigger gating (pp & Au+Au) — unified in firstEventCuts()       */
  /* ------------------------------------------------------------------ */

  fillPPG12Fig7TriggerQA(topNode);

  // DATA ONLY: doNotScale max-cluster-energy trigger-efficiency fill
  //   - baseline gate uses the event-level raw/unscaled GL1 TriggerVector bit
  //   - probe gate uses the event-level GL1 LiveVector bit
  //   - denominator is filled ONCE per pair when the baseline bit is on
  //   - numerator   is filled ONCE per pair when baseline AND probe are on
  //   - run-range/bit mapping is hard-coded from the ALL QA output above
  // ------------------------------------------------------------------
  if (!m_isSim)
  {
    Gl1Packet* gl1Packet = findNode::getClass<Gl1Packet>(topNode, "GL1Packet");
    if (!gl1Packet) gl1Packet = findNode::getClass<Gl1Packet>(topNode, "14001");

    if (gl1Packet)
    {
      const uint64_t runNumber     = static_cast<uint64_t>(currentRunNumber());
      uint64_t triggerVector = 0;
      uint64_t liveVector    = 0;
      getDoNotScaleEventVectors(gl1Packet, triggerVector, liveVector);

      const bool passVzForDoNotScale =
          (std::isfinite(m_vz) && std::fabs(m_vz) < 30.0);

      if (passVzForDoNotScale)
      {
        float max_energy_clus = 0.f;

        if (m_clus)
        {
          const auto range = m_clus->getClusters();
          for (auto it = range.first; it != range.second; ++it)
          {
            const RawCluster* cl = it->second;
            if (!cl) continue;
            const float e = cl->get_energy();
            if (!std::isfinite(e)) continue;
            if (e < 1.0f) continue;
            if (e > max_energy_clus) max_energy_clus = e;
          }
        }
        else if (m_photons)
        {
          const auto range = m_photons->getClusters();
          for (auto it = range.first; it != range.second; ++it)
          {
            const RawCluster* cl = it->second;
            if (!cl) continue;
            const float e = cl->get_energy();
            if (!std::isfinite(e)) continue;
            if (e < 1.0f) continue;
            if (e > max_energy_clus) max_energy_clus = e;
          }
        }

        auto fillDoNotScaleHist = [&](const std::string& histKey)
        {
          const std::string histName = "h_maxEnergyClus_NewTriggerFilling_doNotScale_" + histKey;
          auto& histogramMap = qaHistogramsByTrigger[histKey];

          TH1F* h = nullptr;
          auto it = histogramMap.find(histName);
          if (it != histogramMap.end())
          {
            h = dynamic_cast<TH1F*>(it->second);
          }

          if (!h)
          {
            TDirectory* dir = out->GetDirectory(histKey.c_str());
            if (!dir) dir = out->mkdir(histKey.c_str());
            if (!dir) return;

            TDirectory* prevDir = gDirectory;
            dir->cd();

            h = RJMCWeighting::RJNewTH1F(histName.c_str(),
                         "Max Cluster Energy; Cluster Energy [GeV]",
                         40, 0, 20);
            h->SetDirectory(dir);
            histogramMap[histName] = h;

            if (prevDir) prevDir->cd();
          }

          h->Fill(max_energy_clus);
          bumpHistFill(histKey, histName);
        };

        for (const auto& cfg : getDoNotScalePairConfigs())
        {
          if (!doNotScaleRunMatch(runNumber, cfg)) continue;
          if (!doNotScaleBitIsSet(triggerVector, cfg.baselineBit)) continue;

          fillDoNotScaleHist(doNotScaleBaselineHistKey(cfg));

          if (doNotScaleBitIsSet(liveVector, cfg.probeBit))
          {
            fillDoNotScaleHist(cfg.probeHistKey);
          }
        }
      }
    }

    if (!m_isAuAu)
    {
      auto* directGl1Packet=findNode::getClass<Gl1Packet>(topNode,"GL1Packet");
      if(!directGl1Packet) directGl1Packet=findNode::getClass<Gl1Packet>(topNode,"14001");
      const auto* directRunInfo=findNode::getClass<TriggerRunInfo>(topNode,"TriggerRunInfo");

      const std::string mbdNoVtxDbName    = "MBD N&S >= 1";
      const std::string mbdNoVtxShortName = "MBD_NandS_geq_1";
      const bool isMBNoVtx = RJGl1TriggerContract::firedByName(directGl1Packet,directRunInfo,mbdNoVtxDbName);

      if (isMBNoVtx && m_doPi0Analysis)
      {
        const bool passPi0Vz = (!m_useVzCut || std::fabs(m_vz) < m_vzCut);

        if (passPi0Vz && m_clus && m_clus_nocorr)
        {
          fillPi0MassVsPtHistograms(mbdNoVtxShortName, m_clus, true);
          fillPi0MassVsPtHistograms(mbdNoVtxShortName, m_clus_nocorr, false);
        }
        else if (Verbosity() >= 2)
        {
          LOG(2, CLR_YELLOW,
              "    [process_event][pi0] requested pp pi0 fill skipped"
              << " | passVz=" << (passPi0Vz ? "true" : "false")
              << " | CLUSTERINFO_CEMC=" << (m_clus ? "OK" : "MISSING")
              << " | CLUSTERINFO_CEMC_NOCORR=" << (m_clus_nocorr ? "OK" : "MISSING"));
        }
      }
    }
  }

  std::vector<std::string> activeTrig;
  if (!firstEventCuts(topNode, activeTrig))
  {
    ++m_evtNoTrig;  // keep your legacy counter
    if (m_lastReject == EventReject::Trigger) ++m_bk.evt_fail_trigger;
    else if (m_lastReject == EventReject::Vz) ++m_bk.evt_fail_vz;

    const char* why = "UNKNOWN";
    if (m_lastReject == EventReject::Trigger) why = "Trigger";
    else if (m_lastReject == EventReject::Vz) why = "|vz|";
    else if (m_lastReject == EventReject::Period) why = "PPG12 period";

    std::ostringstream os;
    os << "    event rejected by " << why << " gate – skip"
       << " | vz=" << std::fixed << std::setprecision(3) << m_vz;
    if (m_useVzCut) os << " (|vz|cut=" << m_vzCut << ")";
    os << " | nActiveTrig=" << activeTrig.size();

    if (!activeTrig.empty())
    {
      os << " | triggers={";
      for (std::size_t i = 0; i < activeTrig.size(); ++i)
      {
        if (i) os << ", ";
        os << activeTrig[i];
      }
      os << "}";
    }

    LOG(4, CLR_YELLOW, os.str());
    return Fun4AllReturnCodes::ABORTEVENT;
  }

  /* ------------------------------------------------------------------ */
  /* 3) Trigger counters (one per trigger) + Vertex-z QA                */
  /* ------------------------------------------------------------------ */

  fillPPG12Fig81SlimtreeVertexQA(topNode);

  bookPPG12PhotonYieldSchema(activeTrig);

  // Bump the per-trigger counter once per accepted event (and LOG fills via bumpHistFill)
  for (const auto& t : activeTrig)
  {
    auto itTrig = qaHistogramsByTrigger.find(t);
    if (itTrig == qaHistogramsByTrigger.end()) continue;

    auto& H = itTrig->second;

    // (1) per-trigger event counter
    const std::string hcnt = "cnt_" + t;
    if (auto hc = H.find(hcnt); hc != H.end())
    {
      static_cast<TH1I*>(hc->second)->Fill(1);
      bumpHistFill(t, hcnt);
    }

    // (2) vertex-z QA
    if (auto hvz = H.find("h_vertexZ"); hvz != H.end())
    {
      static_cast<TH1F*>(hvz->second)->Fill(m_vz);
      bumpHistFill(t, "h_vertexZ");
    }
  }

  /* ------------------------------------------------------------------ */
  /* 3b) PPG12 pp photon-slice stitching                                */
  /*     Offline pp photon merging uses fixed sigma ratios, not sigma/N. */
  /* ------------------------------------------------------------------ */
  PPG12PhotonSlice ppPhotonSlice = PPG12PhotonSlice::kNone;
  bool ppPhotonSliceContext = false;
  PPG12InclusiveJetSlice ppInclusiveJetSliceForWeight = PPG12InclusiveJetSlice::kNone;
  bool ppInclusiveJetContextForWeight = false;
  m_ppStitchDiagContext = false;
  m_ppStitchDiagKeep.fill(false);
  m_ppStitchDiagPhotonPt.fill(-1.0);
  if (m_isSim && !m_isAuAu)
  {
    ppPhotonSlice = ppg12PhotonSliceFromContext(Outfile);
    ppPhotonSliceContext = (ppPhotonSlice != PPG12PhotonSlice::kNone);
    ppInclusiveJetSliceForWeight = ppg12InclusiveJetSliceFromContext(Outfile);
    ppInclusiveJetContextForWeight =
      (ppInclusiveJetSliceForWeight != PPG12InclusiveJetSlice::kNone);
    m_ppStitchDiagContext = ppPhotonSliceContext;

    if (ppPhotonSliceContext)
    {
      double stitchLo = std::numeric_limits<double>::quiet_NaN();
      double stitchHi = std::numeric_limits<double>::quiet_NaN();
      const bool haveWindow = ppg12PhotonSliceWindow(ppPhotonSlice, stitchLo, stitchHi);

      auto bookStitch1F = [&](const std::string& name,
                              const std::string& title,
                              int nbins,
                              double xmin,
                              double xmax) -> TH1F*
      {
        HistMap& H = qaHistogramsByTrigger["SIM"];
        if (auto it = H.find(name); it != H.end())
        {
          return dynamic_cast<TH1F*>(it->second);
        }

        TDirectory* dir = (out ? out->GetDirectory("SIM") : nullptr);
        if (!dir && out) dir = out->mkdir("SIM");
        if (!dir) return nullptr;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        auto* h = RJMCWeighting::RJNewRawTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
        h->Sumw2();
        h->SetDirectory(dir);
        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
      };

      auto bookStitch2F = [&](const std::string& name,
                              const std::string& title,
                              int nxbins,
                              double xmin,
                              double xmax,
                              int nybins,
                              double ymin,
                              double ymax) -> TH2F*
      {
        HistMap& H = qaHistogramsByTrigger["SIM"];
        if (auto it = H.find(name); it != H.end())
        {
          return dynamic_cast<TH2F*>(it->second);
        }

        TDirectory* dir = (out ? out->GetDirectory("SIM") : nullptr);
        if (!dir && out) dir = out->mkdir("SIM");
        if (!dir) return nullptr;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        auto* h = RJMCWeighting::RJNewRawTH2F(name.c_str(), title.c_str(),
                                             nxbins, xmin, xmax,
                                             nybins, ymin, ymax);
        h->Sumw2();
        h->SetDirectory(dir);
        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
      };

      auto bookStitch1I = [&](const std::string& name,
                              const std::string& title,
                              int nbins,
                              double xmin,
                              double xmax) -> TH1I*
      {
        HistMap& H = qaHistogramsByTrigger["SIM"];
        if (auto it = H.find(name); it != H.end())
        {
          return dynamic_cast<TH1I*>(it->second);
        }

        TDirectory* dir = (out ? out->GetDirectory("SIM") : nullptr);
        if (!dir && out) dir = out->mkdir("SIM");
        if (!dir) return nullptr;

        TDirectory* prevDir = gDirectory;
        dir->cd();

        auto* h = RJMCWeighting::RJNewRawTH1I(name.c_str(), title.c_str(), nbins, xmin, xmax);
        h->SetDirectory(dir);
        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
      };

      auto fillStitchMetadata = [&](const std::string& name,
                                    const std::string& title,
                                    const double lo,
                                    const double hi,
                                    const double xsecPb,
                                    const double binWidth,
                                    const double truthDefCode,
                                    const double sampleBin) -> void
      {
        auto* hMeta = bookStitch1F(name, title, 8, 0.5, 8.5);
        if (!hMeta) return;
        hMeta->GetXaxis()->SetBinLabel(1, "events_processed");
        hMeta->GetXaxis()->SetBinLabel(2, "window_low_GeV");
        hMeta->GetXaxis()->SetBinLabel(3, "window_high_GeV");
        hMeta->GetXaxis()->SetBinLabel(4, "upper_edge_inclusive");
        hMeta->GetXaxis()->SetBinLabel(5, "bin_width_GeV");
        hMeta->GetXaxis()->SetBinLabel(6, "xsec_pb");
        hMeta->GetXaxis()->SetBinLabel(7, "truth_def_code");
        hMeta->GetXaxis()->SetBinLabel(8, "sample_bin");
        hMeta->Fill(1.0);
        hMeta->SetBinContent(2, lo);
        hMeta->SetBinContent(3, hi);
        hMeta->SetBinContent(4, 1.0);
        hMeta->SetBinContent(5, binWidth);
        hMeta->SetBinContent(6, xsecPb);
        hMeta->SetBinContent(7, truthDefCode);
        hMeta->SetBinContent(8, sampleBin);
      };

      auto fillExactPhotonFamily = [&](const std::string& prefix,
                                       const std::string& axisTitle,
                                       const double pt,
                                       const bool havePt,
                                       const bool passWindow) -> void
      {
        auto* hAll = bookStitch1F(prefix + "_maxPhotonPt_all",
                                  (prefix + "_maxPhotonPt_all;" + axisTitle + " [GeV];Events").c_str(),
                                  120, 0.0, 60.0);
        auto* hKept = bookStitch1F(prefix + "_maxPhotonPt_kept",
                                   (prefix + "_maxPhotonPt_kept;" + axisTitle + " [GeV];Events").c_str(),
                                   120, 0.0, 60.0);
        auto* hRejected = bookStitch1F(prefix + "_maxPhotonPt_rejected",
                                       (prefix + "_maxPhotonPt_rejected;" + axisTitle + " [GeV];Events").c_str(),
                                       120, 0.0, 60.0);
        if (hAll)
        {
          if (havePt) hAll->Fill(pt);
          bumpHistFill("SIM", hAll->GetName());
        }

        if (passWindow && hKept)
        {
          hKept->Fill(pt);
          bumpHistFill("SIM", hKept->GetName());
        }
        else if (hRejected)
        {
          if (havePt) hRejected->Fill(pt);
          bumpHistFill("SIM", hRejected->GetName());
        }
      };

      std::array<bool, 5> diagHaveTruth{};
      std::array<bool, 5> diagPass{};
      std::array<double, 5> diagPt{};
      diagPt.fill(-1.0);

      for (std::size_t iv = 0; iv < kPPStitchDiagVariants.size(); ++iv)
      {
        const PPStitchDiagVariant variant = kPPStitchDiagVariants[iv];
        const std::string key = ppStitchDiagKey(variant);
        const std::string titleKey = ppStitchDiagTitle(variant);

        diagPt[iv] = ppStitchDiagPhotonPt(topNode, m_truthInfo, variant);
        diagHaveTruth[iv] = (diagPt[iv] >= 0.0);
        diagPass[iv] = haveWindow && diagHaveTruth[iv] &&
                       (diagPt[iv] >= stitchLo) &&
                       (diagPt[iv] < stitchHi);

        m_ppStitchDiagPhotonPt[iv] = diagPt[iv];
        m_ppStitchDiagKeep[iv] = diagPass[iv];
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = "SIM";
          row.occurrence_kind = "PP_STITCH_SOURCE";
          row.source_code = static_cast<int>(iv) + 1;
          row.sample_code = ppg12PhotonSliceBin(ppPhotonSlice);
          row.decision = diagPass[iv] ? 1 : (diagHaveTruth[iv] ? 2 : 3);
          if (diagHaveTruth[iv]) row.source_photon_pt = diagPt[iv];
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }

        const std::string prefix = "h_ppPhotonStitch_" + key;
        if (auto* hAll = bookStitch1F(prefix + "_maxPhotonPt_all",
                                      (prefix + "_maxPhotonPt_all;" + titleKey + " p_{T}^{#gamma} [GeV];Events").c_str(),
                                      1000, 0.0, 100.0))
        {
          if (diagHaveTruth[iv]) hAll->Fill(diagPt[iv]);
          bumpHistFill("SIM", hAll->GetName());
        }

        if (diagPass[iv])
        {
          if (auto* hKept = bookStitch1F(prefix + "_maxPhotonPt_kept",
                                         (prefix + "_maxPhotonPt_kept;" + titleKey + " p_{T}^{#gamma} [GeV];Events").c_str(),
                                         1000, 0.0, 100.0))
          {
            hKept->Fill(diagPt[iv]);
            bumpHistFill("SIM", hKept->GetName());
          }
        }
        else
        {
          if (auto* hRejected = bookStitch1F(prefix + "_maxPhotonPt_rejected",
                                             (prefix + "_maxPhotonPt_rejected;" + titleKey + " p_{T}^{#gamma} [GeV];Events").c_str(),
                                             1000, 0.0, 100.0))
          {
            if (diagHaveTruth[iv]) hRejected->Fill(diagPt[iv]);
            bumpHistFill("SIM", hRejected->GetName());
          }
        }

        if (auto* hDecision = bookStitch1I(prefix + "_decision",
                                           (prefix + "_decision;decision;Events").c_str(),
                                           4, 0.5, 4.5))
        {
          hDecision->GetXaxis()->SetBinLabel(1, "kept");
          hDecision->GetXaxis()->SetBinLabel(2, "rejected");
          hDecision->GetXaxis()->SetBinLabel(3, "missing truth");
          hDecision->GetXaxis()->SetBinLabel(4, "unknown sample");
          hDecision->Fill(diagPass[iv] ? 1 : (diagHaveTruth[iv] ? 2 : 3));
          bumpHistFill("SIM", hDecision->GetName());
        }

        if (auto* hSample = bookStitch1I(prefix + "_sample",
                                         (prefix + "_sample;sample;Events").c_str(),
                                         3, 0.5, 3.5))
        {
          hSample->GetXaxis()->SetBinLabel(1, "PhotonJet5");
          hSample->GetXaxis()->SetBinLabel(2, "PhotonJet10");
          hSample->GetXaxis()->SetBinLabel(3, "PhotonJet20");
          hSample->Fill(ppg12PhotonSliceBin(ppPhotonSlice));
          bumpHistFill("SIM", hSample->GetName());
        }
      }

      const std::size_t g4Idx = ppStitchDiagIndex(PPStitchDiagVariant::kG4Stored);
      const double maxPhotonPt = diagPt[g4Idx];
      const bool haveTruth = diagHaveTruth[g4Idx];
      const bool passStitch = diagPass[g4Idx];
      const double fig5PhotonPt = ppg12MaxStoredTruthPhotonPt(topNode, m_truthInfo, true, 0.7);
      const bool fig5HaveTruth = (fig5PhotonPt >= 0.0);
      const bool fig5PassStitch = haveWindow && fig5HaveTruth &&
                                  ppg12WindowContains(fig5PhotonPt, stitchLo, stitchHi);
      const bool g4StoredPpg12PassStitch = haveWindow && haveTruth &&
                                           ppg12WindowContains(maxPhotonPt, stitchLo, stitchHi);
      const double sampleBin = static_cast<double>(ppg12PhotonSliceBin(ppPhotonSlice));
      const double photonXsecPb = ppg12PhotonSliceXsecPb(ppPhotonSlice);
      if (m_replayFoundationEnabled)
      {
        ReplayPPG12DiagnosticOccurrence row;
        row.trigger = "SIM";
        row.occurrence_kind = "PP_STITCH_SOURCE";
        row.source_code = 6;  // PPG12 eta<0.7 post-trigger source.
        row.sample_code = ppg12PhotonSliceBin(ppPhotonSlice);
        row.decision = fig5PassStitch ? 1 : (fig5HaveTruth ? 2 : 3);
        if (fig5HaveTruth) row.source_photon_pt = fig5PhotonPt;
        m_replayPPG12DiagnosticOccurrences.push_back(row);
      }

      fillStitchMetadata("h_ppPhotonStitch_ppg12TruthSpectrum_metadata",
                         "h_ppPhotonStitch_ppg12TruthSpectrum_metadata;metadata;value",
                         stitchLo,
                         std::isinf(stitchHi) ? 200.0 : stitchHi,
                         photonXsecPb,
                         0.5,
                         1.0,
                         sampleBin);

      fillExactPhotonFamily("h_ppPhotonStitch_ppg12TruthSpectrum_eta07",
                            "max truth photon p_{T}, |#eta|<0.7",
                            fig5PhotonPt,
                            fig5HaveTruth,
                            fig5PassStitch);

      fillExactPhotonFamily("h_ppPhotonStitch_ppg12TruthSpectrum_g4Stored",
                            "max stored truth photon p_{T}",
                            maxPhotonPt,
                            haveTruth,
                            g4StoredPpg12PassStitch);

      // Backward-compatible histogram names used by the quick plotting macros.
      if (auto* hAll = bookStitch1F("h_ppPhotonStitch_maxPhotonPt_all",
                                    "h_ppPhotonStitch_maxPhotonPt_all;max stored truth p_{T}^{#gamma} [GeV];Events",
                                    1000, 0.0, 100.0))
      {
        if (haveTruth) hAll->Fill(maxPhotonPt);
        bumpHistFill("SIM", hAll->GetName());
      }
      if (passStitch)
      {
        if (auto* hKept = bookStitch1F("h_ppPhotonStitch_maxPhotonPt_kept",
                                       "h_ppPhotonStitch_maxPhotonPt_kept;max stored truth p_{T}^{#gamma} [GeV];Events",
                                       1000, 0.0, 100.0))
        {
          hKept->Fill(maxPhotonPt);
          bumpHistFill("SIM", hKept->GetName());
        }
      }
      else if (auto* hRejected = bookStitch1F("h_ppPhotonStitch_maxPhotonPt_rejected",
                                              "h_ppPhotonStitch_maxPhotonPt_rejected;max stored truth p_{T}^{#gamma} [GeV];Events",
                                              1000, 0.0, 100.0))
      {
        if (haveTruth) hRejected->Fill(maxPhotonPt);
        bumpHistFill("SIM", hRejected->GetName());
      }
      if (auto* hDecision = bookStitch1I("h_ppPhotonStitch_decision",
                                         "h_ppPhotonStitch_decision;decision;Events",
                                         4, 0.5, 4.5))
      {
        hDecision->GetXaxis()->SetBinLabel(1, "kept");
        hDecision->GetXaxis()->SetBinLabel(2, "rejected");
        hDecision->GetXaxis()->SetBinLabel(3, "missing truth");
        hDecision->GetXaxis()->SetBinLabel(4, "unknown sample");
        hDecision->Fill(passStitch ? 1 : (haveTruth ? 2 : 3));
        bumpHistFill("SIM", hDecision->GetName());
      }
      if (auto* hSample = bookStitch1I("h_ppPhotonStitch_sample",
                                       "h_ppPhotonStitch_sample;sample;Events",
                                       3, 0.5, 3.5))
      {
        hSample->GetXaxis()->SetBinLabel(1, "PhotonJet5");
        hSample->GetXaxis()->SetBinLabel(2, "PhotonJet10");
        hSample->GetXaxis()->SetBinLabel(3, "PhotonJet20");
        hSample->Fill(ppg12PhotonSliceBin(ppPhotonSlice));
        bumpHistFill("SIM", hSample->GetName());
      }

      // PPG12 IAN Fig. 5 parity diagnostic: leading stored truth photon with
      // |eta| < 0.7. Keep the legacy name, but use the PPG12
      // TruthSpectrumCheck.C binning and inclusive upper-edge semantics.
      if (auto* hAll = bookStitch1F("h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_all",
                                    "h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_all;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
                                    120, 0.0, 60.0))
      {
        if (fig5HaveTruth) hAll->Fill(fig5PhotonPt);
        bumpHistFill("SIM", hAll->GetName());
      }
      if (fig5PassStitch)
      {
        if (auto* hKept = bookStitch1F("h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_kept",
                                       "h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_kept;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
                                       120, 0.0, 60.0))
        {
          hKept->Fill(fig5PhotonPt);
          bumpHistFill("SIM", hKept->GetName());
        }
      }
      else if (auto* hRejected = bookStitch1F("h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_rejected",
                                              "h_ppPhotonStitch_ppg12Fig5_maxPhotonPt_rejected;max stored truth p_{T}^{#gamma}, |#eta|<0.7 [GeV];Events",
                                              120, 0.0, 60.0))
      {
        if (fig5HaveTruth) hRejected->Fill(fig5PhotonPt);
        bumpHistFill("SIM", hRejected->GetName());
      }

      auto fillCompare2D = [&](PPStitchDiagVariant yVar)
      {
        const std::size_t yIdx = ppStitchDiagIndex(yVar);
        if (!diagHaveTruth[g4Idx] || !diagHaveTruth[yIdx]) return;

        const std::string name = std::string("h2_ppPhotonStitch_") + ppStitchDiagKey(yVar) + "_vs_g4Stored";
        const std::string title = name + ";G4 stored truth p_{T}^{#gamma} [GeV];" +
                                  ppStitchDiagTitle(yVar) + std::string(" p_{T}^{#gamma} [GeV]");
        if (auto* h2 = bookStitch2F(name, title, 250, 0.0, 50.0, 250, 0.0, 50.0))
        {
          h2->Fill(diagPt[g4Idx], diagPt[yIdx]);
          bumpHistFill("SIM", h2->GetName());
        }
      };
      fillCompare2D(PPStitchDiagVariant::kHepMCParent);
      fillCompare2D(PPStitchDiagVariant::kHepMCParentStable);
      fillCompare2D(PPStitchDiagVariant::kHepMCAnyPhoton);
      fillCompare2D(PPStitchDiagVariant::kG4NoEmbed);

      // Production pp PhotonJet stitching uses one event-ownership decision:
      // the stored G4 truth photon pT in the PPG12 sample window. Alternate
      // HepMC/G4-no-embed variants above are QA only and must not keep events.
      if (!passStitch)
      {
        LOG(5, CLR_YELLOW,
            "    [pp photon stitch] reject event: canonical G4-stored photon outside sample window"
            << " | sample=" << ppg12PhotonSliceName(ppPhotonSlice)
            << " | max stored truth pT^gamma=" << std::fixed << std::setprecision(3) << maxPhotonPt
            << " | haveTruth=" << haveTruth
            << " | keep window=[" << stitchLo << ", " << stitchHi << "]");
        return Fun4AllReturnCodes::ABORTEVENT;
      }

      LOG(6, CLR_GREEN,
          "    [pp photon stitch] process event"
          << " | sample=" << ppg12PhotonSliceName(ppPhotonSlice)
          << " | g4Stored pT^gamma=" << std::fixed << std::setprecision(3) << maxPhotonPt
          << " | keep window=[" << stitchLo << ", " << stitchHi << "]");
    }
    else if (!ppInclusiveJetContextForWeight)
    {
      if (m_ppg12PhotonYieldEnabled)
      {
        LOG(0, CLR_RED,
            "    [PPG12_SIM_WEIGHT][FATAL] canonical pp-SIM output/context did not identify "
            "a PhotonJet5/10/20 or inclusive-jet slice; refusing unity-weight fallback"
            << " | outfile=\"" << Outfile << "\"");
        return Fun4AllReturnCodes::ABORTEVENT;
      }
    }
  }
  const bool ppPpg12McWeightContext = ppPhotonSliceContext || ppInclusiveJetContextForWeight;

  if (m_isSim && !m_isAuAu && ppPpg12McWeightContext && m_vertexReweightOn && m_vertexReweightH)
  {
    m_mcVertexWeight = ppg12TruthVertexWeight(m_vertexReweightH, m_truthVz);
    if (m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldDoubleInteraction)
    {
      if (m_ppg12PeriodStrictDoubleMB &&
          (!std::isfinite(m_truthVzMB) || m_truthVzMB <= kPPG12TruthVtxSentinelThreshold))
      {
        LOG(1, CLR_RED,
            "    [PPG12_PERIOD_CONTRACT][REJECT] double-interaction PPG12 SIM event lacks a usable "
            "MB-overlay truth vertex for the second w(z) factor"
            << " | truthVz=" << m_truthVz
            << " | truthVzMB=" << m_truthVzMB
            << " | period=" << m_ppg12PeriodKey);
        return Fun4AllReturnCodes::ABORTEVENT;
      }
      m_mcVertexWeight *= ppg12TruthVertexWeight(m_vertexReweightH, m_truthVzMB);
    }
    if (m_mcVertexWeight < 0.0)
    {
      return Fun4AllReturnCodes::ABORTEVENT;
    }
  }

  if (m_isSim && !m_isAuAu && ppPpg12McWeightContext)
  {
    const int laneCode = ppPhotonSliceContext ? 1 : 2;
    const double sliceFactor = ppPhotonSliceContext
        ? (ppg12PhotonSliceXsecPb(ppPhotonSlice) / kPPG12Photon20CrossPb)
        : (ppg12InclusiveJetSliceXsecPb(ppInclusiveJetSliceForWeight) / kPPG12Jet50CrossPb);

    // V13 diagnostic-only pre-weight truth-label observer.
    //
    // The V12 foreground diagnostic intentionally ran without the canonical
    // PPG12 yield/period-weight contract, so accepted PhotonJet20 stitch
    // events stopped at configurePPG12SimEventWeight() before reaching
    // processCandidates().  When explicitly requested, inspect the current
    // photon container here using the same truth-map and cluster-truth-track
    // classifier used by processCandidates().  This observer is read-only:
    // it does not fill ROOT objects, mutate candidate state, or bypass the
    // unchanged weight gate below.
    const bool the134TruthLabelDiagnostic =
        RJReplayRuntimeV1::envEnabled(
            "RJ_THE134_TRUTH_LABEL_PREWEIGHT_DIAGNOSTIC_V1");
    if (the134TruthLabelDiagnostic &&
        ppPhotonSliceContext &&
        ppPhotonSlice == PPG12PhotonSlice::kPhoton20)
    {
      PHHepMCGenEventMap* hepmcmap =
          findNode::getClass<PHHepMCGenEventMap>(topNode, "PHHepMCGenEventMap");
      PHHepMCGenEvent* selectedHepMC = nullptr;
      int selectedMapKey = std::numeric_limits<int>::min();
      int selectedEmbeddingId = std::numeric_limits<int>::min();
      std::size_t hepmcMapSize = 0;

      if (hepmcmap)
      {
        hepmcMapSize = hepmcmap->size();
        selectedHepMC = hepmcmap->get(0);
        if (selectedHepMC)
        {
          selectedMapKey = 0;
        }
        else
        {
          selectedHepMC = hepmcmap->get(1);
          if (selectedHepMC)
          {
            selectedMapKey = 1;
          }
        }
        if (!selectedHepMC && !hepmcmap->empty())
        {
          selectedMapKey = hepmcmap->begin()->first;
          selectedHepMC = hepmcmap->begin()->second;
        }
        if (selectedHepMC)
        {
          selectedEmbeddingId = selectedHepMC->get_embedding_id();
        }
      }

      HepMC::GenEvent* selectedEvent =
          selectedHepMC ? selectedHepMC->getEvent() : nullptr;

      std::unique_ptr<CaloRawClusterEval> clustereval(
          new CaloRawClusterEval(topNode, "CEMC"));
      clustereval->set_usetowerinfo(true);
      clustereval->next_event(topNode);
      if (!clustereval->has_reduced_node_pointers())
      {
        clustereval->set_usetowerinfo(false);
        clustereval->next_event(topNode);
      }
      const bool haveCaloEval = clustereval->has_reduced_node_pointers();

      const TruthSignalPhotonMap truthSignalByTrackId =
          buildPPG12TruthSignalPhotonMap(topNode);

      std::size_t candidateCount = 0;
      if (m_photons)
      {
        const auto range = m_photons->getClusters();
        for (auto it = range.first; it != range.second; ++it)
        {
          ++candidateCount;
        }
      }

      std::cout
          << "THE134_PPG12_TRUTH_LABEL_PREWEIGHT_DIAG_V1"
          << " stage=PRE_WEIGHT_GATE"
          << " record=EVENT_CONTEXT"
          << " event=" << event_count
          << " sample=" << ppg12PhotonSliceName(ppPhotonSlice)
          << " lane_code=" << laneCode
          << " photon_yield_enabled=" << (m_ppg12PhotonYieldEnabled ? 1 : 0)
          << " period_contract_enabled=" << (m_ppg12PeriodContractEnabled ? 1 : 0)
          << " weight_gate_bypass=0"
          << " photon_container_present=" << (m_photons ? 1 : 0)
          << " candidate_count=" << candidateCount
          << " hepmc_map_size=" << hepmcMapSize
          << " selected_map_key=" << selectedMapKey
          << " selected_embedding_id=" << selectedEmbeddingId
          << " hepmc_event_present=" << (selectedEvent ? 1 : 0)
          << " calo_eval_present=" << (haveCaloEval ? 1 : 0)
          << " strict_signal_map_size=" << truthSignalByTrackId.size()
          << std::endl;

      if (m_photons)
      {
        const auto range = m_photons->getClusters();
        int candidateIndex = 0;
        for (auto it = range.first; it != range.second; ++it, ++candidateIndex)
        {
          const RawCluster* rc = it->second;
          const auto* photon = dynamic_cast<const PhotonClusterv1*>(rc);
          const double recoEt = photon
              ? photon->get_shower_shape_parameter("cluster_pt")
              : std::numeric_limits<double>::quiet_NaN();

          TruthSignalPhotonInfo matchedTruth;
          int truthTrackId = -1;
          float truthEContrib = std::numeric_limits<float>::lowest();
          bool isPPG12Signal = false;
          if (haveCaloEval && rc)
          {
            isPPG12Signal =
                classifyRecoPhotonWithPPG12TruthTrack(rc,
                                                      *clustereval,
                                                      truthSignalByTrackId,
                                                      matchedTruth,
                                                      truthTrackId,
                                                      truthEContrib);
          }

          const char* reason = "CALO_EVAL_UNAVAILABLE";
          if (!rc)
          {
            reason = "NULL_CLUSTER";
          }
          else if (haveCaloEval)
          {
            if (truthSignalByTrackId.empty())
            {
              reason = "EMPTY_SIGNAL_MAP";
            }
            else if (truthEContrib == std::numeric_limits<float>::lowest())
            {
              reason = "NO_MAX_PRIMARY";
            }
            else if (isPPG12Signal)
            {
              reason = "MATCH";
            }
            else
            {
              reason = "PRIMARY_NOT_IN_MAP";
            }
          }

          std::ostringstream diagnosticLine;
          diagnosticLine
              << "THE134_PPG12_TRUTH_LABEL_PREWEIGHT_DIAG_V1"
              << " stage=PRE_WEIGHT_GATE"
              << " record=CANDIDATE"
              << " event=" << event_count
              << " candidate_index=" << candidateIndex
              << " reco_et=" << std::setprecision(17) << recoEt
              << " reason=" << reason
              << " truth_track_id=" << truthTrackId
              << " truth_energy_contribution=" << truthEContrib
              << " strict_signal_map_size=" << truthSignalByTrackId.size();
          std::cout << diagnosticLine.str() << std::endl;
        }
      }
    }
    // End V13 diagnostic-only pre-weight truth-label observer.

    if (!configurePPG12SimEventWeight(sliceFactor, laneCode))
    {
      return Fun4AllReturnCodes::ABORTEVENT;
    }
  }

  // SIM pi0 fill: not trigger-gated, only vertex-gated (mirrors pp pi0 logic).
  // For pp photon+jet SIM this is filled after stitching and vertex weighting.
  if (m_isSim && m_doPi0Analysis)
  {
    const bool passPi0Vz = (!m_useVzCut || std::fabs(m_vz) < m_vzCut);
    if (passPi0Vz && m_clus && m_clus_nocorr)
    {
      const std::string pi0Trig = "SIM";
      fillPi0MassVsPtHistograms(pi0Trig, m_clus, true);
      fillPi0MassVsPtHistograms(pi0Trig, m_clus_nocorr, false);
    }
  }

  /* ------------------------------------------------------------------ */
  /* 4) Centrality lookup (Au+Au only)                                  */
  /*     Keep m_centBin = -1 in pp (acts as minimum-bias)               */
  /* ------------------------------------------------------------------ */
  if (m_isAuAu)
  {
    CentralityInfo* central =
      findNode::getClass<CentralityInfo>(topNode, "CentralityInfo");

    if (!central)
    {
      LOG(4, CLR_YELLOW,
          "    CentralityInfo node missing (Au+Au) – ABORTEVENT");
      return Fun4AllReturnCodes::ABORTEVENT;
    }

    const float centile =
      central->get_centrality_bin(CentralityInfo::PROP::mbd_NS);

    if (!std::isfinite(centile) || centile < 0.f)
    {
      LOG(4, CLR_YELLOW,
          "    invalid mbd_NS centile – treating as minimum-bias (0–100%)");
      m_centBin = -1;
    }
    else
    {
      m_centBin = static_cast<int>(centile);
      LOG(5, CLR_GREEN, "    centrality bin = " << m_centBin << '%');
    }

    // Fill centrality histogram if booked under each active trigger
    if (centile >= 0.f && centile <= 100.f)
    {
      for (const auto& t : activeTrig)
      {
        auto itTrig = qaHistogramsByTrigger.find(t);
        if (itTrig == qaHistogramsByTrigger.end()) continue;

        auto& H = itTrig->second;
        if (auto hc = H.find("h_centrality"); hc != H.end())
        {
          static_cast<TH1F*>(hc->second)->Fill(centile);
          bumpHistFill(t, "h_centrality");
        }
      }
    }
  }
  else
  {
    // pp: no centrality
    m_centBin = -1;
  }

  /* ------------------------------------------------------------------ */
  /* 5) Vertex-z guard (applies to both, primarily relevant for Au+Au)  */
  /* ------------------------------------------------------------------ */
  if (!std::isfinite(m_vz) || (m_useVzCut && std::fabs(m_vz) >= m_vzCut))
  {
    LOG(4, CLR_YELLOW,
        "    Vertex-z (" << m_vz << " cm) outside bounds – skip event");
    return Fun4AllReturnCodes::ABORTEVENT;
  }

  const int centIdxForJets = (m_isAuAu ? findCentBin(m_centBin) : -1);
  for (const auto& kv : m_jets)
  {
    fillInclusiveJetQA(activeTrig, centIdxForJets, kv.first);
  }

  processCandidates(topNode, activeTrig);

  ++m_bk.evt_accepted;
  LOG(4, CLR_GREEN, "  [process_event] – completed OK");
  return Fun4AllReturnCodes::EVENT_OK;
}

int RecoilJets::ResetEvent(PHCompositeNode*)
{

  m_centBin = -1;

  return Fun4AllReturnCodes::EVENT_OK;
}

int RecoilJets::Reset(PHCompositeNode*)
{
  return Fun4AllReturnCodes::EVENT_OK;
}

// --------------------------------------------------------------------------
//  End – Diagnostics, robust against dangling pointers
// --------------------------------------------------------------------------
int RecoilJets::End(PHCompositeNode*)
{
  auto warn = [&](const std::string& m)
  { std::cerr << CLR_YELLOW << "[End] " << m << CLR_RESET << '\n'; };

  auto info = [&](int lvl, const std::string& m)
  { LOG(lvl, CLR_GREEN, "[End] " << m); };

  if (m_ppg12Fig6EventCanaryEnabled)
  {
    if (m_ppg12Fig6EventCanaryOut.is_open())
    {
      m_ppg12Fig6EventCanaryOut.flush();
      m_ppg12Fig6EventCanaryOut.close();
    }

    std::ofstream summaryOut(m_ppg12Fig6EventCanarySummaryPath.c_str(), std::ios::out);
    if (summaryOut)
    {
      const auto slice = ppg12InclusiveJetSliceFromContext(Outfile);
      const double denomEvents = static_cast<double>(std::max<long long>(1, m_ppg12Fig6CanaryEventsSeen));
      const double meanXsecFactor = m_ppg12Fig6CanarySumXsecFactor / denomEvents;
      const double meanLumiFactor = m_ppg12Fig6CanarySumLumiFactor / denomEvents;
      const double meanMixFactor = m_ppg12Fig6CanarySumMixFactor / denomEvents;
      const double meanVertexWeight = m_ppg12Fig6CanarySumVertexWeight / denomEvents;
      const double meanFinalFillWeight = m_ppg12Fig6CanarySumFinalFillWeight / denomEvents;
      const double ratioToIAN =
          (std::isfinite(m_ppg12Fig6CanaryIANSuffixIntegral) &&
           m_ppg12Fig6CanaryIANSuffixIntegral != 0.0)
          ? (m_ppg12Fig6CanaryWeightedOwnedIntegral / m_ppg12Fig6CanaryIANSuffixIntegral)
          : std::numeric_limits<double>::quiet_NaN();
      const double ratioToTrue =
          (std::isfinite(m_ppg12Fig6CanaryTruePeriodIntegral) &&
           m_ppg12Fig6CanaryTruePeriodIntegral != 0.0)
          ? (m_ppg12Fig6CanaryWeightedOwnedIntegral / m_ppg12Fig6CanaryTruePeriodIntegral)
          : std::numeric_limits<double>::quiet_NaN();
      const double oldClosureDelta =
          std::isfinite(ratioToIAN) ? (ratioToIAN / 1.94) : std::numeric_limits<double>::quiet_NaN();

      auto writeNum = [&](double v)
      {
        if (std::isfinite(v))
        {
          summaryOut << std::setprecision(17) << v;
        }
      };

      summaryOut
          << "sample,component,period,events_seen,events_with_valid_truth_jets,"
          << "events_in_owned_window,raw_owned_window_entries,weighted_owned_window_integral,"
          << "mean_xsec_factor,mean_lumi_factor,mean_mix_factor,mean_vertex_weight,"
          << "mean_final_fill_weight,ian_no_suffix_integral,true_period_combined_integral,"
          << "ratio_to_ian_no_suffix,ratio_to_true_period_combined,"
          << "old_flat_1p94_closure_delta,closure_direction_note\n";
      summaryOut << ppg12InclusiveJetSliceName(slice) << ','
                 << (m_ppg12PhotonYieldDoubleInteraction ? "DI" : "SI") << ','
                 << m_ppg12PeriodKey << ','
                 << m_ppg12Fig6CanaryEventsSeen << ','
                 << m_ppg12Fig6CanaryValidTruthJets << ','
                 << m_ppg12Fig6CanaryOwnedWindowEvents << ','
                 << m_ppg12Fig6CanaryRawOwnedEntries << ',';
      writeNum(m_ppg12Fig6CanaryWeightedOwnedIntegral); summaryOut << ',';
      writeNum(meanXsecFactor); summaryOut << ',';
      writeNum(meanLumiFactor); summaryOut << ',';
      writeNum(meanMixFactor); summaryOut << ',';
      writeNum(meanVertexWeight); summaryOut << ',';
      writeNum(meanFinalFillWeight); summaryOut << ',';
      writeNum(m_ppg12Fig6CanaryIANSuffixIntegral); summaryOut << ',';
      writeNum(m_ppg12Fig6CanaryTruePeriodIntegral); summaryOut << ',';
      writeNum(ratioToIAN); summaryOut << ',';
      writeNum(ratioToTrue); summaryOut << ',';
      writeNum(oldClosureDelta); summaryOut << ',';
      summaryOut << "requires_reference_integrals_for_direction\n";
      LOG(1, CLR_MAGENTA,
          "[End][PPG12_FIG6_EVENT_CANARY] wrote "
          << m_ppg12Fig6EventCanaryRowsWritten << " event rows to "
          << m_ppg12Fig6EventCanaryPath << " and summary to "
          << m_ppg12Fig6EventCanarySummaryPath);
    }
    else
    {
      warn("PPG12 Fig.6 event canary summary could not be opened: " +
           m_ppg12Fig6EventCanarySummaryPath);
    }
  }

  if (m_ppg12EisoPathCanaryEnabled)
  {
    if (m_ppg12EisoPathCanaryOut.is_open())
    {
      m_ppg12EisoPathCanaryOut.flush();
      m_ppg12EisoPathCanaryOut.close();
    }
    if (m_ppg12EisoConeMemberCanaryOut.is_open())
    {
      m_ppg12EisoConeMemberCanaryOut.flush();
      m_ppg12EisoConeMemberCanaryOut.close();
    }
    LOG(1, CLR_MAGENTA,
        "[End][PPG12_EISO_PATH_CANARY] wrote "
        << m_ppg12EisoPathCanaryRowsWritten << " rows to "
        << m_ppg12EisoPathCanaryPath << " and "
        << m_ppg12EisoConeMemberCanaryRowsWritten << " cone-member rows to "
        << m_ppg12EisoConeMemberCanaryPath);
  }

  //--------------------------------------------------------------------
  // 1. Basic checks on the output file pointer
  //--------------------------------------------------------------------
  if (!out)
  {
    warn("TFile* 'out' is nullptr – nothing to write");
    return Fun4AllReturnCodes::ABORTEVENT;
  }
  if (!out->IsOpen())
  {
    warn("Output file is *not* open (" + std::string(out->GetName()) + ")");
    return Fun4AllReturnCodes::ABORTEVENT;
  }

  finalizePPG12SimWeightAudit();

  // The event-leading response family is a fixed SIM schema. Prebook every
  // component so a zero-population canary is distinguishable from a missing
  // producer or a failed write.
  if (m_isSim && !qaHistogramsByTrigger.empty() && !m_jets.empty())
  {
    std::vector<std::string> schemaTriggers;
    schemaTriggers.reserve(qaHistogramsByTrigger.size());
    for (const auto& [trig, unused] : qaHistogramsByTrigger)
    {
      (void) unused;
      schemaTriggers.push_back(trig);
    }

    std::vector<int> schemaCentIndices{-1};
    if (m_isAuAu && m_centEdges.size() >= 2)
    {
      schemaCentIndices.clear();
      for (std::size_t i = 0; i + 1 < m_centEdges.size(); ++i)
        schemaCentIndices.push_back(static_cast<int>(i));
    }

    static constexpr const char* kLeadingResponseComponents[] = {
      "reco", "truth", "response", "fake", "miss", "selectionLoss"
    };
    std::size_t nLeadingResponseSchemaObjects = 0;
    for (const auto& trig : schemaTriggers)
    {
      for (const auto& [baseRKey, unusedJets] : m_jets)
      {
        (void) unusedJets;
        for (const double jetPtCut : activeJetPtCuts())
        {
          for (const double dphiCut : activeBackToBackCuts())
          {
            const std::string histRKey =
              histRKeyForJetPtAndDphi(baseRKey, jetPtCut, dphiCut);
            for (const int centIdx : schemaCentIndices)
            {
              for (const char* component : kLeadingResponseComponents)
              {
                if (getOrBookUnfoldLeadPtXJComponent(
                      trig, histRKey, centIdx, component))
                  ++nLeadingResponseSchemaObjects;
              }
            }
          }
        }
      }
    }
    LOG(1, CLR_GREEN,
        "[THE221_LEADING_RESPONSE_SCHEMA] prebooked="
        << nLeadingResponseSchemaObjects
        << " triggers=" << schemaTriggers.size()
        << " radii=" << m_jets.size()
        << " centrality_views=" << schemaCentIndices.size());
  }

  //--------------------------------------------------------------------
  // 2. Write histograms trigger-by-trigger
  //--------------------------------------------------------------------
  std::size_t nHistExpected = 0, nHistWritten = 0;

  for (auto& [trig, hMap] : qaHistogramsByTrigger)
  {
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    dir->cd();

    std::size_t nExpThis = 0, nWrtThis = 0;

    for (auto& [key, obj] : hMap)
    {
      ++nHistExpected;
      ++nExpThis;

      TH1* h = dynamic_cast<TH1*>(obj);
      if (!h)
      {
        warn("Object '" + key + "' (trigger " + trig + ") is not TH1 – skipped");
        continue;
      }

      const bool keepEmptyStitchParityHist =
        key.rfind("h_ppPhotonStitch_ppg12TruthSpectrum_", 0) == 0 ||
        key.rfind("h_ppPhotonStitch_ppg12Fig5_", 0) == 0 ||
        key.rfind("h_ppInclusiveJetStitch_ppg12TruthSpectrum_", 0) == 0 ||
        key.rfind("h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_", 0) == 0 ||
        key.rfind("h_ppInclusiveJetStitch_r04_", 0) == 0;
      const bool keepEmptyLeadingResponseHist =
        key.rfind("h2_unfoldReco_pTgamma_xJ_lead_", 0) == 0 ||
        key.rfind("h2_unfoldTruth_pTgamma_xJ_lead_", 0) == 0 ||
        key.rfind("h2_unfoldResponse_pTgamma_xJ_lead_", 0) == 0 ||
        key.rfind("h2_unfoldRecoFakes_pTgamma_xJ_lead_", 0) == 0 ||
        key.rfind("h2_unfoldTruthMisses_pTgamma_xJ_lead_", 0) == 0 ||
        key.rfind("h2_unfoldTruthSelectionLoss_pTgamma_xJ_lead_", 0) == 0;
      const bool keepEmptyPPG12TableQAHist =
        m_ppg12TableQAEnabled &&
        (key.rfind("h1d_", 0) == 0 || key.rfind("h2d_", 0) == 0) &&
        key.find("_eta0_pt") != std::string::npos &&
        key.find("_cut") != std::string::npos;
	      const bool keepEmptyReplayCaptureWitnessHist =
	        m_replayFoundationCaptureWitnessEnabled &&
	        key.rfind("h_the119_capture_diagnostic_", 0) == 0;
	      const bool keepEmptyPPG12PhotonYieldHist =
	        m_ppg12PhotonYieldEnabled &&
	        (key == "h_all_cluster_0" ||
         key == "h_common_cluster_0" ||
         key == "h_all_cluster_signal_0" ||
         key == "h_all_cluster_notmatch_0" ||
         key == "h_common_cluster_signal_0" ||
         key == "h_common_cluster_notmatch_0" ||
         key == "h_tight_cluster_0" ||
         key == "h_tight_cluster_signal_0" ||
         key == "h_tight_cluster_notmatch_0" ||
         key == "h_tight_iso_cluster_0" ||
         key == "h_tight_iso_cluster_signal_0" ||
         key == "h_tight_iso_cluster_notmatch_0" ||
         key == "h_tight_noniso_cluster_0" ||
         key == "h_tight_noniso_cluster_signal_0" ||
         key == "h_tight_noniso_cluster_notmatch_0" ||
         key == "h_nontight_iso_cluster_0" ||
         key == "h_nontight_iso_cluster_signal_0" ||
         key == "h_nontight_iso_cluster_notmatch_0" ||
         key == "h_nontight_noniso_cluster_0" ||
         key == "h_nontight_noniso_cluster_signal_0" ||
         key == "h_nontight_noniso_cluster_notmatch_0" ||
         key == "h_pT_reco_response_0" ||
         key == "h_pT_reco_half_response_0" ||
         key == "h_pT_reco_secondhalf_response_0" ||
         key == "h_pT_reco_fake_0" ||
         key == "h_truth_pT_0" ||
         key == "h_truth_pT_novtx_0" ||
         key == "h_truth_pT_vertexcut_0" ||
         key == "h_truth_pT_vertexcut_mbd_cut_0" ||
         key == "h_truth_pT_vertexcut_mbd_north_cut_0" ||
         key == "h_truth_pT_vertexcut_mbd_south_cut_0" ||
         key == "h_pT_truth_response_0" ||
         key == "h_pT_truth_half_response_0" ||
         key == "h_pT_truth_secondhalf_response_0" ||
         key == "h_response_full_0" ||
         key == "h_response_half_0" ||
	         key.rfind("h_ppg12_fig36_", 0) == 0 ||
	         key.rfind("h2_ppg12_fig36_", 0) == 0 ||
	         key.rfind("h_ppg12_fig37_input_", 0) == 0 ||
	         key.rfind("h2_ppg12_fig37_input_", 0) == 0 ||
	         key.rfind("h_ppg12_fig11_ET_isoET_eta0_", 0) == 0 ||
	         key.rfind("h2_ppg12_fig8_", 0) == 0 ||
	         key.rfind("h_ppg12_fig3_", 0) == 0 ||
	         key.rfind("h_ppg12_fig8_", 0) == 0);

      if (h->GetEntries() == 0 &&
          !keepEmptyStitchParityHist &&
          !keepEmptyLeadingResponseHist &&
          !keepEmptyPPG12TableQAHist &&
          !keepEmptyReplayCaptureWitnessHist &&
          !keepEmptyPPG12PhotonYieldHist)
      {
        if (Verbosity() > 1)
          warn("Histogram '" + key + "' (trigger " + trig + ") has 0 entries – skipped");
        continue;
      }

      try
      {
        if (h->Write("", TObject::kOverwrite) > 0)
        {
          ++nHistWritten;
          ++nWrtThis;
        }
        else
        {
          warn("Write() returned 0 for '" + key + "' (trigger " + trig + ")");
        }
      }
      catch (const std::exception& e)
      {
        warn("Exception while writing '" + key + "' – " + std::string(e.what()));
      }
    }

    info(1, "trigger '" + trig + "': " + std::to_string(nWrtThis) + " / "
               + std::to_string(nExpThis) + " histograms written");
    out->cd();
  }

  //--------------------------------------------------------------------
  // 3. Human-readable histogram summary (must run *before* file deletion)
  //--------------------------------------------------------------------
  if (Verbosity() > 0)
  {
    std::cout << "\n\033[1mHistogram summary\033[0m\n"
              << "\033[1mTrigger                        │ Histogram                           │  Entries\033[0m\n"
              << "-------------------------------------------------------------------------------\n";

    for (const auto& [trig, hMap] : qaHistogramsByTrigger)
    {
      for (const auto& [key, obj] : hMap)
      {
        const TH1* h = dynamic_cast<const TH1*>(obj);
        if (!h) continue;
        if (h->GetEntries() == 0) continue;  // only list filled ones

        std::cout << std::left  << std::setw(30) << trig << " │ "
                  << std::setw(32) << key  << " │ "
                  << std::right << std::setw(10)
                  << static_cast<Long64_t>(h->GetEntries()) << '\n';
      }
    }
  }

    // --------------------------------------------------------------------
    // 4. Analysis summary (verbosity-controlled)
    // --------------------------------------------------------------------
    if (Verbosity() >= 1)
    {
      const char* dsLabel = (m_isSim ? "SIM" : (m_isAuAu ? "Au+Au" : "p+p"));

      std::cout << "\n\033[1mSelection summary (dataset: " << dsLabel
                << ", events=" << event_count << ")\033[0m\n";

      // -------------------- ABCD summary (existing) --------------------
      for (const auto& kvT : m_catByTrig)
      {
        const std::string& trig = kvT.first;

        std::cout << "\n\033[1mTrigger: " << trig << "\033[0m\n";

        std::cout << "ABCD (PPG12): iso=Eiso<thrIso; nSB=Eiso>thrIso+gap; GAP excluded; "
                     "NT2=non-tight(>=2 fails); Neither(1 fail) excluded.\n";

        std::cout << "slice                                 |  A(iso,T) | B(nSB,T)   | C(iso,NT2) | D(nSB,NT2)  |  seen\n";
        std::cout << "--------------------------------------+-----------+-----------+------------+-------------+-------\n";

        std::vector<std::string> keys;
        keys.reserve(kvT.second.size());
        for (const auto& s : kvT.second) keys.push_back(s.first);
        std::sort(keys.begin(), keys.end());

        for (const auto& sfx : keys)
        {
          const CatStat& S = kvT.second.at(sfx);
          std::ostringstream lab;
          lab << (sfx.empty() ? "<all>" : sfx);

          std::cout << std::left  << std::setw(38) << lab.str() << " | "
                    << std::right << std::setw(9)  << S.n_iso_tight       << " | "
                    << std::setw(9)  << S.n_nonIso_tight    << " | "
                    << std::setw(10) << S.n_iso_nonTight    << " | "
                    << std::setw(11) << S.n_nonIso_nonTight << " | "
                    << std::setw(5)  << S.seen              << "\n";
        }
      }

      // -------------------- Photon cutflow (existing) --------------------
      printCutSummary();


      // =========================================================================
      //  Jet matching + unfolding summary (computed from already-filled hists)
      //
      // Notes:
      //  - "match status" is filled ONCE per event that has a leading iso∧tight γ
      //    (one fill per rKey), using:
      //      1=NoJetPt, 2=NoJetEta, 3=NoBackToBack, 4=Matched
      //  - Unfolding TH2 "reco" is filled once per (leading iso∧tight γ) × (each recoil jet).
      // =========================================================================
      auto starts_with = [](const std::string& s, const std::string& pfx) -> bool
      {
        return (s.size() >= pfx.size() && std::equal(pfx.begin(), pfx.end(), s.begin()));
      };

      auto fmt_frac = [](double num, double den) -> std::string
      {
        std::ostringstream os;
        if (den <= 0.0) { os << "n/a"; return os.str(); }
        os << std::fixed << std::setprecision(3) << (num / den);
        return os.str();
      };

      struct TH2Stats { double entries = 0.0; double inrange = 0.0; double meanY = std::numeric_limits<double>::quiet_NaN(); };

      auto th2_y_stats = [&](const TH2* h) -> TH2Stats
      {
        TH2Stats S;
        if (!h) return S;

        S.entries = h->GetEntries();

        const int nx = h->GetNbinsX();
        const int ny = h->GetNbinsY();

        double sumW = 0.0;
        double sumY = 0.0;

        for (int ix = 1; ix <= nx; ++ix)
        {
          for (int iy = 1; iy <= ny; ++iy)
          {
            const double w = h->GetBinContent(ix, iy);
            if (w == 0.0) continue;
            const double y = h->GetYaxis()->GetBinCenter(iy);
            sumW += w;
            sumY += w * y;
          }
        }

        S.inrange = sumW;
        if (sumW > 0.0) S.meanY = sumY / sumW;
        return S;
      };

      auto sum_th1_by_prefix = [&](const HistMap& H, const std::string& pfx,
                                   double& outEntries, double& outMean) -> void
      {
        double n = 0.0;
        double sumMean = 0.0;

        for (const auto& kv : H)
        {
          const std::string& name = kv.first;
          if (!starts_with(name, pfx)) continue;
          const TH1* h = dynamic_cast<const TH1*>(kv.second);
          if (!h) continue;

          const double e = static_cast<double>(h->GetEntries());
          if (e <= 0.0) continue;

          n += e;
          sumMean += h->GetMean() * e;
        }

        outEntries = n;
        outMean    = (n > 0.0 ? (sumMean / n) : std::numeric_limits<double>::quiet_NaN());
      };

      std::cout << "\n\033[1mJet matching summary (leading iso\u2227tight photons)\033[0m\n";
      std::cout << "Jet cuts: pT > " << std::fixed << std::setprecision(2) << m_minJetPt
                << " GeV, |Δφ(γ,jet)| >= " << std::setprecision(3) << m_minBackToBack
                << ", fiducial |η_jet| < 1.1 - R\n";

      for (const auto& trigPair : qaHistogramsByTrigger)
      {
        const std::string& trig = trigPair.first;
        const HistMap&      H   = trigPair.second;

        std::cout << "\n\033[1mTrigger: " << trig << "\033[0m\n";

        std::cout << "rKey  | |eta|< (1.1-R) | Nlead(iso\u2227tight) | NoJetPt | NoJetEta | NoBackToBack | Matched | fMatched | fBackToBack(given jets)\n";
        std::cout << "------+---------------+------------------+---------+----------+-------------+---------+---------+--------------------------\n";

        const bool useActiveRKeys = (!m_activeJetRKeys.empty());
        const std::size_t nRKeys = useActiveRKeys ? m_activeJetRKeys.size() : kJetRadii.size();

        for (std::size_t iR = 0; iR < nRKeys; ++iR)
        {
            const std::string rKey = useActiveRKeys ? m_activeJetRKeys[iR] : kJetRadii[iR].key;
            const double etaMax = jetEtaAbsMaxForRKey(rKey);

          // Collect ALL match-status histograms for this rKey (includes centrality-sliced ones in Au+Au)
          const std::string pfxStatus = std::string("h_match_status_vs_pTgamma_") + rKey;

          std::vector<const TH2*> statusHists;
          for (const auto& kv : H)
          {
            if (!starts_with(kv.first, pfxStatus)) continue;
            if (auto* h = dynamic_cast<const TH2*>(kv.second)) statusHists.push_back(h);
          }

          double c1 = 0.0, c2 = 0.0, c3 = 0.0, c4 = 0.0;
          std::vector<std::array<double, 5>> perX; // [ix][1..4]

          if (!statusHists.empty())
          {
            const int nx0 = statusHists.front()->GetNbinsX();
            perX.assign(static_cast<std::size_t>(nx0 + 1), std::array<double, 5>{0,0,0,0,0});

            for (const TH2* h : statusHists)
            {
              const int nx = h->GetNbinsX();
              const int ny = h->GetNbinsY();
              if (nx != nx0 || ny < 4) continue;

              for (int ix = 1; ix <= nx; ++ix)
              {
                const double v1 = h->GetBinContent(ix, 1);
                const double v2 = h->GetBinContent(ix, 2);
                const double v3 = h->GetBinContent(ix, 3);
                const double v4 = h->GetBinContent(ix, 4);

                c1 += v1; c2 += v2; c3 += v3; c4 += v4;

                perX[ix][1] += v1;
                perX[ix][2] += v2;
                perX[ix][3] += v3;
                perX[ix][4] += v4;
              }
            }
          }

          const double nLead = c1 + c2 + c3 + c4;
          const double nJetsExist = c3 + c4;

          std::cout << std::left << std::setw(4) << rKey << " | "
                    << std::right << std::setw(13) << std::fixed << std::setprecision(2) << etaMax << " | "
                    << std::setw(16) << static_cast<long long>(std::llround(nLead)) << " | "
                    << std::setw(7)  << static_cast<long long>(std::llround(c1)) << " | "
                    << std::setw(8)  << static_cast<long long>(std::llround(c2)) << " | "
                    << std::setw(11) << static_cast<long long>(std::llround(c3)) << " | "
                    << std::setw(7)  << static_cast<long long>(std::llround(c4)) << " | "
                    << std::setw(7)  << fmt_frac(c4, nLead) << " | "
                    << std::setw(24) << fmt_frac(c4, nJetsExist)
                    << "\n";

          // Optional per-pTγ-bin breakdown (very useful for debugging)
          if (Verbosity() >= 2 && !statusHists.empty())
          {
            const TH2* href = statusHists.front();
            const int nx = href->GetNbinsX();

            std::cout << "    per-pTγ match status (" << rKey << "):\n";
            std::cout << "    pTγ bin     | NoJetPt | NoJetEta | NoBackToBack | Matched | N\n";
            std::cout << "    ------------+---------+----------+-------------+---------+------\n";

            for (int ix = 1; ix <= nx; ++ix)
            {
              const double lo = href->GetXaxis()->GetBinLowEdge(ix);
              const double hi = href->GetXaxis()->GetBinUpEdge(ix);

              const double b1 = perX[ix][1];
              const double b2 = perX[ix][2];
              const double b3 = perX[ix][3];
              const double b4 = perX[ix][4];
              const double bt = b1 + b2 + b3 + b4;

              if (bt <= 0.0) continue;

              std::ostringstream lab;
              lab << std::fixed << std::setprecision(0) << lo << "–" << hi;

              std::cout << "    " << std::left << std::setw(12) << lab.str() << " | "
                        << std::right << std::setw(7)  << static_cast<long long>(std::llround(b1)) << " | "
                        << std::setw(8)  << static_cast<long long>(std::llround(b2)) << " | "
                        << std::setw(11) << static_cast<long long>(std::llround(b3)) << " | "
                        << std::setw(7)  << static_cast<long long>(std::llround(b4)) << " | "
                        << std::setw(6)  << static_cast<long long>(std::llround(bt)) << "\n";
            }
          }

          // -------------------- matched-only / jet-physics summaries --------------------
          // Mean max|dphi| over events that had >=1 jet passing pT+eta (NoBackToBack + Matched)
          const std::string pfxMaxDphi = std::string("h_match_maxdphi_vs_pTgamma_") + rKey;
          TH2Stats Smax;
          {
            double sumEntries = 0.0;
            double sumInRange = 0.0;
            double sumMeanYw  = 0.0;

            int nUsed = 0;
            for (const auto& kv : H)
            {
              if (!starts_with(kv.first, pfxMaxDphi)) continue;
              const TH2* h = dynamic_cast<const TH2*>(kv.second);
              if (!h) continue;

              TH2Stats s = th2_y_stats(h);
              sumEntries += s.entries;
              sumInRange += s.inrange;
              if (std::isfinite(s.meanY) && s.inrange > 0.0)
              {
                sumMeanYw += s.meanY * s.inrange;
                ++nUsed;
              }
            }

            Smax.entries = sumEntries;
            Smax.inrange = sumInRange;
            if (sumInRange > 0.0) Smax.meanY = sumMeanYw / sumInRange;
          }

          // Mean |dphi| for matched recoil jet1 (only filled when Matched)
          const std::string pfxDphi = std::string("h_match_dphi_vs_pTgamma_") + rKey;
          TH2Stats Sdphi;
          {
            double sumEntries = 0.0;
            double sumInRange = 0.0;
            double sumMeanYw  = 0.0;

            int nUsed = 0;
            for (const auto& kv : H)
            {
              if (!starts_with(kv.first, pfxDphi)) continue;
              const TH2* h = dynamic_cast<const TH2*>(kv.second);
              if (!h) continue;

              TH2Stats s = th2_y_stats(h);
              sumEntries += s.entries;
              sumInRange += s.inrange;
              if (std::isfinite(s.meanY) && s.inrange > 0.0)
              {
                sumMeanYw += s.meanY * s.inrange;
                ++nUsed;
              }
            }

            Sdphi.entries = sumEntries;
            Sdphi.inrange = sumInRange;
            if (sumInRange > 0.0) Sdphi.meanY = sumMeanYw / sumInRange;
          }

          // Mean <N recoil jets> from the profile (if present)
          const std::string pfxNrecoil = std::string("p_nRecoilJets_vs_pTgamma_") + rKey;
          double profEntries = 0.0;
          double profSum     = 0.0;
          for (const auto& kv : H)
          {
            if (!starts_with(kv.first, pfxNrecoil)) continue;
            const TProfile* p = dynamic_cast<const TProfile*>(kv.second);
            if (!p) continue;

            const int nx = p->GetNbinsX();
            for (int ix = 1; ix <= nx; ++ix)
            {
              const double e = p->GetBinEntries(ix);
              if (e <= 0.0) continue;
              profEntries += e;
              profSum     += p->GetBinContent(ix) * e;
            }
          }
          const double meanNrecoil = (profEntries > 0.0 ? profSum / profEntries : std::numeric_limits<double>::quiet_NaN());

          // Matched recoil-jet outputs (leading recoil jet only)
          double xjN=0.0, xjMean=std::numeric_limits<double>::quiet_NaN();
          double aN =0.0, aMean =std::numeric_limits<double>::quiet_NaN();
          double j1N=0.0, j1Mean=std::numeric_limits<double>::quiet_NaN();

          sum_th1_by_prefix(H, std::string("h_xJ_")     + rKey, xjN, xjMean);
          sum_th1_by_prefix(H, std::string("h_alpha_")  + rKey, aN,  aMean);
          sum_th1_by_prefix(H, std::string("h_jet1Pt_") + rKey, j1N, j1Mean);

            auto sum_th2_prefix = [&](const std::string& pfx) -> TH2Stats
            {
              TH2Stats stats;
              double sumEntries = 0.0, sumInRange = 0.0, sumMeanYw = 0.0;

              for (const auto& kv : H)
              {
                if (!starts_with(kv.first, pfx)) continue;
                const TH2* h = dynamic_cast<const TH2*>(kv.second);
                if (!h) continue;

                TH2Stats s = th2_y_stats(h);
                sumEntries += s.entries;
                sumInRange += s.inrange;
                if (std::isfinite(s.meanY) && s.inrange > 0.0)
                  sumMeanYw += s.meanY * s.inrange;
              }

              stats.entries = sumEntries;
              stats.inrange = sumInRange;
              if (sumInRange > 0.0) stats.meanY = sumMeanYw / sumInRange;
              return stats;
            };

          const TH2Stats Ureco  = sum_th2_prefix(std::string("h2_unfoldReco_pTgamma_xJ_incl_")       + rKey);
          const TH2Stats Utruth = sum_th2_prefix(std::string("h2_unfoldTruth_pTgamma_xJ_incl_")      + rKey);
          const TH2Stats Ufakes = sum_th2_prefix(std::string("h2_unfoldRecoFakes_pTgamma_xJ_incl_")  + rKey);
          const TH2Stats Umiss  = sum_th2_prefix(std::string("h2_unfoldTruthMisses_pTgamma_xJ_incl_")+ rKey);

          // Response is "global bin vs global bin" => only count fills
          double rspEntries = 0.0;
          {
            const std::string pfxRsp = std::string("h2_unfoldResponse_pTgamma_xJ_incl_") + rKey;
            for (const auto& kv : H)
            {
              if (!starts_with(kv.first, pfxRsp)) continue;
              const TH2* h = dynamic_cast<const TH2*>(kv.second);
              if (!h) continue;
              rspEntries += h->GetEntries();
            }
          }

          // Print the “extra” stats only if something exists
          if (nLead > 0.0 || xjN > 0.0 || Ureco.entries > 0.0 || Utruth.entries > 0.0 || rspEntries > 0.0)
          {
            std::cout << "    " << rKey << " details:\n";
            if (std::isfinite(meanNrecoil))
              std::cout << "      <N_recoil jets> (profile): " << std::fixed << std::setprecision(3) << meanNrecoil
                        << " (entries=" << static_cast<long long>(std::llround(profEntries)) << ")\n";

            if (std::isfinite(Smax.meanY))
              std::cout << "      <max|Δφ|> over jets passing pT+eta: " << std::fixed << std::setprecision(3) << Smax.meanY
                        << " rad (in-range fills=" << static_cast<long long>(std::llround(Smax.inrange)) << ")\n";

            if (std::isfinite(Sdphi.meanY))
              std::cout << "      <|Δφ(γ,jet1)|> for matched events: " << std::fixed << std::setprecision(3) << Sdphi.meanY
                        << " rad (fills=" << static_cast<long long>(std::llround(Sdphi.inrange)) << ")\n";

            if (xjN > 0.0)
              std::cout << "      xJ fills=" << static_cast<long long>(std::llround(xjN))
                        << "  <xJ>=" << std::fixed << std::setprecision(3) << xjMean << "\n";

            if (j1N > 0.0)
              std::cout << "      jet1 pT fills=" << static_cast<long long>(std::llround(j1N))
                        << "  <pT_jet1>=" << std::fixed << std::setprecision(3) << j1Mean << " GeV\n";

            if (aN > 0.0)
              std::cout << "      alpha fills=" << static_cast<long long>(std::llround(aN))
                        << "  <alpha>=" << std::fixed << std::setprecision(3) << aMean << "\n";

            std::cout << "      Unfolding (inclusive pairing):\n";
            std::cout << "        reco pairs:   entries=" << static_cast<long long>(std::llround(Ureco.entries))
                      << "  in-range=" << static_cast<long long>(std::llround(Ureco.inrange))
                      << "  <xJ>=" << (std::isfinite(Ureco.meanY) ? (static_cast<std::ostringstream&&>(std::ostringstream() << std::fixed << std::setprecision(3) << Ureco.meanY).str()) : std::string("n/a"))
                      << "\n";
            std::cout << "        truth pairs:  entries=" << static_cast<long long>(std::llround(Utruth.entries))
                      << "  in-range=" << static_cast<long long>(std::llround(Utruth.inrange))
                      << "  <xJ>=" << (std::isfinite(Utruth.meanY) ? (static_cast<std::ostringstream&&>(std::ostringstream() << std::fixed << std::setprecision(3) << Utruth.meanY).str()) : std::string("n/a"))
                      << "\n";
            std::cout << "        response fills (global-bin TH2): entries=" << static_cast<long long>(std::llround(rspEntries)) << "\n";
            std::cout << "        reco fakes:   entries=" << static_cast<long long>(std::llround(Ufakes.entries))
                      << "  in-range=" << static_cast<long long>(std::llround(Ufakes.inrange)) << "\n";
            std::cout << "        truth misses: entries=" << static_cast<long long>(std::llround(Umiss.entries))
                      << "  in-range=" << static_cast<long long>(std::llround(Umiss.inrange)) << "\n";
          }
        }
      }
    }


  //--------------------------------------------------------------------
  // 5. Write footer & close the file
  //--------------------------------------------------------------------
  if (Verbosity() >= 1)
  {
      std::cout << "\nOutput ROOT file →  " << out->GetName() << "\n\n";

      info(1, "writing TFile footer and closing (" + std::to_string(nHistWritten)
                 + " / " + std::to_string(nHistExpected) + " objects written)");
  }

    // EventDisplay diagnostics payload (offline rendering; independent of Verbosity()).
    if (m_evtDiagTree)
      {
        const Long64_t nED = m_evtDiagTree->GetEntries();

        if (Verbosity() >= 1)
        {
          std::cout << CLR_CYAN
                    << "\n[End][EventDisplayTree] entries=" << nED
                    << "  fillsRecorded=" << m_evtDiagNFill
                    << "  anyTowers=" << m_evtDiagNFillWithAnyTowers
                    << "  selTowers=" << m_evtDiagNFillWithSelTowers
                    << "  bestTowers=" << m_evtDiagNFillWithBestTowers
                    << CLR_RESET << "\n";

          std::cout << "  byCat(counters): "
                    << "NUM fills=" << m_evtDiagNFillByCat[0] << " anyTowers=" << m_evtDiagNFillWithAnyTowersByCat[0]
                    << "  MissA fills=" << m_evtDiagNFillByCat[1] << " anyTowers=" << m_evtDiagNFillWithAnyTowersByCat[1]
                    << "  MissB fills=" << m_evtDiagNFillByCat[2] << " anyTowers=" << m_evtDiagNFillWithAnyTowersByCat[2]
                    << "\n";

          const int nBr = (m_evtDiagTree->GetListOfBranches() ? m_evtDiagTree->GetListOfBranches()->GetEntries() : -1);
          const bool hasSelEt  = (m_evtDiagTree->GetBranch("sel_etTower")  != nullptr);
          const bool hasBestEt = (m_evtDiagTree->GetBranch("best_etTower") != nullptr);

          std::cout << "  branches=" << nBr
                    << "  hasSel_etTower="  << (hasSelEt  ? "YES" : "NO")
                    << "  hasBest_etTower=" << (hasBestEt ? "YES" : "NO")
                    << "\n";

          if (nED > 0 && (hasSelEt || hasBestEt))
          {
            // Scan a configurable number of entries to validate what is actually stored in the tree.
            const Long64_t scanN =
              (Verbosity() >= 3 ? nED :
               (Verbosity() >= 2 ? std::min<Long64_t>(nED, 200000) :
                                   std::min<Long64_t>(nED,  20000)));

            long long nSelNonEmpty = 0;
            long long nBestNonEmpty = 0;
            long long nAnyNonEmpty = 0;

            long long nSelSizeMismatch = 0;
            long long nBestSizeMismatch = 0;

            long long nBadCat = 0;
            long long nEmptyRKey = 0;

            long long nCat[3]     = {0, 0, 0};
            long long nCatAny[3]  = {0, 0, 0};
            long long nCatSel[3]  = {0, 0, 0};
            long long nCatBest[3] = {0, 0, 0};

            std::unordered_map<std::string, std::array<long long, 4>> byRKey; // [0]=all, [1]=any, [2]=sel, [3]=best

            double sumSelN = 0.0;
            double sumBestN = 0.0;
            long long maxSelN = 0;
            long long maxBestN = 0;

            // Kinematic sanity (presence, not physics validation)
            long long nPtGammaTruthPos = 0;
            long long nSelPtPos = 0;
            long long nBestPtPos = 0;
            long long nTruthLeadPtPos = 0;

            // Example entries that actually have towers (first found in scan)
            bool exAny[3] = {false, false, false};
            int ex_run[3] = {0, 0, 0};
            int ex_evt[3] = {0, 0, 0};
            std::string ex_rKey[3];
            float ex_ptG[3] = {0.0f, 0.0f, 0.0f};
            long long ex_selN[3] = {0, 0, 0};
            long long ex_bestN[3] = {0, 0, 0};

            for (Long64_t i = 0; i < scanN; ++i)
            {
              m_evtDiagTree->GetEntry(i);

              if (m_evtDiag_rKey.empty()) ++nEmptyRKey;

              if (m_evtDiag_ptGammaTruth > 0.0f) ++nPtGammaTruthPos;
              if (m_evtDiag_sel_pt > 0.0f) ++nSelPtPos;
              if (m_evtDiag_best_pt > 0.0f) ++nBestPtPos;
              if (m_evtDiag_truthLead_pt > 0.0f) ++nTruthLeadPtPos;

              const long long selN  = static_cast<long long>(m_evtDiag_sel_etTower.size());
              const long long bestN = static_cast<long long>(m_evtDiag_best_etTower.size());

              const bool selOK =
                (m_evtDiag_sel_etaTower.size() == m_evtDiag_sel_phiTower.size() &&
                 m_evtDiag_sel_phiTower.size() == m_evtDiag_sel_etTower.size());

              const bool bestOK =
                (m_evtDiag_best_etaTower.size() == m_evtDiag_best_phiTower.size() &&
                 m_evtDiag_best_phiTower.size() == m_evtDiag_best_etTower.size());

              if (!selOK) ++nSelSizeMismatch;
              if (!bestOK) ++nBestSizeMismatch;

              const bool hasSelT  = (selN > 0);
              const bool hasBestT = (bestN > 0);
              const bool hasAnyT  = (hasSelT || hasBestT);

              if (hasSelT)  ++nSelNonEmpty;
              if (hasBestT) ++nBestNonEmpty;
              if (hasAnyT)  ++nAnyNonEmpty;

              sumSelN  += selN;
              sumBestN += bestN;
              if (selN > maxSelN)   maxSelN = selN;
              if (bestN > maxBestN) maxBestN = bestN;

              const int cat = m_evtDiag_cat;
              int catIdx = -1;
              if (cat == static_cast<int>(EventDisplayCat::NUM))   catIdx = 0;
              if (cat == static_cast<int>(EventDisplayCat::MissA)) catIdx = 1;
              if (cat == static_cast<int>(EventDisplayCat::MissB)) catIdx = 2;

              if (catIdx < 0 || catIdx > 2)
              {
                ++nBadCat;
              }
              else
              {
                ++nCat[catIdx];
                if (hasAnyT)  ++nCatAny[catIdx];
                if (hasSelT)  ++nCatSel[catIdx];
                if (hasBestT) ++nCatBest[catIdx];

                if (!exAny[catIdx] && hasAnyT)
                {
                  exAny[catIdx]   = true;
                  ex_run[catIdx]  = m_evtDiag_run;
                  ex_evt[catIdx]  = m_evtDiag_evt;
                  ex_rKey[catIdx] = m_evtDiag_rKey;
                  ex_ptG[catIdx]  = m_evtDiag_ptGammaTruth;
                  ex_selN[catIdx] = selN;
                  ex_bestN[catIdx] = bestN;
                }
              }

              auto& arr = byRKey[m_evtDiag_rKey];
              arr[0] += 1;
              if (hasAnyT)  arr[1] += 1;
              if (hasSelT)  arr[2] += 1;
              if (hasBestT) arr[3] += 1;
            }

            auto frac = [&](long long a, long long b) -> std::string
            {
              if (b <= 0) return "n/a";
              std::ostringstream os;
              os << std::fixed << std::setprecision(3)
                 << (static_cast<double>(a) / static_cast<double>(b));
              return os.str();
            };

            std::cout << "  scan: entriesScanned=" << scanN;
            if (scanN < nED) std::cout << "  (increase Verbosity to scan more)";
            std::cout << "\n";

            std::cout << "  towers(from tree scan): any=" << nAnyNonEmpty << " (" << frac(nAnyNonEmpty, scanN) << ")"
                      << "  sel=" << nSelNonEmpty << " (" << frac(nSelNonEmpty, scanN) << ")"
                      << "  best=" << nBestNonEmpty << " (" << frac(nBestNonEmpty, scanN) << ")"
                      << "  <selN>=" << std::fixed << std::setprecision(2) << (scanN > 0 ? (sumSelN / scanN) : 0.0)
                      << "  <bestN>=" << std::fixed << std::setprecision(2) << (scanN > 0 ? (sumBestN / scanN) : 0.0)
                      << "  maxSelN=" << maxSelN
                      << "  maxBestN=" << maxBestN
                      << "\n";

            std::cout << "  kinematics(from tree scan): "
                      << "ptGammaTruth>0: " << nPtGammaTruthPos << "/" << scanN
                      << "  sel_pt>0: " << nSelPtPos << "/" << scanN
                      << "  best_pt>0: " << nBestPtPos << "/" << scanN
                      << "  truthLead_pt>0: " << nTruthLeadPtPos << "/" << scanN
                      << "  emptyRKey: " << nEmptyRKey
                      << "\n";

            if (nSelSizeMismatch > 0 || nBestSizeMismatch > 0)
            {
              std::cout << CLR_YELLOW
                        << "  [WARN] tower vector size mismatches observed in scan: "
                        << "selMismatch=" << nSelSizeMismatch
                        << "  bestMismatch=" << nBestSizeMismatch
                        << CLR_RESET << "\n";
            }

            if (nBadCat > 0)
            {
              std::cout << CLR_YELLOW
                        << "  [WARN] cat out of expected range (0=NUM,1=MissA,2=MissB) in scan: nBadCat=" << nBadCat
                        << CLR_RESET << "\n";
            }

            if (Verbosity() >= 2)
            {
              std::cout << "  byCat(from tree scan):\n";
              std::cout << "    NUM   entries=" << nCat[0] << " any=" << nCatAny[0] << " sel=" << nCatSel[0] << " best=" << nCatBest[0]
                        << "  fAny=" << frac(nCatAny[0], nCat[0]) << "\n";
              std::cout << "    MissA entries=" << nCat[1] << " any=" << nCatAny[1] << " sel=" << nCatSel[1] << " best=" << nCatBest[1]
                        << "  fAny=" << frac(nCatAny[1], nCat[1]) << "\n";
              std::cout << "    MissB entries=" << nCat[2] << " any=" << nCatAny[2] << " sel=" << nCatSel[2] << " best=" << nCatBest[2]
                        << "  fAny=" << frac(nCatAny[2], nCat[2]) << "\n";

              std::cout << "  byRKey(from tree scan):\n";
              for (const auto& kv : byRKey)
              {
                const auto& k = kv.first;
                const auto& a = kv.second;
                std::cout << "    " << std::left << std::setw(4) << k
                          << " entries=" << std::right << std::setw(8) << a[0]
                          << " any="     << std::setw(8) << a[1]
                          << " sel="     << std::setw(8) << a[2]
                          << " best="    << std::setw(8) << a[3]
                          << "  fAny="   << frac(a[1], a[0])
                          << "\n";
              }

              auto catName = [&](int i) -> const char*
              {
                if (i == 0) return "NUM";
                if (i == 1) return "MissA";
                if (i == 2) return "MissB";
                return "UNK";
              };

              for (int ic = 0; ic < 3; ++ic)
              {
                if (exAny[ic])
                {
                  std::cout << "  exampleWithTowers[" << catName(ic) << "]: "
                            << "rKey=" << ex_rKey[ic]
                            << " run=" << ex_run[ic]
                            << " evt=" << ex_evt[ic]
                            << " ptGammaTruth=" << std::fixed << std::setprecision(3) << ex_ptG[ic]
                            << " selN=" << ex_selN[ic]
                            << " bestN=" << ex_bestN[ic]
                            << "\n";
                }
                else
                {
                  std::cout << "  exampleWithTowers[" << catName(ic) << "]: none found in scan\n";
                }
              }
            }

            if (nED > 0 && nAnyNonEmpty == 0)
            {
              std::cout << CLR_YELLOW
                        << "  [WARN] EventDisplayTree has entries but ALL tower payloads are empty in scanned entries. "
                        << "Most likely: Jet constituents not accessible (Jetv2 comp_vec vs begin_comp) OR Jet::SRC mismatch vs TowerInfo nodes."
                        << CLR_RESET << "\n";
            }
          }
          else if (nED > 0)
          {
            std::cout << CLR_YELLOW
                      << "  [WARN] EventDisplayTree has entries but expected tower branches are missing (sel_etTower/best_etTower). "
                      << "Tree schema mismatch? (older file format?)"
                      << CLR_RESET << "\n";
          }
          else
          {
            std::cout << CLR_YELLOW
                      << "  [WARN] EventDisplayTree exists but has 0 entries."
                      << CLR_RESET << "\n";
          }
        }

        out->cd();
        m_evtDiagTree->Write("", TObject::kOverwrite);
      }

      if (m_ppPhotonIDTrainingTree)
      {
        out->cd();
        m_ppPhotonIDTrainingTree->Write("", TObject::kOverwrite);
        info(1, "pp photon-ID training tree entries=" +
                 std::to_string(m_ppPhotonIDTrainingTreeEntries));
      }

      if (!m_analysisConfigYAMLText.empty())
      {
        out->cd();
        TObjString yamlObj(m_analysisConfigYAMLText.c_str());
        yamlObj.Write("analysis_config_yaml", TObject::kOverwrite);
        m_analysisConfigStamped = true;
      }

      // A failed ReplayFoundation event transaction invalidates every
      // candidate sidecar derived from this job.  Fail before either writer
      // can stamp a terminal completion marker; Condor must observe a nonzero
      // run result and no partially valid training artifact may be certified.
      if (m_replayWriteFailed)
      {
        warn("ReplayFoundationV1 event transaction failed; refusing to finalize replay or photon-training artifacts");
        return Fun4AllReturnCodes::ABORTRUN;
      }

      if (m_replayFoundationEnabled && m_replayRuntime)
      {
        if ((m_triggerScalerWriter && !m_triggerScalerWriter->finish()) ||
            (m_triggerRunInfoWriter && !m_triggerRunInfoWriter->finish()))
        {
          warn("RJTriggerScalersV1 finish failed; refusing replay completion");
          return Fun4AllReturnCodes::ABORTRUN;
        }
        std::string replayError;
        if (!m_replayRuntime->finish(&replayError))
        {
          warn("ReplayFoundationV1 finish failed: " + replayError);
          return Fun4AllReturnCodes::ABORTRUN;
        }
      }

      // The labeled sidecar is downstream of the authoritative replay
      // transaction.  Finalize it only after the main replay artifact has
      // successfully written its own terminal completion state.
      if (m_photonTrainingViewRuntime)
      {
        std::string trainingError;
        if (!m_photonTrainingViewRuntime->finish(&trainingError))
        {
          warn("RJPhotonTrainingViewV1 finish failed: " + trainingError);
          return Fun4AllReturnCodes::ABORTRUN;
        }
      }

      if (m_the134MultiviewSidecarOnly)
      {
        out->cd();
        const auto& replayMetadata = m_replayRuntime->metadata();
        const std::pair<std::string,std::string> markers[] = {
            {"rj_the134_multiview_sidecar_only_v1","1"},
            {"rj_replay_transaction_state",
             m_the134FastExtraction
                 ? "SIDECAR_DEPENDENCY_SLICE_VALIDATED"
                 : "CONSTRUCTED_AND_VALIDATED"},
            {"rj_replay_serialization_state","DISABLED"},
            {"rj_replay_cache_applicability","NOT_APPLICABLE"},
            {"rj_replay_schema_sha256",
             replayMetadata.schema_sha256},
            {"rj_replay_semantic_sha256",
             replayMetadata.semantic_sha256},
            {"rj_replay_source_sha256",
             replayMetadata.source_sha256},
            {"rj_replay_model_sha256",
             replayMetadata.model_sha256},
            {"rj_replay_config_sha256",
             replayMetadata.config_sha256},
            {"rj_replay_code_sha256",
             replayMetadata.code_sha256}};
        for (const auto& marker : markers)
        {
          TNamed value(marker.first.c_str(),marker.second.c_str());
          if (value.Write(marker.first.c_str(),TObject::kOverwrite) <= 0)
          {
            warn("THE-134 sidecar-only marker write failed: " +
                 std::string(marker.first));
            return Fun4AllReturnCodes::ABORTRUN;
          }
        }
        if (m_the134FastExtraction)
        {
          TNamed fastMarker("rj_the134_fast_extraction_v1","1");
          if (fastMarker.Write(
                  "rj_the134_fast_extraction_v1",
                  TObject::kOverwrite) <= 0)
          {
            warn("THE-134 fast-extraction marker write failed");
            return Fun4AllReturnCodes::ABORTRUN;
          }
        }
      }

    try
    {
      out->Close();
  }
  catch (const std::exception& e)
  {
    warn("Exception during TFile::Write/Close – " + std::string(e.what()));
  }

  delete out;
  out = nullptr;

  info(0, "Done.");
  return Fun4AllReturnCodes::EVENT_OK;
}



// Build SSVars from PhotonClusterv1 (names come from PhotonClusterBuilder)
RecoilJets::SSVars RecoilJets::makeSSFromPhoton(const PhotonClusterv1* pho, double pt_gamma) const
{
  SSVars v{};
  v.pt_gamma = pt_gamma;

  if (!pho)
  {
    if (Verbosity() >= 3)
      LOG(3, CLR_YELLOW, "  [makeSSFromPhoton] pho==nullptr → returning default SSVars");
    return v;
  }

  // Raw stored shower-shape parameters (PhotonClusterBuilder names)
  const double weta_cogx = pho->get_shower_shape_parameter("weta_cogx");
  const double wphi_cogx = pho->get_shower_shape_parameter("wphi_cogx");
  const double weta33_cogx = pho->get_shower_shape_parameter("weta33_cogx");
  const double wphi33_cogx = pho->get_shower_shape_parameter("wphi33_cogx");
  const double weta35_cogx = pho->get_shower_shape_parameter("weta35_cogx");
  const double wphi53_cogx = pho->get_shower_shape_parameter("wphi53_cogx");
  const double et1       = pho->get_shower_shape_parameter("et1");
  const double et2       = pho->get_shower_shape_parameter("et2");
  const double et3       = pho->get_shower_shape_parameter("et3");
  const double et4       = pho->get_shower_shape_parameter("et4");

  const double e11 = pho->get_shower_shape_parameter("e11");
  const double e13 = pho->get_shower_shape_parameter("e13");
  const double e15 = pho->get_shower_shape_parameter("e15");
  const double e17 = pho->get_shower_shape_parameter("e17");
  const double e22 = pho->get_shower_shape_parameter("e22");
  const double e31 = pho->get_shower_shape_parameter("e31");
  const double e33 = pho->get_shower_shape_parameter("e33");
  const double e32 = pho->get_shower_shape_parameter("e32");
  const double e35 = pho->get_shower_shape_parameter("e35");
  const double e37 = pho->get_shower_shape_parameter("e37");
  const double e51 = pho->get_shower_shape_parameter("e51");
  const double e53 = pho->get_shower_shape_parameter("e53");
  const double e71 = pho->get_shower_shape_parameter("e71");
  const double e77 = pho->get_shower_shape_parameter("e77");
  const double w32 = pho->get_shower_shape_parameter("w32");
  const double w52 = pho->get_shower_shape_parameter("w52");
  const double w72 = pho->get_shower_shape_parameter("w72");
  const double mean_time = pho->get_shower_shape_parameter("mean_time");
  const double cluster_prob = pho->get_prob();

  // Derived ratios (protect denominators)
  auto ratio = [](double num, double den) -> double
  {
    return (std::isfinite(num) && std::isfinite(den) && den > 0.0)
        ? (num / den)
        : std::numeric_limits<double>::quiet_NaN();
  };
  const double e11_over_e33_raw = ratio(e11, e33);
  const double e32_over_e35_raw = ratio(e32, e35);

  v.weta_cogx    = weta_cogx;
  v.wphi_cogx    = wphi_cogx;
  v.weta33_cogx  = weta33_cogx;
  v.wphi33_cogx  = wphi33_cogx;
  v.weta35_cogx  = weta35_cogx;
  v.wphi53_cogx  = wphi53_cogx;
  v.et1          = et1;
  v.et2          = et2;
  v.et3          = et3;
  v.et4          = et4;

  // Preserve NaN for invalid denominators/inputs.
  // This ensures preselection/tight cuts fail cleanly for invalid SS inputs.
  v.e11_over_e33 = e11_over_e33_raw;
  v.e17_over_e77 = ratio(e17, e77);
  v.e32_over_e35 = e32_over_e35_raw;
  v.e11_over_e22 = ratio(e11, e22);
  v.e11_over_e13 = ratio(e11, e13);
  v.e11_over_e15 = ratio(e11, e15);
  v.e11_over_e17 = ratio(e11, e17);
  v.e11_over_e31 = ratio(e11, e31);
  v.e11_over_e51 = ratio(e11, e51);
  v.e11_over_e71 = ratio(e11, e71);
  v.e22_over_e33 = ratio(e22, e33);
  v.e22_over_e35 = ratio(e22, e35);
  v.e22_over_e37 = ratio(e22, e37);
  v.e22_over_e53 = ratio(e22, e53);
  v.w32 = w32;
  v.w52 = w52;
  v.w72 = w72;
  v.mean_time = mean_time;
  v.cluster_prob = cluster_prob;
  v.ppg12_shape_n_owned = pho->get_shower_shape_parameter("ppg12_shape_n_owned");
  v.ppg12_shape_owned_e = pho->get_shower_shape_parameter("ppg12_shape_owned_e");
  v.ppg12_shape_all_e = pho->get_shower_shape_parameter("ppg12_shape_all_e");
  v.ppg12_shape_den_e = pho->get_shower_shape_parameter("ppg12_shape_den_e");
  v.ppg12_shape_weta_cogx_num = pho->get_shower_shape_parameter("ppg12_shape_weta_cogx_num");
  v.ppg12_shape_wphi_cogx_num = pho->get_shower_shape_parameter("ppg12_shape_wphi_cogx_num");
  v.ppg12_shape_cog_eta = pho->get_shower_shape_parameter("ppg12_shape_cog_eta");
  v.ppg12_shape_cog_phi = pho->get_shower_shape_parameter("ppg12_shape_cog_phi");
  v.ppg12_shape_center_ieta = pho->get_shower_shape_parameter("ppg12_shape_center_ieta");
  v.ppg12_shape_center_iphi = pho->get_shower_shape_parameter("ppg12_shape_center_iphi");

  attachVariantScoresToSSVars(pho, v);

  // Print only when:
  //   - Verbosity >= 8 (always), OR
  //   - Verbosity >= 6 and something looks wrong (non-finite / denom<=0)
  const bool bad =
      !std::isfinite(weta_cogx) || !std::isfinite(wphi_cogx) || !std::isfinite(et1) ||
      !std::isfinite(e11) || !std::isfinite(e33) || !std::isfinite(e32) || !std::isfinite(e35) ||
      !std::isfinite(cluster_prob) ||
      (e33 <= 0.0) || (e35 <= 0.0);

  if (Verbosity() >= 8 || (Verbosity() >= 6 && bad))
  {
    std::ostringstream os;
    os << "      [SS extract] pT^γ=" << std::fixed << std::setprecision(2) << pt_gamma
       << " | weta_cogx=" << std::setprecision(4) << weta_cogx
       << " wphi_cogx=" << std::setprecision(4) << wphi_cogx
       << " et1=" << std::setprecision(4) << et1
       << " | e11=" << std::setprecision(4) << e11
       << " e33=" << std::setprecision(4) << e33
       << " (e11/e33=" << std::setprecision(4) << (std::isfinite(e11_over_e33_raw) ? e11_over_e33_raw : -999.0) << ")"
       << " | e32=" << std::setprecision(4) << e32
       << " e35=" << std::setprecision(4) << e35
       << " (e32/e35=" << std::setprecision(4) << (std::isfinite(e32_over_e35_raw) ? e32_over_e35_raw : -999.0) << ")";
    if (std::isfinite(v.npb_score))
      os << " | npb=" << std::setprecision(4) << v.npb_score;
    if (std::isfinite(v.tight_bdt_score))
      os << " | tightBDT=" << std::setprecision(4) << v.tight_bdt_score;
    if (bad) os << "  [WARN]";
    LOG(6, bad ? CLR_YELLOW : CLR_BLUE, os.str());
  }

  return v;
}



void RecoilJets::fillUnfoldResponseMatrixAndTruthDistributions(
    const std::vector<std::string>& activeTrig,
    const std::string& rKey,
    const int effCentIdx_M,
    const double leadPtGamma,
    const double leadEtaGamma,
    const double leadPhiGamma,
    const bool haveTruthPho,
    const double tPt,
    const double tEta,
    const double tPhi,
    const std::vector<const Jet*>& recoJetsFid,
    const std::vector<char>& recoJetsFidIsRecoil,
    const Jet* recoil1Jet)
{
  // Keep local dR identical in behavior to the caller
  auto dR = [](double eta1, double phi1, double eta2, double phi2) -> double
  {
    const double dphi = TVector2::Phi_mpi_pi(phi1 - phi2);
    const double deta = eta1 - eta2;
    return std::sqrt(deta*deta + dphi*dphi);
  };

    const bool haveRecoPhoton  = (std::isfinite(leadPtGamma) && leadPtGamma > 0.0);
    const bool haveTruthTarget = (std::isfinite(tPt) && tPt > 0.0);

    const std::string jetRKey = baseRKeyFromDphiHistKey(rKey);

    JetContainer* truthJets = nullptr;
    if (haveTruthTarget)
    {
      if (auto itT = m_truthJetsByRKey.find(jetRKey); itT != m_truthJetsByRKey.end()) truthJets = itT->second;
      if (!truthJets) return;
    }

    const double etaMaxTruth = jetEtaAbsMaxForRKey(jetRKey);

    std::vector<const Jet*> truthJetsFid;
    std::vector<char>       truthJetsFidIsRecoil;
    if (truthJets)
    {
      truthJetsFid.reserve(truthJets->size());
      truthJetsFidIsRecoil.reserve(truthJets->size());

      // 1) Build truth jet lists + fill truth inclusive distribution
      for (const Jet* tj : *truthJets)
      {
        if (!tj) continue;

        const double ptj  = tj->get_pt();
        const double etaj = tj->get_eta();
        const double phij = tj->get_phi();

        if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
        if (ptj < m_minJetPt) continue;

        // Photon–jet overlap veto (truth): exclude jets near the truth photon direction (ΔR < 0.4)
        const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
        const double detaPho = (etaj - tEta);
        const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

        if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
        {
          continue;
        }

        if (std::fabs(etaj) >= etaMaxTruth) continue;

        const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(phij - tPhi));
        const bool isRecoil = (dphiAbs >= m_minBackToBack);

        truthJetsFid.push_back(tj);
        truthJetsFidIsRecoil.push_back(isRecoil ? 1 : 0);

        if (isRecoil)
        {
          const double xJt = ptj / tPt;

          for (const auto& trigShort : activeTrig)
          {
            if (auto* h2t = getOrBookUnfoldTruthPtXJIncl(trigShort, rKey, effCentIdx_M))
            {
              h2t->Fill(tPt, xJt);
              bumpHistFill(trigShort, h2t->GetName());
            }

            // inclusive |Δphi(γ,jet)| for each TRUTH recoil jet passing cuts
            if (auto* h2dt = getOrBookUnfoldTruthPtDphiIncl(trigShort, rKey, effCentIdx_M))
            {
              h2dt->Fill(tPt, dphiAbs);
              bumpHistFill(trigShort, h2dt->GetName());
            }
          }
        }
      }
    }

    // ------------------------------------------------------------------
    // dedicated jet-efficiency bookkeeping for post-unfold ATLAS-style correction
    //   Den: truth recoil jets in truth unfolding phase space
    //   Num: subset with a selection-aware reco jet match, built independently
    //        of the geometry-first response MissA/MissB taxonomy
    // ------------------------------------------------------------------
    std::vector<char> truthJetEffRecoPass(truthJetsFid.size(), 0);

    if (haveTruthTarget)
    {
      JetContainer* recoJetsAll = nullptr;
      if (auto itR = m_jets.find(jetRKey); itR != m_jets.end()) recoJetsAll = itR->second;

      std::vector<const Jet*> recoJetsForJetEff;
      if (recoJetsAll)
      {
        recoJetsForJetEff.reserve(recoJetsAll->size());

        const double etaMaxRecoJetEff = jetEtaAbsMaxForRKey(jetRKey);
        const double xJMinJetEff = (!m_unfoldXJBins.empty() ? m_unfoldXJBins.front() : 0.0);
        const double xJMaxJetEff = (!m_unfoldXJBins.empty() ? m_unfoldXJBins.back() : std::numeric_limits<double>::infinity());

        for (const Jet* rj : *recoJetsAll)
        {
          if (!rj) continue;

          const double ptj  = rj->get_pt();
          const double etaj = rj->get_eta();
          const double phij = rj->get_phi();

          if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
          if (ptj < m_minJetPt) continue;

          const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
          const double detaPho = (etaj - tEta);
          const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

          if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4))) continue;
          if (std::fabs(etaj) >= etaMaxRecoJetEff) continue;

          const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(phij - tPhi));
          if (!std::isfinite(dphiAbs) || dphiAbs < m_minBackToBack) continue;

          const double xJrTruthPho = ptj / tPt;
          if (!(xJrTruthPho >= xJMinJetEff && xJrTruthPho < xJMaxJetEff)) continue;

          recoJetsForJetEff.push_back(rj);
        }
      }

      if (!recoJetsForJetEff.empty())
      {
        struct JetEffCandPair { double dr; int iReco; int iTruth; };
        std::vector<JetEffCandPair> jetEffCands;
        jetEffCands.reserve(recoJetsForJetEff.size() * truthJetsFid.size());

        for (int ir = 0; ir < static_cast<int>(recoJetsForJetEff.size()); ++ir)
        {
          const Jet* rj = recoJetsForJetEff[ir];
          if (!rj) continue;

          for (int it = 0; it < static_cast<int>(truthJetsFid.size()); ++it)
          {
            if (!truthJetsFidIsRecoil[it]) continue;

            const Jet* tj = truthJetsFid[it];
            if (!tj) continue;

            const double dr = dR(rj->get_eta(), rj->get_phi(), tj->get_eta(), tj->get_phi());
            if (dr < m_jetMatchDRMax) jetEffCands.push_back({dr, ir, it});
          }
        }

        std::sort(jetEffCands.begin(), jetEffCands.end(),
                  [](const JetEffCandPair& a, const JetEffCandPair& b){ return a.dr < b.dr; });

        std::vector<char> recoJetEffMatched(recoJetsForJetEff.size(), 0);
        std::vector<char> truthJetEffMatched(truthJetsFid.size(), 0);

        for (const auto& cp : jetEffCands)
        {
          if (recoJetEffMatched[cp.iReco]) continue;
          if (truthJetEffMatched[cp.iTruth]) continue;

          recoJetEffMatched[cp.iReco]    = 1;
          truthJetEffMatched[cp.iTruth]  = 1;
          truthJetEffRecoPass[cp.iTruth] = 1;
        }
      }
    }

    // ------------------------------------------------------------------
    //  leading-truth recoil jet1 match bookkeeping vs truth pT^gamma
    // ------------------------------------------------------------------
    const Jet* tjLead = nullptr;
    bool hasRecoMatchToTruthLead = false;
    bool leadRecoMatches = false;

    if (haveTruthTarget && haveRecoPhoton)
    {
        const double kLeadMatchDR = m_jetMatchDRMax;

        // Histmaker-style leading-jet definition (truth): mirror RECO chronology
        //   - pick the GLOBAL leading truth jet excluding photon overlap (ΔR(γ^truth,jet) > 0.4)
        //     with only the pT gate applied (NO eta/dphi pre-veto)
        //   - THEN veto if that chosen jet is not fiducial in eta (NO fallback)
        //   - THEN require it be back-to-back to define the truth-leading recoil jet
        double all1PtTruth = -1.0;
        const Jet* all1Truth = nullptr;

        for (const Jet* tj : *truthJets)
        {
          if (!tj) continue;

          const double ptj  = tj->get_pt();
          const double etaj = tj->get_eta();
          const double phij = tj->get_phi();

          if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
          if (ptj < m_minJetPt) continue;

          // Photon–jet overlap veto: exclude jets near the truth photon direction (ΔR < 0.4)
          const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
          const double detaPho = (etaj - tEta);
          const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

          if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
          {
            continue;
          }

          if (ptj > all1PtTruth)
          {
            all1PtTruth = ptj;
            all1Truth   = tj;
          }
        }

        if (all1Truth && all1PtTruth > 0.0)
        {
          const double etaLead = all1Truth->get_eta();
          if (std::isfinite(etaLead) && std::fabs(etaLead) < etaMaxTruth)
          {
            const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(all1Truth->get_phi() - tPhi));
            if (std::isfinite(dphiAbs) && dphiAbs >= m_minBackToBack)
            {
                tjLead = all1Truth;
            }
          }
        }

        if (tjLead)
        {

        // DEN: truth-leading away-side recoil jet exists
        for (const auto& trigShort : activeTrig)
        {
          if (auto* hDen = getOrBookLeadTruthRecoilMatchDenPtGammaTruth(trigShort, rKey, effCentIdx_M))
          { hDen->Fill(tPt); bumpHistFill(trigShort, hDen->GetName()); }
        }

        // Best reco fid match to truth-leading recoil jet (independent of the selected recoil1Jet)
        const Jet* rjTruthBest = nullptr;
        double drTruthBest = 1e9;
        if (tjLead)
        {
          for (const Jet* rjAny : recoJetsFid)
          {
            if (!rjAny) continue;

            const double drAny = dR(rjAny->get_eta(), rjAny->get_phi(),
                                    tjLead->get_eta(), tjLead->get_phi());
            if (drAny < drTruthBest)
            {
              drTruthBest = drAny;
              rjTruthBest = rjAny;
            }
          }
        }
        hasRecoMatchToTruthLead = (rjTruthBest && drTruthBest < kLeadMatchDR);

        // For MissA subtyping: does the reco jet matched to the truth-leading recoil jet
        // itself pass the recoil definition? (pT/eta are already satisfied by recoJetsFid,
        // but we evaluate sequentially to support a robust MissA2 cutflow histogram.)
        bool truthMatchPassesRecoil = false;
        int  truthMatchFailCut = 0; // 1=pTmin, 2=|eta|, 3=dphi
        if (hasRecoMatchToTruthLead && rjTruthBest)
        {
          const double ptm  = rjTruthBest->get_pt();
          const double etam = rjTruthBest->get_eta();
          const double phim = rjTruthBest->get_phi();

          const bool passPt  = (std::isfinite(ptm)  && ptm  >= m_minJetPt);
          const bool passEta = (std::isfinite(etam) && std::fabs(etam) < etaMaxTruth);

          const double dphiAbsM = std::fabs(TVector2::Phi_mpi_pi(phim - tPhi));
          const bool passDphi = (std::isfinite(dphiAbsM) && dphiAbsM >= m_minBackToBack);

          truthMatchPassesRecoil = (passPt && passEta && passDphi);

          if (!passPt)        truthMatchFailCut = 1;
          else if (!passEta)  truthMatchFailCut = 2;
          else if (!passDphi) truthMatchFailCut = 3;
          else                truthMatchFailCut = 0;
        }

        // Does the analysis-selected reco recoilJet1 match the truth-leading recoil jet?
        double drLead = 1e9;
        if (recoil1Jet && tjLead)
        {
          drLead = dR(recoil1Jet->get_eta(), recoil1Jet->get_phi(),
                      tjLead->get_eta(), tjLead->get_phi());
          leadRecoMatches = (drLead < kLeadMatchDR);
        }

        // Fill the standard NUM / MissA / MissB bookkeeping (+ MissA subtypes)
        if (leadRecoMatches)
        {
            for (const auto& trigShort : activeTrig)
            {
              if (auto* hNum = getOrBookLeadTruthRecoilMatchNumPtGammaTruth(trigShort, rKey, effCentIdx_M))
              { hNum->Fill(tPt); bumpHistFill(trigShort, hNum->GetName()); }
            }
          }
          else if (hasRecoMatchToTruthLead)
          {
            for (const auto& trigShort : activeTrig)
            {
              if (auto* hA = getOrBookLeadTruthRecoilMatchMissA_PtGammaTruth(trigShort, rKey, effCentIdx_M))
              { hA->Fill(tPt); bumpHistFill(trigShort, hA->GetName()); }

              if (truthMatchPassesRecoil)
              {
                if (auto* hA1 = getOrBookLeadTruthRecoilMatchMissA1_PtGammaTruth(trigShort, rKey, effCentIdx_M))
                { hA1->Fill(tPt); bumpHistFill(trigShort, hA1->GetName()); }
              }
              else
              {
                if (auto* hA2 = getOrBookLeadTruthRecoilMatchMissA2_PtGammaTruth(trigShort, rKey, effCentIdx_M))
                { hA2->Fill(tPt); bumpHistFill(trigShort, hA2->GetName()); }

                if (truthMatchFailCut > 0)
                {
                  if (auto* hCF = getOrBookLeadTruthRecoilMatchMissA2_Cutflow(trigShort, rKey, effCentIdx_M))
                  { hCF->Fill((double)truthMatchFailCut); bumpHistFill(trigShort, hCF->GetName()); }
                }
              }
            }
          }
          else
          {
            for (const auto& trigShort : activeTrig)
            {
              if (auto* hB = getOrBookLeadTruthRecoilMatchMissB_PtGammaTruth(trigShort, rKey, effCentIdx_M))
              { hB->Fill(tPt); bumpHistFill(trigShort, hB->GetName()); }
            }
          }

            // -------------------------------------------------------------------------
            // EventDisplay diagnostics payload (offline rendering; independent of Verbosity()).
            // One entry per (event, rKey) when enabled.
            // -------------------------------------------------------------------------
            if (m_evtDiagEnabled && fillCanonicalThisView())
            {
              if (!m_evtDiagNodesReady)
              {
                if (Verbosity() >= 3)
                {
                  LOG(3, CLR_YELLOW,
                      "[EventDisplayTree][skip] nodes not ready "
                      << "(evt=" << ecvt << " rKey=" << rKey << ")");
                }
              }
              else
              {
                  const bool isSim = m_isSim;

                  const double diagPt  = (isSim ? tPt  : leadPtGamma);

                  const int ptBin = findPtBin(diagPt);

                  EventDisplayCat cat = EventDisplayCat::NUM;
                  if (isSim)
                  {
                    cat = EventDisplayCat::MissB;
                    if (leadRecoMatches)
                    {
                      cat = EventDisplayCat::NUM;
                    }
                    else if (hasRecoMatchToTruthLead)
                    {
                      cat = EventDisplayCat::MissA;
                    }
                  }

                  if (ptBin < 0)
                  {
                    if (Verbosity() >= 4)
                    {
                      LOG(4, CLR_YELLOW,
                          "[EventDisplayTree][skip] ptBin<0 (out of range) "
                          << "(evt=" << ecvt << " rKey=" << rKey
                          << " diagPt=" << diagPt
                          << " isSim=" << (isSim ? "true" : "false") << ")");
                    }
                  }
                else if (!(recoil1Jet || rjTruthBest || tjLead))
                {
                  if (Verbosity() >= 4)
                  {
                    LOG(4, CLR_YELLOW,
                        "[EventDisplayTree][skip] no jets available for diagnostics "
                        << "(evt=" << ecvt << " rKey=" << rKey
                        << " ptBin=" << ptBin
                        << " cat=" << static_cast<int>(cat) << ")");
                  }
                }
                else
                {
                  const bool need = eventDisplayDiagnosticsNeed(rKey, ptBin, cat);

                  if (Verbosity() >= 5)
                  {
                    LOG(5, CLR_CYAN,
                        "[EventDisplayTree][check] "
                        << "(evt=" << ecvt << " rKey=" << rKey
                        << " ptBin=" << ptBin
                        << " cat=" << static_cast<int>(cat)
                        << " need=" << (need ? "YES" : "NO")
                        << " sel=" << (recoil1Jet ? "Y" : "N")
                        << " best=" << (rjTruthBest ? "Y" : "N")
                        << " truthLead=" << (tjLead ? "Y" : "N")
                        << " diagPt=" << diagPt
                        << " leadPtGamma=" << leadPtGamma
                        << " isSim=" << (isSim ? "true" : "false") << ")");
                  }

                  if (need)
                  {
                    if (Verbosity() >= 4)
                    {
                      LOG(4, CLR_CYAN,
                          "[EventDisplayTree][fill] dispatching fillEventDisplayDiagnostics "
                          << "(evt=" << ecvt << " rKey=" << rKey
                          << " ptBin=" << ptBin
                          << " cat=" << static_cast<int>(cat) << ")");
                    }

                      fillEventDisplayDiagnostics(rKey,
                                                 ptBin,
                                                 cat,
                                                 (m_isSim ? tPt : -9999.0),
                                                 (m_isSim ? tPhi : -9999.0),
                                                 leadPtGamma,
                                                 leadEtaGamma,
                                                 leadPhiGamma,
                                                 recoil1Jet,
                                                 (m_isSim ? rjTruthBest : nullptr),
                                                 (m_isSim ? tjLead : nullptr));

                    if (Verbosity() >= 4)
                    {
                      LOG(4, CLR_GREEN,
                          "[EventDisplayTree][fill] returned from fillEventDisplayDiagnostics "
                          << "(evt=" << ecvt << " rKey=" << rKey
                          << " ptBin=" << ptBin
                          << " cat=" << static_cast<int>(cat) << ")");
                    }
                  }
                }
              }
            }

        // ------------------------------------------------------------------
        // diagnostics (SIM-only): characterize the selected recoilJet1 in each class.
        //
        // Filled only when recoil1Jet exists (i.e. the event actually contributes to reco xJ).
        // ------------------------------------------------------------------
        if (recoil1Jet && tjLead)
        {
          const double ptReco1  = recoil1Jet->get_pt();
          const double ptTruth  = tjLead->get_pt();

          const double phiReco1 = recoil1Jet->get_phi();

          if (std::isfinite(ptReco1) && std::isfinite(ptTruth) && ptReco1 > 0.0 && ptTruth > 0.0)
          {
            // Use truth photon axis (tPhi) to keep this within the truth-conditioned block.
            // (haveTruthPho ensures reco and truth photon directions are aligned event-by-event.)
            const double dphiReco1 = std::fabs(TVector2::Phi_mpi_pi(phiReco1 - tPhi));
            const double dRReco1TruthLead = drLead;

            const double xJReco1 = (leadPtGamma > 0.0 ? (ptReco1 / leadPtGamma) : 0.0);

            for (const auto& trigShort : activeTrig)
            {
              if (leadRecoMatches)
              {
                // (A1) pT(recoilJet1^reco) vs pT(truth-leading recoil jet)
                if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtTruthLead_num(trigShort, rKey, effCentIdx_M))
                { h->Fill(ptTruth, ptReco1); bumpHistFill(trigShort, h->GetName()); }

                // (A2) pT(recoilJet1^reco) vs pT(reco jet matched to truth-leading recoil jet)
                if (hasRecoMatchToTruthLead && rjTruthBest)
                {
                  const double ptRecoMatch = rjTruthBest->get_pt();
                  if (std::isfinite(ptRecoMatch) && ptRecoMatch > 0.0)
                  {
                    if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtRecoTruthMatch_num(trigShort, rKey, effCentIdx_M))
                    { h->Fill(ptRecoMatch, ptReco1); bumpHistFill(trigShort, h->GetName()); }
                  }
                }

                // (B3) |Δphi(γ^truth, recoilJet1^reco)| vs pTγ,truth
                if (auto* h = getOrBookLeadTruthRecoilMatchDphiRecoJet1VsPtGammaTruth_num(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dphiReco1); bumpHistFill(trigShort, h->GetName()); }

                // (B4) ΔR(recoilJet1^reco, truth-leading recoil jet) vs pTγ,truth
                if (auto* h = getOrBookLeadTruthRecoilMatchDRRecoJet1VsPtGammaTruth_num(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dRReco1TruthLead); bumpHistFill(trigShort, h->GetName()); }

                // (C5) xJ(recoilJet1^reco) vs |Δphi(γ^truth, recoilJet1^reco)|
                if (auto* h = getOrBookLeadTruthRecoilMatchXJRecoJet1VsDphiRecoJet1_num(trigShort, rKey, effCentIdx_M))
                { h->Fill(dphiReco1, xJReco1); bumpHistFill(trigShort, h->GetName()); }
              }
              else if (hasRecoMatchToTruthLead)
              {
                // MissA: truth-leading recoil jet is reconstructed, but we selected the wrong reco recoilJet1

                if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtTruthLead_missA(trigShort, rKey, effCentIdx_M))
                { h->Fill(ptTruth, ptReco1); bumpHistFill(trigShort, h->GetName()); }

                if (truthMatchPassesRecoil)
                {
                  if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtTruthLead_missA1(trigShort, rKey, effCentIdx_M))
                  { h->Fill(ptTruth, ptReco1); bumpHistFill(trigShort, h->GetName()); }
                }
                else
                {
                  if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtTruthLead_missA2(trigShort, rKey, effCentIdx_M))
                  { h->Fill(ptTruth, ptReco1); bumpHistFill(trigShort, h->GetName()); }
                }

                if (rjTruthBest)
                {
                  const double ptRecoMatch = rjTruthBest->get_pt();
                  if (std::isfinite(ptRecoMatch) && ptRecoMatch > 0.0)
                  {
                    if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtRecoTruthMatch_missA(trigShort, rKey, effCentIdx_M))
                    { h->Fill(ptRecoMatch, ptReco1); bumpHistFill(trigShort, h->GetName()); }

                    if (truthMatchPassesRecoil)
                    {
                      if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtRecoTruthMatch_missA1(trigShort, rKey, effCentIdx_M))
                      { h->Fill(ptRecoMatch, ptReco1); bumpHistFill(trigShort, h->GetName()); }
                    }
                    else
                    {
                      if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtRecoTruthMatch_missA2(trigShort, rKey, effCentIdx_M))
                      { h->Fill(ptRecoMatch, ptReco1); bumpHistFill(trigShort, h->GetName()); }
                    }
                  }
                }

                if (auto* h = getOrBookLeadTruthRecoilMatchDphiRecoJet1VsPtGammaTruth_missA(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dphiReco1); bumpHistFill(trigShort, h->GetName()); }

                if (auto* h = getOrBookLeadTruthRecoilMatchDRRecoJet1VsPtGammaTruth_missA(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dRReco1TruthLead); bumpHistFill(trigShort, h->GetName()); }

                if (auto* h = getOrBookLeadTruthRecoilMatchXJRecoJet1VsDphiRecoJet1_missA(trigShort, rKey, effCentIdx_M))
                { h->Fill(dphiReco1, xJReco1); bumpHistFill(trigShort, h->GetName()); }
              }
              else
              {
                // MissB: truth-leading recoil jet has no reco match among recoJetsFid

                if (auto* h = getOrBookLeadTruthRecoilMatchPtRecoJet1VsPtTruthLead_missB(trigShort, rKey, effCentIdx_M))
                { h->Fill(ptTruth, ptReco1); bumpHistFill(trigShort, h->GetName()); }

                if (auto* h = getOrBookLeadTruthRecoilMatchDphiRecoJet1VsPtGammaTruth_missB(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dphiReco1); bumpHistFill(trigShort, h->GetName()); }

                if (auto* h = getOrBookLeadTruthRecoilMatchDRRecoJet1VsPtGammaTruth_missB(trigShort, rKey, effCentIdx_M))
                { h->Fill(tPt, dRReco1TruthLead); bumpHistFill(trigShort, h->GetName()); }

                if (auto* h = getOrBookLeadTruthRecoilMatchXJRecoJet1VsDphiRecoJet1_missB(trigShort, rKey, effCentIdx_M))
                { h->Fill(dphiReco1, xJReco1); bumpHistFill(trigShort, h->GetName()); }
              }
            }
          }
        }
      }
    }

    // Complete event-leading response bookkeeping. Keep this family separate
    // from the inclusive per-photon response: one selected reco recoilJet1
    // and one no-fallback global-leading truth recoil jet per event.
    if (haveRecoPhoton || tjLead)
    {
      for (const auto& trigShort : activeTrig)
      {
        auto* hLeadReco = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "reco");
        auto* hLeadTruth = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "truth");
        auto* hLeadResponse = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "response");
        auto* hLeadFake = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "fake");
        auto* hLeadMiss = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "miss");
        auto* hLeadSelectionLoss = getOrBookUnfoldLeadPtXJComponent(trigShort, rKey, effCentIdx_M, "selectionLoss");

        if (!hLeadReco || !hLeadTruth || !hLeadResponse || !hLeadFake ||
            !hLeadMiss || !hLeadSelectionLoss)
          continue;

        const bool validTruthLead =
          (tjLead && std::isfinite(tPt) && tPt > 0.0 &&
           std::isfinite(tjLead->get_pt()) && tjLead->get_pt() > 0.0);
        const bool validRecoLead =
          (recoil1Jet && std::isfinite(leadPtGamma) && leadPtGamma > 0.0 &&
           std::isfinite(recoil1Jet->get_pt()) && recoil1Jet->get_pt() > 0.0);

        const double xJTruthLead = validTruthLead ? tjLead->get_pt() / tPt : 0.0;
        const double xJRecoLead = validRecoLead ? recoil1Jet->get_pt() / leadPtGamma : 0.0;

        if (validTruthLead)
        {
          hLeadTruth->Fill(tPt, xJTruthLead);
          bumpHistFill(trigShort, hLeadTruth->GetName());
        }

        if (haveTruthPho && validTruthLead && validRecoLead && leadRecoMatches)
        {
          const int gTruth = hLeadTruth->FindBin(tPt, xJTruthLead);
          const int gReco = hLeadReco->FindBin(leadPtGamma, xJRecoLead);
          hLeadResponse->Fill(static_cast<double>(gTruth), static_cast<double>(gReco));
          bumpHistFill(trigShort, hLeadResponse->GetName());
        }
        else
        {
          if (validTruthLead)
          {
            hLeadMiss->Fill(tPt, xJTruthLead);
            bumpHistFill(trigShort, hLeadMiss->GetName());
          }
          if (validRecoLead)
          {
            hLeadFake->Fill(leadPtGamma, xJRecoLead);
            bumpHistFill(trigShort, hLeadFake->GetName());
          }
          if (haveTruthPho && validTruthLead &&
              hasRecoMatchToTruthLead && !leadRecoMatches)
          {
            hLeadSelectionLoss->Fill(tPt, xJTruthLead);
            bumpHistFill(trigShort, hLeadSelectionLoss->GetName());
          }
        }
      }
    }

  // 2) Jet ΔR matching (fiducial jets only) to build response + fakes/misses
  struct CandPair { double dr; int iReco; int iTruth; };
  std::vector<CandPair> cands;
  cands.reserve(recoJetsFid.size() * truthJetsFid.size());

  for (int ir = 0; ir < static_cast<int>(recoJetsFid.size()); ++ir)
  {
    const Jet* rj = recoJetsFid[ir];
    if (!rj) continue;

    for (int it = 0; it < static_cast<int>(truthJetsFid.size()); ++it)
    {
      const Jet* tj = truthJetsFid[it];
      if (!tj) continue;

      const double dr = dR(rj->get_eta(), rj->get_phi(), tj->get_eta(), tj->get_phi());
      if (dr < m_jetMatchDRMax) cands.push_back({dr, ir, it});
    }
  }

  std::sort(cands.begin(), cands.end(),
            [](const CandPair& a, const CandPair& b){ return a.dr < b.dr; });

  std::vector<char> recoMatched(recoJetsFid.size(), 0);
  std::vector<char> truthMatched(truthJetsFid.size(), 0);

  for (const auto& trigShort : activeTrig)
  {
    // IMPORTANT:
    // recoMatched/truthMatched must be per-trigger bookkeeping because we fill a
    // complete set of histograms per trigger. If activeTrig has multiple entries,
    // we must reset these flags each iteration to avoid cross-trigger state leakage.
    std::fill(recoMatched.begin(), recoMatched.end(), 0);
    std::fill(truthMatched.begin(), truthMatched.end(), 0);

    auto* h2Reco  = getOrBookUnfoldRecoPtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* h2Truth = getOrBookUnfoldTruthPtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* hRsp    = getOrBookUnfoldResponsePtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* hFake   = getOrBookUnfoldRecoFakesPtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* hMiss   = getOrBookUnfoldTruthMissesPtXJIncl(trigShort, rKey, effCentIdx_M);

    auto* h2RecoM  = getOrBookUnfoldRecoMatchedPtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* h2TruthM = getOrBookUnfoldTruthMatchedPtXJIncl(trigShort, rKey, effCentIdx_M);

    auto* hJetEffDen = getOrBookUnfoldJetEffDenPtXJIncl(trigShort, rKey, effCentIdx_M);
    auto* hJetEffNum = getOrBookUnfoldJetEffNumPtXJIncl(trigShort, rKey, effCentIdx_M);

    auto* hFakeA   = getOrBookUnfoldRecoFakesPtXJIncl_typeA(trigShort, rKey, effCentIdx_M);
    auto* hFakeB   = getOrBookUnfoldRecoFakesPtXJIncl_typeB(trigShort, rKey, effCentIdx_M);
    auto* hMissA   = getOrBookUnfoldTruthMissesPtXJIncl_typeA(trigShort, rKey, effCentIdx_M);
    auto* hMissB   = getOrBookUnfoldTruthMissesPtXJIncl_typeB(trigShort, rKey, effCentIdx_M);

    auto* hDR           = getOrBookUnfoldJetMatchDR(trigShort, rKey, effCentIdx_M);
    auto* hPtResp       = getOrBookUnfoldJetPtResponsePtTruth(trigShort, rKey, effCentIdx_M);
    auto* hPtRespAll    = getOrBookUnfoldJetPtResponseAllPtTruth(trigShort, rKey, effCentIdx_M);
    auto* hPtRespLead   = getOrBookLeadRecoilJetPtResponsePtTruth(trigShort, rKey, effCentIdx_M);
    auto* hPtScatterLead= getOrBookLeadRecoilJetPtTruthPtReco(trigShort, rKey, effCentIdx_M);
    auto* hDRLead       = getOrBookLeadRecoilJetMatchDR(trigShort, rKey, effCentIdx_M);

    if (!h2Reco || !h2Truth || !hRsp || !hFake || !hMiss || !hJetEffDen || !hJetEffNum) continue;

    if (haveTruthTarget)
    {
        const double ptTruthMinJetEff = (!m_unfoldTruthPhotonPtBins.empty() ? m_unfoldTruthPhotonPtBins.front() : 0.0);
        const double ptTruthMaxJetEff = (!m_unfoldTruthPhotonPtBins.empty() ? m_unfoldTruthPhotonPtBins.back() : std::numeric_limits<double>::infinity());
        const double xJMinJetEff = (!m_unfoldXJBins.empty() ? m_unfoldXJBins.front() : 0.0);
        const double xJMaxJetEff = (!m_unfoldXJBins.empty() ? m_unfoldXJBins.back() : std::numeric_limits<double>::infinity());

        if (tPt >= ptTruthMinJetEff && tPt < ptTruthMaxJetEff)
        {
          for (std::size_t it = 0; it < truthJetsFid.size(); ++it)
          {
            if (!truthJetsFidIsRecoil[it]) continue;

            const Jet* tj = truthJetsFid[it];
            if (!tj) continue;

            const double xJt = tj->get_pt() / tPt;
            if (!(xJt >= xJMinJetEff && xJt < xJMaxJetEff)) continue;

            hJetEffDen->Fill(tPt, xJt);
            bumpHistFill(trigShort, hJetEffDen->GetName());

            if (truthJetEffRecoPass[it])
            {
              hJetEffNum->Fill(tPt, xJt);
              bumpHistFill(trigShort, hJetEffNum->GetName());
            }
          }
        }
      }

      if (!haveTruthPho)
      {
        if (haveTruthTarget)
        {
          for (std::size_t it = 0; it < truthJetsFid.size(); ++it)
          {
            if (!truthJetsFidIsRecoil[it]) continue;

            const Jet* tj = truthJetsFid[it];
            if (!tj) continue;

            const double xJt = tj->get_pt() / tPt;

            hMiss->Fill(tPt, xJt);
            bumpHistFill(trigShort, hMiss->GetName());
          }
        }

        if (haveRecoPhoton)
        {
          for (std::size_t ir = 0; ir < recoJetsFid.size(); ++ir)
          {
            if (!recoJetsFidIsRecoil[ir]) continue;

            const Jet* rj = recoJetsFid[ir];
            if (!rj) continue;

            const double xJr = rj->get_pt() / leadPtGamma;

            hFake->Fill(leadPtGamma, xJr);
            bumpHistFill(trigShort, hFake->GetName());
          }
        }

        continue;
      }

    // --- greedy one-to-one matching ---
    for (const auto& cp : cands)
    {
        if (recoMatched[cp.iReco]) continue;
        if (truthMatched[cp.iTruth]) continue;

        recoMatched[cp.iReco]   = 1;
        truthMatched[cp.iTruth] = 1;

        const Jet* rj = recoJetsFid[cp.iReco];
        const Jet* tj = truthJetsFid[cp.iTruth];
        if (!rj || !tj) continue;

        const bool recoSel  = (recoJetsFidIsRecoil[cp.iReco] != 0);
        const bool truthSel = (truthJetsFidIsRecoil[cp.iTruth] != 0);

        const double xJr = rj->get_pt() / leadPtGamma;
        const double xJt = tj->get_pt() / tPt;

        // --- inclusive matched-fiducial pT response (no truthSel/recoSel gating) ---
        if (hPtRespAll && tj->get_pt() > 0.0)
        {
          hPtRespAll->Fill(tj->get_pt(), rj->get_pt() / tj->get_pt());
          bumpHistFill(trigShort, hPtRespAll->GetName());
        }

        // --- lead recoil jet1 response + ΔR sanity + pT scatter ---
        if (recoil1Jet && (rj == recoil1Jet))
        {
          if (hDRLead)
          { hDRLead->Fill(cp.dr); bumpHistFill(trigShort, hDRLead->GetName()); }

          if (tj->get_pt() > 0.0)
          {
            if (hPtRespLead)
            { hPtRespLead->Fill(tj->get_pt(), rj->get_pt() / tj->get_pt()); bumpHistFill(trigShort, hPtRespLead->GetName()); }

            if (hPtScatterLead)
            { hPtScatterLead->Fill(tj->get_pt(), rj->get_pt()); bumpHistFill(trigShort, hPtScatterLead->GetName()); }
          }
        }

        if (truthSel && recoSel)
        {
          const int gTruth = h2Truth->FindBin(tPt, xJt);
          const int gReco  = h2Reco->FindBin(leadPtGamma, xJr);

          hRsp->Fill(static_cast<double>(gTruth), static_cast<double>(gReco));
          bumpHistFill(trigShort, hRsp->GetName());

          if (h2TruthM)
          { h2TruthM->Fill(tPt, xJt); bumpHistFill(trigShort, h2TruthM->GetName()); }

          if (h2RecoM)
          { h2RecoM->Fill(leadPtGamma, xJr); bumpHistFill(trigShort, h2RecoM->GetName()); }

          if (hDR)
          { hDR->Fill(cp.dr); bumpHistFill(trigShort, hDR->GetName()); }

          if (hPtResp && tj->get_pt() > 0.0)
          { hPtResp->Fill(tj->get_pt(), rj->get_pt() / tj->get_pt()); bumpHistFill(trigShort, hPtResp->GetName()); }
      }
      else if (truthSel && !recoSel)
      {
        hMiss->Fill(tPt, xJt);
        bumpHistFill(trigShort, hMiss->GetName());

        if (hMissA)
        { hMissA->Fill(tPt, xJt); bumpHistFill(trigShort, hMissA->GetName()); }
      }
      else if (!truthSel && recoSel)
      {
        hFake->Fill(leadPtGamma, xJr);
        bumpHistFill(trigShort, hFake->GetName());

        if (hFakeA)
        { hFakeA->Fill(leadPtGamma, xJr); bumpHistFill(trigShort, hFakeA->GetName()); }
      }
    }

    // --- unmatched truth recoil jets => MISS type B ---
    for (std::size_t it = 0; it < truthJetsFid.size(); ++it)
    {
      if (truthMatched[it]) continue;
      if (!truthJetsFidIsRecoil[it]) continue;

      const Jet* tj = truthJetsFid[it];
      if (!tj) continue;

      const double xJt = tj->get_pt() / tPt;

      hMiss->Fill(tPt, xJt);
      bumpHistFill(trigShort, hMiss->GetName());

      if (hMissB)
      { hMissB->Fill(tPt, xJt); bumpHistFill(trigShort, hMissB->GetName()); }
    }

    // --- unmatched reco recoil jets => FAKE type B ---
    for (std::size_t ir = 0; ir < recoJetsFid.size(); ++ir)
    {
      if (recoMatched[ir]) continue;
      if (!recoJetsFidIsRecoil[ir]) continue;

      const Jet* rj = recoJetsFid[ir];
      if (!rj) continue;

      const double xJr = rj->get_pt() / leadPtGamma;

      hFake->Fill(leadPtGamma, xJr);
      bumpHistFill(trigShort, hFake->GetName());

      if (hFakeB)
      { hFakeB->Fill(leadPtGamma, xJr); bumpHistFill(trigShort, hFakeB->GetName()); }
    }
  }
}



void RecoilJets::fillRecoTruthJES3MatchingQA(const std::vector<std::string>& activeTrig,
                                            const std::string& rKey,
                                            const int effCentIdx_M,
                                            const double leadPtGamma,
                                            const double xJ,
                                            const double alpha,
                                            const double tPt,
                                            const double tEta,
                                            const double tPhi,
                                            const Jet* recoil1Jet)
{
  // Local dR helper (identical behavior to the lambda you use in the caller)
  auto dR = [](double eta1, double phi1, double eta2, double phi2) -> double
  {
    const double dphi = TVector2::Phi_mpi_pi(phi1 - phi2);
    const double deta = eta1 - eta2;
    return std::sqrt(deta*deta + dphi*dphi);
  };

  //  RECO truth-PHOTON-tagged subset (photon match only; no truth-jet match required)
  for (const auto& trigShort : activeTrig)
  {
    if (auto* hTagPho = getOrBookJES3RecoTruthPhoTagged_xJ_alphaHist(trigShort, rKey, effCentIdx_M))
    { hTagPho->Fill(leadPtGamma, xJ, alpha); bumpHistFill(trigShort, hTagPho->GetName()); }
  }

  const std::string jetRKey = baseRKeyFromDphiHistKey(rKey);
  JetContainer* truthJets = nullptr;
  if (auto itT = m_truthJetsByRKey.find(jetRKey); itT != m_truthJetsByRKey.end()) truthJets = itT->second;

  if (!truthJets)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW, "      [truthQA] rKey=" << rKey << " truth jets missing → skip truth JES3 fills");
    return;
  }
  else if (tPt <= 0.0)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW, "      [truthQA] rKey=" << rKey << " matched truth gamma has invalid pT → skip truth JES3 fills");
    return;
  }

  // truth recoil jets (same R): mirror RECO chronology for the jet1 definition
  //   - pick GLOBAL leading truth jet first (after pT gate; NO eta/dphi pre-veto)
  //   - then veto if that chosen jet is not fiducial in eta (NO fallback)
  //   - then require it be back-to-back to the truth gamma
  const double etaMaxTruth = jetEtaAbsMaxForRKey(jetRKey);

  double tj1Pt = -1.0;
  const Jet* tj1 = nullptr;

  // 1) truth jet1: GLOBAL leading truth jet (pT gate only; no eta/dphi preselection)
  for (const Jet* tj : *truthJets)
  {
        if (!tj) continue;

        const double ptj  = tj->get_pt();
        const double etaj = tj->get_eta();
        const double phij = tj->get_phi();

        if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
        if (ptj < m_minJetPt) continue;

        // Photon–jet overlap veto (truth): exclude jets near the truth photon direction (ΔR < 0.4)
        const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
        const double detaPho = (etaj - tEta);
        const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

        if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
        {
          continue;
        }

        if (ptj > tj1Pt)
        {
          tj1Pt = ptj;
          tj1   = tj;
        }
    }

    if (!tj1 || tj1Pt <= 0.0)
    {
      if (Verbosity() >= 5)
        LOG(5, CLR_YELLOW, "      [truthQA] rKey=" << rKey << " no truth jet1 found → skip truth JES3 fills");
      return;
    }

    // 2) histmaker-style veto: if the chosen global-leading jet is not fiducial, reject (NO fallback)
    {
      const double etaj = tj1->get_eta();
      if (!std::isfinite(etaj) || (std::fabs(etaj) >= etaMaxTruth))
      {
        if (Verbosity() >= 5)
          LOG(5, CLR_YELLOW, "      [truthQA] rKey=" << rKey << " truth jet1 fails eta fiducial → skip truth JES3 fills");
        return;
      }
    }

    // 3) recoil requirement applied LAST to the chosen global-leading jet
    {
      const double phij = tj1->get_phi();
      const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(phij - tPhi));
      if (!std::isfinite(dphiAbs) || (dphiAbs < m_minBackToBack))
      {
        if (Verbosity() >= 5)
          LOG(5, CLR_YELLOW, "      [truthQA] rKey=" << rKey << " truth jet1 fails back-to-back → skip truth JES3 fills");
        return;
      }
  }

    // 2) truth jet2 for α: highest-pT fiducial truth jet excluding tj1 (NO Δφ requirement)
    double tj2Pt = -1.0;
    for (const Jet* tj : *truthJets)
    {
      if (!tj) continue;

      const double ptj  = tj->get_pt();
      const double etaj = tj->get_eta();
      const double phij = tj->get_phi();

      if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
      if (ptj < m_minJetPt) continue;

      // Photon–jet overlap veto (truth): exclude jets near the truth photon direction (ΔR < 0.4)
      const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
      const double detaPho = (etaj - tEta);
      const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

      if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
      {
        continue;
      }

      if (std::fabs(etaj) >= etaMaxTruth) continue;
      if (tj == tj1) continue;

      if (ptj > tj2Pt) tj2Pt = ptj;
    }

  const double xJt = tj1Pt / tPt;
  const double aT  = (tj2Pt > 0.0 ? (tj2Pt / tPt) : 0.0);

  // TRUTH reco-conditioned but NO reco↔truth jet match requirement
  for (const auto& trigShort : activeTrig)
  {
    if (auto* ht3_nm = getOrBookJES3TruthRecoCondNoJetMatch_xJ_alphaHist(trigShort, rKey, effCentIdx_M))
    { ht3_nm->Fill(tPt, xJt, aT); bumpHistFill(trigShort, ht3_nm->GetName()); }
  }

  // require reco jet1 ↔ truth jet1 match in ΔR for the "jet-matched truth" JES3
  const double recoJeta = recoil1Jet->get_eta();
  const double recoJphi = recoil1Jet->get_phi();
  const double drJet = dR(recoJeta, recoJphi, tj1->get_eta(), tj1->get_phi());

  if (drJet > m_jetMatchDRMax)
  {
      if (Verbosity() >= 5)
        LOG(5, CLR_YELLOW, "      [truthQA] rKey=" << rKey
                        << " reco jet1 ↔ truth jet1 ΔR=" << drJet << " > " << m_jetMatchDRMax << " → skip jet-matched truth JES3 fills");
      return;
  }

  for (const auto& trigShort : activeTrig)
  {
    // existing: TRUTH reco-conditioned + jet-matched
    if (auto* ht3x = getOrBookJES3Truth_xJ_alphaHist(trigShort, rKey, effCentIdx_M))
    { ht3x->Fill(tPt, xJt, aT); bumpHistFill(trigShort, ht3x->GetName()); }

    if (auto* ht3j = getOrBookJES3Truth_jet1Pt_alphaHist(trigShort, rKey, effCentIdx_M))
    { ht3j->Fill(tPt, tj1Pt, aT); bumpHistFill(trigShort, ht3j->GetName()); }

    // RECO truth-tagged (photon match + jet match)
    if (auto* hRecoTag = getOrBookJES3RecoTruthTagged_xJ_alphaHist(trigShort, rKey, effCentIdx_M))
    { hRecoTag->Fill(leadPtGamma, xJ, alpha); bumpHistFill(trigShort, hRecoTag->GetName()); }
  }
}


bool RecoilJets::runLeadIsoTightPhotonJetLoopAllRadii(
    const std::vector<std::string>& activeTrig,
    const int effCentIdx_M,
    const int centIdx,
    const int leadPhoIndex,
    const int leadPtIdx,
    const double leadPtGamma,
    const double leadEtaGamma,
    const double leadPhiGamma,
    const bool haveTruthPho,
    const double tPt,
    const double tEta,
    const double tPhi,
    PHG4TruthInfoContainer* truth)
{
  bool filledAnyRadius = false;

    // Run the EXACT SAME jet logic for every configured radius in parallel
  for (const auto& kv : m_jets)
  {
    const std::string baseRKey = kv.first;
    JetContainer* jets = kv.second;

    // Radius-dependent containment cut: |eta_jet| < 1.1 - R
    const double Rjet            = jetRFromKey(baseRKey);
    const double jetEtaAbsMaxUse = jetEtaAbsMaxForRKey(baseRKey);
    const double savedMinJetPt = m_minJetPt;
    const double savedMinBackToBack = m_minBackToBack;
    const std::vector<double> jetPtCuts = activeJetPtCuts();
    const std::vector<double> dphiCuts = activeBackToBackCuts();

    for (const double jetPtCut : jetPtCuts)
    {
      m_minJetPt = jetPtCut;
    for (const double dphiCut : dphiCuts)
    {
      m_minBackToBack = dphiCut;
      const std::string rKey = histRKeyForJetPtAndDphi(baseRKey, jetPtCut, dphiCut);

      if (!jets)
      {
        LOG(3, CLR_YELLOW,
            "      [lead pho#" << leadPhoIndex << "] rKey=" << rKey
            << " jet container is nullptr - cannot form xJ");

        // Still fill matching-QA once per event-leading iso+tight photon (per rKey)
        const int    status = 1;          // NoJetPt
        const double maxDphiFill = -0.01; // underflow sentinel

        for (const auto& trigShort : activeTrig)
        {
          if (auto* hs = getOrBookMatchStatusVsPtGamma(trigShort, rKey, effCentIdx_M))
          { hs->Fill(leadPtGamma, status); bumpHistFill(trigShort, hs->GetName()); }

          if (auto* hm = getOrBookMatchMaxDphiVsPtGamma(trigShort, rKey, effCentIdx_M))
          { hm->Fill(leadPtGamma, maxDphiFill); bumpHistFill(trigShort, hm->GetName()); }

          if (auto* pn = getOrBookNRecoilJetsVsPtGamma(trigShort, rKey, effCentIdx_M))
          { pn->Fill(leadPtGamma, 0.0); bumpHistFill(trigShort, pn->GetName()); }
        }
        continue;
      }

    // Scan jets:
    //   - baseline pT gate:        pT > m_minJetPt
    //   - fiducial containment:    |eta_jet| < jetEtaAbsMaxUse
    //   - recoil selection:        |Δφ(γ,jet)| >= m_minBackToBack
    //
    // IMPORTANT:
    //   - recoil1/recoil2 are still the leading/subleading recoil jets (your existing alpha logic).
    //   - we also cache *all* fiducial jets and a recoil-flag per jet so we can do
    //     inclusive photon–jet pairing (ATLAS-like) + build the unfolding response.
    int nPassPt   = 0;
    int nPassEta  = 0;
    int nPassDphi = 0;

    // lists for inclusive pairing + truth matching response
    std::vector<const Jet*> recoJetsFid;          // jets passing pT+eta
    std::vector<char>       recoJetsFidIsRecoil;  // whether each fid jet passes the recoil Δφ cut
    recoJetsFid.reserve(jets->size());
    recoJetsFidIsRecoil.reserve(jets->size());

    // Leading recoil jet (pass pT+eta+dphi): defines xJgamma
    double recoil1Pt = -1.0;
    const Jet* recoil1Jet = nullptr;

    // Leading + subleading jets in the full fiducial set (pass pT+eta; NO Δφ requirement)
    // Used for:
    //   - recoil-is-leading QA (compare recoil1Jet vs all1Jet)
    //   - alpha jet2 definition: highest-pT fiducial jet excluding recoil1Jet
    double all1Pt = -1.0;
    const Jet* all1Jet = nullptr;
    double all2Pt = -1.0;
    [[maybe_unused]]const Jet* all2Jet = nullptr;

    // max |Δφ| over jets that pass pT+eta (even if they fail the Δφ cut)
    double maxDphi = -1.0;

    for (const Jet* j : *jets)
    {
      if (!j) continue;

      const double jpt  = j->get_pt();
      const double jeta = j->get_eta();
      const double jphi = j->get_phi();

      if (!std::isfinite(jpt) || !std::isfinite(jeta) || !std::isfinite(jphi)) continue;
      if (jpt < m_minJetPt) continue;
        ++nPassPt;

        const bool passEta = (std::fabs(jeta) < jetEtaAbsMaxUse);


 //      // Track leading+subleading jets in the pT+eta set (NO Δφ requirement)
  //      if (jpt > all1Pt)
  //      {
  //        all2Pt  = all1Pt;
  //        all2Jet = all1Jet;
  //
  //        all1Pt  = jpt;
  //        all1Jet = j;
  //      }
  //      else if (jpt > all2Pt)
  //      {
  //        all2Pt  = jpt;
  //        all2Jet = j;
  //      }
          // Track leading+subleading jets in the pT+eta set (NO Δφ requirement)
          //   - ensure "leading jet" is not the photon: veto jets with ΔR(γ,jet) < 0.4
          // Photon–jet overlap veto: exclude jets near the photon direction (ΔR < 0.4)
                  const double dphiPho = TVector2::Phi_mpi_pi(jphi - leadPhiGamma);
                  const double detaPho = (jeta - leadEtaGamma);
                  const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

                  if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
                  {
                    continue;
                  }

                  // Track leading+subleading jets in the pT+eta set (NO Δφ requirement)
                  // NOTE: this is now the GLOBAL leading jet (after pT + overlap), regardless of eta.
                  if (jpt > all1Pt)
                  {
                    all2Pt  = all1Pt;
                    all2Jet = all1Jet;

                    all1Pt  = jpt;
                    all1Jet = j;
                  }
                  else if (jpt > all2Pt)
                  {
                    all2Pt  = jpt;
                    all2Jet = j;
                  }


                if (passEta)
                {
                  ++nPassEta;
                  const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(jphi - leadPhiGamma));
                  if (std::isfinite(dphiAbs) && dphiAbs > maxDphi) maxDphi = dphiAbs;

                  const bool isRecoil = (dphiAbs >= m_minBackToBack);

                  // cache fiducial jets for inclusive pairing / response matching
                  recoJetsFid.push_back(j);
                  recoJetsFidIsRecoil.push_back(isRecoil ? 1 : 0);

                  if (isRecoil)
                  {
                    ++nPassDphi;
                  }
                }
      }


      // Histmaker-style leading-jet definition:
      //   - pick the GLOBAL leading jet excluding photon overlap (all1Jet)
      //   - THEN veto the event if that chosen jet is not fiducial in eta (NO fallback)
      //   - THEN require it be back-to-back to define recoil1Jet
      if (all1Jet)
      {
        const double etaLead = all1Jet->get_eta();
        if (!std::isfinite(etaLead) || std::fabs(etaLead) >= jetEtaAbsMaxUse)
        {
          all1Pt  = -1.0;
          all1Jet = nullptr;
        }
      }

      if (all1Jet)
      {
        const double dphiLeadAbs = std::fabs(TVector2::Phi_mpi_pi(all1Jet->get_phi() - leadPhiGamma));
        if (std::isfinite(dphiLeadAbs) && dphiLeadAbs >= m_minBackToBack)
        {
          recoil1Pt  = all1Pt;
          recoil1Jet = all1Jet;
        }
      }

    // matching status category
    int status = 0;
    if (nPassPt == 0)                        status = 1; // NoJetPt
    else if (nPassEta == 0)                  status = 2; // NoJetEta
    else if (nPassDphi == 0 || !recoil1Jet)  status = 3; // NoBackToBack
    else                                     status = 4; // Matched

    const double maxDphiFill = (maxDphi >= 0.0 ? maxDphi : -0.01);

    // fill matching-QA histograms (radius-tagged; centrality-only suffix; pTgamma is axis)
    for (const auto& trigShort : activeTrig)
    {
      if (auto* hs = getOrBookMatchStatusVsPtGamma(trigShort, rKey, effCentIdx_M))
      { hs->Fill(leadPtGamma, status); bumpHistFill(trigShort, hs->GetName()); }

      if (auto* hm = getOrBookMatchMaxDphiVsPtGamma(trigShort, rKey, effCentIdx_M))
      { hm->Fill(leadPtGamma, maxDphiFill); bumpHistFill(trigShort, hm->GetName()); }

      if (auto* pn = getOrBookNRecoilJetsVsPtGamma(trigShort, rKey, effCentIdx_M))
      { pn->Fill(leadPtGamma, static_cast<double>(nPassDphi)); bumpHistFill(trigShort, pn->GetName()); }

      if (recoil1Jet)
      {
        const double dphiSel = std::fabs(TVector2::Phi_mpi_pi(recoil1Jet->get_phi() - leadPhiGamma));
        if (auto* hd = getOrBookMatchDphiVsPtGamma(trigShort, rKey, effCentIdx_M))
        { hd->Fill(leadPtGamma, dphiSel); bumpHistFill(trigShort, hd->GetName()); }

        const double isLeading = (all1Jet && recoil1Jet == all1Jet) ? 1.0 : 0.0;
        if (auto* hl = getOrBookRecoilIsLeadingVsPtGamma(trigShort, rKey, effCentIdx_M))
        { hl->Fill(leadPtGamma, isLeading); bumpHistFill(trigShort, hl->GetName()); }
      }
    }

      // ------------------------------------------------------------------
      // Inclusive γ–jet pairing histograms for unfolding (ATLAS-style)
      //
      // DATA reco stays unchanged.
      // SIM reco is now truth-signal-photon anchored so the reco marginal used by
      // RooUnfold matches the same photon-tagged signal definition as the 2D response.
      // Pairwise truth↔reco jet matching still happens below in
      // fillUnfoldResponseMatrixAndTruthDistributions().
      // ------------------------------------------------------------------
      if (!m_isSim || haveTruthPho)
      {
        for (std::size_t irj = 0; irj < recoJetsFid.size(); ++irj)
        {
          if (!recoJetsFidIsRecoil[irj]) continue;

          const Jet* rj = recoJetsFid[irj];
          if (!rj) continue;

          const double jpt  = rj->get_pt();
          const double jphi = rj->get_phi();
          if (!std::isfinite(jpt) || jpt <= 0.0) continue;
          if (!std::isfinite(jphi)) continue;

          const double xJr     = jpt / leadPtGamma;
          const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(jphi - leadPhiGamma));

          for (const auto& trigShort : activeTrig)
          {
            if (auto* h2 = getOrBookUnfoldRecoPtXJIncl(trigShort, rKey, effCentIdx_M))
            {
              h2->Fill(leadPtGamma, xJr);
              bumpHistFill(trigShort, h2->GetName());
            }

            // inclusive |Δphi(γ,jet)| for each recoil jet passing cuts
            if (auto* h2d = getOrBookUnfoldRecoPtDphiIncl(trigShort, rKey, effCentIdx_M))
            {
              h2d->Fill(leadPtGamma, dphiAbs);
              bumpHistFill(trigShort, h2d->GetName());
            }
          }
        }
      }

      // ------------------------------------------------------------------
      // response matrix + truth distribution for unfolding
      // ------------------------------------------------------------------
      if (m_isSim)
      {
          fillUnfoldResponseMatrixAndTruthDistributions(activeTrig,
                                                        rKey,
                                                        effCentIdx_M,
                                                        leadPtGamma,
                                                        leadEtaGamma,
                                                        leadPhiGamma,
                                                        haveTruthPho,
                                                        tPt,
                                                        tEta,
                                                        tPhi,
                                                        recoJetsFid,
                                                        recoJetsFidIsRecoil,
                                                        recoil1Jet);
      }

    // ------------------------------------------------------------------
    // Physics-output fills (xJ, alpha, JES3) + Jet13/Profile3D — radius-tagged
    // ------------------------------------------------------------------
    if (recoil1Pt > 0.0 && recoil1Jet)
    {
      filledAnyRadius = true;

      const double xJ = recoil1Pt / leadPtGamma;

        // α definition (correct + robust):
        //   jet2 = highest-pT *fiducial* jet (pT+eta) excluding the selected recoil jet,
        //          WITH photon–jet overlap removal so we do NOT count the photon clustered as a jet.
        //
        //   Overlap removal:
        //     require ΔR(γ, jet2) > max(0.30, R)  (0.30 ~ your isolation cone; R is jet radius)
        //
        //   No Δφ requirement on jet2 (standard α radiation proxy).
        const Jet* jet2Jet = nullptr;
        double jet2Pt = 0.0;

        auto dR = [](double eta1, double phi1, double eta2, double phi2) -> double
        {
          const double dphi = TVector2::Phi_mpi_pi(phi1 - phi2);
          const double deta = eta1 - eta2;
          return std::sqrt(deta*deta + dphi*dphi);
        };

        const double minPhoJetDR = std::max(0.30, Rjet);

        for (const Jet* j2 : recoJetsFid) // recoJetsFid already pass pT + eta
        {
          if (!j2) continue;
          if (j2 == recoil1Jet) continue;

          const double j2pt  = j2->get_pt();
          const double j2eta = j2->get_eta();
          const double j2phi = j2->get_phi();

          if (!std::isfinite(j2pt) || !std::isfinite(j2eta) || !std::isfinite(j2phi)) continue;

          // Photon–jet overlap removal (prevents alpha from being dominated by a jet at the photon direction)
          const double drPho = dR(j2eta, j2phi, leadEtaGamma, leadPhiGamma);
          if (drPho <= minPhoJetDR) continue;

          if (j2pt > jet2Pt)
          {
            jet2Pt  = j2pt;
            jet2Jet = j2;
          }
      }

      const double alpha = (leadPtGamma > 0.0 ? (jet2Pt / leadPtGamma) : 0.0);

      if (Verbosity() >= 5)
      {
        LOG(5, CLR_GREEN,
            "      [lead pho#" << leadPhoIndex << "] rKey=" << rKey
            << " (R=" << std::fixed << std::setprecision(2) << Rjet
            << ", |eta|<" << std::fixed << std::setprecision(2) << jetEtaAbsMaxUse << ")"
            << " | xJ=" << std::fixed << std::setprecision(3) << xJ
            << " jet1Pt=" << recoil1Pt
            << " jet2Pt(fid,no#Delta#phi)=" << jet2Pt
            << " alpha=" << alpha
            << " (passed dphi=" << nPassDphi
            << ", passed pt=" << nPassPt << ")");
      }

      const int effCentIdx = (m_isAuAu ? centIdx : -1);

      // Jet-only QA for selected jets (jet2 uses alpha-definition above)
      fillSelectedJetQA(activeTrig, leadPtIdx, effCentIdx, rKey, recoil1Jet, jet2Jet);

      // Jet13 + Balance3 (radius-tagged)
      {
        const double jeta1 = recoil1Jet->get_eta();
        const double jphi1 = TVector2::Phi_mpi_pi(recoil1Jet->get_phi());

        for (const auto& trigShort : activeTrig)
        {
          if (auto* h3j = getOrBookJet13RecoilJet1(trigShort, rKey))
          { h3j->Fill(leadPtGamma, jeta1, jphi1); bumpHistFill(trigShort, h3j->GetName()); }

          if (auto* p3 = getOrBookBalance3(trigShort, rKey))
          { p3->Fill(leadPtGamma, jeta1, jphi1, xJ); bumpHistFill(trigShort, p3->GetName()); }
        }
      }

      for (const auto& trigShort : activeTrig)
      {
        // DATA uses the selected photon directly; SIM keeps the same
        // truth-signal-photon anchor as the inclusive reco marginal.
        if (!m_isSim || haveTruthPho)
        {
          if (auto* hLeadReco = getOrBookUnfoldLeadPtXJComponent(
                trigShort, rKey, effCentIdx_M, "reco"))
          {
            hLeadReco->Fill(leadPtGamma, xJ);
            bumpHistFill(trigShort, hLeadReco->GetName());
          }
        }

        if (auto* hx = getOrBookXJHist(trigShort, rKey, leadPtIdx, effCentIdx))
        { hx->Fill(xJ); bumpHistFill(trigShort, hx->GetName()); }

        if (auto* hj1 = getOrBookJet1PtHist(trigShort, rKey, leadPtIdx, effCentIdx))
        { hj1->Fill(recoil1Pt); bumpHistFill(trigShort, hj1->GetName()); }

        if (auto* hj2 = getOrBookJet2PtHist(trigShort, rKey, leadPtIdx, effCentIdx))
        { hj2->Fill(jet2Pt); bumpHistFill(trigShort, hj2->GetName()); }

        if (auto* ha = getOrBookAlphaHist(trigShort, rKey, leadPtIdx, effCentIdx))
        { ha->Fill(alpha); bumpHistFill(trigShort, ha->GetName()); }

        if (auto* h3x = getOrBookJES3_xJ_alphaHist(trigShort, rKey, effCentIdx))
        { h3x->Fill(leadPtGamma, xJ, alpha); bumpHistFill(trigShort, h3x->GetName()); }

        if (auto* h3j = getOrBookJES3_jet1Pt_alphaHist(trigShort, rKey, effCentIdx))
        { h3j->Fill(leadPtGamma, recoil1Pt, alpha); bumpHistFill(trigShort, h3j->GetName()); }
      }

      // -------------------- SIM ONLY: truth matching QA (radius-tagged) --------------------
      if (m_isSim && truth && haveTruthPho)
      {
          fillRecoTruthJES3MatchingQA(activeTrig,
                                      rKey,
                                      effCentIdx_M,
                                      leadPtGamma,
                                      xJ,
                                      alpha,
                                      tPt,
                                      tEta,
                                      tPhi,
                                      recoil1Jet);
      }
    }
    else
    {
      if (Verbosity() >= 4)
      {
        LOG(4, CLR_YELLOW,
            "      [lead pho#" << leadPhoIndex << "] rKey=" << rKey
            << " no recoil jet1 passes Δφ/pt/eta cuts"
            << " [passed dphi=" << nPassDphi
            << ", passed pt=" << nPassPt
            << ", minBackToBack=" << m_minBackToBack
            << ", minJetPt=" << m_minJetPt
            << ", |eta|<" << std::fixed << std::setprecision(2) << jetEtaAbsMaxUse << "]");
      }
    }
    }
    }
    m_minBackToBack = savedMinBackToBack;
    m_minJetPt = savedMinJetPt;
  } // radii loop

  return filledAnyRadius;
}


void RecoilJets::runLeadIsoNonTightPhotonJetLoopAllRadii_SidebandC(
      const std::vector<std::string>& activeTrig,
      const int effCentIdx_M,
      const double leadPtGamma,
      const double leadEtaGamma,
      const double leadPhiGamma)
{
    for (const auto& kv : m_jets)
    {
      const std::string baseRKey = kv.first;
      JetContainer* jets = kv.second;
      const double jetEtaAbsMaxUse = jetEtaAbsMaxForRKey(baseRKey);

      if (!jets) continue;

      const double savedMinJetPt = m_minJetPt;
      const double savedMinBackToBack = m_minBackToBack;
      const std::vector<double> jetPtCuts = activeJetPtCuts();
      const std::vector<double> dphiCuts = activeBackToBackCuts();
      for (const double jetPtCut : jetPtCuts)
      {
      m_minJetPt = jetPtCut;
      for (const double dphiCut : dphiCuts)
      {
      m_minBackToBack = dphiCut;
      const std::string rKey = histRKeyForJetPtAndDphi(baseRKey, jetPtCut, dphiCut);

      std::vector<const Jet*> recoJetsFid;
      std::vector<char> recoJetsFidIsRecoil;
      recoJetsFid.reserve(jets->size());
      recoJetsFidIsRecoil.reserve(jets->size());

      for (const Jet* j : *jets)
      {
        if (!j) continue;

        const double jpt  = j->get_pt();
        const double jeta = j->get_eta();
        const double jphi = j->get_phi();

        if (!std::isfinite(jpt) || !std::isfinite(jeta) || !std::isfinite(jphi)) continue;
        if (jpt < m_minJetPt) continue;

        const double dphiPho = TVector2::Phi_mpi_pi(jphi - leadPhiGamma);
        const double detaPho = (jeta - leadEtaGamma);
        const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

        if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4))) continue;
        if (std::fabs(jeta) >= jetEtaAbsMaxUse) continue;

        const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(jphi - leadPhiGamma));

        recoJetsFid.push_back(j);
        recoJetsFidIsRecoil.push_back((dphiAbs >= m_minBackToBack) ? 1 : 0);
      }

      for (std::size_t irj = 0; irj < recoJetsFid.size(); ++irj)
      {
        if (!recoJetsFidIsRecoil[irj]) continue;

        const Jet* rj = recoJetsFid[irj];
        if (!rj) continue;

        const double jpt = rj->get_pt();
        if (!std::isfinite(jpt) || jpt <= 0.0) continue;

        const double xJr = jpt / leadPtGamma;

        for (const auto& trigShort : activeTrig)
        {
          if (auto* h2 = getOrBookUnfoldRecoPtXJInclSidebandC(trigShort, rKey, effCentIdx_M))
          {
            h2->Fill(leadPtGamma, xJr);
            bumpHistFill(trigShort, h2->GetName());
          }
        }
      }
      }
      }
      m_minBackToBack = savedMinBackToBack;
      m_minJetPt = savedMinJetPt;
   }
}


bool RecoilJets::runLeadIsoTightPhotonJetMatchingAndUnfolding(
    const std::vector<std::string>& activeTrig,
    const int effCentIdx_M,
    const int centIdx,
    const int leadPhoIndex,
    const int leadPtIdx,
    const double leadPtGamma,
    const double leadEtaGamma,
    const double leadPhiGamma,
    const bool haveTruthSigPho,
    const double tPtSig,
    const bool haveTruthPhoPPG12,
    const double recoPtTruthMatchPPG12,
    const bool haveTruthPho,
    const double tPt,
    const double tEta,
    const double tPhi,
    PHG4TruthInfoContainer* truth)
{
  // This function only does unfolding photon bookkeeping + delegates jet logic per radius.
  (void)haveTruthPhoPPG12;
  (void)recoPtTruthMatchPPG12;

    // -------------------- Photon-only unfolding fills (N_gamma) --------------------
    for (const auto& trigShort : activeTrig)
    {
      // DATA reco stays unchanged.
      // SIM reco is now truth-signal-photon conditioned so the measured SIM marginal
      // handed to RooUnfold is consistent with the strict selected-anchor response.
      if (!m_isSim || haveTruthPho)
      {
        if (auto* hR = getOrBookUnfoldRecoPhoPtGamma(trigShort, effCentIdx_M))
        { hR->Fill(leadPtGamma); bumpHistFill(trigShort, hR->GetName()); }
      }

      // Measured reco photon spectrum for the exploratory PPG12-style object-match family
      // is filled per reco iso+tight photon candidate in the photon loop for DATA only.
      // The SIM truth-tagged reco marginal is filled later, at the truth-object match point.

      if (m_isSim)
      {
        // Baseline reco photon fakes: selected reco photon not matching the truth signal photon
        // under the strict selected-anchor definition.
        if (!haveTruthPho)
        {
          if (auto* hRF = getOrBookUnfoldRecoPhoFakesPtGamma(trigShort, effCentIdx_M))
          { hRF->Fill(leadPtGamma); bumpHistFill(trigShort, hRF->GetName()); }
        }

          // Exploratory reco photon fakes under the PPG12-style object-match definition
          // are filled per reco iso+tight photon candidate before this event-level
          // jet-matching call so unmatched candidates are counted inclusively.

          // Baseline photon response (truth -> reco): strict selected-anchor definition.
          if (haveTruthSigPho && haveTruthPho)
          {
            if (auto* hResp = getOrBookUnfoldResponsePhoPtGamma(trigShort, effCentIdx_M))
            { hResp->Fill(tPtSig, leadPtGamma); bumpHistFill(trigShort, hResp->GetName()); }
          }

          // Baseline truth misses: strict selected-anchor definition.
          if (haveTruthSigPho && !haveTruthPho)
          {
            if (auto* hTM = getOrBookUnfoldTruthPhoMissesPtGamma(trigShort, effCentIdx_M))
            { hTM->Fill(tPtSig); bumpHistFill(trigShort, hTM->GetName()); }
          }
      }
    }

    if (m_isSim)
    {
      if (haveTruthPho)
      {
        fillPPG12Fig37LeadTagInput1D(activeTrig,
                                      "h_ppg12_fig37_input_leadtag_reco_pT_0",
                                      m_unfoldRecoPhotonPtBins,
                                      "p_{T}^{#gamma,reco} [GeV]",
                                      "Reco photons",
                                      leadPtGamma);
      }
      else
      {
        fillPPG12Fig37LeadTagInput1D(activeTrig,
                                      "h_ppg12_fig37_input_leadtag_fake_pT_0",
                                      m_unfoldRecoPhotonPtBins,
                                      "p_{T}^{#gamma,reco} [GeV]",
                                      "Reco fakes",
                                      leadPtGamma);
      }

      if (haveTruthSigPho && haveTruthPho)
      {
        fillPPG12Fig37LeadTagResponse(activeTrig,
                                       "h2_ppg12_fig37_input_leadtag_response_truth_reco_0",
                                       tPtSig,
                                       leadPtGamma);
      }
      else if (haveTruthSigPho)
      {
        fillPPG12Fig37LeadTagInput1D(activeTrig,
                                      "h_ppg12_fig37_input_leadtag_miss_pT_0",
                                      m_unfoldTruthPhotonPtBins,
                                      "p_{T}^{#gamma,truth} [GeV]",
                                      "Truth misses",
                                      tPtSig);
      }
    }


  if (Verbosity() >= 5)
  {
    LOG(5, CLR_CYAN,
        "      [lead pho#" << leadPhoIndex << "] jet matching for all radii"
        << " | pT^γ=" << std::fixed << std::setprecision(2) << leadPtGamma
        << " eta^γ=" << std::fixed << std::setprecision(3) << leadEtaGamma
        << " phi^γ=" << std::fixed << std::setprecision(3) << leadPhiGamma);
  }

  bool filledAnyRadius = false;

    filledAnyRadius =
        runLeadIsoTightPhotonJetLoopAllRadii(activeTrig,
                                             effCentIdx_M,
                                             centIdx,
                                             leadPhoIndex,
                                             leadPtIdx,
                                             leadPtGamma,
                                             leadEtaGamma,
                                             leadPhiGamma,
                                             haveTruthPho,
                                             tPt,
                                             tEta,
                                             tPhi,
                                             truth);

  return filledAnyRadius;
}

void RecoilJets::fillPureIsolationQA(PHCompositeNode* topNode,
                                     const std::vector<std::string>& activeTrig,
                                     const PhotonClusterv1* pho,
                                     const RawCluster* rc,
                                     const int ptIdx,
                                     const int centIdx,
                                     const double pt_gamma)
{
  const int effCentIdx = (m_isAuAu ? centIdx : -1);

  // Total isolation. PPG12 pp photon-yield mode uses the topo-cluster scalar;
  // legacy/default analyses keep the PhotonClusterBuilder tower-cone scalar.
  const bool usePPG12YieldIso =
      (m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldUseTopoIso && !m_isAuAu);
  const double builder_eiso_tot = eiso(rc, topNode);
  const double ppg12YieldRawEisoEt =
      usePPG12YieldIso ? ppg12PhotonYieldRawEiso(rc, topNode) : builder_eiso_tot;
  const double ppg12YieldEisoEt =
      usePPG12YieldIso ? ppg12PhotonYieldEiso(ppg12YieldRawEisoEt) : builder_eiso_tot;
  const double eiso_tot =
      usePPG12YieldIso ? ppg12YieldEisoEt : builder_eiso_tot;

  // Component isolation (PhotonClusterBuilder iso_* pieces)
  // Default to fail-safe (goes to overflow with your [-5,12] binning).
  double eiso_emcal  = 1e9;
  double eiso_hcalin = 1e9;
  double eiso_hcalout= 1e9;

  const int cone10 = static_cast<int>(std::lround(10.0 * m_isoConeR));

  // ----------------------------------------------------------------
  //  accumulate negative-iso fractions once per reco photon candidate
  // (NOT per trigger), and BEFORE any SS-based cuts.
  // ----------------------------------------------------------------
  if (ptIdx >= 0 && ptIdx < static_cast<int>(m_nIsoBuilderByPt.size()))
  {
    if (std::isfinite(builder_eiso_tot) && builder_eiso_tot < 1e8)
    {
      ++m_nIsoBuilderByPt[ptIdx];
      if (builder_eiso_tot < 0.0) ++m_nIsoBuilderNegByPt[ptIdx];
    }
  }

  const char* k_em = nullptr;
  const char* k_hi = nullptr;
  const char* k_ho = nullptr;

  if (cone10 == 3)
  {
    k_em = "iso_03_emcal";
    k_hi = "iso_03_hcalin";
    k_ho = "iso_03_hcalout";
  }
  else if (cone10 == 4)
  {
    k_em = "iso_04_emcal";
    k_hi = "iso_04_hcalin";
    k_ho = "iso_04_hcalout";
  }

  if (pho && k_em && k_hi && k_ho)
  {
    eiso_emcal   = pho->get_shower_shape_parameter(k_em);
    eiso_hcalin  = pho->get_shower_shape_parameter(k_hi);
    eiso_hcalout = pho->get_shower_shape_parameter(k_ho);

    // If any component is non-finite, treat as fail-safe (overflow)
    if (!std::isfinite(eiso_emcal) || !std::isfinite(eiso_hcalin) || !std::isfinite(eiso_hcalout))
    {
      eiso_emcal = eiso_hcalin = eiso_hcalout = 1e9;
    }
  }

  // Pure isolation threshold decision (signal line only)
  const double thrIso  = recoIsoThreshold(pt_gamma);
  const bool   isoPass = (eiso_tot < thrIso);
  const bool   doCone  = fillConeThisView();

  for (const auto& trigShort : activeTrig)
  {
    if (doCone)
    {
      // Raw isolation spectra depend on cone radius only, not fixed/sliding WP.
      if (auto* hIso = getOrBookIsoHist(trigShort, ptIdx, effCentIdx))
      {
        hIso->Fill(eiso_tot);
        bumpHistFill(trigShort, hIso->GetName());
      }

      if (usePPG12YieldIso)
      {
        if (auto* hRaw = getOrBookIsoPartHist(trigShort, "h_Eiso_ppg12_topo_raw",
                                             "E_{T}^{iso,raw topo} [GeV]",
                                             ptIdx, effCentIdx))
        {
          hRaw->Fill(ppg12YieldRawEisoEt);
          bumpHistFill(trigShort, hRaw->GetName());
        }
        if (auto* hReco = getOrBookIsoPartHist(trigShort, "h_Eiso_ppg12_topo_reco",
                                              "E_{T}^{iso,reco PPG12} [GeV]",
                                              ptIdx, effCentIdx))
        {
          hReco->Fill(ppg12YieldEisoEt);
          bumpHistFill(trigShort, hReco->GetName());
        }
      }
      else
      {
        if (auto* hEm = getOrBookIsoPartHist(trigShort, "h_Eiso_emcal",
                                             "E_{T}^{iso,EMCal} [GeV]",
                                             ptIdx, effCentIdx))
        {
          hEm->Fill(eiso_emcal);
          bumpHistFill(trigShort, hEm->GetName());
        }

        if (auto* hHi = getOrBookIsoPartHist(trigShort, "h_Eiso_hcalin",
                                             "E_{T}^{iso,IHCAL} [GeV]",
                                             ptIdx, effCentIdx))
        {
          hHi->Fill(eiso_hcalin);
          bumpHistFill(trigShort, hHi->GetName());
        }

        if (auto* hHo = getOrBookIsoPartHist(trigShort, "h_Eiso_hcalout",
                                             "E_{T}^{iso,OHCAL} [GeV]",
                                             ptIdx, effCentIdx))
        {
          hHo->Fill(eiso_hcalout);
          bumpHistFill(trigShort, hHo->GetName());
        }
      }
    }

    // The threshold decision depends on the full fixed/sliding iso view.
    if (auto* hDec = getOrBookIsoDecisionHist(trigShort, ptIdx, effCentIdx))
    {
      hDec->Fill(isoPass ? 1 : 2);   // bin 1 = PASS, bin 2 = FAIL
      bumpHistFill(trigShort, hDec->GetName());
    }
  }
}


void RecoilJets::fillTruthSigABCDLeakageCounters(PHCompositeNode* topNode,
                                                 const std::vector<std::string>& activeTrig,
                                                 const int centIdx)
{
  const int effCentIdx_sig = (m_isAuAu ? centIdx : -1);
  const bool doCanonical = fillCanonicalThisView();

  // G4 truth, not HepMC availability, defines the denominator population.
  // CaloRawClusterEval enforces the "BEST-MATCHED truth primary particle" condition
  CaloRawClusterEval clustereval(topNode, "CEMC");
  clustereval.set_usetowerinfo(true);
  clustereval.next_event(topNode);

  // Fallback if CLUSTERINFO_* is not available in the DST
  if (!clustereval.has_reduced_node_pointers())
  {
    if (Verbosity() >= 6)
    {
      LOG(6, CLR_YELLOW,
          "    [sigABCD] SIM: CaloRawClusterEval reduced nodes missing with towerinfo=true → retry with towerinfo=false");
    }

    clustereval.set_usetowerinfo(false);
    clustereval.next_event(topNode);
  }

  if (!clustereval.has_reduced_node_pointers())
  {
    if (Verbosity() >= 4)
    {
      LOG(4, CLR_YELLOW,
          "    [sigABCD] SIM: CaloRawClusterEval missing required nodes → cannot truth↔reco match photons → skip leakage counters");
    }
    return;
  }

  const TruthSignalPhotonMap truthSignalByTrackIdForDiag =
      buildPPG12TruthSignalPhotonMap(topNode);
  const auto truthWitnesses = buildPPG12TruthPhotonWitnessMap(topNode);

  const PPG12PhotonSlice fig24PhotonSlice =
      (m_isSim && !m_isAuAu && m_ppg12PhotonYieldEnabled)
          ? ppg12PhotonSliceFromContext(Outfile)
          : PPG12PhotonSlice::kNone;
  double fig24StitchLo = std::numeric_limits<double>::quiet_NaN();
  double fig24StitchHi = std::numeric_limits<double>::quiet_NaN();
  const bool fig24PhotonSampleContext = (fig24PhotonSlice != PPG12PhotonSlice::kNone);
  const bool fig24HaveWindow =
      fig24PhotonSampleContext && ppg12PhotonSliceWindow(fig24PhotonSlice,
                                                         fig24StitchLo,
                                                         fig24StitchHi);
  const double fig24OwnerPhotonPt =
      fig24HaveWindow
          ? ppg12MaxStoredTruthPhotonPt(topNode, m_truthInfo, true, kPPG12Fig24EtaAbsMax)
          : -1.0;
  const bool fig24HaveOwnerTruth = (fig24OwnerPhotonPt >= 0.0);
  const bool fig24OwnedBySample =
      fig24HaveWindow && fig24HaveOwnerTruth &&
      ppg12WindowContains(fig24OwnerPhotonPt, fig24StitchLo, fig24StitchHi);

  const PPG12PhotonSlice fig6PhotonSlice = fig24PhotonSlice;
  double fig6StitchLo = std::numeric_limits<double>::quiet_NaN();
  double fig6StitchHi = std::numeric_limits<double>::quiet_NaN();
  const bool fig6PhotonSampleContext = (fig6PhotonSlice != PPG12PhotonSlice::kNone);
  const bool fig6HaveWindow =
      fig6PhotonSampleContext && ppg12PhotonSliceWindow(fig6PhotonSlice,
                                                        fig6StitchLo,
                                                        fig6StitchHi);
  const double fig6OwnerPhotonPt =
      fig6HaveWindow
          ? ppg12MaxStoredTruthPhotonPt(topNode, m_truthInfo, true)
          : -1.0;
  const bool fig6HaveOwnerTruth = (fig6OwnerPhotonPt >= 0.0);
  const bool fig6OwnedBySample =
      fig6HaveWindow && fig6HaveOwnerTruth &&
      ppg12WindowContains(fig6OwnerPhotonPt, fig6StitchLo, fig6StitchHi);
  const PPG12PhotonSlice fig3PhotonSlice = fig24PhotonSlice;
  const bool fig3PhotonSampleContext = (fig3PhotonSlice != PPG12PhotonSlice::kNone);
  // PPG12 RecoEffCalculator_TTreeReader rejects the complete event before
  // filling h_{direct,frag}_pT_truth_isoET_0 unless the largest stored truth
  // photon belongs to the declared PhotonJet5/10/20 ownership window.  The
  // stored-particle contract is identical to the Fig. 6 gate above, so reuse
  // that audited decision rather than allowing every slice to fill Fig. 3.
  const bool fig3HaveWindow = fig6HaveWindow;
  const bool fig3HaveOwnerTruth = fig6HaveOwnerTruth;
  const bool fig3OwnedBySample = fig6OwnedBySample;
  const bool fig3SampleAccepted =
      fig3PhotonSampleContext && fig3HaveWindow &&
      fig3HaveOwnerTruth && fig3OwnedBySample;
  const double fig3PhotonSliceWeight = fig3PhotonSampleContext
      ? (ppg12PhotonSliceXsecPb(fig3PhotonSlice) / kPPG12Photon20CrossPb)
      : 0.0;
  static int s_ppg12Fig6DebugPrints = 0;
  int ppg12Fig6DebugPrintLimit = 0;
  if (const char* raw = std::getenv("RJ_PPG12_FIG6_DEBUG_PRINT"))
  {
    try
    {
      ppg12Fig6DebugPrintLimit = std::max(0, std::stoi(raw));
    }
    catch (...)
    {
      ppg12Fig6DebugPrintLimit = 0;
    }
  }

  auto getOrBookPPStitchFlowHist = [&](const std::string& trig,
                                       const std::string& name,
                                       const std::string& xAxisTitle) -> TH1F*
  {
    if (trig.empty() || name.empty()) return nullptr;
    if (m_gammaPtBins.size() < 2) return nullptr;
    const std::string viewName = name;

    auto& H = qaHistogramsByTrigger[trig];
    if (auto it = H.find(viewName); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
      return nullptr;
    }

    if (!out || !out->IsOpen()) return nullptr;

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }

    dir->cd();
    const int nb = static_cast<int>(m_gammaPtBins.size()) - 1;
    const std::string title = viewName + ";" + xAxisTitle + ";raw entries";
    auto* h = RJMCWeighting::RJNewRawTH1F(viewName.c_str(), title.c_str(), nb, m_gammaPtBins.data());
    if (h) H[viewName] = h;
    if (prevDir) prevDir->cd();
    return h;
  };

  auto fillPPStitchFlow = [&](const std::string& base,
                              const double pt,
                              const std::string& xAxisTitle)
  {
    if (!doCanonical) return;
    if (!(m_isSim && !m_isAuAu && m_ppStitchDiagContext)) return;
    if (!std::isfinite(pt)) return;

    int replayStageCode = 0;
    static const std::array<const char*, 13> kReplayFlowNames{{
        "h_ppStitchDiag_flow_truthIso_truthPt_noVtxW",
        "h_ppStitchDiag_flow_truthIsoG4_truthPt_noVtxW",
        "h_ppStitchDiag_flow_rawClusterDR005_truthPt_noVtxW",
        "h_ppStitchDiag_flow_rawClusterDR010_truthPt_noVtxW",
        "h_ppStitchDiag_flow_rawPPG12Track_truthPt_noVtxW",
        "h_ppStitchDiag_flow_rawPPG12TrackFid_truthPt_noVtxW",
        "h_ppStitchDiag_flow_selectedPhotonDR005_truthPt_noVtxW",
        "h_ppStitchDiag_flow_selectedPhotonDR010_truthPt_noVtxW",
        "h_ppStitchDiag_flow_selectedPPG12Track_truthPt_noVtxW",
        "h_ppStitchDiag_flow_selectedPPG12TrackFid_truthPt_noVtxW",
        "h_ppStitchDiag_flow_legacyBarcodeDR005_truthPt_noVtxW",
        "h_ppStitchDiag_flow_recoMatched_recoPt_noVtxW",
        "h_ppStitchDiag_flow_validEiso_recoPt_noVtxW"}};
    for (std::size_t i = 0; i < kReplayFlowNames.size(); ++i)
    {
      if (base == kReplayFlowNames[i])
      {
        replayStageCode = static_cast<int>(i) + 1;
        break;
      }
    }
    if (replayStageCode == 0 &&
        base.rfind("h_ppStitchDiag_flow_stitch_", 0) == 0)
    {
      for (std::size_t i = 0; i < kPPStitchDiagVariants.size(); ++i)
      {
        const std::string expected = std::string("h_ppStitchDiag_flow_stitch_") +
            ppStitchDiagKey(kPPStitchDiagVariants[i]) +
            "_validEiso_recoPt_noVtxW";
        if (base == expected)
        {
          replayStageCode = 14 + static_cast<int>(i);
          break;
        }
      }
    }

    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookPPStitchFlowHist(trigShort, base, xAxisTitle))
      {
        h->Fill(pt);
        bumpHistFill(trigShort, base);
        if (m_replayFoundationEnabled && replayStageCode > 0)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "PP_STITCH_FLOW";
          row.stage_code = replayStageCode;
          row.flow_value = pt;
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
    }
  };

  auto fillPPG12PhotonEfficiencyStage = [&](const std::string& name,
                                            const double truthPt,
                                            const double weight)
  {
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!(m_isSim && !m_isAuAu)) return;
    if (name.empty() || !std::isfinite(truthPt) || truthPt <= 0.0) return;

    bookPPG12PhotonYieldSchema(activeTrig);
    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name,
                                                m_ppg12PhotonYieldTruthPtBins,
                                                "p_{T}^{#gamma,truth} [GeV]",
                                                "Entries"))
      {
        h->Fill(truthPt, weight);
        bumpHistFill(trigShort, name);
        if (m_replayFoundationEnabled &&
            name == "h_photonEffTruthDen_pTgamma_0")
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "TRUTH_EFFICIENCY_DEN_FILL";
          row.truth_photon_pt = truthPt;
          row.occurrence_weight = m_mcEventWeight * weight;
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
        if (m_replayFoundationEnabled)
        {
          static const std::map<std::string, int> kFig6StageCode = {
              {"h_photonEffPpg12Fig6TruthDen_pTgamma_0", 1},
              {"h_photonEffPpg12Fig6Reco_pTgamma_0", 2},
              {"h_photonEffPpg12Fig6RecoTight_pTgamma_0", 3},
              {"h_photonEffPpg12Fig6RecoIso_pTgamma_0", 4},
              {"h_photonEffPpg12Fig6RecoTightIso_pTgamma_0", 5}};
          if (const auto stage = kFig6StageCode.find(name); stage != kFig6StageCode.end())
          {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = trigShort;
            row.occurrence_kind = "PP_FIG6_EFFICIENCY_STAGE";
            row.stage_code = stage->second;
            row.truth_photon_pt = truthPt;
            row.occurrence_weight = m_mcEventWeight * weight;
            m_replayPPG12DiagnosticOccurrences.push_back(row);
          }
        }
      }
    }
  };

  auto fillPPG12Fig6OwnershipAudit = [&](const int stage,
                                         const double weight)
  {
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!(m_isSim && !m_isAuAu)) return;

    static const std::vector<double> kFig6AuditBins = {0.5, 1.5, 2.5, 3.5, 4.5, 5.5};
    bookPPG12PhotonYieldSchema(activeTrig);
    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookPPG12PhotonYield1D(trigShort,
                                                "h_ppg12_fig6_sample_ownership_audit",
                                                kFig6AuditBins,
                                                "Fig. 6 ownership gate stage",
                                                "Weighted entries"))
      {
        h->Fill(static_cast<double>(stage), weight);
        bumpHistFill(trigShort, h->GetName());
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "FIG6_OWNERSHIP_AUDIT";
          row.stage_code = stage;
          row.occurrence_weight = weight * RJMCWeighting::SafeWeight();
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
    }
  };

  auto fillPPG12Fig3OwnershipAudit = [&](const int stage)
  {
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!(m_isSim && !m_isAuAu)) return;

    static const std::vector<double> kFig3AuditBins = {0.5, 1.5, 2.5, 3.5, 4.5, 5.5};
    bookPPG12PhotonYieldSchema(activeTrig);
    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookPPG12PhotonYield1D(trigShort,
                                                "h_ppg12_fig3_sample_ownership_audit",
                                                kFig3AuditBins,
                                                "Fig. 3 ownership gate stage",
                                                "Weighted events"))
      {
        h->GetXaxis()->SetBinLabel(1, "input_event");
        h->GetXaxis()->SetBinLabel(2, "sample_context");
        h->GetXaxis()->SetBinLabel(3, "owner_truth_found");
        h->GetXaxis()->SetBinLabel(4, "owned_accepted");
        h->GetXaxis()->SetBinLabel(5, "ownership_rejected");
        h->Fill(static_cast<double>(stage));
        bumpHistFill(trigShort, h->GetName());
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "FIG3_OWNERSHIP_AUDIT";
          row.stage_code = stage;
          row.occurrence_weight = RJMCWeighting::SafeWeight();
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
    }
  };

  fillPPG12Fig3OwnershipAudit(1);
  if (fig3PhotonSampleContext) fillPPG12Fig3OwnershipAudit(2);
  if (fig3HaveOwnerTruth) fillPPG12Fig3OwnershipAudit(3);
  if (fig3SampleAccepted) fillPPG12Fig3OwnershipAudit(4);
  else fillPPG12Fig3OwnershipAudit(5);

  auto ppg12Fig6SampleAccepted = [&]() -> bool
  {
    if (!m_ppg12PhotonYieldEnabled) return true;
    if (!(m_isSim && !m_isAuAu)) return true;
    return fig6PhotonSampleContext && fig6HaveWindow &&
           fig6HaveOwnerTruth && fig6OwnedBySample;
  };

  auto maybePrintPPG12Fig6Gate = [&](const double truthPt,
                                     const double weight,
                                     const bool accepted)
  {
    if (ppg12Fig6DebugPrintLimit <= 0) return;
    if (s_ppg12Fig6DebugPrints >= ppg12Fig6DebugPrintLimit) return;
    ++s_ppg12Fig6DebugPrints;

    std::cout << "[PPG12_FIG6_GATE]"
              << " event=" << event_count
              << " sample=" << ppg12PhotonSliceName(fig6PhotonSlice)
              << " ownerPt=" << fig6OwnerPhotonPt
              << " window=[" << fig6StitchLo << ","
              << (std::isinf(fig6StitchHi) ? 200.0 : fig6StitchHi) << "]"
              << " truthPt=" << truthPt
              << " weight=" << weight
              << " context=" << fig6PhotonSampleContext
              << " haveWindow=" << fig6HaveWindow
              << " haveOwner=" << fig6HaveOwnerTruth
              << " owned=" << fig6OwnedBySample
              << " accepted=" << accepted
              << std::endl;
  };

  static int s_ppg12Fig6MatchDebugPrints = 0;
  int ppg12Fig6MatchDebugPrintLimit = 0;
  if (const char* raw = std::getenv("RJ_PPG12_FIG6_MATCH_DEBUG_PRINT"))
  {
    try
    {
      ppg12Fig6MatchDebugPrintLimit = std::max(0, std::stoi(raw));
    }
    catch (...)
    {
      ppg12Fig6MatchDebugPrintLimit = 0;
    }
  }

  auto fillPPG12Fig2TruthIso = [&](const int photonClass,
                                   const double truthPt,
                                   const double isoEtTruth)
  {
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!(m_isSim && !m_isAuAu)) return;
    if (!(photonClass == 1 || photonClass == 2)) return;
    if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
    if (!std::isfinite(isoEtTruth)) return;
    if (!std::isfinite(m_vz) || std::fabs(m_vz) >= 30.0) return;

    struct Fig2PtBin { double lo; double hi; const char* label; };
    static const std::array<Fig2PtBin, 3> kFig2PtBins = {{
        {10.0, 15.0, "10_15"},
        {15.0, 20.0, "15_20"},
        {25.0, 30.0, "25_30"},
    }};

    const Fig2PtBin* ptBin = nullptr;
    for (const auto& candidate : kFig2PtBins)
    {
      if (truthPt >= candidate.lo && truthPt < candidate.hi)
      {
        ptBin = &candidate;
        break;
      }
    }
    if (!ptBin) return;

    const char* classKey = (photonClass == 1) ? "direct" : "frag";
    const std::string histName =
        std::string("h_ppg12_fig2_truthIso_") + classKey +
        "_pT_" + ptBin->label + "_eta07_vz30_r03";

    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookTruthIsoHist(trigShort, histName, 500, 0.0, 50.0))
      {
        h->Fill(isoEtTruth);
        bumpHistFill(trigShort, histName);
      }
    }
  };

  auto getOrBookPPG12Fig3TruthIso2D = [&](const std::string& trig,
                                          const std::string& classKey) -> TH2D*
  {
    if (trig.empty() || classKey.empty()) return nullptr;

    const std::string name =
        (classKey == "direct") ? "h_direct_pT_truth_isoET_0" :
        (classKey == "frag")   ? "h_frag_pT_truth_isoET_0"   :
                                  "";
    if (name.empty()) return nullptr;

    auto& H = qaHistogramsByTrigger[trig];
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH2D*>(it->second)) return h;
      H.erase(it);
    }

    if (!out || !out->IsOpen()) return nullptr;

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }

    dir->cd();
    const std::string title = name + ";p_{T}^{#gamma,truth} [GeV];E_{T}^{iso,truth} [GeV]";
    auto* h = RJMCWeighting::RJNewTH2D(name.c_str(), title.c_str(),
                                      400, 0.0, 40.0,
                                      400, 0.0, 40.0);
    if (h) h->Sumw2();
    H[name] = h;
    if (prevDir) prevDir->cd();
    return h;
  };

  auto fillPPG12Fig3TruthPt = [&](const int photonClass,
                                  const double truthPt,
                                  const double isoEtTruth,
                                  const bool passTruthIso)
  {
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!(m_isSim && !m_isAuAu)) return;
    if (!(photonClass == 1 || photonClass == 2)) return;
    if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
    if (!std::isfinite(m_vz) || std::fabs(m_vz) >= 30.0) return;
    if (!fig3PhotonSampleContext) return;
    if (!fig3SampleAccepted) return;
    if (!std::isfinite(fig3PhotonSliceWeight) || fig3PhotonSliceWeight <= 0.0) return;

    const char* classKey = (photonClass == 1) ? "direct" : "frag";
    if (std::isfinite(isoEtTruth))
    {
      for (const auto& trigShort : activeTrig)
      {
        if (auto* h2 = getOrBookPPG12Fig3TruthIso2D(trigShort, classKey))
        {
          h2->Fill(truthPt, isoEtTruth);
          bumpHistFill(trigShort, h2->GetName());
          if (m_replayFoundationEnabled)
          {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = trigShort;
            row.occurrence_kind = "PP_FIG3_TRUTH_ISOLATION";
            row.source_code = photonClass;
            row.truth_photon_pt = truthPt;
            row.flow_value = isoEtTruth;
            row.occurrence_weight = m_mcEventWeight;
            m_replayPPG12DiagnosticOccurrences.push_back(row);
          }
        }
      }
    }

    if (!passTruthIso) return;
    if (truthPt < 10.0 || truthPt >= 35.0) return;

    static const std::vector<double> kFig3TruthPtBins = []()
    {
      std::vector<double> bins;
      for (int edge = 10; edge <= 35; ++edge) bins.push_back(static_cast<double>(edge));
      return bins;
    }();

    const std::array<std::string, 2> names = {{
      "h_ppg12_fig3_truthPt_total_eta07_vz30_r03_iso4",
      std::string("h_ppg12_fig3_truthPt_") + classKey + "_eta07_vz30_r03_iso4"
    }};

    for (const auto& trigShort : activeTrig)
    {
      for (const auto& histName : names)
      {
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, histName,
                                                  kFig3TruthPtBins,
                                                  "p_{T}^{#gamma,truth} [GeV]",
                                                  "Weighted entries"))
        {
          h->Fill(truthPt);
          bumpHistFill(trigShort, histName);
        }
      }
    }
  };

  int nTruthSig        = 0;
  int nTruthSigMatched = 0;

  for (const auto& truthEntry : truthWitnesses)
  {
    const auto& truthWitness = truthEntry.second;
    const int ppg12Fig2Class = truthWitness.photonClass;
    const double isoEtTruth = truthWitness.isoEtR03;
    const int targetTrackIdForDiag = truthEntry.first;
    const bool havePPG12TruthForDiag =
        truthSignalByTrackIdForDiag.count(targetTrackIdForDiag) != 0;
    const auto& ppg12TruthInfoForDiag = truthWitness;
    const bool passTruthIso = havePPG12TruthForDiag;
    fillPPG12Fig3TruthPt(ppg12Fig2Class, truthWitness.pt, isoEtTruth, passTruthIso);

    // ---------------------------
    //  Truth isolation QA (SIM)
    // ---------------------------
    // Fill the isoEtTruth distribution for ALL prompt truth photons where isoEtTruth was computed
    // (this includes both PASS and FAIL of the iso cut).
    if (doCanonical && std::isfinite(isoEtTruth))
    {
      const double truthPtForFig2 = truthWitness.pt;
      fillPPG12Fig2TruthIso(ppg12Fig2Class, truthPtForFig2, isoEtTruth);

      for (const auto& trigShort : activeTrig)
      {
        // Distribution
        if (auto* hIsoT = getOrBookTruthIsoHist(trigShort, "h_EisoTruth", 200, 0.0, 50.0))
        {
          hIsoT->Fill(isoEtTruth);
          bumpHistFill(trigShort, hIsoT->GetName());
        }

        // PASS/FAIL decision (bin1=PASS, bin2=FAIL)
        if (auto* hDecT = getOrBookTruthIsoDecisionHist(trigShort, "h_EisoTruthDecision"))
        {
          hDecT->Fill(passTruthIso ? 1 : 2);
          bumpHistFill(trigShort, hDecT->GetName());
        }
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "TRUTH_ISOLATION_FILL";
          row.decision = passTruthIso ? 1 : 2;
          row.generator_barcode = truthWitness.barcode;
          row.flow_value = isoEtTruth;
          row.truth_photon_pt = truthPtForFig2;
          row.occurrence_weight = m_mcEventWeight;
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
    }

    // Every analysis consumer uses the same nominal G4 truth-signal map.
    if (!passTruthIso) continue;
    ++nTruthSig;

    const double truthPtFromHepMC = truthWitness.pt;
    const double truthPtForDiag = (havePPG12TruthForDiag &&
                                   std::isfinite(ppg12TruthInfoForDiag.pt) &&
                                   ppg12TruthInfoForDiag.pt > 0.0)
                                      ? ppg12TruthInfoForDiag.pt
                                      : truthPtFromHepMC;
    if (!std::isfinite(truthPtForDiag) || truthPtForDiag <= 0.0) continue;
    // The weighted histogram wrapper already carries the full PPG12 SIM
    // event weight; explicit weights here are extra multipliers only.
    constexpr double photonEffWeight = 1.0;
    const bool fig6SampleAccepted = ppg12Fig6SampleAccepted();
    fillPPG12Fig6OwnershipAudit(1, photonEffWeight);
    if (fig6PhotonSampleContext) fillPPG12Fig6OwnershipAudit(2, photonEffWeight);
    if (fig6HaveOwnerTruth) fillPPG12Fig6OwnershipAudit(3, photonEffWeight);
    if (fig6SampleAccepted) fillPPG12Fig6OwnershipAudit(4, photonEffWeight);
    else fillPPG12Fig6OwnershipAudit(5, photonEffWeight);
    maybePrintPPG12Fig6Gate(truthPtForDiag, photonEffWeight, fig6SampleAccepted);

    fillPPG12PhotonEfficiencyStage("h_photonEffTruthDen_pTgamma_0",
                                   truthPtForDiag,
                                   photonEffWeight);
    if (fig6SampleAccepted)
    {
      fillPPG12PhotonEfficiencyStage("h_photonEffPpg12Fig6TruthDen_pTgamma_0",
                                     truthPtForDiag,
                                     photonEffWeight);
    }
    fillPPStitchFlow("h_ppStitchDiag_flow_truthIso_truthPt_noVtxW",
                     truthPtForDiag,
                     "truth p_{T}^{#gamma} [GeV]");

    bool truthHasMatchedG4ForDiag = havePPG12TruthForDiag;
    if (truthHasMatchedG4ForDiag)
    {
      fillPPStitchFlow("h_ppStitchDiag_flow_truthIsoG4_truthPt_noVtxW",
                       truthPtForDiag,
                       "truth p_{T}^{#gamma} [GeV]");
    }

    if (targetTrackIdForDiag >= 0)
    {
      const double truthEtaForDiag = truthWitness.eta;
      const double truthPhiForDiag = truthWitness.phi;

      bool rawNearestDR005 = false;
      bool rawNearestDR010 = false;
      bool rawPPG12TrackAny = false;
      bool rawPPG12TrackFid = false;

      if (m_clus && std::isfinite(truthEtaForDiag) && std::isfinite(truthPhiForDiag))
      {
        const CLHEP::Hep3Vector vertex(0.0, 0.0, m_vz);
        const auto crange = m_clus->getClusters();
        for (auto cit = crange.first; cit != crange.second; ++cit)
        {
          const RawCluster* rc = cit->second;
          if (!rc) continue;

          const CLHEP::Hep3Vector eVec = RawClusterUtility::GetEVec(*rc, vertex);
          const double e = eVec.mag();
          if (!std::isfinite(e) || e <= 0.0) continue;

          TLorentzVector rawPhoton;
          rawPhoton.SetPxPyPzE(eVec.x(), eVec.y(), eVec.z(), e);
          const double rawPt = rawPhoton.Pt();
          const double rawEta = rawPhoton.Eta();
          const double rawPhi = TVector2::Phi_mpi_pi(rawPhoton.Phi());
          if (!std::isfinite(rawPt) || !std::isfinite(rawEta) || !std::isfinite(rawPhi)) continue;

          const double rawDphi = TVector2::Phi_mpi_pi(rawPhi - truthPhiForDiag);
          const double rawDeta = rawEta - truthEtaForDiag;
          const double dr = std::sqrt(rawDeta * rawDeta + rawDphi * rawDphi);
          if (rawPt > 1.0 && dr < 0.05) rawNearestDR005 = true;
          if (rawPt > 1.0 && dr < 0.10) rawNearestDR010 = true;

          TruthSignalPhotonInfo matchedTruth;
          int clusterTruthTrackId = -1;
          float econtrib = std::numeric_limits<float>::lowest();
          if (classifyRecoPhotonWithPPG12TruthTrack(rc, clustereval, truthSignalByTrackIdForDiag,
                                                     matchedTruth, clusterTruthTrackId, econtrib) &&
              clusterTruthTrackId == targetTrackIdForDiag)
          {
            rawPPG12TrackAny = true;
            if (rawPt > 5.0 && std::fabs(rawEta) < 0.7) rawPPG12TrackFid = true;
          }
        }
      }

      if (rawNearestDR005)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_rawClusterDR005_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (rawNearestDR010)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_rawClusterDR010_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (rawPPG12TrackAny)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_rawPPG12Track_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (rawPPG12TrackFid)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_rawPPG12TrackFid_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }

      bool selectedNearestDR005 = false;
      bool selectedNearestDR010 = false;
      bool selectedPPG12TrackAny = false;
      bool selectedPPG12TrackFid = false;
      bool legacyBarcodeDR005 = false;

      if (m_photons && std::isfinite(truthEtaForDiag) && std::isfinite(truthPhiForDiag))
      {
        const auto prange = m_photons->getClusters();
        for (auto pit = prange.first; pit != prange.second; ++pit)
        {
          const auto* pho = dynamic_cast<const PhotonClusterv1*>(pit->second);
          if (!pho) continue;

          const RawCluster* rc = pho;
          const double eta = pho->get_shower_shape_parameter("cluster_eta");
          const double phi = TVector2::Phi_mpi_pi(pho->get_shower_shape_parameter("cluster_phi"));
          const double pt = pho->get_shower_shape_parameter("cluster_pt");
          if (!std::isfinite(eta) || !std::isfinite(phi) || !std::isfinite(pt)) continue;

          const double selDphi = TVector2::Phi_mpi_pi(phi - truthPhiForDiag);
          const double selDeta = eta - truthEtaForDiag;
          const double dr = std::sqrt(selDeta * selDeta + selDphi * selDphi);
          if (pt > 1.0 && dr < 0.05) selectedNearestDR005 = true;
          if (pt > 1.0 && dr < 0.10) selectedNearestDR010 = true;

          RawCluster* rc_nc = const_cast<RawCluster*>(rc);
          PHG4Particle* primary = clustereval.max_truth_primary_particle_by_energy(rc_nc);
          if (primary && primary->get_pid() == 22 &&
              primary->get_barcode() == truthWitness.barcode && dr < 0.05)
          {
            legacyBarcodeDR005 = true;
          }

          TruthSignalPhotonInfo matchedTruth;
          int clusterTruthTrackId = -1;
          float econtrib = std::numeric_limits<float>::lowest();
          if (classifyRecoPhotonWithPPG12TruthTrack(rc, clustereval, truthSignalByTrackIdForDiag,
                                                     matchedTruth, clusterTruthTrackId, econtrib) &&
              clusterTruthTrackId == targetTrackIdForDiag)
          {
            selectedPPG12TrackAny = true;
            if (pt > 5.0 && std::fabs(eta) < 0.7) selectedPPG12TrackFid = true;
          }
        }
      }

      if (selectedNearestDR005)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_selectedPhotonDR005_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (selectedNearestDR010)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_selectedPhotonDR010_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (selectedPPG12TrackAny)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_selectedPPG12Track_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (selectedPPG12TrackFid)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_selectedPPG12TrackFid_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }
      if (legacyBarcodeDR005)
      {
        fillPPStitchFlow("h_ppStitchDiag_flow_legacyBarcodeDR005_truthPt_noVtxW",
                         truthPtForDiag,
                         "truth p_{T}^{#gamma} [GeV]");
      }

      bool ppg12Fig6Reco = false;
      bool ppg12Fig6Iso = false;
      bool ppg12Fig6ID = false;
      bool ppg12Fig6PrintedMatch = false;

      if (m_photons)
      {
        int candidateIndex = 0;
        const auto prange = m_photons->getClusters();
        for (auto pit = prange.first; pit != prange.second; ++pit, ++candidateIndex)
        {
          const auto* recoPhoForEff = dynamic_cast<const PhotonClusterv1*>(pit->second);
          if (!recoPhoForEff) continue;
          if (ppg12PhotonYieldTowerMasked(recoPhoForEff)) continue;

          const RawCluster* recoForEff = recoPhoForEff;
          TruthSignalPhotonInfo matchedTruthForEff;
          int clusterTruthTrackIdForEff = -1;
          float eContribForEff = std::numeric_limits<float>::lowest();
          if (!classifyRecoPhotonWithPPG12TruthTrack(recoForEff, clustereval,
                                                     truthSignalByTrackIdForDiag,
                                                     matchedTruthForEff,
                                                     clusterTruthTrackIdForEff,
                                                     eContribForEff))
          {
            continue;
          }
          if (clusterTruthTrackIdForEff != targetTrackIdForDiag) continue;

          const double etaForEff = recoPhoForEff->get_shower_shape_parameter("cluster_eta");
          const double rawPtForEff = recoPhoForEff->get_shower_shape_parameter("cluster_pt");
          const double ptForCuts = ppg12PhotonYieldClusterEtForCuts(rawPtForEff, candidateIndex);
          if (!std::isfinite(etaForEff) || std::fabs(etaForEff) >= 0.7) continue;
          if (!std::isfinite(ptForCuts) || ptForCuts < kPPG12YieldRecoMinET) continue;

          ppg12Fig6Reco = true;

          const double eisoForEff =
              ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(recoForEff, topNode));
          if (std::isfinite(eisoForEff) && eisoForEff <= 1e8)
          {
            const double isoMaxForEff = recoIsoThreshold(ptForCuts);
            if (eisoForEff > kPPG12YieldRecoIsoMin && eisoForEff < isoMaxForEff)
            {
              ppg12Fig6Iso = true;
            }
          }

          const SSVars stageVarsForEff = makeSSFromPhoton(recoPhoForEff, ptForCuts);
          const TightTag ppg12Fig6TightTag = classifyPPG12PhotonYieldTightness(stageVarsForEff);
          if (ppg12Fig6TightTag == TightTag::kTight)
          {
            ppg12Fig6ID = true;
          }
          if (!ppg12Fig6PrintedMatch &&
              ppg12Fig6MatchDebugPrintLimit > 0 &&
              s_ppg12Fig6MatchDebugPrints < ppg12Fig6MatchDebugPrintLimit)
          {
            ++s_ppg12Fig6MatchDebugPrints;
            ppg12Fig6PrintedMatch = true;
            std::cout << "[PPG12_FIG6_MATCH]"
                      << " event=" << event_count
                      << " sample=" << ppg12PhotonSliceName(fig6PhotonSlice)
                      << " truthPt=" << truthPtForDiag
                      << " ownerPt=" << fig6OwnerPhotonPt
                      << " accepted=" << fig6SampleAccepted
                      << " recoPtRaw=" << rawPtForEff
                      << " recoPtForCuts=" << ptForCuts
                      << " eta=" << etaForEff
                      << " rawEiso=" << ppg12PhotonYieldRawEiso(recoForEff, topNode)
                      << " recoEiso=" << eisoForEff
                      << " isoMax=" << recoIsoThreshold(ptForCuts)
                      << " bdt=" << stageVarsForEff.tight_bdt_score
                      << " bdtMin=" << configuredTightBDTMin(ptForCuts)
                      << " common=" << passesPPG12PhotonYieldCommon(stageVarsForEff)
                      << " tag=" << tightTagName(ppg12Fig6TightTag)
                      << " reco=" << ppg12Fig6Reco
                      << " iso=" << ppg12Fig6Iso
                      << " id=" << ppg12Fig6ID
                      << std::endl;
          }
        }
      }

      if (fig6SampleAccepted && ppg12Fig6Reco)
      {
        fillPPG12PhotonEfficiencyStage("h_photonEffPpg12Fig6Reco_pTgamma_0",
                                       truthPtForDiag,
                                       photonEffWeight);
      }
      if (fig6SampleAccepted && ppg12Fig6Reco && ppg12Fig6ID)
      {
        fillPPG12PhotonEfficiencyStage("h_photonEffPpg12Fig6RecoTight_pTgamma_0",
                                       truthPtForDiag,
                                       photonEffWeight);
      }
      if (fig6SampleAccepted && ppg12Fig6Reco && ppg12Fig6Iso)
      {
        fillPPG12PhotonEfficiencyStage("h_photonEffPpg12Fig6RecoIso_pTgamma_0",
                                       truthPtForDiag,
                                       photonEffWeight);
      }
      if (fig6SampleAccepted && ppg12Fig6Reco && ppg12Fig6Iso && ppg12Fig6ID)
      {
        fillPPG12PhotonEfficiencyStage("h_photonEffPpg12Fig6RecoTightIso_pTgamma_0",
                                       truthPtForDiag,
                                       photonEffWeight);
      }
    }

    const RawCluster* recoMatch = nullptr;
    double rPt = 0.0, rEta = 0.0, rPhi = 0.0, drBest = 1e9;
    float  eBest = -1.0f;

    if (!findRecoPhotonMatchedToTruthSignal(truthSignalByTrackIdForDiag, targetTrackIdForDiag, clustereval,
                                           recoMatch, rPt, rEta, rPhi, drBest, eBest))
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " passTruthIso=1 but no reco match found");
      }
      continue;
    }
    ++nTruthSigMatched;
    fillPPStitchFlow("h_ppStitchDiag_flow_recoMatched_recoPt_noVtxW",
                     rPt,
                     "matched reco p_{T}^{#gamma} [GeV]");

    const auto* recoPho = dynamic_cast<const PhotonClusterv1*>(recoMatch);
    if (!recoPho)
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " matched reco cluster is not PhotonClusterv1 → skip");
      }
      continue;
    }
    if (ppg12PhotonYieldTowerMasked(recoPho))
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " matched reco cluster fails PPG12 tower mask -> skip");
      }
      continue;
    }

    const double eiso_et = ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(recoMatch, topNode));
    const bool eisoEtValid = (std::isfinite(eiso_et) && eiso_et <= 1e8);

    if (doCanonical && m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu)
    {
      auto fillFig24AuditOne = [&](const std::string& trigShort, const int bin)
      {
        if (trigShort.empty()) return;
        if (auto* hAudit = getOrBookPPG12Fig24AuditHist(trigShort))
        {
          hAudit->Fill(bin);
          bumpHistFill(trigShort, hAudit->GetName());
        }
      };

      auto fillFig24Audit = [&](const int bin)
      {
        for (const auto& trigShort : activeTrig)
        {
          fillFig24AuditOne(trigShort, bin);
        }
      };

      auto fillPPG12Fig24SignalRecoIso = [&]()
      {
        fillFig24Audit(1);
        if (!std::isfinite(rEta) || std::fabs(rEta) >= kPPG12Fig24EtaAbsMax) return;
        fillFig24Audit(2);

        const int fig24PtIdx = findPPG12Fig24RecoPtBin(rPt);
        if (fig24PtIdx < 0) return;
        fillFig24Audit(3);

        if (!std::isfinite(eiso_et) || eiso_et >= 1e8)
        {
          return;
        }
        fillFig24Audit(4);

        if (!fig24PhotonSampleContext)
        {
          fillFig24Audit(12);
          return;
        }
        fillFig24Audit(5);

        if (!fig24HaveWindow)
        {
          fillFig24Audit(12);
          return;
        }
        fillFig24Audit(6);

        if (!fig24HaveOwnerTruth)
        {
          fillFig24Audit(11);
          return;
        }

        if (!fig24OwnedBySample)
        {
          fillFig24Audit(10);
          return;
        }
        fillFig24Audit(7);

        for (const auto& trigShort : activeTrig)
        {
          if (trigShort.empty()) continue;

          if (auto* hCompat = getOrBookPPG12Fig24ETIsoHist(trigShort,
                                                           kPPG12Fig24PPG12CompatName))
          {
            hCompat->Fill(rPt, eiso_et);
            bumpHistFill(trigShort, hCompat->GetName());
          }
          if (auto* hNamed = getOrBookPPG12Fig24ETIsoHist(trigShort,
                                                          kPPG12Fig24SignalRecoIsoName))
          {
            hNamed->Fill(rPt, eiso_et);
            bumpHistFill(trigShort, hNamed->GetName());
          }
          fillFig24AuditOne(trigShort, 8);

          if (auto* hIsoBin = getOrBookPPG12Fig24IsoHist(trigShort, fig24PtIdx))
          {
            hIsoBin->Fill(eiso_et);
            bumpHistFill(trigShort, hIsoBin->GetName());
          }
          fillFig24AuditOne(trigShort, 9);
        }
      };

      fillPPG12Fig24SignalRecoIso();
    }

    const int ptIdx_sig = findPtBin(rPt);
    if (ptIdx_sig < 0)
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " matched reco pT=" << std::fixed << std::setprecision(2) << rPt
            << " outside configured m_gammaPtBins → skip");
      }
      continue;
    }

    fillPPG12PhotonEfficiencyStage("h_photonEffReco_pTgamma_0",
                                   truthPtForDiag,
                                   photonEffWeight);

    const SSVars   stageVars = makeSSFromPhoton(recoPho, rPt);
    const TightTag stageTag  = classifyPPG12PhotonYieldTightness(stageVars);
    const bool stageTight = (stageTag == TightTag::kTight);
    if (stageTight)
    {
      fillPPG12PhotonEfficiencyStage("h_photonEffRecoTight_pTgamma_0",
                                     truthPtForDiag,
                                     photonEffWeight);
    }

    if (!eisoEtValid)
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " reco pT=" << std::fixed << std::setprecision(2) << rPt
            << " has invalid Eiso=" << eiso_et << " → skip");
      }
      continue;
    }

    const double stageIsoMax = recoIsoThreshold(rPt);
    const bool stageIso =
        (eiso_et > kPPG12YieldRecoIsoMin) && (eiso_et < stageIsoMax);
    if (stageIso)
    {
      fillPPG12PhotonEfficiencyStage("h_photonEffRecoIso_pTgamma_0",
                                     truthPtForDiag,
                                     photonEffWeight);
    }
    if (stageTight && stageIso)
    {
      fillPPG12PhotonEfficiencyStage("h_photonEffRecoTightIso_pTgamma_0",
                                     truthPtForDiag,
                                     photonEffWeight);
    }
    fillPPStitchFlow("h_ppStitchDiag_flow_validEiso_recoPt_noVtxW",
                     rPt,
                     "matched reco p_{T}^{#gamma} [GeV]");

    // reco isolation distribution for TRUTH-ISOLATED signal photons (direct+frag),
    // independent of reco shower-shape classification.
    if (fillConeThisView())
    {
      for (const auto& trigShort : activeTrig)
      {
        if (auto* hIso = getOrBookIsoPartHist(trigShort,
                                             "h_EisoReco_truthSigMatched",
                                             "E_{T}^{iso,reco} [GeV] (truth iso signal match)",
                                             ptIdx_sig, effCentIdx_sig))
        {
          hIso->Fill(eiso_et);
          bumpHistFill(trigShort, hIso->GetName());
        }

        if (m_isSim && !m_isAuAu && m_ppStitchDiagContext)
        {
          for (const PPStitchDiagVariant variant : kPPStitchDiagVariants)
          {
            const std::size_t iv = ppStitchDiagIndex(variant);
            if (iv >= m_ppStitchDiagKeep.size() || !m_ppStitchDiagKeep[iv]) continue;

            const std::string key = ppStitchDiagKey(variant);

            const std::string baseWeighted =
                std::string("h_EisoReco_truthSigMatched_stitch_") + key + "_vtxW";
            if (auto* hVar = getOrBookIsoPartHist(trigShort,
                                                  baseWeighted,
                                                  "E_{T}^{iso,reco} [GeV] (truth iso signal match, stitch variant, vtx weighted)",
                                                  ptIdx_sig, effCentIdx_sig))
            {
              hVar->Fill(eiso_et);
              bumpHistFill(trigShort, hVar->GetName());
            }

            const std::string baseUnweighted =
                std::string("h_EisoReco_truthSigMatched_stitch_") + key + "_noVtxW";
            if (auto* hVarNoVtx = getOrBookIsoPartHist(trigShort,
                                                       baseUnweighted,
                                                       "E_{T}^{iso,reco} [GeV] (truth iso signal match, stitch variant, no vtx weight)",
                                                       ptIdx_sig, effCentIdx_sig))
            {
              // Explicit raw diagnostic opt-out. This object predates the full
              // PPG12 event-weight contract and intentionally carries no SIM
              // event factors; the canonical physics object above is weighted.
              RJMCWeighting::RecordRawFill();
              hVarNoVtx->TH1F::Fill(eiso_et, 1.0);
              bumpHistFill(trigShort, hVarNoVtx->GetName());
            }

            fillPPStitchFlow(std::string("h_ppStitchDiag_flow_stitch_") + key + "_validEiso_recoPt_noVtxW",
                             rPt,
                             "matched reco p_{T}^{#gamma} [GeV]");
          }
        }
      }
    }

    // In the PPG12 photon-yield pp-SIM contract, signal leakage is counted
    // from reco clusters (CaloAna24/RecoEffCalculator style), not by choosing
    // one best reco cluster per truth photon.  Keep the truth-flow diagnostics
    // above, but let the cluster-anchored block after this loop fill A/B/C/D.
    if (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu)
    {
      continue;
    }

    // Reco-side ABCD classification (PPG12-equivalent)
    const SSVars   v   = makeSSFromPhoton(recoPho, rPt);
    const TightTag tag = classifyPhotonTightness(v);

    // Exclude: preselection fail and Neither(1 fail), consistent with your ABCD logic
    if (!(tag == TightTag::kTight || tag == TightTag::kNonTight))
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " reco pT=" << std::fixed << std::setprecision(2) << rPt
            << " fails preselection/Neither → tag=" << tightTagName(tag) << " → skip");
      }
      continue;
    }

    const double thrIso    = recoIsoThreshold(rPt);
    const double thrNonIso = recoNonIsoThreshold(rPt);

    const bool iso    = (eiso_et < thrIso);
    const bool nonIso = (eiso_et > thrNonIso);

    // GAP excluded
    if (!iso && !nonIso)
    {
      if (Verbosity() >= 8)
      {
        LOG(8, CLR_YELLOW,
            "    [sigABCD] truth barcode=" << truthWitness.barcode
            << " reco pT=" << std::fixed << std::setprecision(2) << rPt
            << " lies in ISO GAP (Eiso=" << std::fixed << std::setprecision(3) << eiso_et
            << ", thrIso=" << thrIso
            << ", thrNonIso=" << thrNonIso << ") → skip");
      }
      continue;
    }

    int regBin = 0;
    if      (iso    && tag == TightTag::kTight)    regBin = 1; // A
    else if (nonIso && tag == TightTag::kTight)    regBin = 2; // B
    else if (iso    && tag == TightTag::kNonTight) regBin = 3; // C
    else if (nonIso && tag == TightTag::kNonTight) regBin = 4; // D

    if (regBin <= 0) continue;

    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookSigABCDLeakageHist(trigShort, ptIdx_sig, effCentIdx_sig))
      {
        h->Fill(regBin);
        bumpHistFill(trigShort, h->GetName());
      }
    }

    if (Verbosity() >= 7)
    {
      LOG(7, CLR_CYAN,
          "    [sigABCD] truth barcode=" << truthWitness.barcode
          << " reco pT=" << std::fixed << std::setprecision(2) << rPt
          << " Eiso=" << std::fixed << std::setprecision(3) << eiso_et
          << " thrIso=" << std::fixed << std::setprecision(3) << thrIso
          << " thrNonIso=" << std::fixed << std::setprecision(3) << thrNonIso
          << " tag=" << tightTagName(tag)
          << " → region=" << regBin
          << " (drBest=" << std::fixed << std::setprecision(4) << drBest
          << ", eContrib=" << eBest
          << ", isoEtTruth=" << std::fixed << std::setprecision(3) << isoEtTruth << ")");
    }
  } // end truth particle loop

  int nPPG12ClusterSignal = 0;
  int nPPG12ClusterABCD = 0;
  if (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu)
  {
    auto fillPPG12DiagPt = [&](const char* name, const double pt, const double weight)
    {
      if (!m_ppg12PhotonYieldDiagFeatures) return;
      if (!name || !std::isfinite(pt)) return;
      for (const auto& trigShort : activeTrig)
      {
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                                  "p_{T}^{#gamma,reco} [GeV]", "Entries"))
        {
          h->Fill(pt, weight);
          bumpHistFill(trigShort, name);
        }
      }
    };

    auto rawClusterPPG12TowerMasked = [&](const RawCluster* rc) -> bool
    {
      if (!(m_ppg12PhotonYieldApplyTowerMask && m_ppg12PhotonYieldTowerMask)) return false;
      if (!rc) return false;
      const std::vector<float> showershape = rc->get_shower_shapes(0.070);
      if (showershape.size() < 6) return false;
      const int ieta = static_cast<int>(showershape[4]);
      const int iphi = static_cast<int>(showershape[5]);
      if (ieta < 0 || ieta >= m_ppg12PhotonYieldTowerMask->GetNbinsX()) return false;
      if (iphi < 0 || iphi >= m_ppg12PhotonYieldTowerMask->GetNbinsY()) return false;
      return m_ppg12PhotonYieldTowerMask->GetBinContent(ieta + 1, iphi + 1) > 0.0;
    };

    auto rawClusterPPG12EdgeAccepted = [](const RawCluster* rc) -> bool
    {
      if (!rc) return false;
      const std::vector<float> showershape = rc->get_shower_shapes(0.070);
      if (showershape.size() < 6) return false;
      const int cogIeta = static_cast<int>(std::floor(showershape[4] + 0.5f));
      return !(cogIeta < 3 || cogIeta > 92);
    };

    fillPPG12Fig8ResponseTargets(activeTrig, clustereval, truthSignalByTrackIdForDiag);

    if (m_ppg12PhotonYieldDiagFeatures && m_clus)
    {
      constexpr double diagWeight = 1.0;
      int rawCandidateIndex = 0;
      const CLHEP::Hep3Vector rawVertex(0.0, 0.0, ppg12PhotonYieldKinematicVertexZ());
      const auto crange = m_clus->getClusters();
      for (auto cit = crange.first; cit != crange.second; ++cit, ++rawCandidateIndex)
      {
        const RawCluster* rc = cit->second;
        if (!rc) continue;

        TruthSignalPhotonInfo matchedTruth;
        int clusterTruthTrackId = -1;
        float eContrib = std::numeric_limits<float>::lowest();
        if (!classifyRecoPhotonWithPPG12TruthTrack(rc, clustereval,
                                                   truthSignalByTrackIdForDiag,
                                                   matchedTruth, clusterTruthTrackId,
                                                   eContrib))
        {
          continue;
        }

        const double rawEta = RawClusterUtility::GetPseudorapidity(*rc, rawVertex);
        const double rawPt = std::isfinite(rawEta) ? rc->get_energy() / std::cosh(rawEta)
                                                   : std::numeric_limits<double>::quiet_NaN();
        const double rawPtForCuts = ppg12PhotonYieldClusterEtForCuts(rawPt, rawCandidateIndex);
        if (!std::isfinite(rawPtForCuts) || rawPtForCuts <= 0.0) continue;

        fillPPG12DiagPt("h_ppg12_diag_raw_signal_cluster_0", rawPtForCuts, diagWeight);

        if (!rawClusterPPG12EdgeAccepted(rc))
        {
          fillPPG12DiagPt("h_ppg12_diag_raw_signal_edge_reject_0", rawPtForCuts, diagWeight);
          continue;
        }
        fillPPG12DiagPt("h_ppg12_diag_raw_signal_edge_accept_0", rawPtForCuts, diagWeight);

        if (rawClusterPPG12TowerMasked(rc))
        {
          fillPPG12DiagPt("h_ppg12_diag_raw_signal_tower_masked_0", rawPtForCuts, diagWeight);
          continue;
        }
        fillPPG12DiagPt("h_ppg12_diag_raw_signal_unmasked_0", rawPtForCuts, diagWeight);

        if (ppg12PhotonYieldInResponseWindow(rawPtForCuts, matchedTruth.pt))
        {
          fillPPG12DiagPt("h_ppg12_diag_raw_signal_response_window_0", rawPtForCuts, diagWeight);
        }
      }
    }

    if (!m_photons)
    {
      if (Verbosity() >= 4)
      {
        LOG(4, CLR_YELLOW,
            "    [sigABCD][PPG12 cluster anchored] photon cluster container missing -> skip leakage counters");
      }
    }
    else
    {
      int candidateIndex = 0;
      const auto prange = m_photons->getClusters();
      for (auto pit = prange.first; pit != prange.second; ++pit, ++candidateIndex)
      {
        const auto* recoPho = dynamic_cast<const PhotonClusterv1*>(pit->second);
        if (!recoPho) continue;

        const RawCluster* recoMatch = recoPho;
        if (ppg12PhotonYieldTowerMasked(recoPho))
        {
          continue;
        }

        TruthSignalPhotonInfo matchedTruth;
        int clusterTruthTrackId = -1;
        float eContrib = std::numeric_limits<float>::lowest();
        if (!classifyRecoPhotonWithPPG12TruthTrack(recoMatch, clustereval,
                                                   truthSignalByTrackIdForDiag,
                                                   matchedTruth, clusterTruthTrackId,
                                                   eContrib))
        {
          continue;
        }
        ++nPPG12ClusterSignal;

        const double rawPt = recoPho->get_shower_shape_parameter("cluster_pt");
        const double rPt = ppg12PhotonYieldClusterEtForCuts(rawPt, candidateIndex);
        const double responsePt =
            ppg12PhotonYieldClusterEtForResponse(rawPt, matchedTruth.pt, candidateIndex);
        const int ptIdx_sig = findPtBin(rPt);
        if (ptIdx_sig < 0) continue;

        const double eiso_et = ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(recoMatch, topNode));
        if (!std::isfinite(eiso_et) || eiso_et > 1e8) continue;

        const SSVars v = makeSSFromPhoton(recoPho, rPt);
        const TightTag tag = classifyPPG12PhotonYieldTightness(v);
        const bool commonPass = passesPPG12PhotonYieldCommon(v);
        const bool diagTightBDT = configuredTightBDTPass(v.tight_bdt_score, v.pt_gamma);
        const bool diagNonTightBDT = configuredNonTightBDTPass(v.tight_bdt_score, v.pt_gamma);
        const bool diagNonTightShape =
            in_open_interval(v.cluster_prob, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
            in_open_interval(v.weta_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
            in_open_interval(v.wphi_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
            in_open_interval(v.et1, kPPG12YieldNonTightEt1Min, kPPG12YieldNonTightEt1Max) &&
            in_open_interval(v.et4, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
            in_open_interval(v.e11_over_e33, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
            in_open_interval(v.e32_over_e35, kPPG12YieldTightE32E35Min, kPPG12YieldTightE32E35Max);
        auto fillPPG12Diag = [&](const char* name)
        {
          fillPPG12DiagPt(name, rPt, 1.0);
        };
        if (m_ppg12PhotonYieldDiagFeatures && commonPass)
        {
          static const std::vector<double> kScoreBins = []()
          {
            std::vector<double> b;
            for (int i = 0; i <= 55; ++i) b.push_back(-0.05 + 0.02 * i);
            return b;
          }();
          static const std::vector<double> kShapeBins = []()
          {
            std::vector<double> b;
            for (int i = 0; i <= 80; ++i) b.push_back(0.0 + 0.025 * i);
            return b;
          }();
          static const std::vector<double> kFracBins = []()
          {
            std::vector<double> b;
            for (int i = 0; i <= 60; ++i) b.push_back(0.0 + 0.02 * i);
            return b;
          }();
          static const std::vector<double> kIsoBins = []()
          {
            std::vector<double> b;
            for (int i = 0; i <= 100; ++i) b.push_back(-20.0 + 0.4 * i);
            return b;
          }();
          static const std::vector<double> kEtBins = []()
          {
            std::vector<double> b;
            for (int i = 0; i <= 80; ++i) b.push_back(0.0 + 0.5 * i);
            return b;
          }();

          auto edgeLabel = [](double edge)
          {
            std::ostringstream os;
            const double rounded = std::round(edge);
            if (std::fabs(edge - rounded) < 1e-6)
            {
              os << static_cast<int>(rounded);
            }
            else
            {
              os << std::fixed << std::setprecision(1) << edge;
            }
            std::string label = os.str();
            for (char& c : label)
            {
              if (c == '.') c = 'p';
              else if (c == '-') c = 'm';
            }
            return label;
          };
          const std::string ptSuffix =
              "pT" + edgeLabel(m_ppg12PhotonYieldRecoPtBins[ptIdx_sig]) +
              "_" + edgeLabel(m_ppg12PhotonYieldRecoPtBins[ptIdx_sig + 1]);
          constexpr double featureWeight = 1.0;
          const char* tagName = "neither";
          if (tag == TightTag::kTight) tagName = "tight";
          else if (tag == TightTag::kNonTight) tagName = "nontight";

          auto fillFeature = [&](const char* feature,
                                 double value,
                                 const std::vector<double>& bins,
                                 const char* xAxisTitle)
          {
            if (!std::isfinite(value)) return;
            const std::string baseName =
                std::string("h_ppg12_diag_common_feature_") + feature + "_0";
            const std::string ptName =
                std::string("h_ppg12_diag_common_feature_") + feature + "_" + ptSuffix + "_0";
            const std::string tagNameFull =
                std::string("h_ppg12_diag_common_tag_") + tagName + "_feature_" + feature + "_0";
            for (const auto& trigShort : activeTrig)
            {
              auto fillNamed = [&](const std::string& histName)
              {
                if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, histName, bins,
                                                          xAxisTitle, "Entries"))
                {
                  h->Fill(value, featureWeight);
                  bumpHistFill(trigShort, h->GetName());
                }
              };
              fillNamed(baseName);
              fillNamed(ptName);
              fillNamed(tagNameFull);
            }
          };

          fillFeature("bdt_score", v.tight_bdt_score, kScoreBins, "tight BDT score");
          fillFeature("npb_score", v.npb_score, kScoreBins, "NPB score");
          fillFeature("cluster_prob", v.cluster_prob, kScoreBins, "cluster probability");
          fillFeature("weta_cogx", v.weta_cogx, kShapeBins, "w_{#eta}^{COG}");
          fillFeature("wphi_cogx", v.wphi_cogx, kShapeBins, "w_{#phi}^{COG}");
          fillFeature("et1", v.et1, kFracBins, "E_{T,1}/E_{T}^{cluster}");
          fillFeature("et2", v.et2, kFracBins, "E_{T,2}/E_{T}^{cluster}");
          fillFeature("et3", v.et3, kFracBins, "E_{T,3}/E_{T}^{cluster}");
          fillFeature("et4", v.et4, kFracBins, "E_{T,4}/E_{T}^{cluster}");
          fillFeature("e11_over_e33", v.e11_over_e33, kFracBins, "E_{1x1}/E_{3x3}");
          fillFeature("e32_over_e35", v.e32_over_e35, kFracBins, "E_{3x2}/E_{3x5}");
          fillFeature("eiso", eiso_et, kIsoBins, "E_{T}^{iso,reco} [GeV]");
          fillFeature("reco_et_for_cuts", rPt, kEtBins, "smeared reco E_{T} [GeV]");
        }
        fillPPG12Diag("h_ppg12_diag_signal_cluster_0");
        if (commonPass)
        {
          fillPPG12Diag("h_ppg12_diag_common_signal_0");
          if (diagTightBDT) fillPPG12Diag("h_ppg12_diag_bdt_tight_window_signal_0");
          if (diagNonTightBDT) fillPPG12Diag("h_ppg12_diag_bdt_nontight_window_signal_0");
          if (diagNonTightShape) fillPPG12Diag("h_ppg12_diag_nontight_shape_signal_0");
          if (tag == TightTag::kTight) fillPPG12Diag("h_ppg12_diag_tag_tight_signal_0");
          else if (tag == TightTag::kNonTight) fillPPG12Diag("h_ppg12_diag_tag_nontight_signal_0");
          else if (tag == TightTag::kNeither) fillPPG12Diag("h_ppg12_diag_tag_neither_signal_0");
        }
        else
        {
          fillPPG12Diag("h_ppg12_diag_preselection_fail_signal_0");
        }

        const double thrIso = recoIsoThreshold(rPt);
        const double thrNonIso = recoNonIsoThreshold(rPt);
        const bool iso =
            (eiso_et > kPPG12YieldRecoIsoMin) && (eiso_et < thrIso);
        const bool nonIso =
            (eiso_et > thrNonIso) && (eiso_et < kPPG12YieldRecoNonIsoMax);
        const bool hasPPG12YieldClass =
            (tag == TightTag::kTight || tag == TightTag::kNonTight);
        const bool validRegion = hasPPG12YieldClass && (iso || nonIso);
        const bool inResponseWindowSig =
            ppg12PhotonYieldInResponseWindow(rPt, matchedTruth.pt);
        constexpr double fillWeight = 1.0;

        fillPPG12PhotonYieldAllCommon(activeTrig,
                                      rPt,
                                      commonPass,
                                      true,
                                      true,
                                      fillWeight,
                                      inResponseWindowSig,
                                      false);
        // PPG12 fills the tight stage for tight signal clusters inside the
        // response window even if the candidate falls in the isolation gap.
        // Region-specific A/B/C/D histograms still require iso or non-iso.
        if (hasPPG12YieldClass)
        {
          fillPPG12PhotonYieldTightAndABCD(activeTrig,
                                           rPt,
                                           responsePt,
                                           matchedTruth.pt,
                                           tag,
                                           iso,
                                           nonIso,
                                           true,
                                           true,
                                           fillWeight,
                                           false);
        }

        if (!validRegion) continue;

        int regBin = 0;
        if      (iso    && tag == TightTag::kTight)    regBin = 1; // A
        else if (nonIso && tag == TightTag::kTight)    regBin = 2; // B
        else if (iso    && tag == TightTag::kNonTight) regBin = 3; // C
        else if (nonIso && tag == TightTag::kNonTight) regBin = 4; // D
        if (regBin <= 0) continue;

        // PPG12 fills A only inside the truth/reco response window; B/C/D are
        // still counted by reco pT bin.  Replicate that asymmetric convention.
        if (regBin == 1 && !ppg12PhotonYieldInResponseWindow(rPt, matchedTruth.pt))
        {
          continue;
        }

        for (const auto& trigShort : activeTrig)
        {
          if (auto* h = getOrBookSigABCDLeakageHist(trigShort, ptIdx_sig, effCentIdx_sig))
          {
            h->Fill(regBin, fillWeight);
            bumpHistFill(trigShort, h->GetName());
            ++nPPG12ClusterABCD;
          }
        }

        if (Verbosity() >= 7)
        {
          LOG(7, CLR_CYAN,
              "    [sigABCD][PPG12 cluster anchored] evt=" << event_count
              << " truthTrack=" << clusterTruthTrackId
              << " truthPt=" << std::fixed << std::setprecision(2) << matchedTruth.pt
              << " recoEtRaw=" << rawPt
              << " recoEtForCuts=" << rPt
              << " Eiso=" << std::fixed << std::setprecision(3) << eiso_et
              << " tag=" << tightTagName(tag)
              << " region=" << regBin
              << " weight=" << fillWeight
              << " eContrib=" << eContrib);
        }
      }
    }
  }

  if (Verbosity() >= 5)
  {
    LOG(5, CLR_BLUE,
        "    [sigABCD] summary: truthSig=" << nTruthSig
        << " truthSigMatchedReco=" << nTruthSigMatched
        << " ppg12ClusterSignal=" << nPPG12ClusterSignal
        << " ppg12ClusterABCD=" << nPPG12ClusterABCD
        << " (ABCD filled only if reco passes preselection AND is not GAP AND not Neither)");
  }
}





// Centralized candidate processing for the event.  In optimized production,
// coneR and fixed/sliding isolation are internal histogram views inside one
// cfg-tagged output file.  Each view reuses the exact legacy candidate/recoil
// logic below under a scoped isolation setting.
void RecoilJets::processCandidates(PHCompositeNode* topNode,
                                   const std::vector<std::string>& activeTrig)
{
    if (m_internalIsoViews.empty())
    {
        m_activeIsoViewSuffix.clear();
        processCandidatesForCurrentIsoView(topNode, activeTrig);
        return;
    }

    const double savedConeR = m_isoConeR;
    const double savedFixed = m_isoFixed;
    const bool savedSliding = m_isSlidingIso;
    const std::string savedSuffix = m_activeIsoViewSuffix;

    for (const auto& view : m_internalIsoViews)
    {
        m_isoConeR = view.coneR;
        m_isoFixed = view.fixedGeV;
        m_isSlidingIso = view.isSliding;
        m_activeIsoViewSuffix = "_" + view.label;
        processCandidatesForCurrentIsoView(topNode, activeTrig);
    }

    m_isoConeR = savedConeR;
    m_isoFixed = savedFixed;
    m_isSlidingIso = savedSliding;
    m_activeIsoViewSuffix = savedSuffix;
}

void RecoilJets::processCandidatesForCurrentIsoView(PHCompositeNode* topNode,
                                                    const std::vector<std::string>& activeTrig)
{
    // -------- guards & context ------------------------------------------------
    if (!topNode)
    {
        LOG(0, CLR_YELLOW, "  [processCandidates] topNode == nullptr – aborting this event :(");
        return;
    }
    if (activeTrig.empty())
    {
        LOG(0, CLR_YELLOW, "  [processCandidates] activeTrig is EMPTY – nothing to fill this event :(");
        return;
    }

    // Centrality bin index (Au+Au only, else -1)
    const int centIdx = (m_isAuAu ? findCentBin(m_centBin) : -1);
    const bool doCanonical = fillCanonicalThisView();
    const PPG12PhotonSlice ppPhotonSlice =
        (m_isSim && !m_isAuAu) ? ppg12PhotonSliceFromContext(Outfile) : PPG12PhotonSlice::kNone;
    const bool ppPhotonSliceContext = (ppPhotonSlice != PPG12PhotonSlice::kNone);
    const PPG12InclusiveJetSlice ppInclusiveJetSlice =
        (m_isSim && !m_isAuAu) ? ppg12InclusiveJetSliceFromContext(Outfile) : PPG12InclusiveJetSlice::kNone;
    const bool ppInclusiveJetContext = (ppInclusiveJetSlice != PPG12InclusiveJetSlice::kNone);
    const double ppInclusiveJetClusterEtUpper = ppg12InclusiveJetClusterEtUpper(ppInclusiveJetSlice);
    double ppInclusiveJetStitchLo = -999.0;
    double ppInclusiveJetStitchHi = -999.0;
    const bool ppInclusiveJetHaveWindow =
        ppInclusiveJetContext && ppg12InclusiveJetSliceWindow(ppInclusiveJetSlice,
                                                              ppInclusiveJetStitchLo,
                                                              ppInclusiveJetStitchHi);
    double ppInclusiveJetMaxTruthJetPt = -1.0;
    double ppInclusiveJetMaxTruthJetPtR04 = -1.0;
    if (m_isSim && !m_isAuAu && ppInclusiveJetContext)
    {
        for (const auto& kvT : m_truthJetsByRKey)
        {
            JetContainer* truthJets = kvT.second;
            if (!truthJets) continue;
            for (const Jet* tj : *truthJets)
            {
                if (!tj) continue;
                const double ptj = tj->get_pt();
                if (std::isfinite(ptj) && ptj > ppInclusiveJetMaxTruthJetPt) ppInclusiveJetMaxTruthJetPt = ptj;
            }
        }

        if (auto itR04 = m_truthJetsByRKey.find("r04"); itR04 != m_truthJetsByRKey.end())
        {
            JetContainer* truthJetsR04 = itR04->second;
            if (truthJetsR04)
            {
                for (const Jet* tj : *truthJetsR04)
                {
                    if (!tj) continue;
                    const double ptj = tj->get_pt();
                    if (std::isfinite(ptj) && ptj > ppInclusiveJetMaxTruthJetPtR04) ppInclusiveJetMaxTruthJetPtR04 = ptj;
                }
            }
        }
    }
    const bool ppInclusiveJetHaveR04 = (ppInclusiveJetMaxTruthJetPtR04 >= 0.0);
    const bool ppInclusiveJetPassR04 =
        ppInclusiveJetHaveWindow && ppInclusiveJetHaveR04 &&
        ppg12WindowContains(ppInclusiveJetMaxTruthJetPtR04,
                            ppInclusiveJetStitchLo,
                            ppInclusiveJetStitchHi);
    const bool ppInclusiveJetHaveAnyR = (ppInclusiveJetMaxTruthJetPt >= 0.0);
    const bool ppInclusiveJetPassAnyR =
        ppInclusiveJetHaveWindow && ppInclusiveJetHaveAnyR &&
        ppg12WindowContains(ppInclusiveJetMaxTruthJetPt,
                            ppInclusiveJetStitchLo,
                            ppInclusiveJetStitchHi);

    if (Verbosity() >= 4)
    {
        std::ostringstream os;
        os << "  [processCandidates] dataset=" << (m_isAuAu ? "Au+Au" : "p+p")
        << "  centIdx=" << centIdx
        << "  m_centBin=" << m_centBin
        << "  nTriggers=" << activeTrig.size()
        << "  triggers={";

        for (std::size_t i = 0; i < activeTrig.size(); ++i)
        {
            if (i) os << ", ";
            os << activeTrig[i];
        }
        os << "}";

        LOG(4, CLR_BLUE, os.str());
    }

    // If neither photons nor clusters are present, we cannot do anything
    if (!m_photons && !m_clus)
    {
        LOG(2, CLR_YELLOW, "  [processCandidates] PHOTONCLUSTER_CEMC and CLUSTERINFO_CEMC both MISSING – nothing to process - sus");
        return;
    }

    // ==========================================================================
    //  Truth-signal → reco ABCD leakage counters
    //
    // For each truth "signal photon" (prompt + truth-iso) that has a matched reco
    // PhotonClusterBuilder cluster, classify the reco cluster into PPG12 ABCD
    // regions using the SAME reco definitions as your purity logic:
    //   - preselection must pass
    //   - GAP excluded
    //   - Neither(1 fail) excluded
    //
    // Output histograms (under /SIM/):
    //   h_sigABCD_MC_pT_lo_hi[_cent_lo_hi]  (TH1I, bins: 1=A, 2=B, 3=C, 4=D)
    // ==========================================================================
    if (m_isSim && m_photons)
    {
        fillTruthSigABCDLeakageCounters(topNode, activeTrig, centIdx);
    }

    // ==========================================================================
    // (SIM ONLY): PURE truth xJgamma distribution (NO reco gating)
    //
    // Books/Fills (per trigger, per radius, per centrality-suffix):
    //   h_JES3TruthPure_pT_xJ_alpha_<rKey><centSuffix>
    //
    // Truth photon:
    //   uses your encoded truth-signal definition:
    //     buildPPG12TruthSignalPhotonMap(topNode)
    //
    // Truth recoil jets (per rKey truth jet container):
    //   - pT > m_minJetPt
    //   - |eta| < (1.1 - R)
    //   - |Δphi(truth gamma, truth jet)| >= m_minBackToBack
    //
    // Then fill:
    //   (tPt, xJt=tj1Pt/tPt, aT=tj2Pt/tPt)
    // ==========================================================================
    if (m_isSim && doCanonical)
    {
        const int effCentIdx_truth = (m_isAuAu ? centIdx : -1);

        {
            bool haveTruthSigPho = false;
            double tPt = -1.0, tEta = 0.0, tPhi = 0.0;
            const auto truthSignalByTrackId = buildPPG12TruthSignalPhotonMap(topNode);
            for (const auto& truthEntry : truthSignalByTrackId)
            {
                const auto& info = truthEntry.second;
                if (!haveTruthSigPho || info.pt > tPt)
                {
                    haveTruthSigPho = true;
                    tPt = info.pt;
                    tEta = info.eta;
                    tPhi = info.phi;
                }
            }

            if (!haveTruthSigPho || tPt <= 0.0)
            {
                if (Verbosity() >= 5)
                {
                    LOG(5, CLR_YELLOW,
                        "    [truthXJgamma] no truth signal photon found → skip pure truth xJgamma fills");
                }
            }
            else
            {
                // Fill per jet radius (truth jets are radius-tagged)
                for (const auto& kvT : m_truthJetsByRKey)
                {
                    const std::string baseRKey = kvT.first;

                    JetContainer* truthJets = kvT.second;

                    if (!truthJets)
                    {
                        if (Verbosity() >= 5)
                        {
                            LOG(5, CLR_YELLOW,
                                "    [truthXJgamma] rKey=" << baseRKey << " truth jet container missing -> skip");
                        }
                        continue;
                    }

                    const double etaMaxTruth = jetEtaAbsMaxForRKey(baseRKey);
                    const double savedMinJetPt = m_minJetPt;
                    const double savedMinBackToBack = m_minBackToBack;
                    for (const double jetPtCut : activeJetPtCuts())
                    {
                    m_minJetPt = jetPtCut;
                    for (const double dphiCut : activeBackToBackCuts())
                    {
                    m_minBackToBack = dphiCut;
                    const std::string rKey = recoilRKeyForScope(baseRKey, jetPtCut, dphiCut, HistViewScope::Canonical);

                    double tj1Pt = -1.0;
                    const Jet* tj1 = nullptr;

                    // 1) Histmaker-style truth recoil jet1 definition (mirror RECO chronology):
                    //   - pick GLOBAL leading truth jet first (after pT gate + photon overlap veto; NO eta/dphi pre-veto)
                    //   - then veto if that chosen jet is not fiducial in eta (NO fallback)
                    //   - then require it be back-to-back to the truth gamma
                    double all1PtTruth = -1.0;
                    const Jet* all1Truth = nullptr;

                    for (const Jet* tj : *truthJets)
                    {
                        if (!tj) continue;

                        const double ptj  = tj->get_pt();
                        const double etaj = tj->get_eta();
                        const double phij = tj->get_phi();

                        if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
                        if (ptj < m_minJetPt) continue;

                        // Photon–jet overlap veto: exclude jets near the truth photon direction (ΔR < 0.4)
                        const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
                        const double detaPho = (etaj - tEta);
                        const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

                        if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
                        {
                            continue;
                        }

                        if (ptj > all1PtTruth)
                        {
                            all1PtTruth = ptj;
                            all1Truth   = tj;
                        }
                    }

                    if (!all1Truth || all1PtTruth <= 0.0)
                    {
                        if (Verbosity() >= 6)
                        {
                            LOG(6, CLR_YELLOW,
                                "    [truthXJgamma] rKey=" << rKey << " no truth jet1 found → skip");
                        }
                        continue;
                    }

                    {
                        const double etaj = all1Truth->get_eta();
                        if (!std::isfinite(etaj) || (std::fabs(etaj) >= etaMaxTruth))
                        {
                            if (Verbosity() >= 6)
                            {
                                LOG(6, CLR_YELLOW,
                                    "    [truthXJgamma] rKey=" << rKey << " truth jet1 fails eta fiducial → skip");
                            }
                            continue;
                        }
                    }

                    {
                        const double phij = all1Truth->get_phi();
                        const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(phij - tPhi));
                        if (!std::isfinite(dphiAbs) || (dphiAbs < m_minBackToBack))
                        {
                            if (Verbosity() >= 6)
                            {
                                LOG(6, CLR_YELLOW,
                                    "    [truthXJgamma] rKey=" << rKey << " truth jet1 fails back-to-back → skip");
                            }
                            continue;
                        }
                    }

                    tj1Pt = all1PtTruth;
                    tj1   = all1Truth;

                    // 2) truth jet2 for α: highest-pT fiducial truth jet excluding tj1 (NO Δφ requirement)
                    double tj2Pt = -1.0;
                    for (const Jet* tj : *truthJets)
                    {
                        if (!tj) continue;

                        const double ptj  = tj->get_pt();
                        const double etaj = tj->get_eta();
                        const double phij = tj->get_phi();

                        if (!std::isfinite(ptj) || !std::isfinite(etaj) || !std::isfinite(phij)) continue;
                        if (ptj < m_minJetPt) continue;

                        // Photon–jet overlap veto: exclude jets near the truth photon direction (ΔR < 0.4)
                        const double dphiPho = TVector2::Phi_mpi_pi(phij - tPhi);
                        const double detaPho = (etaj - tEta);
                        const double dRPho2  = (detaPho*detaPho + dphiPho*dphiPho);

                        if (!std::isfinite(dRPho2) || (dRPho2 < (0.4 * 0.4)))
                        {
                            continue;
                        }

                        if (std::fabs(etaj) >= etaMaxTruth) continue;
                        if (tj == tj1) continue;

                        if (ptj > tj2Pt) tj2Pt = ptj;
                    }

                    const double xJt = tj1Pt / tPt;
                    const double aT  = (tj2Pt > 0.0 ? (tj2Pt / tPt) : 0.0);

                    for (const auto& trigShort : activeTrig)
                    {
                        if (auto* ht3_pure = getOrBookJES3TruthPure_xJ_alphaHist(trigShort, rKey, effCentIdx_truth))
                        {
                            ht3_pure->Fill(tPt, xJt, aT);
                            bumpHistFill(trigShort, ht3_pure->GetName());
                        }
                    }

                    if (Verbosity() >= 7)
                    {
                        LOG(7, CLR_CYAN,
                            "    [truthXJgamma] rKey=" << rKey
                            << " tPt=" << std::fixed << std::setprecision(2) << tPt
                            << " tj1Pt=" << std::fixed << std::setprecision(2) << tj1Pt
                            << " tj2Pt(fid,no#Delta#phi)=" << std::fixed << std::setprecision(2) << (tj2Pt > 0.0 ? tj2Pt : 0.0)
                            << " → xJt=" << std::fixed << std::setprecision(3) << xJt
                            << " aT="  << std::fixed << std::setprecision(3) << aT);
                    }
                    }
                    }
                    m_minBackToBack = savedMinBackToBack;
                    m_minJetPt = savedMinJetPt;
                } // end rKey loop
            }
        }
    }

    if (m_isSim && !m_isAuAu && doCanonical && ppInclusiveJetContext)
    {
        if (m_replayFoundationEnabled)
        {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = "SIM";
            row.occurrence_kind = "PP_INCLUSIVE_JET_EVENT";
            row.sample_code = ppg12InclusiveJetSliceBin(ppInclusiveJetSlice);
            if (ppInclusiveJetHaveAnyR) row.source_photon_pt = ppInclusiveJetMaxTruthJetPt;
            if (ppInclusiveJetHaveR04) row.flow_value = ppInclusiveJetMaxTruthJetPtR04;
            row.selection_bitmask =
                (ppInclusiveJetHaveAnyR ? 1ULL : 0ULL) |
                (ppInclusiveJetPassAnyR ? 2ULL : 0ULL) |
                (ppInclusiveJetHaveR04 ? 4ULL : 0ULL) |
                (ppInclusiveJetPassR04 ? 8ULL : 0ULL);
            m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
        for (const auto& trigShort : activeTrig)
        {
            HistMap& H = qaHistogramsByTrigger[trigShort];
            TDirectory* dir = (out ? out->GetDirectory(trigShort.c_str()) : nullptr);
            if (!dir && out) dir = out->mkdir(trigShort.c_str());
            if (!dir) continue;
            TDirectory* prevDir = gDirectory;
            dir->cd();

            TH1F* hMax = nullptr;
            if (auto it = H.find("h_ppInclusiveJetStitch_maxTruthJetPt_all"); it != H.end())
            {
                hMax = dynamic_cast<TH1F*>(it->second);
            }
            if (!hMax)
            {
                hMax = RJMCWeighting::RJNewRawTH1F("h_ppInclusiveJetStitch_maxTruthJetPt_all",
                                                   "h_ppInclusiveJetStitch_maxTruthJetPt_all;max truth jet p_{T} [GeV];Events",
                                                   1000, 0.0, 200.0);
                hMax->Sumw2();
                hMax->SetDirectory(dir);
                H["h_ppInclusiveJetStitch_maxTruthJetPt_all"] = hMax;
            }
            if (ppInclusiveJetMaxTruthJetPt >= 0.0)
            {
                hMax->Fill(ppInclusiveJetMaxTruthJetPt);
                bumpHistFill(trigShort, hMax->GetName());
            }

            TH1F* hMaxR04 = nullptr;
            if (auto it = H.find("h_ppInclusiveJetStitch_r04_maxTruthJetPt_all"); it != H.end())
            {
                hMaxR04 = dynamic_cast<TH1F*>(it->second);
            }
            if (!hMaxR04)
            {
                hMaxR04 = RJMCWeighting::RJNewRawTH1F("h_ppInclusiveJetStitch_r04_maxTruthJetPt_all",
                                                      "h_ppInclusiveJetStitch_r04_maxTruthJetPt_all;max R=0.4 truth jet p_{T} [GeV];Events",
                                                      1000, 0.0, 100.0);
                hMaxR04->Sumw2();
                hMaxR04->SetDirectory(dir);
                H["h_ppInclusiveJetStitch_r04_maxTruthJetPt_all"] = hMaxR04;
            }
            if (ppInclusiveJetMaxTruthJetPtR04 >= 0.0)
            {
                hMaxR04->Fill(ppInclusiveJetMaxTruthJetPtR04);
                bumpHistFill(trigShort, hMaxR04->GetName());
            }

            TH1I* hSample = nullptr;
            if (auto it = H.find("h_ppInclusiveJetStitch_sample"); it != H.end())
            {
                hSample = dynamic_cast<TH1I*>(it->second);
            }
            if (!hSample)
            {
                hSample = RJMCWeighting::RJNewRawTH1I("h_ppInclusiveJetStitch_sample",
                                                     "h_ppInclusiveJetStitch_sample;sample;Events",
                                                     6, 0.5, 6.5);
                hSample->GetXaxis()->SetBinLabel(1, "Jet5");
                hSample->GetXaxis()->SetBinLabel(2, "Jet8");
                hSample->GetXaxis()->SetBinLabel(3, "Jet12");
                hSample->GetXaxis()->SetBinLabel(4, "Jet20");
                hSample->GetXaxis()->SetBinLabel(5, "Jet30");
                hSample->GetXaxis()->SetBinLabel(6, "Jet40");
                hSample->SetDirectory(dir);
                H["h_ppInclusiveJetStitch_sample"] = hSample;
            }
            hSample->Fill(ppg12InclusiveJetSliceBin(ppInclusiveJetSlice));
            bumpHistFill(trigShort, hSample->GetName());

            if (prevDir) prevDir->cd();
        }

        for (const auto& trigShort : activeTrig)
        {
            HistMap& H = qaHistogramsByTrigger[trigShort];
            TDirectory* dir = (out ? out->GetDirectory(trigShort.c_str()) : nullptr);
            if (!dir && out) dir = out->mkdir(trigShort.c_str());
            if (!dir) continue;
            TDirectory* prevDir = gDirectory;
            dir->cd();

            auto bookExact1F = [&](const std::string& name,
                                   const std::string& title,
                                   int nbins,
                                   double xmin,
                                   double xmax) -> TH1F*
            {
                if (auto it = H.find(name); it != H.end())
                {
                    return dynamic_cast<TH1F*>(it->second);
                }
                TH1F* h = RJMCWeighting::RJNewRawTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
                h->Sumw2();
                h->SetDirectory(dir);
                H[name] = h;
                return h;
            };

            auto fillExactJetFamily = [&](const std::string& prefix,
                                          const std::string& axisTitle,
                                          const double pt,
                                          const bool havePt,
                                          const bool passWindow) -> void
            {
                // Match the PPG12 Fig. 6 source convention: h_max_truth_jet_pT
                // is kept over 0-100 GeV and later rebinned/plotted as needed.
                // Downstream smooth-stitch QA may crop to 50 GeV, but the
                // parity diagnostic must not truncate the jet40 tail at write time.
                constexpr int kPPG12Fig6JetPtBins = 100;
                constexpr double kPPG12Fig6JetPtMin = 0.0;
                constexpr double kPPG12Fig6JetPtMax = 100.0;
                auto* hAll = bookExact1F(prefix + "_all",
                                         (prefix + "_all;" + axisTitle + " [GeV];Events").c_str(),
                                         kPPG12Fig6JetPtBins,
                                         kPPG12Fig6JetPtMin,
                                         kPPG12Fig6JetPtMax);
                auto* hKept = bookExact1F(prefix + "_kept",
                                          (prefix + "_kept;" + axisTitle + " [GeV];Events").c_str(),
                                          kPPG12Fig6JetPtBins,
                                          kPPG12Fig6JetPtMin,
                                          kPPG12Fig6JetPtMax);
                auto* hRejected = bookExact1F(prefix + "_rejected",
                                              (prefix + "_rejected;" + axisTitle + " [GeV];Events").c_str(),
                                              kPPG12Fig6JetPtBins,
                                              kPPG12Fig6JetPtMin,
                                              kPPG12Fig6JetPtMax);
                if (hAll)
                {
                    if (havePt)
                    {
                        hAll->Fill(pt);
                    }
                    bumpHistFill(trigShort, hAll->GetName());
                }

                if (passWindow && hKept)
                {
                    hKept->Fill(pt);
                    bumpHistFill(trigShort, hKept->GetName());
                }
                else if (hRejected)
                {
                    if (havePt)
                    {
                        hRejected->Fill(pt);
                    }
                    bumpHistFill(trigShort, hRejected->GetName());
                }
            };

            auto* hMeta = bookExact1F("h_ppInclusiveJetStitch_ppg12TruthSpectrum_metadata",
                                      "h_ppInclusiveJetStitch_ppg12TruthSpectrum_metadata;metadata;value",
                                      8, 0.5, 8.5);
            if (hMeta)
            {
                hMeta->GetXaxis()->SetBinLabel(1, "events_processed");
                hMeta->GetXaxis()->SetBinLabel(2, "window_low_GeV");
                hMeta->GetXaxis()->SetBinLabel(3, "window_high_GeV");
                hMeta->GetXaxis()->SetBinLabel(4, "upper_edge_inclusive");
                hMeta->GetXaxis()->SetBinLabel(5, "bin_width_GeV");
                hMeta->GetXaxis()->SetBinLabel(6, "xsec_pb");
                hMeta->GetXaxis()->SetBinLabel(7, "truth_def_code");
                hMeta->GetXaxis()->SetBinLabel(8, "sample_bin");
                hMeta->Fill(1.0);
                hMeta->SetBinContent(2, ppInclusiveJetStitchLo);
                hMeta->SetBinContent(3, ppInclusiveJetStitchHi);
                hMeta->SetBinContent(4, 1.0);
                hMeta->SetBinContent(5, 1.0);
                hMeta->SetBinContent(6, ppg12InclusiveJetSliceXsecPb(ppInclusiveJetSlice));
                hMeta->SetBinContent(7, 10.0);
                hMeta->SetBinContent(8, static_cast<double>(ppg12InclusiveJetSliceBin(ppInclusiveJetSlice)));
            }

            fillExactJetFamily("h_ppInclusiveJetStitch_ppg12TruthSpectrum_r04_maxTruthJetPt",
                               "max R=0.4 truth jet p_{T}",
                               ppInclusiveJetMaxTruthJetPtR04,
                               ppInclusiveJetHaveR04,
                               ppInclusiveJetPassR04);

            fillExactJetFamily("h_ppInclusiveJetStitch_ppg12TruthSpectrum_anyR_maxTruthJetPt",
                               "max truth jet p_{T}, any R key",
                               ppInclusiveJetMaxTruthJetPt,
                               ppInclusiveJetHaveAnyR,
                               ppInclusiveJetPassAnyR);

            if (prevDir) prevDir->cd();
        }
    }

    // ========================= PHOTON path ========================
    if (m_photons)
    {
        RawClusterContainer::ConstRange prange = m_photons->getClusters();

        // Quick emptiness check
        std::size_t nPho = 0;
        for (auto tmp = prange.first; tmp != prange.second; ++tmp) ++nPho;
        LOG(4, CLR_BLUE, "    [processCandidates] photons present: " << nPho);
        if (nPho == 0)
            LOG(3, CLR_YELLOW, "    [processCandidates] photon container is EMPTY for this event");

        // Per-event counters
        std::size_t nUsed = 0;
        std::size_t nSkipEta = 0, nSkipEtBin = 0, nSkipPhi = 0, nNoRC = 0, nNotIso = 0, nNotTight = 0;

        try
        {
            // ---- Event-level de-duplication for jet matching / JES fills ----
            // If multiple photons pass (iso ∧ tight) in the same event, keep ONLY
            // the leading one in pT^gamma and do jet matching + JES3 fills once.
            bool   haveLeadIsoTight = false;
            int    leadPhoIndex     = -1;
            int    leadPtIdx        = -1;
            double leadPtGamma      = -1.0;
            double leadEtaGamma     = 0.0;
            double leadPhiGamma     = 0.0;

            // Region-C sideband candidate for purity subtraction:
            // keep ONLY the event-leading iso ∧ nonTight photon (PPG12 non-tight = fails >=2 tight cuts).
            bool   haveLeadIsoNonTight = false;
            double leadNonTightPtGamma  = -1.0;
            double leadNonTightEtaGamma = 0.0;
            double leadNonTightPhiGamma = 0.0;
            const RawCluster* leadNonTightRc = nullptr;

            // Event-leading ABCD photons for xJ purity normalization.  These
            // are deliberately separate from the candidate-level ABCD counters:
            // the xJ spectra use one leading photon per event/region.
            bool   haveLeadNonIsoTight = false;
            double leadNonIsoTightPtGamma  = -1.0;
            const RawCluster* leadNonIsoTightRc = nullptr;
            bool   haveLeadNonIsoNonTight = false;
            double leadNonIsoNonTightPtGamma  = -1.0;
            const RawCluster* leadNonIsoNonTightRc = nullptr;

            //  leading reco photon candidate in pT^gamma within analysis pT bins,
            // WITHOUT requiring iso or tightness (used for jet-level cutflow QA vs pT^gamma)
            bool   haveLeadAnyPho  = false;
            int    leadAnyPtIdx    = -1;
            double leadAnyPtGamma  = -1.0;
            double leadAnyPhiGamma = 0.0;

            // Keep a pointer to the actual leading reco photon cluster (needed for SIM truth↔reco association)
            const RawCluster* leadRc = nullptr;

            // Event-level diagnostic: number of reco photon candidates that pass the SAME
            // iso∧tight gate used for the event-leading photon selection in this event.
            int nIsoTightPhoCand = 0;

            // PPG12-style photon-only bookkeeping: keep every reco iso∧tight candidate so the
            // alternate reco and fake spectra can be filled per object, independent of leading selection.
            std::vector<const RawCluster*> recoIsoTightPhoClustersPPG12;
            std::vector<double>            recoIsoTightPhoPtsPPG12;
            std::vector<const RawCluster*> recoMatchedTruthPhoClustersPPG12;

            // ------------------------------------------------------------------
            // SIM ONLY: objects needed to truth-tag reco clusters for PPG12-style
            // shower-shape templates (signal vs background).
            // ------------------------------------------------------------------
            HepMC::GenEvent* evtHepMC_SS = nullptr;
            bool haveCaloEval_SS = false;
            std::unique_ptr<CaloRawClusterEval> clustereval_SS;
            TruthSignalPhotonMap truthSignalByTrackId_SS;
            TruthSignalPhotonMap truthPhotonWitnessByTrackId_SS;
            const bool the134TruthLabelDiagnostic =
                RJReplayRuntimeV1::envEnabled("RJ_THE134_TRUTH_LABEL_DIAGNOSTIC_V1");
            int hepmcMapKey_SS = std::numeric_limits<int>::min();
            int hepmcEmbeddingId_SS = std::numeric_limits<int>::min();
            std::size_t hepmcMapSize_SS = 0;

            if (m_isSim)
            {
                PHHepMCGenEventMap* hepmcmap_SS = findNode::getClass<PHHepMCGenEventMap>(topNode, "PHHepMCGenEventMap");
                PHHepMCGenEvent*    hepmc_SS    = nullptr;

                if (hepmcmap_SS)
                {
                    hepmcMapSize_SS = hepmcmap_SS->size();
                    hepmc_SS = hepmcmap_SS->get(0);
                    if (hepmc_SS)
                    {
                        hepmcMapKey_SS = 0;
                    }
                    else
                    {
                        hepmc_SS = hepmcmap_SS->get(1);
                        if (hepmc_SS)
                        {
                            hepmcMapKey_SS = 1;
                        }
                    }
                    if (!hepmc_SS && !hepmcmap_SS->empty())
                    {
                        hepmcMapKey_SS = hepmcmap_SS->begin()->first;
                        hepmc_SS = hepmcmap_SS->begin()->second;
                    }
                    if (hepmc_SS)
                    {
                        hepmcEmbeddingId_SS = hepmc_SS->get_embedding_id();
                        evtHepMC_SS = hepmc_SS->getEvent();
                    }
                }

                clustereval_SS.reset(new CaloRawClusterEval(topNode, "CEMC"));
                clustereval_SS->set_usetowerinfo(true);
                clustereval_SS->next_event(topNode);

                if (!clustereval_SS->has_reduced_node_pointers())
                {
                    clustereval_SS->set_usetowerinfo(false);
                    clustereval_SS->next_event(topNode);
                }

                haveCaloEval_SS = clustereval_SS->has_reduced_node_pointers();

                if (!evtHepMC_SS && Verbosity() >= 5)
                    LOG(5, CLR_YELLOW, "      [SS templates] HepMC event missing → valid G4 photons retain explicit unknown class");
                if (!haveCaloEval_SS && Verbosity() >= 5)
                    LOG(5, CLR_YELLOW, "      [SS templates] CaloRawClusterEval missing required nodes → will fill *_bkg only");

                if (m_isSim)
                {
                    truthSignalByTrackId_SS = buildPPG12TruthSignalPhotonMap(topNode);
                    truthPhotonWitnessByTrackId_SS = buildPPG12TruthPhotonWitnessMap(topNode);
                }

                if (the134TruthLabelDiagnostic && !m_isAuAu && doCanonical)
                {
                    std::cout
                        << "THE134_PPG12_TRUTH_LABEL_DIAG_V1"
                        << " stage=EVENT_CONTEXT"
                        << " event=" << event_count
                        << " hepmc_map_size=" << hepmcMapSize_SS
                        << " selected_map_key=" << hepmcMapKey_SS
                        << " selected_embedding_id=" << hepmcEmbeddingId_SS
                        << " hepmc_event_present=" << (evtHepMC_SS ? 1 : 0)
                        << " calo_eval_present=" << (haveCaloEval_SS ? 1 : 0)
                        << " strict_signal_map_size=" << truthSignalByTrackId_SS.size()
                        << std::endl;
                }
            }

            std::string ppPhotonIDResolvedRole = m_ppPhotonIDSourceRole;
            if (m_isSim && !m_isAuAu && ppPhotonIDResolvedRole == "auto")
            {
                std::string outLower = Outfile;
                std::transform(outLower.begin(), outLower.end(), outLower.begin(),
                               [](unsigned char c){ return std::tolower(c); });
                if (outLower.find("photonjet") != std::string::npos ||
                    outLower.find("photon") != std::string::npos)
                {
                    ppPhotonIDResolvedRole = "signal";
                }
                else if (outLower.find("jet") != std::string::npos ||
                         ppInclusiveJetContext)
                {
                    ppPhotonIDResolvedRole = "background";
                }
                else
                {
                    ppPhotonIDResolvedRole = "all";
                }
            }

            int iPho = 0;
            for (auto pit = prange.first; pit != prange.second; ++pit, ++iPho)
            {
                // Concrete type: PhotonClusterv1
                const auto* pho = dynamic_cast<const PhotonClusterv1*>(pit->second);
                if (!pho)
                {
                    LOG(5, CLR_YELLOW, "      [pho#" << iPho << "] pointer is not PhotonClusterv1 – skipping");
                    continue;
                }

                // Upcast through inheritance (no RTTI, no second cast)
                const RawCluster* rc = pho;



                if (doCanonical) ++m_bk.pho_total;

                // --------------------------------------------------------------
                // Use the EXACT kinematics produced by PhotonClusterBuilder:
                //   - vertex_z    (MBD z used in builder)
                //   - cluster_eta / cluster_phi
                //   - cluster_pt
                //
                // This prevents ET/pT mismatches from recomputing with a different
                // vertex choice or a different construction path.
                // --------------------------------------------------------------
                double eta      = pho->get_shower_shape_parameter("cluster_eta");
                double phi      = pho->get_shower_shape_parameter("cluster_phi");
                double pt_gamma = pho->get_shower_shape_parameter("cluster_pt");
                const double ppg12ScoreInputEt = pt_gamma;
                double cluster_et_for_inclusive_cut = pho->get_shower_shape_parameter("cluster_et");
                if (!std::isfinite(cluster_et_for_inclusive_cut))
                {
                    cluster_et_for_inclusive_cut = pt_gamma;
                }
                const double energy = rc->get_energy();

                // Strict mode: ONLY use PhotonClusterBuilder-provided kinematics.
                // If they are missing/non-finite, skip this candidate and print why.
                if (!std::isfinite(eta) || !std::isfinite(phi) || !std::isfinite(pt_gamma))
                {
                    LOG(0, CLR_YELLOW,
                        "      [pho#" << iPho << "] PhotonClusterBuilder kinematics are non-finite/missing: "
                        << "eta=" << eta << " phi=" << phi << " pt=" << pt_gamma
                        << " → skipping candidate.");
                    continue;
                }

                if (ppg12PhotonYieldTowerMasked(pho))
                {
                    if (Verbosity() >= 6)
                    {
                        LOG(6, CLR_YELLOW,
                            "      [pho#" << iPho << "][PPG12_PHOTON_YIELD_V1] tower-mask veto"
                            << " ieta=" << pho->get_shower_shape_parameter("cluster_ietacent")
                            << " iphi=" << pho->get_shower_shape_parameter("cluster_iphicent"));
                    }
                    continue;
                }

                if (m_ppg12PhotonYieldEnabled)
                {
                    pt_gamma = ppg12PhotonYieldClusterEtForCuts(pt_gamma, iPho);
                    if (m_isSim && !m_isAuAu)
                    {
                        cluster_et_for_inclusive_cut = pt_gamma;
                    }
                }

                // -------- reco pT^gamma floor (PPG12 reco-matching requirement) ----
                // PPG12 requirement you stated: pT_reco > 5 GeV  (and for photons pT == ET).
                constexpr double kMinPtGamma = 5.0; // GeV

                if (pt_gamma < kMinPtGamma)
                {
                    ++nSkipEtBin; if (doCanonical) ++m_bk.pho_early_E;

                    if (Verbosity() >= 6)
                    {
                        const int dbgPtIdx = findPtBin(pt_gamma);

                        std::ostringstream os;
                        os << "      [pho#" << iPho << "] early reject (pT^#gamma floor)"
                        << " | pT="  << std::fixed << std::setprecision(2) << pt_gamma
                        << " < "     << kMinPtGamma
                        << " | E="   << std::fixed << std::setprecision(2) << energy
                        << " | eta=" << std::fixed << std::setprecision(3) << eta
                        << " | phi=" << std::fixed << std::setprecision(3) << phi
                        << " | pTbinIdx=" << dbgPtIdx;
                        LOG(6, CLR_YELLOW, os.str());
                    }
                    continue;
                }

                if (ppInclusiveJetContext &&
                    std::isfinite(ppInclusiveJetClusterEtUpper) &&
                    cluster_et_for_inclusive_cut > ppInclusiveJetClusterEtUpper)
                {
                    ++nSkipEtBin; if (doCanonical) ++m_bk.pho_early_E;

                    if (Verbosity() >= 6)
                    {
                        LOG(6, CLR_YELLOW,
                            "      [pho#" << iPho << "] inclusive-jet sample reject"
                            << " | sample=" << ppg12InclusiveJetSliceName(ppInclusiveJetSlice)
                            << " | cluster_ET=" << std::fixed << std::setprecision(2) << cluster_et_for_inclusive_cut
                            << " > cluster_ET_upper=" << ppInclusiveJetClusterEtUpper);
                    }
                    continue;
                }

                // |η| fiducial cut
                if (!std::isfinite(eta) || std::fabs(eta) >= m_etaAbsMax)
                {
                    ++nSkipEta; if (doCanonical) ++m_bk.pho_eta_fail;
                    if (Verbosity() >= 2)
                    {
                        std::cout << CLR_MAGENTA
                        << "      [skip:eta pho#" << iPho << "]"
                        << "  pT=" << std::fixed << std::setprecision(2) << pt_gamma
                        << "  E="  << std::fixed << std::setprecision(2) << energy
                        << "  eta="<< std::fixed << std::setprecision(3) << eta
                        << "  phi="<< std::fixed << std::setprecision(3) << phi
                        << "  (|eta|>=" << m_etaAbsMax << ")"
                        << CLR_RESET << std::endl;
                    }
                    continue;
                }

                // Now do your configured pT binning (drives ALL pT-sliced histograms + JES objects)
                const int ptIdx = findPtBin(pt_gamma);
                if (ptIdx < 0)
                {
                    ++nSkipEtBin; if (doCanonical) ++m_bk.pho_etbin_out;
                    if (Verbosity() >= 2)
                    {
                        std::cout << CLR_MAGENTA
                        << "      [skip:pTbin pho#" << iPho << "]"
                        << "  pT=" << std::fixed << std::setprecision(2) << pt_gamma
                        << "  E="  << std::fixed << std::setprecision(2) << energy
                        << "  eta="<< std::fixed << std::setprecision(3) << eta
                        << "  phi="<< std::fixed << std::setprecision(3) << phi
                        << CLR_RESET << std::endl;
                    }
                    continue;
                }

                // φ to use for jet matching (used later for jet scan)
                const double phi_gamma = phi;

                //  choose event-leading reco photon candidate in pT^gamma (within analysis bins),
                // WITHOUT iso/tight requirement.
                if (!haveLeadAnyPho || pt_gamma > leadAnyPtGamma)
                {
                    haveLeadAnyPho  = true;
                    leadAnyPtIdx    = ptIdx;
                    leadAnyPtGamma  = pt_gamma;
                    leadAnyPhiGamma = phi_gamma;
                }

                fillPureIsolationQA(topNode, activeTrig, pho, rc, ptIdx, centIdx, pt_gamma);

                // 1) Build shower-shape inputs (for preselection and tightness)
                const SSVars v = makeSSFromPhoton(pho, pt_gamma);
                if (doCanonical) ++m_bk.pho_reached_pre_iso;

                const int effCentIdx_SS = (m_isAuAu ? centIdx : -1);
                const std::string slice_SS = suffixForBins(ptIdx, effCentIdx_SS);

                bool isPPG12Signal = false;
                double ppg12SignalTruthPt = std::numeric_limits<double>::quiet_NaN();
                int ppg12SignalTruthClass = -999;
                int truthTrackId = -1;
                int truthBarcode = -1;
                float truthEContrib = std::numeric_limits<float>::lowest();
                double truthIsoEtR03 = std::numeric_limits<double>::quiet_NaN();
                double truthIsoEtR04 = std::numeric_limits<double>::quiet_NaN();
                int truthIsoValid = -1;
                int truthHepMCAssociationValid = -1;
                if (m_isSim && haveCaloEval_SS && clustereval_SS)
                {
                    TruthSignalPhotonInfo matchedSignalTruth;
                    isPPG12Signal =
                        classifyRecoPhotonWithPPG12TruthTrack(rc,
                                                              *clustereval_SS,
                                                              truthSignalByTrackId_SS,
                                                              matchedSignalTruth,
                                                              truthTrackId,
                                                              truthEContrib);
                    TruthSignalPhotonInfo matchedTruthWitness;
                    int witnessTrackId = -1;
                    float witnessEnergyContribution = std::numeric_limits<float>::lowest();
                    const bool haveTruthWitness =
                        classifyRecoPhotonWithPPG12TruthTrack(rc,
                                                              *clustereval_SS,
                                                              truthPhotonWitnessByTrackId_SS,
                                                              matchedTruthWitness,
                                                              witnessTrackId,
                                                              witnessEnergyContribution);
                    if (haveTruthWitness)
                    {
                        truthTrackId = witnessTrackId;
                        truthEContrib = witnessEnergyContribution;
                        truthBarcode = matchedTruthWitness.barcode;
                        ppg12SignalTruthClass = matchedTruthWitness.photonClass;
                        truthIsoEtR03 = matchedTruthWitness.isoEtR03;
                        truthIsoEtR04 = matchedTruthWitness.isoEtR04;
                        truthIsoValid = matchedTruthWitness.truthIsolationValid ? 1 : 0;
                        truthHepMCAssociationValid = matchedTruthWitness.hepmcAssociationValid ? 1 : 0;
                    }
                    if (isPPG12Signal)
                    {
                        ppg12SignalTruthPt = matchedSignalTruth.pt;
                    }
                }

                if (the134TruthLabelDiagnostic && m_isSim && !m_isAuAu && doCanonical)
                {
                    const char* reason = "CALO_EVAL_UNAVAILABLE";
                    if (haveCaloEval_SS && clustereval_SS)
                    {
                        if (truthSignalByTrackId_SS.empty())
                        {
                            reason = "EMPTY_SIGNAL_MAP";
                        }
                        else if (truthEContrib == std::numeric_limits<float>::lowest())
                        {
                            reason = "NO_MAX_PRIMARY";
                        }
                        else if (isPPG12Signal)
                        {
                            reason = "MATCH";
                        }
                        else
                        {
                            reason = "PRIMARY_NOT_IN_MAP";
                        }
                    }

                    std::ostringstream diagnosticLine;
                    diagnosticLine
                        << "THE134_PPG12_TRUTH_LABEL_DIAG_V1"
                        << " stage=CANDIDATE"
                        << " event=" << event_count
                        << " candidate_index=" << iPho
                        << " reco_et=" << std::setprecision(17) << pt_gamma
                        << " reason=" << reason
                        << " truth_track_id=" << truthTrackId
                        << " truth_energy_contribution=" << truthEContrib
                        << " strict_signal_map_size=" << truthSignalByTrackId_SS.size();
                    std::cout << diagnosticLine.str() << std::endl;
                }

                bool keepPPG12TableQARow = true;
                constexpr double ppg12TableQARowWeight = 1.0;
                if (m_ppg12TableQAEnabled && m_isSim && !m_isAuAu)
                {
                    if (ppInclusiveJetContext)
                    {
                        keepPPG12TableQARow = ppInclusiveJetPassR04;
                    }
                    else if (ppPhotonIDResolvedRole == "signal")
                    {
                        keepPPG12TableQARow = isPPG12Signal;
                    }
                    else if (ppPhotonIDResolvedRole == "background" || ppPhotonIDResolvedRole == "bkg")
                    {
                        keepPPG12TableQARow = !isPPG12Signal;
                    }
                }

                fillPPG12Fig14Fig15TimingQA(activeTrig, v, eta, phi_gamma, ppg12ScoreInputEt, 1.0);

                if (doCanonical)
                {
                    for (const auto& trigShort : activeTrig)
                    {
                        if (preselectionUsesNPB(m_preselectionVariant))
                        {
                            const bool finiteNPB = std::isfinite(v.npb_score);
                            if (auto* h = getOrBookCountHist(trigShort, finiteNPB ? "h_npbScore_finite" : "h_npbScore_missing",
                                                             ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                            {
                                h->Fill(1);
                                bumpHistFill(trigShort, std::string(finiteNPB ? "h_npbScore_finite" : "h_npbScore_missing") + slice_SS);
                            }
                            if (finiteNPB)
                            {
                                if (auto* hScore = getOrBookBDTScoreHist(trigShort, "h_npbScore_allCandidates", ptIdx, effCentIdx_SS))
                                {
                                    hScore->Fill(v.npb_score);
                                    bumpHistFill(trigShort, std::string("h_npbScore_allCandidates") + slice_SS);
                                }
                            }
                        }

                        if (m_tightVariant == "newPPG12")
                        {
                            const bool finiteTight = std::isfinite(v.tight_bdt_score);
                            if (auto* h = getOrBookCountHist(trigShort, finiteTight ? "h_tightBDTScore_finite" : "h_tightBDTScore_missing",
                                                             ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                            {
                                h->Fill(1);
                                bumpHistFill(trigShort, std::string(finiteTight ? "h_tightBDTScore_finite" : "h_tightBDTScore_missing") + slice_SS);
                            }
                            if (finiteTight)
                            {
                                if (auto* hScore = getOrBookBDTScoreHist(trigShort, "h_tightBDTScore_allCandidates", ptIdx, effCentIdx_SS))
                                {
                                    hScore->Fill(v.tight_bdt_score);
                                    bumpHistFill(trigShort, std::string("h_tightBDTScore_allCandidates") + slice_SS);
                                }
                            }
                        }
                    }
                }

                // ------------------------------------------------------------------
                // Deliverable Set A:
                //   Shower-shape spectra split by isolation tag (inclusive / iso / nonIso)
                //   - "iso"    : Eiso < (A + B * pT)           (or fixedGeV if sliding iso disabled)
                //   - "nonIso" : Eiso > (A + B * pT + gap)     (strict sideband; GAP excluded)
                // ------------------------------------------------------------------
                const double eiso_et = eiso(rc, topNode);
                PPG12EisoPathAudit ppg12EisoAudit;
                const double ppg12YieldRawEisoEt = ppg12PhotonYieldRawEisoDetailed(
                    rc,
                    topNode,
                    m_ppg12EisoPathCanaryEnabled ? &ppg12EisoAudit : nullptr);
                const double ppg12YieldEisoEt = ppg12PhotonYieldEiso(ppg12YieldRawEisoEt);
                const double ppg12ParityEisoEt =
                    (m_ppg12PhotonYieldEnabled && !m_isAuAu) ? ppg12YieldEisoEt : eiso_et;
                const bool usePPG12TableQAShowerShapeIso =
                    (m_ppg12TableQAEnabled && m_isSim && !m_isAuAu &&
                     m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldUseTopoIso &&
                     std::isfinite(ppg12YieldRawEisoEt) && ppg12YieldRawEisoEt < 1e8);
                const double ppg12TableQAEisoEt = usePPG12TableQAShowerShapeIso
                    ? (m_ppg12TableQAMcIsoScale * ppg12YieldRawEisoEt + m_ppg12TableQAMcIsoShift)
                    : ppg12ParityEisoEt;

                const bool ppg12Fig11PhotonSignalContext =
                    ppPhotonSliceContext &&
                    ppPhotonIDResolvedRole != "background" &&
                    ppPhotonIDResolvedRole != "bkg";
                fillPPG12Fig11SBDiagnostic(activeTrig,
                                            v,
                                            eta,
                                            ppg12ScoreInputEt,
                                            ppg12YieldRawEisoEt,
                                            ppg12Fig11PhotonSignalContext,
                                            isPPG12Signal,
                                            1.0,
                                            ppInclusiveJetContext,
                                            ppInclusiveJetPassR04,
                                            1.0);

                if (!m_isSim)
                {
                    fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "data", 0, ppg12ScoreInputEt);
                }
                else if (!m_isAuAu)
                {
                    if (ppInclusiveJetContext)
                    {
                        if (ppInclusiveJetPassR04)
                        {
                            fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "inclusive_mc", 0, ppg12ScoreInputEt);
                        }
                    }
                    else if (ppPhotonIDResolvedRole == "signal")
                    {
                        if (isPPG12Signal)
                        {
                            fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "signal_mc", 0, ppg12ScoreInputEt);
                        }
                    }
                    else if (ppPhotonIDResolvedRole == "background" || ppPhotonIDResolvedRole == "bkg")
                    {
                        fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "inclusive_mc", 0, ppg12ScoreInputEt);
                    }
                    else if (ppPhotonIDResolvedRole == "all")
                    {
                        fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "inclusive_mc", 0, ppg12ScoreInputEt);
                        if (isPPG12Signal)
                        {
                            fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "signal_mc", 0, ppg12ScoreInputEt);
                        }
                    }
                }

                const double ppg12DataYieldWeight = ppg12DataTriggerEfficiencyWeight(pt_gamma);
                if (!m_isSim && !m_isAuAu)
                {
                    fillPPG12DataTriggerEfficiencyAudit(activeTrig,
                                                        pt_gamma,
                                                        ppg12DataYieldWeight);
                }

                const bool ppg12PhotonYieldCommonPass = passesPPG12PhotonYieldCommon(v);
                const bool ppg12UseClusterAnchoredSignalHists =
                    (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu && isPPG12Signal);
                const bool ppg12MainLoopHaveTruthClass =
                    (m_isSim && !m_isAuAu) && !ppg12UseClusterAnchoredSignalHists;
                fillPPG12PhotonYieldAllCommon(activeTrig,
                                              pt_gamma,
                                              ppg12PhotonYieldCommonPass,
                                              ppg12MainLoopHaveTruthClass,
                                              isPPG12Signal,
                                              ppg12DataYieldWeight);

                const double ppg12YieldIsoMax = recoIsoThreshold(pt_gamma);
                const double ppg12YieldNonIsoMin = recoNonIsoThreshold(pt_gamma);
                const bool ppg12YieldValidIso =
                    (std::isfinite(ppg12YieldEisoEt) && ppg12YieldEisoEt < 1e8);
                const bool ppg12YieldIso =
                    ppg12YieldValidIso && (ppg12YieldEisoEt > kPPG12YieldRecoIsoMin) &&
                    (ppg12YieldEisoEt < ppg12YieldIsoMax);
                const bool ppg12YieldNonIso =
                    ppg12YieldValidIso && (ppg12YieldEisoEt > ppg12YieldNonIsoMin) &&
                    (ppg12YieldEisoEt < kPPG12YieldRecoNonIsoMax);

                const TightTag ppg12YieldTag = classifyPPG12PhotonYieldTightness(v);

                if (m_ppg12EisoPathCanaryEnabled)
                {
                    recordPPG12EisoPathCanary(ppg12EisoAudit,
                                              iPho,
                                              pt_gamma,
                                              eta,
                                              phi_gamma,
                                              isPPG12Signal,
                                              v,
                                              ppg12YieldEisoEt,
                                              ppg12YieldIsoMax,
                                              ppg12YieldNonIsoMin,
                                              ppg12YieldTag);
                }

                fillPPG12PhotonYieldTightAndABCD(activeTrig,
                                                 pt_gamma,
                                                 pt_gamma,
                                                 ppg12SignalTruthPt,
                                                 ppg12YieldTag,
                                                 ppg12YieldIso,
                                                 ppg12YieldNonIso,
                                                 ppg12MainLoopHaveTruthClass,
                                                 isPPG12Signal,
                                                 ppg12DataYieldWeight);
                if (ppg12PhotonYieldCommonPass)
                {
                    fillPPG12IsoStackQA(activeTrig,
                                        pt_gamma,
                                        ppg12YieldEisoEt,
                                        ppg12YieldTag,
                                        ppg12DataYieldWeight);
                }

                if (keepPPG12TableQARow)
                {
                    fillPPG12TableQA(activeTrig, v, ppg12TableQAEisoEt, effCentIdx_SS, 0, ppg12TableQARowWeight, ppg12ScoreInputEt);
                }
                if (!m_isSim)
                {
                    double npbDeltaT = std::numeric_limits<double>::quiet_NaN();
                    double npbMbdTime = std::numeric_limits<double>::quiet_NaN();
                    bool npbHasAwayJet = false;
                    if (isPPG12TableQADataNPBTaggedCluster(v, phi_gamma, npbDeltaT, npbMbdTime, npbHasAwayJet, true))
                    {
                        (void) npbDeltaT;
                        (void) npbMbdTime;
                        (void) npbHasAwayJet;
                        fillPPG12Fig13E11E33(activeTrig, v, ppg12ParityEisoEt, "npb_tagged_data", 4, ppg12ScoreInputEt);
                        fillPPG12TableQA(activeTrig, v, ppg12TableQAEisoEt, effCentIdx_SS, 4, 1.0, ppg12ScoreInputEt);
                    }
                }

                bool ssIso = false;
                bool ssNonIso = false;

                if (std::isfinite(ppg12ParityEisoEt) && ppg12ParityEisoEt < 1e8)
                {
                    const double thrIsoSS    = recoIsoThreshold(pt_gamma);
                    const double thrNonIsoSS = recoNonIsoThreshold(pt_gamma);

                    ssIso    = (ppg12ParityEisoEt < thrIsoSS);
                    ssNonIso = (ppg12ParityEisoEt > thrNonIsoSS);
                }

                if (doCanonical && m_ppPhotonIDTrainingTreeEnabled && !m_isAuAu)
                {
                    const bool isPPG12SourceRoleSignal =
                        ppg12SignalTruthClass == 1 || ppg12SignalTruthClass == 2;
                    bool keepTrainingRow = true;
                    if (m_isSim && m_ppPhotonIDPPG12Filter)
                    {
                        if (ppPhotonIDResolvedRole == "signal") keepTrainingRow = isPPG12SourceRoleSignal;
                        else if (ppPhotonIDResolvedRole == "background" || ppPhotonIDResolvedRole == "bkg") keepTrainingRow = !isPPG12SourceRoleSignal;
                    }
                    if (keepTrainingRow && m_ppPhotonIDRequirePreselection)
                    {
                        keepTrainingRow = passesPhotonPreselection(v);
                    }

                    if (keepTrainingRow)
                    {
                        // The executable uses calibrated, unsmeared ET for the
                        // model route, thresholds, tag, and ABCD cell.  The
                        // resolution correction is a response-only value and
                        // is recorded separately so it cannot silently feed
                        // back into classification.
                        const double ppg12ResponseEt = isPPG12Signal
                            ? ppg12PhotonYieldClusterEtForResponse(
                                  pt_gamma, ppg12SignalTruthPt, iPho)
                            : pt_gamma;
                        const int ppg12AnalysisWindowPass = isPPG12Signal
                            ? (ppg12PhotonYieldInResponseWindow(
                                   pt_gamma, ppg12SignalTruthPt) ? 1 : 0)
                            : -1;
                        const int ppg12ResponseWindowPass = isPPG12Signal
                            ? (ppg12PhotonYieldInResponseWindow(
                                   ppg12ResponseEt, ppg12SignalTruthPt) ? 1 : 0)
                            : -1;
                        int ppg12LogicalABCDRegion = 0;
                        if (ppg12YieldIso && ppg12YieldTag == TightTag::kTight)
                            ppg12LogicalABCDRegion = 1;
                        else if (ppg12YieldNonIso && ppg12YieldTag == TightTag::kTight)
                            ppg12LogicalABCDRegion = 2;
                        else if (ppg12YieldIso && ppg12YieldTag == TightTag::kNonTight)
                            ppg12LogicalABCDRegion = 3;
                        else if (ppg12YieldNonIso && ppg12YieldTag == TightTag::kNonTight)
                            ppg12LogicalABCDRegion = 4;

                        // Signal leakage follows the preserved PPG12
                        // asymmetry: A is accepted only in the unsmeared
                        // truth/reco analysis window, while B/C/D are binned
                        // by reconstructed ET without that additional veto.
                        const int ppg12SignalFillA =
                            (isPPG12Signal && ppg12LogicalABCDRegion == 1 &&
                             ppg12AnalysisWindowPass == 1) ? 1 : 0;
                        const int ppg12SignalFillB =
                            (isPPG12Signal && ppg12LogicalABCDRegion == 2) ? 1 : 0;
                        const int ppg12SignalFillC =
                            (isPPG12Signal && ppg12LogicalABCDRegion == 3) ? 1 : 0;
                        const int ppg12SignalFillD =
                            (isPPG12Signal && ppg12LogicalABCDRegion == 4) ? 1 : 0;
                        const int ppg12SignalFillMultiplicity =
                            ppg12SignalFillA + ppg12SignalFillB +
                            ppg12SignalFillC + ppg12SignalFillD;
                        const double ppXsecPb = ppInclusiveJetContext
                            ? ppg12InclusiveJetSliceXsecPb(ppInclusiveJetSlice)
                            : -999.0;
                        const double ppXsecWeight = ppInclusiveJetContext
                            ? (ppXsecPb / kPPG12Jet50CrossPb)
                            : 1.0;
                        fillPPPhotonIDTrainingTree(v,
                                                   eta,
                                                   phi,
                                                   iPho,
                                                   ppg12ScoreInputEt,
                                                   ppg12ResponseEt,
                                                   ppg12ParityEisoEt,
                                                   ppg12YieldRawEisoEt,
                                                   ppg12YieldEisoEt,
                                                   ppg12YieldIsoMax,
                                                   ppg12YieldNonIsoMin,
                                                   ppg12YieldIso,
                                                   ppg12YieldNonIso,
                                                   ppg12PhotonYieldCommonPass,
                                                   static_cast<int>(ppg12YieldTag),
                                                   ptIdx,
                                                   ppPhotonIDResolvedRole == "signal" && isPPG12SourceRoleSignal,
                                                   ppg12SignalTruthClass,
                                                   ppg12AnalysisWindowPass,
                                                   ppg12ResponseWindowPass,
                                                   ppg12LogicalABCDRegion,
                                                   ppg12SignalFillA,
                                                   ppg12SignalFillB,
                                                   ppg12SignalFillC,
                                                   ppg12SignalFillD,
                                                   ppg12SignalFillMultiplicity,
                                                   truthTrackId,
                                                   truthBarcode,
                                                   truthEContrib,
                                                   ppInclusiveJetContext ? ppg12InclusiveJetSliceBin(ppInclusiveJetSlice) : 0,
                                                   static_cast<float>(ppXsecPb),
                                                   static_cast<float>(ppXsecWeight),
                                                   static_cast<float>(ppInclusiveJetContext ? ppInclusiveJetStitchLo : -999.0),
                                                   static_cast<float>(ppInclusiveJetContext ? ppInclusiveJetStitchHi : -999.0),
                                                   static_cast<float>(ppInclusiveJetContext ? ppInclusiveJetMaxTruthJetPtR04 : -999.0),
                                                   ppInclusiveJetContext ? (ppInclusiveJetPassR04 ? 1 : 0) : -1,
                                                   truthIsoEtR03,
                                                   truthIsoEtR04,
                                                   truthIsoValid,
                                                   truthHepMCAssociationValid);
                    }
                }

                auto fillSSSpectra = [&](const std::string& trigShort, const std::string& tagKey, HistViewScope scope)
                {
                    auto fill1 = [&](const std::string& key, double val)
                    {
                        if (!std::isfinite(val)) return;

                        if (auto* h = getOrBookSSHist(trigShort, key, tagKey, ptIdx, effCentIdx_SS, scope))
                        {
                            h->Fill(val);
                            bumpHistFill(trigShort, h->GetName());
                        }
                    };

                    fill1("weta",   v.weta_cogx);
                    fill1("wphi",   v.wphi_cogx);
                    fill1("et1",    v.et1);
                    fill1("e11e33", v.e11_over_e33);
                    fill1("e32e35", v.e32_over_e35);
                };

                for (const auto& trigShort : activeTrig)
                {
                    if (doCanonical) fillSSSpectra(trigShort, "inclusive", HistViewScope::Canonical);
                    if (ssIso)    fillSSSpectra(trigShort, "iso", HistViewScope::IsoView);
                    if (ssNonIso) fillSSSpectra(trigShort, "nonIso", HistViewScope::IsoView);
                }

                // ---------- NPB preselection shadow QA ----------
                // If an NPB-gated preselection is active, keep that decision untouched,
                // but also evaluate the reference pp/PPG12 preselection as diagnostics.
                if (doCanonical && preselectionUsesNPB(m_preselectionVariant))
                {
                    const bool npbPassForAudit =
                        std::isfinite(v.npb_score) &&
                        std::isfinite(v.pt_gamma) &&
                        (v.npb_score > m_npbCut);

                    const std::string npbTagKey = (npbPassForAudit ? "npbPass" : "npbFail");

                    const bool ref_pass_e11e33 = (v.e11_over_e33 < PRE_E11E33_MAX);
                    const bool ref_pass_et1    = in_open_interval(v.et1, PRE_ET1_MIN, PRE_ET1_MAX);
                    const bool ref_pass_e32e35 = in_open_interval(v.e32_over_e35, PRE_E32E35_MIN, PRE_E32E35_MAX);
                    const bool ref_pass_weta   = (v.weta_cogx < PRE_WETA_MAX);

                    const bool ref_fail_e11e33 = !ref_pass_e11e33;
                    const bool ref_fail_et1    = !ref_pass_et1;
                    const bool ref_fail_e32e35 = !ref_pass_e32e35;
                    const bool ref_fail_weta   = !ref_pass_weta;

                    int preRefFailMask = 0;
                    if (ref_fail_e11e33) preRefFailMask |= 1;
                    if (ref_fail_et1)    preRefFailMask |= 2;
                    if (ref_fail_e32e35) preRefFailMask |= 4;
                    if (ref_fail_weta)   preRefFailMask |= 8;

                    const bool refPassForAudit = (preRefFailMask == 0);

                    auto fillNPBScore = [&](const std::string& trigShort, const std::string& tagKey)
                    {
                        if (!std::isfinite(v.npb_score)) return;

                        if (auto* h = getOrBookSSHist(trigShort, "npbScore", tagKey, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            h->Fill(v.npb_score);
                            bumpHistFill(trigShort, h->GetName());
                        }
                    };

                    auto fillPreRefFailCount = [&](const std::string& trigShort, const std::string& base)
                    {
                        const std::string baseAll = base + "_all";
                        if (auto* h = getOrBookCountHist(trigShort, baseAll, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            h->Fill(1);
                            bumpHistFill(trigShort, baseAll + slice_SS);
                        }

                        const std::string baseNPB = base + "_" + npbTagKey;
                        if (auto* h = getOrBookCountHist(trigShort, baseNPB, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            h->Fill(1);
                            bumpHistFill(trigShort, baseNPB + slice_SS);
                        }
                    };

                    for (const auto& trigShort : activeTrig)
                    {
                        fillSSSpectra(trigShort, npbTagKey, HistViewScope::Canonical);
                        fillNPBScore(trigShort, "inclusive");
                        fillNPBScore(trigShort, npbTagKey);

                        if (auto* hMaskAll = getOrBookCountHist(trigShort, "h_preRefFailMask_all", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            hMaskAll->Fill(preRefFailMask);
                            bumpHistFill(trigShort, std::string("h_preRefFailMask_all") + slice_SS);
                        }

                        const std::string maskNPB = "h_preRefFailMask_" + npbTagKey;
                        if (auto* hMaskNPB = getOrBookCountHist(trigShort, maskNPB, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            hMaskNPB->Fill(preRefFailMask);
                            bumpHistFill(trigShort, maskNPB + slice_SS);
                        }

                        const std::string matrixBase =
                            std::string("h_preRefMatrix_") +
                            npbTagKey + "_" +
                            (refPassForAudit ? "refPass" : "refFail");

                        if (auto* hMatrix = getOrBookCountHist(trigShort, matrixBase, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                        {
                            hMatrix->Fill(1);
                            bumpHistFill(trigShort, matrixBase + slice_SS);
                        }

                        if (ref_fail_weta)
                            fillPreRefFailCount(trigShort, "h_preRefFail_weta");

                        if (ref_fail_et1)
                        {
                            const std::string base = (v.et1 <= PRE_ET1_MIN) ? "h_preRefFail_et1_low" : "h_preRefFail_et1_high";
                            fillPreRefFailCount(trigShort, base);
                        }

                        if (ref_fail_e11e33)
                            fillPreRefFailCount(trigShort, "h_preRefFail_e11e33_high");

                        if (ref_fail_e32e35)
                        {
                            const std::string base = (v.e32_over_e35 <= PRE_E32E35_MIN) ? "h_preRefFail_e32e35_low" : "h_preRefFail_e32e35_high";
                            fillPreRefFailCount(trigShort, base);
                        }
                    }
                }

                // ---------- Preselection breakdown (count by criterion) ----------

                const bool pre_ok = passesPhotonPreselection(v);
                if (!pre_ok)
                {
                    if (preselectionUsesNPB(m_preselectionVariant))
                    {
                        if (doCanonical)
                        {
                            for (const auto& trigShort : activeTrig)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_preFail_bdt", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                {
                                    h->Fill(1);
                                    bumpHistFill(trigShort, std::string("h_preFail_bdt") + slice_SS);
                                }
                            }
                        }

                        if (Verbosity() >= 4)
                        {
                            std::ostringstream msg;
                            msg << "      [pho#" << iPho << "] preselection FAIL"
                                << " | variant=" << m_preselectionVariant << "(NPB-gated)"
                                << " | npb_score=" << std::fixed << std::setprecision(4) << v.npb_score
                                << " | cut:>" << m_npbCut
                                << " | pT^{#gamma}=" << std::fixed << std::setprecision(2) << v.pt_gamma;
                            LOG(4, CLR_MAGENTA, msg.str());
                        }
                    }
                    else
                    {
                        const bool pass_e11e33 = (v.e11_over_e33 < PRE_E11E33_MAX);
                        const bool pass_et1    = in_open_interval(v.et1, PRE_ET1_MIN, PRE_ET1_MAX);
                        const bool pass_e32e35 = in_open_interval(v.e32_over_e35, PRE_E32E35_MIN, PRE_E32E35_MAX);
                        const bool pass_weta   = (v.weta_cogx < PRE_WETA_MAX);

                        const bool fail_e11e33 = !pass_e11e33;
                        const bool fail_et1    = !pass_et1;
                        const bool fail_e32e35 = !pass_e32e35;
                        const bool fail_weta   = !pass_weta;

                        int preFailMask = 0;
                        if (fail_e11e33) preFailMask |= 1;
                        if (fail_et1)    preFailMask |= 2;
                        if (fail_e32e35) preFailMask |= 4;
                        if (fail_weta)   preFailMask |= 8;

                        if (doCanonical)
                        {
                            for (const auto& trigShort : activeTrig)
                            {
                                if (auto* hMask = getOrBookCountHist(trigShort, "h_preFailMask", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                {
                                    hMask->Fill(preFailMask);
                                    bumpHistFill(trigShort, std::string("h_preFailMask") + slice_SS);
                                }

                                if (!pass_weta)
                                {
                                    if (auto* h = getOrBookCountHist(trigShort, "h_preFail_weta", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                    { h->Fill(1); bumpHistFill(trigShort, std::string("h_preFail_weta") + slice_SS); }
                                }
                                if (!pass_et1)
                                {
                                    const char* base = (v.et1 <= PRE_ET1_MIN) ? "h_preFail_et1_low" : "h_preFail_et1_high";
                                    if (auto* h = getOrBookCountHist(trigShort, base, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                    { h->Fill(1); bumpHistFill(trigShort, std::string(base) + slice_SS); }
                                }
                                if (!pass_e11e33)
                                {
                                    if (auto* h = getOrBookCountHist(trigShort, "h_preFail_e11e33_high", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                    { h->Fill(1); bumpHistFill(trigShort, std::string("h_preFail_e11e33_high") + slice_SS); }
                                }
                                if (!pass_e32e35)
                                {
                                    const char* base = (v.e32_over_e35 <= PRE_E32E35_MIN) ? "h_preFail_e32e35_low" : "h_preFail_e32e35_high";
                                    if (auto* h = getOrBookCountHist(trigShort, base, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                    { h->Fill(1); bumpHistFill(trigShort, std::string(base) + slice_SS); }
                                }
                            }
                        }

                        if (doCanonical)
                        {
                            if (!pass_weta)   ++m_bk.pre_fail_weta;
                            if (!pass_et1)    { if (v.et1 <= PRE_ET1_MIN) ++m_bk.pre_fail_et1_low; else ++m_bk.pre_fail_et1_high; }
                            if (!pass_e11e33) ++m_bk.pre_fail_e11e33_high;
                            if (!pass_e32e35) { if (v.e32_over_e35 <= PRE_E32E35_MIN) ++m_bk.pre_fail_e32e35_low; else ++m_bk.pre_fail_e32e35_high; }
                        }

                        if (Verbosity() >= 4)
                        {
                            const char* et1_state    = pass_et1    ? "PASS" : (v.et1 <= PRE_ET1_MIN ? "FAIL(low)" : "FAIL(high)");
                            const char* e32e35_state = pass_e32e35 ? "PASS" : (v.e32_over_e35 <= PRE_E32E35_MIN ? "FAIL(low)" : "FAIL(high)");

                            std::ostringstream msg;
                            msg << "      [pho#" << iPho << "] preselection FAIL"
                                << " | weta="    << std::fixed << std::setprecision(3) << v.weta_cogx
                                << "  cut:<"     << PRE_WETA_MAX       << " → " << (pass_weta ? "PASS" : "FAIL")
                                << " | et1="     << std::fixed << std::setprecision(3) << v.et1
                                << "  cut:("     << PRE_ET1_MIN        << "," << PRE_ET1_MAX       << ") → " << et1_state
                                << " | e11/e33=" << std::fixed << std::setprecision(3) << v.e11_over_e33
                                << "  cut:<"     << PRE_E11E33_MAX     << " → " << (pass_e11e33 ? "PASS" : "FAIL")
                                << " | e32/e35=" << std::fixed << std::setprecision(3) << v.e32_over_e35
                                << "  cut:("     << PRE_E32E35_MIN     << "," << PRE_E32E35_MAX    << ") → " << e32e35_state
                                << " | pT^{#gamma}=" << std::fixed << std::setprecision(2) << v.pt_gamma;
                            LOG(4, CLR_MAGENTA, msg.str());
                        }
                    }

                    ++nNotTight;
                    continue;
                }

                if (Verbosity() >= 4)
                {
                    std::ostringstream msg;
                    msg << "      [pho#" << iPho << "] preselection PASS";
                    if (preselectionUsesNPB(m_preselectionVariant))
                    {
                        msg << " | variant=" << m_preselectionVariant << "(NPB-gated)"
                            << " | npb_score=" << std::fixed << std::setprecision(4) << v.npb_score
                            << " | cut:>" << m_npbCut;
                    }
                    else
                    {
                        msg << " | weta="    << std::fixed << std::setprecision(3) << v.weta_cogx  << "  cut:<"  << PRE_WETA_MAX    << " → PASS"
                            << " | et1="     << std::fixed << std::setprecision(3) << v.et1        << "  cut:("  << PRE_ET1_MIN     << "," << PRE_ET1_MAX     << ") → PASS"
                            << " | e11/e33=" << std::fixed << std::setprecision(3) << v.e11_over_e33 << "  cut:<" << PRE_E11E33_MAX  << " → PASS"
                            << " | e32/e35=" << std::fixed << std::setprecision(3) << v.e32_over_e35 << "  cut:(" << PRE_E32E35_MIN  << "," << PRE_E32E35_MAX  << ") → PASS";
                    }
                    msg << " | pT^{#gamma}=" << std::fixed << std::setprecision(2) << v.pt_gamma;
                    LOG(4, CLR_RED, msg.str());
                }
                if (doCanonical) ++m_bk.pre_pass;
                if (keepPPG12TableQARow)
                {
                    fillPPG12TableQA(activeTrig, v, ppg12TableQAEisoEt, effCentIdx_SS, 1, ppg12TableQARowWeight, ppg12ScoreInputEt);
                }

                if (doCanonical && m_tightVariant == "newPPG12" && std::isfinite(v.tight_bdt_score))
                {
                    for (const auto& trigShort : activeTrig)
                    {
                        if (auto* hScore = getOrBookBDTScoreHist(trigShort, "h_tightBDTScore_preselected", ptIdx, effCentIdx_SS))
                        {
                            hScore->Fill(v.tight_bdt_score);
                            bumpHistFill(trigShort, std::string("h_tightBDTScore_preselected") + slice_SS);
                        }
                    }
                }

                // ---------- Isolation (count pass/fail) ----------
                // Use the same strict ISO / NONISO / GAP definition as
                // fillIsoSSTagCounters so xJ-purity leading-region counters are
                // matched to the ABCD sideband definitions.
                const double thrIsoForABCD    = recoIsoThreshold(pt_gamma);
                const double thrNonIsoForABCD = recoNonIsoThreshold(pt_gamma);
                const bool validIsoForABCD = (std::isfinite(ppg12ParityEisoEt) && ppg12ParityEisoEt < 1e8);
                const bool iso    = validIsoForABCD && (ppg12ParityEisoEt < thrIsoForABCD);
                const bool nonIso = validIsoForABCD && (ppg12ParityEisoEt > thrNonIsoForABCD);
                if (doCanonical)
                {
                    if (iso) ++m_bk.iso_pass;
                    else ++m_bk.iso_fail;
                }

                // ---------- Tight classification breakdown ----------
                RecoilJets::TightTag tightTag;
                if (m_tightVariant == "newPPG12")
                {
                    const double tight_min = configuredTightBDTMin(v.pt_gamma);
                    const double non_tight_min = configuredNonTightBDTMin(v.pt_gamma);
                    const double non_tight_max = configuredNonTightBDTMax(v.pt_gamma);
                    const bool pass_tight_bdt = configuredTightBDTPass(v.tight_bdt_score, v.pt_gamma);
                    const bool pass_non_tight_bdt = configuredNonTightBDTPass(v.tight_bdt_score, v.pt_gamma);

                    tightTag = configuredVariantABDTTag(v.tight_bdt_score, v.pt_gamma);

                    if (doCanonical)
                    {
                        if (tightTag == TightTag::kTight) ++m_bk.tight_tight;
                        else if (tightTag == TightTag::kNonTight) ++m_bk.tight_nonTight;
                        else ++m_bk.tight_neither;
                    }

                    if (doCanonical)
                    {
                        for (const auto& trigShort : activeTrig)
                        {
                            if (tightTag != TightTag::kTight)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_bdt", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                {
                                    h->Fill(1);
                                    bumpHistFill(trigShort, std::string("h_tightFail_bdt") + slice_SS);
                                }
                            }
                        }
                    }

                    if (Verbosity() >= 4)
                    {
                        std::ostringstream msg;
                        msg << "      [pho#" << iPho << "] tight classification"
                            << " | variant=newPPG12(PPG12 BDT)"
                            << " | tight_bdt_score=" << std::fixed << std::setprecision(4) << v.tight_bdt_score
                            << " | tight=(" << tight_min << ",+inf) pass=" << pass_tight_bdt
                            << " | nonTight=(" << non_tight_min << "," << non_tight_max << ") pass=" << pass_non_tight_bdt
                            << " | nonTightVariant=" << m_nonTightVariant
                            << " | tag=" << tightTagName(tightTag);
                        LOG(4, (tightTag == TightTag::kTight ? CLR_RED :
                                (tightTag == TightTag::kNonTight ? CLR_GREEN : CLR_YELLOW)), msg.str());
                    }
                }
                else
                {
                    const double w_hi = tight_w_hi(v.pt_gamma);
                    const bool t_weta   = in_open_interval(v.weta_cogx,  TIGHT_W_LO, w_hi);
                    const bool t_wphi   = in_open_interval(v.wphi_cogx,  TIGHT_W_LO, w_hi);
                    const bool t_e11e33 = in_open_interval(v.e11_over_e33, TIGHT_E11E33_MIN, TIGHT_E11E33_MAX);
                    const bool t_et1    = in_open_interval(v.et1,          TIGHT_ET1_MIN,    TIGHT_ET1_MAX);
                    const bool t_e32e35 = in_open_interval(v.e32_over_e35, TIGHT_E32E35_MIN, TIGHT_E32E35_MAX);

                    int tight_fails = 0;
                    if (!t_weta)   { if (doCanonical) ++m_bk.tight_fail_weta;   ++tight_fails; }
                    if (!t_wphi)   { if (doCanonical) ++m_bk.tight_fail_wphi;   ++tight_fails; }
                    if (!t_e11e33) { if (doCanonical) ++m_bk.tight_fail_e11e33; ++tight_fails; }
                    if (!t_et1)    { if (doCanonical) ++m_bk.tight_fail_et1;    ++tight_fails; }
                    if (!t_e32e35) { if (doCanonical) ++m_bk.tight_fail_e32e35; ++tight_fails; }

                    if (tight_fails == 0)      { tightTag = TightTag::kTight;      if (doCanonical) ++m_bk.tight_tight; }
                    else if (tight_fails >= 2) { tightTag = TightTag::kNonTight;   if (doCanonical) ++m_bk.tight_nonTight; }
                    else                       { tightTag = TightTag::kNeither;    if (doCanonical) ++m_bk.tight_neither; }

                    int tightFailMask = 0;
                    if (!t_weta)   tightFailMask |= 1;
                    if (!t_wphi)   tightFailMask |= 2;
                    if (!t_e11e33) tightFailMask |= 4;
                    if (!t_et1)    tightFailMask |= 8;
                    if (!t_e32e35) tightFailMask |= 16;

                    if (doCanonical)
                    {
                        for (const auto& trigShort : activeTrig)
                        {
                            if (auto* hMaskAll = getOrBookCountHist(trigShort, "h_tightFailMask_allPreselected", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                            {
                                hMaskAll->Fill(tightFailMask);
                                bumpHistFill(trigShort, std::string("h_tightFailMask_allPreselected") + slice_SS);
                            }

                            if (tightTag == TightTag::kNonTight)
                            {
                                if (auto* hMaskNonTight = getOrBookCountHist(trigShort, "h_tightFailMask_nonTight", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                {
                                    hMaskNonTight->Fill(tightFailMask);
                                    bumpHistFill(trigShort, std::string("h_tightFailMask_nonTight") + slice_SS);
                                }
                            }
                            else if (tightTag == TightTag::kNeither)
                            {
                                if (auto* hMaskNeither = getOrBookCountHist(trigShort, "h_tightFailMask_neither", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                {
                                    hMaskNeither->Fill(tightFailMask);
                                    bumpHistFill(trigShort, std::string("h_tightFailMask_neither") + slice_SS);
                                }
                            }

                            if (!t_weta)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_weta", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                { h->Fill(1); bumpHistFill(trigShort, std::string("h_tightFail_weta") + slice_SS); }
                            }
                            if (!t_wphi)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_wphi", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                { h->Fill(1); bumpHistFill(trigShort, std::string("h_tightFail_wphi") + slice_SS); }
                            }
                            if (!t_e11e33)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_e11e33", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                { h->Fill(1); bumpHistFill(trigShort, std::string("h_tightFail_e11e33") + slice_SS); }
                            }
                            if (!t_et1)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_et1", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                { h->Fill(1); bumpHistFill(trigShort, std::string("h_tightFail_et1") + slice_SS); }
                            }
                            if (!t_e32e35)
                            {
                                if (auto* h = getOrBookCountHist(trigShort, "h_tightFail_e32e35", ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                                { h->Fill(1); bumpHistFill(trigShort, std::string("h_tightFail_e32e35") + slice_SS); }
                            }
                        }
                    }
                }

                if (tightTag == TightTag::kTight)
                {
                    if (keepPPG12TableQARow)
                    {
                        fillPPG12TableQA(activeTrig, v, ppg12TableQAEisoEt, effCentIdx_SS, 2, ppg12TableQARowWeight, ppg12ScoreInputEt);
                    }
                }
                else if (tightTag == TightTag::kNonTight)
                {
                    if (keepPPG12TableQARow)
                    {
                        fillPPG12TableQA(activeTrig, v, ppg12TableQAEisoEt, effCentIdx_SS, 3, ppg12TableQARowWeight, ppg12ScoreInputEt);
                    }
                }

                // -------------------------------------------------------------------------
                // NEW: PPG12-style SS template histograms (preselection / tight / non-tight)
                //   - DATA: tagKey = pre / tight / nonTight
                //   - SIM : tagKey = pre_sig / pre_bkg, tight_sig / tight_bkg, nonTight_sig / nonTight_bkg
                //     where "sig" is the truth isolated prompt photon definition and "bkg" is its complement.
                // -------------------------------------------------------------------------
                if (doCanonical)
                {
                    std::string mcSuffix;
                    if (!m_isSim) mcSuffix = "";
                    else
                    {
                        bool isSig = false;
                        if (clustereval_SS && haveCaloEval_SS)
                        {
                            TruthSignalPhotonInfo matchedTruth;
                            int clusterTruthTrackId = -1;
                            float eContrib = std::numeric_limits<float>::lowest();
                            isSig = classifyRecoPhotonWithPPG12TruthTrack(rc, *clustereval_SS,
                                                                          truthSignalByTrackId_SS,
                                                                          matchedTruth,
                                                                          clusterTruthTrackId,
                                                                          eContrib);
                        }
                        mcSuffix = (isSig ? "_sig" : "_bkg");
                    }

                    auto fillSSPPG12 = [&](const std::string& trigShort, const std::string& baseTag)
                    {
                        const std::string tagKey = baseTag + mcSuffix;

                        auto fill1 = [&](const std::string& key, double val)
                        {
                            if (!std::isfinite(val)) return;
                            if (auto* h = getOrBookSSHist(trigShort, key, tagKey, ptIdx, effCentIdx_SS, HistViewScope::Canonical))
                            {
                                h->Fill(val);
                                bumpHistFill(trigShort, h->GetName());
                            }
                        };

                        fill1("weta",   v.weta_cogx);
                        fill1("wphi",   v.wphi_cogx);
                        fill1("et1",    v.et1);
                        fill1("e11e33", v.e11_over_e33);
                        fill1("e32e35", v.e32_over_e35);
                    };

                    for (const auto& trigShort : activeTrig)
                    {
                        fillSSPPG12(trigShort, "pre");
                        if (tightTag == TightTag::kTight) fillSSPPG12(trigShort, "tight");
                        else if (tightTag == TightTag::kNonTight) fillSSPPG12(trigShort, "nonTight");
                    }
                }

                // -------------------------------------------------------------------------
                // Deliverable Set B:
                //   Isolation-energy spectra split by tightness (NO isolation requirement)
                //
                //   - inclusive: already filled in fillPureIsolationQA() as:
                //       default/AuAu: h_Eiso, h_Eiso_emcal, h_Eiso_hcalin, h_Eiso_hcalout
                //       pp PPG12:    h_Eiso, h_Eiso_ppg12_topo_raw, h_Eiso_ppg12_topo_reco
                //
                //   - tight / nonTight use the active configured tight/non-tight variant; "Neither" excluded:
                //       default/AuAu: h_Eiso_{tight,nonTight} plus EMCal/IHCal/OHCal pieces
                //       pp PPG12:    h_Eiso_{tight,nonTight} plus explicit topo raw/reco pieces
                // -------------------------------------------------------------------------
                if (tightTag == TightTag::kTight || tightTag == TightTag::kNonTight)
                {
                    const char* base_tot = (tightTag == TightTag::kTight) ? "h_Eiso_tight" : "h_Eiso_nonTight";
                    const char* base_em  = (tightTag == TightTag::kTight) ? "h_Eiso_emcal_tight" : "h_Eiso_emcal_nonTight";
                    const char* base_hi  = (tightTag == TightTag::kTight) ? "h_Eiso_hcalin_tight" : "h_Eiso_hcalin_nonTight";
                    const char* base_ho  = (tightTag == TightTag::kTight) ? "h_Eiso_hcalout_tight" : "h_Eiso_hcalout_nonTight";
                    const char* base_ppg12_raw =
                        (tightTag == TightTag::kTight) ? "h_Eiso_ppg12_topo_raw_tight" : "h_Eiso_ppg12_topo_raw_nonTight";
                    const char* base_ppg12_reco =
                        (tightTag == TightTag::kTight) ? "h_Eiso_ppg12_topo_reco_tight" : "h_Eiso_ppg12_topo_reco_nonTight";

                    // Component isolation (PhotonClusterBuilder iso_* pieces)
                    double eiso_emcal   = 1e9;
                    double eiso_hcalin  = 1e9;
                    double eiso_hcalout = 1e9;

                    const int cone10 = static_cast<int>(std::lround(10.0 * m_isoConeR));

                    const char* k_em = nullptr;
                    const char* k_hi = nullptr;
                    const char* k_ho = nullptr;

                    if (cone10 == 3)
                    {
                        k_em = "iso_03_emcal";
                        k_hi = "iso_03_hcalin";
                        k_ho = "iso_03_hcalout";
                    }
                    else if (cone10 == 4)
                    {
                        k_em = "iso_04_emcal";
                        k_hi = "iso_04_hcalin";
                        k_ho = "iso_04_hcalout";
                    }

                    if (pho && k_em && k_hi && k_ho)
                    {
                        eiso_emcal   = pho->get_shower_shape_parameter(k_em);
                        eiso_hcalin  = pho->get_shower_shape_parameter(k_hi);
                        eiso_hcalout = pho->get_shower_shape_parameter(k_ho);

                        if (!std::isfinite(eiso_emcal) || !std::isfinite(eiso_hcalin) || !std::isfinite(eiso_hcalout))
                        {
                            eiso_emcal = eiso_hcalin = eiso_hcalout = 1e9;
                        }
                    }

                    if (fillConeThisView())
                    {
                      for (const auto& trigShort : activeTrig)
                      {
                          if (auto* hIso = getOrBookIsoPartHist(trigShort, base_tot,
                                                                "E_{T}^{iso} [GeV]",
                                                                ptIdx, effCentIdx_SS))
                          {
                              hIso->Fill(ppg12ParityEisoEt);
                              bumpHistFill(trigShort, hIso->GetName());
                          }

                          if (m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldUseTopoIso && !m_isAuAu)
                          {
                              if (auto* hRaw = getOrBookIsoPartHist(trigShort, base_ppg12_raw,
                                                                    "E_{T}^{iso,raw topo} [GeV]",
                                                                    ptIdx, effCentIdx_SS))
                              {
                                  hRaw->Fill(ppg12YieldRawEisoEt);
                                  bumpHistFill(trigShort, hRaw->GetName());
                              }
                              if (auto* hReco = getOrBookIsoPartHist(trigShort, base_ppg12_reco,
                                                                     "E_{T}^{iso,reco PPG12} [GeV]",
                                                                     ptIdx, effCentIdx_SS))
                              {
                                  hReco->Fill(ppg12YieldEisoEt);
                                  bumpHistFill(trigShort, hReco->GetName());
                              }
                          }
                          else
                          {
                              if (auto* hEm = getOrBookIsoPartHist(trigShort, base_em,
                                                                   "E_{T}^{iso,EMCal} [GeV]",
                                                                   ptIdx, effCentIdx_SS))
                              {
                                  hEm->Fill(eiso_emcal);
                                  bumpHistFill(trigShort, hEm->GetName());
                              }

                              if (auto* hHi = getOrBookIsoPartHist(trigShort, base_hi,
                                                                   "E_{T}^{iso,IHCAL} [GeV]",
                                                                   ptIdx, effCentIdx_SS))
                              {
                                  hHi->Fill(eiso_hcalin);
                                  bumpHistFill(trigShort, hHi->GetName());
                              }

                              if (auto* hHo = getOrBookIsoPartHist(trigShort, base_ho,
                                                                   "E_{T}^{iso,OHCAL} [GeV]",
                                                                   ptIdx, effCentIdx_SS))
                              {
                                  hHo->Fill(eiso_hcalout);
                                  bumpHistFill(trigShort, hHo->GetName());
                              }
                          }
                      }
                    }
                }

                // record the 2×2 (iso, tight) category + SS variable hists
                // This also fills h_Eiso once and prints a detailed decision line.
                for (const auto& trigShort : activeTrig)
                {
                    fillIsoSSTagCounters(trigShort, rc, v, tightTag, pt_gamma, centIdx, topNode);
                }

                //  xJ / unfolding gate (preselection already passed above):
                //    - Region A: iso ∧ tight               -> nominal signal sample
                //    - Region C: iso ∧ nonTight(>=2 fail) -> fake-photon sideband template
                //    - all other categories are NOT used for jet-level xJ filling
                const bool useSignalA   = (iso && tightTag == TightTag::kTight);
                const bool useSidebandC = (iso && tightTag == TightTag::kNonTight);
                const bool useSidebandB = (nonIso && tightTag == TightTag::kTight);
                const bool useSidebandD = (nonIso && tightTag == TightTag::kNonTight);

                if (useSidebandB && (!haveLeadNonIsoTight || pt_gamma > leadNonIsoTightPtGamma))
                {
                    haveLeadNonIsoTight = true;
                    leadNonIsoTightPtGamma = pt_gamma;
                    leadNonIsoTightRc = rc;
                }

                if (useSidebandD && (!haveLeadNonIsoNonTight || pt_gamma > leadNonIsoNonTightPtGamma))
                {
                    haveLeadNonIsoNonTight = true;
                    leadNonIsoNonTightPtGamma = pt_gamma;
                    leadNonIsoNonTightRc = rc;
                }

                if (!useSignalA && !useSidebandC)
                {
                    if (!iso) ++nNotIso;
                    if (tightTag != TightTag::kTight) ++nNotTight;
                    if (Verbosity() >= 6)
                        LOG(6, CLR_BLUE, "      [pho#" << iPho << "] NOT used for xJ (iso=" << iso
                            << ", tightTag=" << tightTagName(tightTag) << ")");
                    continue;
                }

                if (useSignalA)
                {
                    // Count ALL iso∧tight photon candidates in this event (photon-side ambiguity diagnostic)
                    ++nIsoTightPhoCand;

                    for (const auto& trigShort : activeTrig)
                    {
                        if (auto* h3 = getOrBookPho3TightIso(trigShort))
                        {
                            h3->Fill(pt_gamma, eta, TVector2::Phi_mpi_pi(phi_gamma));
                            bumpHistFill(trigShort, h3->GetName());
                        }
                    }

                    recoIsoTightPhoClustersPPG12.push_back(rc);
                    recoIsoTightPhoPtsPPG12.push_back(pt_gamma);

                    const int effCentIdx_PPG12 = (m_isAuAu ? centIdx : -1);
                    if (!m_isSim)
                    {
                        for (const auto& trigShort : activeTrig)
                        {
                            if (auto* hRAlt = getOrBookUnfoldRecoPhoPtGammaPPG12Obj(trigShort, effCentIdx_PPG12))
                            {
                                hRAlt->Fill(pt_gamma);
                                bumpHistFill(trigShort, hRAlt->GetName());
                            }
                        }
                    }

                    // Do NOT jet-match here. If >1 photon passes iso∧tight in the same event,
                    // jet-matching here would double-fill xJ/JES histograms.
                    //
                    // Instead: keep ONLY the event-leading iso∧tight photon (highest pT^gamma),
                    // and do jet matching + JES3 fills ONCE after the photon loop.
                    if (!haveLeadIsoTight || pt_gamma > leadPtGamma)
                    {
                        haveLeadIsoTight = true;
                        leadPhoIndex     = iPho;
                        leadPtIdx        = ptIdx;
                        leadPtGamma      = pt_gamma;
                        leadEtaGamma     = eta;
                        leadPhiGamma     = phi_gamma;

                        // Store the actual cluster pointer for later truth↔reco association
                        leadRc           = rc;

                        if (Verbosity() >= 6)
                            LOG(6, CLR_GREEN, "      [pho#" << iPho << "] marked as event-leading iso∧tight photon for jet matching (pT="
                                << std::fixed << std::setprecision(2) << leadPtGamma << ")");
                    }

                    // Defer jet matching (prevents double-filling JES TH3s if multiple photons pass).
                    continue;
                }

                // Region C sideband: keep ONLY the event-leading iso∧nonTight photon.
                ++nNotTight;

                if (!haveLeadIsoNonTight || pt_gamma > leadNonTightPtGamma)
                {
                    haveLeadIsoNonTight = true;
                    leadNonTightPtGamma  = pt_gamma;
                    leadNonTightEtaGamma = eta;
                    leadNonTightPhiGamma = phi_gamma;
                    leadNonTightRc       = rc;

                    if (Verbosity() >= 6)
                        LOG(6, CLR_CYAN, "      [pho#" << iPho << "] marked as event-leading iso∧nonTight photon for sideband-C recoil filling (pT="
                            << std::fixed << std::setprecision(2) << leadNonTightPtGamma << ")");
                }

                continue;
            } // photon loop

            // ------------------------------------------------------------------
            // Event-level photon-side diagnostic:
            //   N = number of iso∧tight photon candidates in this event.
            // Fill once per event (only when a leading iso∧tight photon exists),
            // binned by the selected leading-photon pT bin (leadPtIdx).
            // ------------------------------------------------------------------
            if (haveLeadIsoTight && leadPtIdx >= 0)
            {
                for (const auto& trigShort : activeTrig)
                {
                    if (auto* hN = getOrBookNIsoTightPhoCandHist(trigShort, leadPtIdx, centIdx))
                    {
                        hN->Fill(nIsoTightPhoCand);
                        bumpHistFill(trigShort, hN->GetName());
                    }
                }
            }

            // ------------------------------------------------------------------
            // Jet matching + JES fills ONCE per event using the event-leading
            // iso∧tight photon (by pT^gamma), but run identically for ALL radii
            // in kJetRadii (r02 + r04) in the SAME loop.
            // ------------------------------------------------------------------

            // Centrality index used for unfolding/matching-QA suffixing (centrality-only suffix in Au+Au)
            const int effCentIdx_M = (m_isAuAu ? centIdx : -1);

            auto fillLeadXJPurityABCDCount =
                [&](const char* base, const bool have, const double pt)
            {
                if (!have || !(std::isfinite(pt) && pt > 0.0)) return;
                const int idx = findPtBin(pt);
                if (idx < 0) return;

                for (const auto& trigShort : activeTrig)
                {
                    if (auto* h = getOrBookCountHist(trigShort, base, idx, effCentIdx_M))
                    {
                        h->Fill(1);
                        bumpHistFill(trigShort, h->GetName());
                    }
                }
            };

            fillLeadXJPurityABCDCount("h_xJpurityLead_isIsolated_isTight",
                                      haveLeadIsoTight, leadPtGamma);
            fillLeadXJPurityABCDCount("h_xJpurityLead_notIsolated_isTight",
                                      haveLeadNonIsoTight, leadNonIsoTightPtGamma);
            fillLeadXJPurityABCDCount("h_xJpurityLead_isIsolated_notTight",
                                      haveLeadIsoNonTight, leadNonTightPtGamma);
            fillLeadXJPurityABCDCount("h_xJpurityLead_notIsolated_notTight",
                                      haveLeadNonIsoNonTight, leadNonIsoNonTightPtGamma);

            if (m_isSim && clustereval_SS && haveCaloEval_SS)
            {
                auto fillLeadXJPurityLeakage =
                    [&](const bool have, const RawCluster* rcLead, const double pt, const int regBin)
                {
                    if (!have || !rcLead || !(std::isfinite(pt) && pt > 0.0) || regBin <= 0) return;

                    TruthSignalPhotonInfo matchedTruth;
                    int clusterTruthTrackId = -1;
                    float eContrib = std::numeric_limits<float>::lowest();
                    if (!classifyRecoPhotonWithPPG12TruthTrack(rcLead, *clustereval_SS,
                                                               truthSignalByTrackId_SS,
                                                               matchedTruth,
                                                               clusterTruthTrackId,
                                                               eContrib))
                    {
                        return;
                    }

                    const int idx = findPtBin(pt);
                    if (idx < 0) return;

                    for (const auto& trigShort : activeTrig)
                    {
                        if (auto* h = getOrBookSigABCDLeakageHist(trigShort, idx, effCentIdx_M,
                                                                  "h_xJpurityLead_sigABCD_MC"))
                        {
                            h->Fill(regBin);
                            bumpHistFill(trigShort, h->GetName());
                        }
                    }
                };

                fillLeadXJPurityLeakage(haveLeadIsoTight, leadRc, leadPtGamma, 1);
                fillLeadXJPurityLeakage(haveLeadNonIsoTight, leadNonIsoTightRc, leadNonIsoTightPtGamma, 2);
                fillLeadXJPurityLeakage(haveLeadIsoNonTight, leadNonTightRc, leadNonTightPtGamma, 3);
                fillLeadXJPurityLeakage(haveLeadNonIsoNonTight, leadNonIsoNonTightRc, leadNonIsoNonTightPtGamma, 4);
            }

            // -------------------- SIM: define the event-leading truth signal photon (for N_gamma unfolding) --------------------
            bool haveTruthSigPho = false;
            int truthSigTrackId = -1;
            double tPtSig = 0.0, tEtaSig = 0.0, tPhiSig = 0.0, tIsoEtSig = 0.0;
            const TruthSignalPhotonMap truthSignalByTrackId =
                m_isSim ? buildPPG12TruthSignalPhotonMap(topNode) : TruthSignalPhotonMap{};
            std::vector<TruthSignalPhotonInfo> truthSigPhoPPG12Objs;

            if (m_isSim)
            {
                for (const auto& truthEntry : truthSignalByTrackId)
                {
                    const auto& info = truthEntry.second;
                    truthSigPhoPPG12Objs.push_back(info);
                    if (!haveTruthSigPho || info.pt > tPtSig)
                    {
                        haveTruthSigPho = true;
                        truthSigTrackId = truthEntry.first;
                        tPtSig = info.pt;
                        tEtaSig = info.eta;
                        tPhiSig = info.phi;
                        tIsoEtSig = info.isoEtR03;
                    }
                }

                // Fill truth photon spectrum once per event (SIM) for the baseline selected-anchor family.
                if (haveTruthSigPho)
                {
                    fillPPG12Fig37LeadTagInput1D(activeTrig,
                                                  "h_ppg12_fig37_input_leadtag_truth_pT_0",
                                                  m_unfoldTruthPhotonPtBins,
                                                  "p_{T}^{#gamma,truth} [GeV]",
                                                  "Truth photons",
                                                  tPtSig);
                    if (!haveLeadIsoTight)
                    {
                        fillPPG12Fig37LeadTagInput1D(activeTrig,
                                                      "h_ppg12_fig37_input_leadtag_miss_pT_0",
                                                      m_unfoldTruthPhotonPtBins,
                                                      "p_{T}^{#gamma,truth} [GeV]",
                                                      "Truth misses",
                                                      tPtSig);
                    }

	                    for (const auto& trigShort : activeTrig)
	                    {
	                        if (doCanonical)
	                        {
	                            if (auto* hT = getOrBookUnfoldTruthPhoPtGamma(trigShort, effCentIdx_M))
	                            { hT->Fill(tPtSig); bumpHistFill(trigShort, hT->GetName()); }
	                        }

                        // If no reco leading iso∧tight photon exists, this truth photon is a MISS for N_gamma
                        if (!haveLeadIsoTight)
                        {
                            if (auto* hTM = getOrBookUnfoldTruthPhoMissesPtGamma(trigShort, effCentIdx_M))
                            { hTM->Fill(tPtSig); bumpHistFill(trigShort, hTM->GetName()); }
                        }
                    }
                }

                // Fill the exploratory PPG12-style truth photon spectrum per truth signal photon object.
                for (const auto& truthPhoPPG12 : truthSigPhoPPG12Objs)
                {

                    const double tPtPPG12 = truthPhoPPG12.pt;
                    if (!std::isfinite(tPtPPG12) || tPtPPG12 <= 0.0) continue;

	                    for (const auto& trigShort : activeTrig)
	                    {
                            if (m_ppg12PhotonYieldEnabled)
                            {
                                auto fillYieldTruth = [&](const std::string& name)
                                {
                                    if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name,
                                                                              m_ppg12PhotonYieldTruthPtBins,
                                                                              "p_{T}^{#gamma,truth} [GeV]",
                                                                              "Entries"))
                                    {
                                        h->Fill(tPtPPG12);
                                        bumpHistFill(trigShort, name);
                                    }
                                };
                                fillYieldTruth("h_truth_pT_0");
                                fillYieldTruth("h_truth_pT_novtx_0");
                                fillYieldTruth("h_truth_pT_vertexcut_0");
                                fillYieldTruth("h_truth_pT_vertexcut_mbd_cut_0");
                                fillYieldTruth("h_truth_pT_vertexcut_mbd_north_cut_0");
                                fillYieldTruth("h_truth_pT_vertexcut_mbd_south_cut_0");
                                if (m_replayFoundationEnabled)
                                {
                                    ReplayPPG12DiagnosticOccurrence row;
                                    row.trigger = trigShort;
                                    row.occurrence_kind = "PP_TRUTH_SPECTRUM_FILL";
                                    row.generator_barcode = truthPhoPPG12.barcode;
                                    row.truth_photon_pt = tPtPPG12;
                                    row.occurrence_weight = m_mcEventWeight;
                                    m_replayPPG12DiagnosticOccurrences.push_back(row);
                                }
                            }

	                        if (doCanonical)
	                        {
	                            if (auto* hTAlt = getOrBookUnfoldTruthPhoPtGammaPPG12Obj(trigShort, effCentIdx_M))
	                            { hTAlt->Fill(tPtPPG12); bumpHistFill(trigShort, hTAlt->GetName()); }
	                        }

                        if (!haveLeadIsoTight)
                        {
                            if (auto* hTMAlt = getOrBookUnfoldTruthPhoMissesPtGammaPPG12Obj(trigShort, effCentIdx_M))
                            { hTMAlt->Fill(tPtPPG12); bumpHistFill(trigShort, hTMAlt->GetName()); }
                        }
                    }
                }
            }

            if (haveLeadIsoTight)
            {
                // ΔR helper (used for SIM truth matching)
                auto dR = [](double eta1, double phi1, double eta2, double phi2) -> double
                {
                    const double dphi = TVector2::Phi_mpi_pi(phi1 - phi2);
                    const double deta = eta1 - eta2;
                    return std::sqrt(deta*deta + dphi*dphi);
                };

                // -------------------- SIM truth↔reco photon association --------------------
                //   haveTruthPho:
                //     selected leading reco iso∧tight photon has PPG12 cluster_truthtrkID
                //     mapped to the event-leading truth signal photon.
                //
                //   haveTruthPhoPPG12:
                //     PPG12-style photon-only unfolding association:
                //     event-leading truth signal photon matched to a reco cluster that passes
                //     the final iso+tight reco photon selection, independent of event-leading competition.
                bool   haveTruthPho = false;
                bool   haveTruthPhoPPG12 = false;
                double recoPtTruthMatchPPG12 = 0.0;

                double tPt  = (haveTruthSigPho ? tPtSig  : 0.0);
                double tEta = (haveTruthSigPho ? tEtaSig : 0.0);
                double tPhi = (haveTruthSigPho ? tPhiSig : 0.0);

                PHG4TruthInfoContainer* truth = nullptr;

                if (m_isSim)
                {
                    truth = findNode::getClass<PHG4TruthInfoContainer>(topNode, "G4TruthInfo");
                    if (!truth)
                    {
                        LOG(4, CLR_YELLOW, "      [truthQA] G4TruthInfo missing → skip truth matching QA (all radii)");
                    }
                    else if (!haveTruthSigPho || truthSigTrackId < 0)
                    {
                        LOG(4, CLR_YELLOW,
                            "      [truthQA] no nominal G4 truth signal photon → skip truth photon association to reco photons");
                    }
                    else if (!leadRc)
                    {
                        LOG(4, CLR_YELLOW,
                            "      [truthQA] leadRc is nullptr (unexpected) → skip truth photon matching");
                    }
                    else
                    {
                        // CaloRawClusterEval enforces the "BEST-MATCHED truth primary particle" condition
                        CaloRawClusterEval clustereval(topNode, "CEMC");
                        clustereval.set_usetowerinfo(true);
                        clustereval.next_event(topNode);

                        // Fallback if CLUSTERINFO_* is not available in the DST
                        if (!clustereval.has_reduced_node_pointers())
                        {
                            clustereval.set_usetowerinfo(false);
                            clustereval.next_event(topNode);
                        }

                        if (!clustereval.has_reduced_node_pointers())
                        {
                            LOG(4, CLR_YELLOW,
                                "      [truthQA] CaloRawClusterEval missing required nodes (clusters/towers/truth) → skip truth↔reco photon association");
                        }
                        else
                        {
                            const RawCluster* recoMatch = nullptr;
                            double rPt = 0.0, rEta = 0.0, rPhi = 0.0, drBest = 1e9;
                            float  eBest = -1.0f;

                            if (findRecoPhotonMatchedToTruthSignal(truthSignalByTrackId, truthSigTrackId, clustereval,
                                                                   recoMatch, rPt, rEta, rPhi, drBest, eBest))
                            {
                                const auto* recoPhoPPG12 = dynamic_cast<const PhotonClusterv1*>(recoMatch);
                                if (recoPhoPPG12)
                                {
                                    const SSVars vMatch = makeSSFromPhoton(recoPhoPPG12, rPt);
                                    const TightTag recoMatchTag = classifyPhotonTightness(vMatch);
                                    const bool recoMatchIso = isIsolated(recoMatch, rPt, topNode);

                                    if (recoMatchTag == TightTag::kTight && recoMatchIso)
                                    {
                                        haveTruthPhoPPG12 = true;
                                        recoPtTruthMatchPPG12 = rPt;

                                        if (Verbosity() >= 5)
                                        {
                                            LOG(5, CLR_GREEN,
                                                "      [truthQA] PPG12 photon match found:"
                                                << " barcode=" << truthSignalByTrackId.at(truthSigTrackId).barcode
                                                << " pT^truth=" << std::fixed << std::setprecision(2) << tPtSig
                                                << " pT^reco(match)=" << std::fixed << std::setprecision(2) << recoPtTruthMatchPPG12
                                                << " eta^reco(match)=" << std::fixed << std::setprecision(3) << rEta
                                                << " phi^reco(match)=" << std::fixed << std::setprecision(3) << rPhi
                                                << " ETiso^truth=" << std::fixed << std::setprecision(3) << tIsoEtSig
                                                << " ΔR(match)=" << std::fixed << std::setprecision(4) << drBest
                                                << " Edep(best)=" << eBest);
                                        }
                                    }
                                }

                            }

                            TruthSignalPhotonInfo leadMatchedTruth;
                            int leadTruthTrackId = -1;
                            float leadEContrib = std::numeric_limits<float>::lowest();
                            if (classifyRecoPhotonWithPPG12TruthTrack(leadRc, clustereval, truthSignalByTrackId,
                                                                       leadMatchedTruth, leadTruthTrackId, leadEContrib) &&
                                leadTruthTrackId == truthSigTrackId)
                            {
                                haveTruthPho = true;
                                tPt  = leadMatchedTruth.pt;
                                tEta = leadMatchedTruth.eta;
                                tPhi = leadMatchedTruth.phi;

                                if (Verbosity() >= 5)
                                {
                                    const double drPho = dR(leadEtaGamma, leadPhiGamma, tEta, tPhi);
                                    LOG(5, CLR_GREEN,
                                        "      [truthQA] lead reco photon has PPG12 cluster_truthtrkID matched to the event-leading truth signal photon:"
                                        << " barcode=" << leadMatchedTruth.barcode
                                        << " truthTrackID=" << leadTruthTrackId
                                        << " pT^truth=" << std::fixed << std::setprecision(2) << tPt
                                        << " eta^truth=" << std::fixed << std::setprecision(3) << tEta
                                        << " phi^truth=" << std::fixed << std::setprecision(3) << tPhi
                                        << " ETiso^truth=" << std::fixed << std::setprecision(3) << leadMatchedTruth.isoEt
                                        << " ΔR(diagnostic)=" << std::fixed << std::setprecision(4) << drPho
                                        << " Edep(best)=" << leadEContrib);
                                }
                            }

                            if (!haveTruthPho && Verbosity() >= 5)
                            {
                                LOG(5, CLR_YELLOW,
                                    "      [truthQA] event-leading truth signal photon does NOT match the event-leading reco iso∧tight photon");
                            }

                            if (haveTruthPhoPPG12 && !haveTruthPho && Verbosity() >= 5)
                            {
                                LOG(5, CLR_CYAN,
                                    "      [truthQA] PPG12 photon match passes iso+tight, but is not the selected event-leading reco iso∧tight photon");
                            }

                            for (const auto& truthPhoPPG12 : truthSigPhoPPG12Objs)
                            {

                                const double tPtPPG12 = truthPhoPPG12.pt;
                                if (!std::isfinite(tPtPPG12) || tPtPPG12 <= 0.0) continue;

                                const RawCluster* recoMatchAlt = nullptr;
                                double rPtAlt = 0.0, rEtaAlt = 0.0, rPhiAlt = 0.0, drBestAlt = 1e9;
                                float  eBestAlt = -1.0f;

                                bool haveTruthPhoPPG12Obj = false;

                                if (findRecoPhotonMatchedToTruthSignal(truthSignalByTrackId, truthPhoPPG12.trackId, clustereval,
                                                                       recoMatchAlt, rPtAlt, rEtaAlt, rPhiAlt, drBestAlt, eBestAlt))
                                {
                                    const auto* recoPhoPPG12Obj = dynamic_cast<const PhotonClusterv1*>(recoMatchAlt);
                                    if (recoPhoPPG12Obj)
                                    {
                                        const SSVars vMatchAlt = makeSSFromPhoton(recoPhoPPG12Obj, rPtAlt);
                                        const TightTag recoMatchTagAlt = classifyPhotonTightness(vMatchAlt);
                                        const bool recoMatchIsoAlt = isIsolated(recoMatchAlt, rPtAlt, topNode);

                                        if (recoMatchTagAlt == TightTag::kTight && recoMatchIsoAlt)
                                        {
                                            haveTruthPhoPPG12Obj = true;
                                            recoMatchedTruthPhoClustersPPG12.push_back(recoMatchAlt);
                                        }
                                    }
                                }

                                for (const auto& trigShort : activeTrig)
                                {
                                    if (haveTruthPhoPPG12Obj)
                                    {
                                        if (auto* hRAlt = getOrBookUnfoldRecoPhoPtGammaPPG12Obj(trigShort, effCentIdx_M))
                                        { hRAlt->Fill(rPtAlt); bumpHistFill(trigShort, hRAlt->GetName()); }

                                        if (auto* hRespAlt = getOrBookUnfoldResponsePhoPtGammaPPG12Obj(trigShort, effCentIdx_M))
                                        { hRespAlt->Fill(tPtPPG12, rPtAlt); bumpHistFill(trigShort, hRespAlt->GetName()); }
                                    }
                                    else
                                    {
                                        if (auto* hTMAlt = getOrBookUnfoldTruthPhoMissesPtGammaPPG12Obj(trigShort, effCentIdx_M))
                                        { hTMAlt->Fill(tPtPPG12); bumpHistFill(trigShort, hTMAlt->GetName()); }
                                    }
                                }
                            }
                        }
                    }
                }

                if (m_isSim)
                {
                    for (const auto& trigShort : activeTrig)
                    {
                        if (auto* hRFAlt = getOrBookUnfoldRecoPhoFakesPtGammaPPG12Obj(trigShort, effCentIdx_M))
                        {
                            for (size_t iPPG12 = 0; iPPG12 < recoIsoTightPhoPtsPPG12.size(); ++iPPG12)
                            {
                                if (std::find(recoMatchedTruthPhoClustersPPG12.begin(),
                                              recoMatchedTruthPhoClustersPPG12.end(),
                                              recoIsoTightPhoClustersPPG12[iPPG12]) != recoMatchedTruthPhoClustersPPG12.end()) continue;
                                hRFAlt->Fill(recoIsoTightPhoPtsPPG12[iPPG12]);
                                bumpHistFill(trigShort, hRFAlt->GetName());
                            }
                        }
                    }
                }

                const bool filledAnyRadius =
                runLeadIsoTightPhotonJetMatchingAndUnfolding(activeTrig,
                                                             effCentIdx_M,
                                                             centIdx,
                                                             leadPhoIndex,
                                                             leadPtIdx,
                                                             leadPtGamma,
                                                             leadEtaGamma,
                                                             leadPhiGamma,
                                                             haveTruthSigPho,
                                                             tPtSig,
                                                             haveTruthPhoPPG12,
                                                             recoPtTruthMatchPPG12,
                                                             haveTruthPho,
                                                             tPt,
                                                             tEta,
                                                             tPhi,
                                                             truth);

                if (filledAnyRadius) ++nUsed;

            }
            else
            {
                if (Verbosity() >= 5)
                    LOG(5, CLR_BLUE, "      [processCandidates] no iso∧tight photon in this event → no jet matching / JES fills");

                if (m_isSim && haveTruthSigPho)
                {
                    const std::vector<const Jet*> noRecoJetsFid;
                    const std::vector<char>       noRecoJetsFidIsRecoil;

                    for (const auto& kv : m_jets)
                    {
                        const std::string baseRKey = kv.first;
                        const double savedMinJetPt = m_minJetPt;
                        const double savedMinBackToBack = m_minBackToBack;
                        for (const double jetPtCut : activeJetPtCuts())
                        {
                            m_minJetPt = jetPtCut;
                        for (const double dphiCut : activeBackToBackCuts())
                        {
                            m_minBackToBack = dphiCut;
                            const std::string histRKey = histRKeyForJetPtAndDphi(baseRKey, jetPtCut, dphiCut);
                            fillUnfoldResponseMatrixAndTruthDistributions(activeTrig,
                                                                          histRKey,
                                                                          effCentIdx_M,
                                                                          0.0,
                                                                          0.0,
                                                                          0.0,
                                                                          false,
                                                                          tPtSig,
                                                                          tEtaSig,
                                                                          tPhiSig,
                                                                          noRecoJetsFid,
                                                                          noRecoJetsFidIsRecoil,
                                                                          nullptr);
                        }
                        }
                        m_minBackToBack = savedMinBackToBack;
                        m_minJetPt = savedMinJetPt;
                    }
                }
            }

            if (haveLeadIsoNonTight)
            {
                runLeadIsoNonTightPhotonJetLoopAllRadii_SidebandC(activeTrig,
                                                                  effCentIdx_M,
                                                                  leadNonTightPtGamma,
                                                                  leadNonTightEtaGamma,
                                                                  leadNonTightPhiGamma);
            }
            else
            {
                if (Verbosity() >= 6)
                    LOG(6, CLR_BLUE, "      [processCandidates] no iso∧nonTight photon in this event → no sideband-C recoil fill");
            }

            // ------------------------------------------------------------------
            //  jet-by-jet cutflow status vs pT^gamma (NOT event-level).
            // Uses the event-leading reco photon candidate in pT^gamma WITHOUT requiring iso/tight.
            //
            // Fills: h_jetcutflow_status_vs_pTgamma_<rKey><centSuffix>
            // Y bins:
            //   1 = FailJetPt
            //   2 = FailJetEta
            //   3 = FailBackToBack
            //   4 = PassAll
            // ------------------------------------------------------------------
            if (doCanonical && haveLeadAnyPho && leadAnyPtIdx >= 0)
            {

                for (const auto& kvJ : m_jets)
                {
                    const std::string& baseRKey = kvJ.first;

                    JetContainer* jets = kvJ.second;
                    if (!jets) continue;

                    const double jetEtaAbsMaxUse = jetEtaAbsMaxForRKey(baseRKey);
                    const double savedMinJetPt = m_minJetPt;
                    const double savedMinBackToBack = m_minBackToBack;
                    for (const double jetPtCut : activeJetPtCuts())
                    {
                    m_minJetPt = jetPtCut;
                    for (const double dphiCut : activeBackToBackCuts())
                    {
                    m_minBackToBack = dphiCut;
                    const std::string rKey = recoilRKeyForScope(baseRKey, jetPtCut, dphiCut, HistViewScope::Canonical);

                    for (const Jet* j : *jets)
                    {
                        if (!j) continue;

                        const double jpt  = j->get_pt();
                        const double jeta = j->get_eta();
                        const double jphi = j->get_phi();

                        if (!std::isfinite(jpt) || !std::isfinite(jeta) || !std::isfinite(jphi)) continue;

                        int jStatus = 0;
                        if (jpt < m_minJetPt) jStatus = 1;
                        else if (std::fabs(jeta) >= jetEtaAbsMaxUse) jStatus = 2;
                        else
                        {
                            const double dphiAbs = std::fabs(TVector2::Phi_mpi_pi(jphi - leadAnyPhiGamma));
                            jStatus = (dphiAbs >= m_minBackToBack) ? 4 : 3;
                        }

                        for (const auto& trigShort : activeTrig)
                        {
                            if (auto* hj = getOrBookJetCutflowStatusVsPtGamma(trigShort, rKey, effCentIdx_M))
                            { hj->Fill(leadAnyPtGamma, jStatus); bumpHistFill(trigShort, hj->GetName()); }
                        }
                    }
                    }
                    }
                    m_minBackToBack = savedMinBackToBack;
                    m_minJetPt = savedMinJetPt;
                }
            }

            // Summary for photon path
            if (Verbosity() >= 4)
                LOG(4, CLR_BLUE, "    [processCandidates] photon summary: used=" << nUsed
                    << "  skipEta=" << nSkipEta
                    << "  skipEtBin=" << nSkipEtBin
                    << "  skipPhi=" << nSkipPhi
                    << "  noRC=" << nNoRC
                    << "  notIso=" << nNotIso
                    << "  notTight=" << nNotTight);
        }
        catch (const std::exception& e)
        {
            LOG(0, CLR_YELLOW, "    [processCandidates] EXCEPTION in photon path: " << e.what());
        }
        catch (...)
        {
            LOG(0, CLR_YELLOW, "    [processCandidates] UNKNOWN exception in photon path");
        }

        return; // keep original behavior: prefer photon path and return
    } // end photon path
    // Require PhotonClusterBuilder products for ALL photon kinematics.
    LOG(0, CLR_YELLOW,
        "  [processCandidates] PHOTONCLUSTER_CEMC is MISSING for this event. ");

    return;
}

void RecoilJets::fillPi0MassVsPtHistograms(const std::string& trig,
                                             RawClusterContainer* clusterContainer,
                                             bool useCorr)
{
    if (!m_doPi0Analysis || !clusterContainer) return;

    auto itTrig = qaHistogramsByTrigger.find(trig);
    if (itTrig == qaHistogramsByTrigger.end()) return;

    auto& H = itTrig->second;

    const std::string hMassPi0PtName = useCorr ? "h2_pi0_mass_vs_pi0pt_corr" : "h2_pi0_mass_vs_pi0pt_nocorr";
    const std::string hMassLeadPtName = useCorr ? "h2_pi0_mass_vs_leadcluspt_corr" : "h2_pi0_mass_vs_leadcluspt_nocorr";

    auto itMassPi0Pt = H.find(hMassPi0PtName);
    auto itMassLeadPt = H.find(hMassLeadPtName);
    if (itMassPi0Pt == H.end() || itMassLeadPt == H.end()) return;

    TH2F* hMassPi0Pt = dynamic_cast<TH2F*>(itMassPi0Pt->second);
    TH2F* hMassLeadPt = dynamic_cast<TH2F*>(itMassLeadPt->second);
    if (!hMassPi0Pt || !hMassLeadPt) return;

    CLHEP::Hep3Vector vertex(0, 0, m_vz);
    RawClusterContainer::ConstRange cRange = clusterContainer->getClusters();

    for (auto cIt1 = cRange.first; cIt1 != cRange.second; ++cIt1)
    {
      const RawCluster* clus1 = cIt1->second;
      if (!clus1) continue;

      const CLHEP::Hep3Vector eVec1 = RawClusterUtility::GetEVec(*clus1, vertex);
      const double e1 = eVec1.mag();
      if (!std::isfinite(e1) || e1 <= 0.0) continue;
      if (e1 < 1.0) continue;

      const double chi1 = clus1->get_chi2();
      if (!std::isfinite(chi1) || chi1 > 4.0) continue;

      TLorentzVector photon1;
      photon1.SetPxPyPzE(eVec1.x(), eVec1.y(), eVec1.z(), e1);

      if (!std::isfinite(photon1.Pt()) || photon1.Pt() <= 0.0) continue;

      auto cIt2 = cIt1;
      ++cIt2;
      for (; cIt2 != cRange.second; ++cIt2)
      {
        const RawCluster* clus2 = cIt2->second;
        if (!clus2) continue;

        const CLHEP::Hep3Vector eVec2 = RawClusterUtility::GetEVec(*clus2, vertex);
        const double e2 = eVec2.mag();
        if (!std::isfinite(e2) || e2 <= 0.0) continue;
        if (e2 < 1.0) continue;

        const double chi2 = clus2->get_chi2();
        if (!std::isfinite(chi2) || chi2 > 4.0) continue;

        TLorentzVector photon2;
        photon2.SetPxPyPzE(eVec2.x(), eVec2.y(), eVec2.z(), e2);

        const double pt2 = photon2.Pt();
        if (!std::isfinite(pt2) || pt2 < 0.9 || pt2 > 100.0) continue;

        const double alpha = std::fabs(e1 - e2) / (e1 + e2);
        if (!std::isfinite(alpha) || alpha > 0.6) continue;

        const TLorentzVector pi0 = photon1 + photon2;
        const double mass = pi0.M();
        const double pi0pt = pi0.Pt();
        const double leadClusPt = std::max(photon1.Pt(), photon2.Pt());

        if (!std::isfinite(mass) || !std::isfinite(pi0pt) || !std::isfinite(leadClusPt)) continue;

        hMassPi0Pt->Fill(mass, pi0pt);
        bumpHistFill(trig, hMassPi0PtName);

        hMassLeadPt->Fill(mass, leadClusPt);
        bumpHistFill(trig, hMassLeadPtName);
      }
   }
}



const PhotonClusterv1* RecoilJets::findMatchedPhotonByKinematics(const RawClusterContainer* container,
                                                                 const PhotonClusterv1* ref) const
{
  if (!container || !ref) return nullptr;

  const double ref_eta = ref->get_shower_shape_parameter("cluster_eta");
  const double ref_phi = ref->get_shower_shape_parameter("cluster_phi");
  const double ref_pt  = ref->get_shower_shape_parameter("cluster_pt");

  if (!std::isfinite(ref_eta) || !std::isfinite(ref_phi) || !std::isfinite(ref_pt))
    return nullptr;

  constexpr double eps_eta = 1e-5;
  constexpr double eps_phi = 1e-5;
  constexpr double eps_pt  = 1e-4;

  const auto range = container->getClusters();
  for (auto it = range.first; it != range.second; ++it)
  {
    const auto* pho = dynamic_cast<const PhotonClusterv1*>(it->second);
    if (!pho) continue;

    const double eta = pho->get_shower_shape_parameter("cluster_eta");
    const double phi = pho->get_shower_shape_parameter("cluster_phi");
    const double pt  = pho->get_shower_shape_parameter("cluster_pt");

    if (!std::isfinite(eta) || !std::isfinite(phi) || !std::isfinite(pt))
      continue;

    if (std::fabs(eta - ref_eta) < eps_eta &&
        std::fabs(TVector2::Phi_mpi_pi(phi - ref_phi)) < eps_phi &&
        std::fabs(pt - ref_pt) < eps_pt)
    {
      return pho;
    }
  }

  return nullptr;
}

void RecoilJets::attachVariantScoresToSSVars(const PhotonClusterv1* pho, SSVars& v) const
{
  v.npb_score = std::numeric_limits<double>::quiet_NaN();
  v.tight_bdt_score = std::numeric_limits<double>::quiet_NaN();

  if (!pho) return;

  // PPG12 pp SIM parity diagnostics need these score nodes even when the
  // active local output selection is not the newPPG12 variant.
  const bool wantsPPG12PPSimYieldScores =
    m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu;

  const bool wantsNPBScore =
    preselectionUsesNPB(m_preselectionVariant) ||
    (m_ppPhotonIDTrainingTreeEnabled && !m_isAuAu) ||
    m_ppg12TableQAEnabled ||
    wantsPPG12PPSimYieldScores;
  if (wantsNPBScore)
  {
    if (m_photons_npb == m_photons)
    {
      v.npb_score = pho->get_shower_shape_parameter("npb_score");
    }
    else
    {
      const PhotonClusterv1* match = findMatchedPhotonByKinematics(m_photons_npb, pho);
      if (match)
        v.npb_score = match->get_shower_shape_parameter("bdt_score");
    }
  }

  if (m_tightVariant == "newPPG12" ||
      m_ppg12TableQAEnabled ||
      wantsPPG12PPSimYieldScores)
  {
    if (m_photons_tightbdt == m_photons)
    {
      v.tight_bdt_score = pho->get_shower_shape_parameter("tight_bdt_score");
    }
    else
    {
      const PhotonClusterv1* match = findMatchedPhotonByKinematics(m_photons_tightbdt, pho);
      if (match)
        v.tight_bdt_score = match->get_shower_shape_parameter("bdt_score");
    }
  }
}

bool RecoilJets::passesPhotonPreselection(const SSVars& v)
{
  if (preselectionIsNoPreCriteria(m_preselectionVariant))
  {
    if (Verbosity() >= 5)
      LOG(5, CLR_BLUE, "  [passesPhotonPreselection] preselection=noPreCriteria(no preselection cuts) → PASS");
    return true;
  }

  if (preselectionIsOnlyNPB(m_preselectionVariant))
  {
    const bool pass_npb = std::isfinite(v.npb_score) && (v.npb_score > m_npbCut);
    if (Verbosity() >= 5)
    {
      LOG(5, CLR_BLUE,
          "  [passesPhotonPreselection] preselection=onlyNPB(NPB only)"
          << " | npb_score=" << v.npb_score
          << " cut:>" << m_npbCut << " -> " << pass_npb);
    }
    return pass_npb;
  }

  if (preselectionIsNewPPG12(m_preselectionVariant))
  {
    const bool ok_vals =
      std::isfinite(v.npb_score) &&
      std::isfinite(v.et1) &&
      std::isfinite(v.e11_over_e33) &&
      std::isfinite(v.e32_over_e35);

    if (!ok_vals)
    {
      LOG(2, CLR_YELLOW,
          "  [passesPhotonPreselection] invalid newPPG12 preselection inputs: "
          << "npb_score=" << v.npb_score
          << " et1=" << v.et1
          << " e11/e33=" << v.e11_over_e33
          << " e32/e35=" << v.e32_over_e35);
      return false;
    }

    const bool pass_npb = (v.npb_score > m_npbCut);
    const bool pass_et1    = in_open_interval(v.et1, kPPG12PreEt1Min, kPPG12PreEt1Max);
    const bool pass_e11e33 = (v.e11_over_e33 < kPPG12PreE11E33Max);
    const bool pass_e32e35 = in_open_interval(v.e32_over_e35, kPPG12PreE32E35Min, kPPG12PreE32E35Max);
    const bool pass_all = pass_npb && pass_et1 && pass_e11e33 && pass_e32e35;

    if (Verbosity() >= 5)
    {
      LOG(5, CLR_BLUE,
          "  [passesPhotonPreselection] preselection=newPPG12(PPG12 common + NPB, no weta cut)"
          << " | npb_score=" << v.npb_score
          << " cut:>" << m_npbCut << " → " << pass_npb
          << " | et1=" << v.et1
          << " cut:(" << kPPG12PreEt1Min << "," << kPPG12PreEt1Max << ") → " << pass_et1
          << " | e11/e33=" << v.e11_over_e33
          << " cut:<" << kPPG12PreE11E33Max << " → " << pass_e11e33
          << " | e32/e35=" << v.e32_over_e35
          << " cut:(" << kPPG12PreE32E35Min << "," << kPPG12PreE32E35Max << ") → " << pass_e32e35
          << " | all → " << pass_all);
    }

    if (Verbosity() >= 4)
    {
      if (!pass_all)
      {
        LOG(4, CLR_YELLOW,
            "  [passesPhotonPreselection] FAILED newPPG12(PPG12 common + NPB, no weta cut): "
            << "npb=" << v.npb_score
            << ", et1=" << v.et1
            << ", e11/e33=" << v.e11_over_e33
            << ", e32/e35=" << v.e32_over_e35);
      }
      else
      {
        LOG(4, CLR_RED,
            "  [passesPhotonPreselection] PASS newPPG12(PPG12 common + NPB, no weta cut): "
            << "npb=" << v.npb_score
            << ", et1=" << v.et1
            << ", e11/e33=" << v.e11_over_e33
            << ", e32/e35=" << v.e32_over_e35);
      }
    }

    return pass_all;
  }

  if (preselectionIsRefPlusNPB(m_preselectionVariant))
  {
    const bool ok_vals =
      std::isfinite(v.npb_score) &&
      std::isfinite(v.weta_cogx) &&
      std::isfinite(v.wphi_cogx) &&
      std::isfinite(v.et1) &&
      std::isfinite(v.e11_over_e33) &&
      std::isfinite(v.e32_over_e35) &&
      std::isfinite(v.pt_gamma);

    if (!ok_vals)
    {
      LOG(2, CLR_YELLOW,
          "  [passesPhotonPreselection] refPlusNPB non-finite SSVars/NPB detected: "
          << "npb_score=" << v.npb_score
          << " weta=" << v.weta_cogx << " wphi=" << v.wphi_cogx
          << " et1=" << v.et1
          << " e11/e33=" << v.e11_over_e33
          << " e32/e35=" << v.e32_over_e35
          << " pT^gamma=" << v.pt_gamma);
      return false;
    }

    const bool pass_npb    = (v.npb_score > m_npbCut);
    const bool pass_e11e33 = (v.e11_over_e33 < m_phoid_pre_e11e33_max);
    const bool pass_et1    = in_open_interval(v.et1, m_phoid_pre_et1_min, m_phoid_pre_et1_max);
    const bool pass_e32e35 = in_open_interval(v.e32_over_e35, m_phoid_pre_e32e35_min, m_phoid_pre_e32e35_max);
    const bool pass_weta   = (v.weta_cogx < m_phoid_pre_weta_max);
    const bool pass_all = pass_npb && pass_e11e33 && pass_et1 && pass_e32e35 && pass_weta;

    if (Verbosity() >= 5)
    {
      LOG(5, CLR_BLUE,
          "  [passesPhotonPreselection] preselection=refPlusNPB(reference + NPB)"
          << " | npb_score=" << v.npb_score << " cut:>" << m_npbCut << " -> " << pass_npb
          << " | weta=" << v.weta_cogx << " (<" << m_phoid_pre_weta_max << ") -> " << pass_weta
          << " | et1=" << v.et1 << " in (" << m_phoid_pre_et1_min << "," << m_phoid_pre_et1_max << ") -> " << pass_et1
          << " | e11/e33=" << v.e11_over_e33 << " (<" << m_phoid_pre_e11e33_max << ") -> " << pass_e11e33
          << " | e32/e35=" << v.e32_over_e35 << " in (" << m_phoid_pre_e32e35_min << "," << m_phoid_pre_e32e35_max << ") -> " << pass_e32e35
          << " | all -> " << pass_all);
    }

    return pass_all;
  }

  // Basic sanity on inputs
  const bool ok_vals =
  std::isfinite(v.weta_cogx) &&
  std::isfinite(v.wphi_cogx) &&
  std::isfinite(v.et1) &&
  std::isfinite(v.e11_over_e33) &&
  std::isfinite(v.e32_over_e35) &&
  std::isfinite(v.pt_gamma);

  if (!ok_vals)
  {
    LOG(2, CLR_YELLOW,
        "  [passesPhotonPreselection] non-finite SSVars detected: "
        << "weta=" << v.weta_cogx << " wphi=" << v.wphi_cogx
        << " et1=" << v.et1 << " e11/e33=" << v.e11_over_e33
        << " e32/e35=" << v.e32_over_e35 << " pT^γ=" << v.pt_gamma);
    return false;
  }

  const bool pass_e11e33 = (v.e11_over_e33 < m_phoid_pre_e11e33_max);
  const bool pass_et1    = in_open_interval(v.et1, m_phoid_pre_et1_min, m_phoid_pre_et1_max);
  const bool pass_e32e35 = in_open_interval(v.e32_over_e35, m_phoid_pre_e32e35_min, m_phoid_pre_e32e35_max);
  const bool pass_weta   = (v.weta_cogx < m_phoid_pre_weta_max);

  if (Verbosity() >= 5)
  {
    LOG(5, CLR_BLUE,
        "  [passesPhotonPreselection] "
        << "weta=" << v.weta_cogx << " (<" << m_phoid_pre_weta_max << ") → " << pass_weta
        << " | et1=" << v.et1 << " ∈ (" << m_phoid_pre_et1_min << "," << m_phoid_pre_et1_max << ") → " << pass_et1
        << " | e11/e33=" << v.e11_over_e33 << " (<" << m_phoid_pre_e11e33_max << ") → " << pass_e11e33
        << " | e32/e35=" << v.e32_over_e35 << " ∈ (" << m_phoid_pre_e32e35_min << "," << m_phoid_pre_e32e35_max << ") → " << pass_e32e35);
  }

  const bool pass_all = pass_e11e33 && pass_et1 && pass_e32e35 && pass_weta;

  if (Verbosity() >= 4)
  {
    if (!pass_all)
    {
      LOG(4, CLR_YELLOW,
          "  [passesPhotonPreselection] FAILED: weta=" << v.weta_cogx
          << ", et1=" << v.et1
          << ", e11/e33=" << v.e11_over_e33
          << ", e32/e35=" << v.e32_over_e35);
    }
    else
    {
      LOG(4, CLR_RED,
          "  [passesPhotonPreselection] PASS: weta=" << v.weta_cogx
          << ", et1=" << v.et1
          << ", e11/e33=" << v.e11_over_e33
          << ", e32/e35=" << v.e32_over_e35);
    }
  }
  return pass_all;
}


double RecoilJets::configuredTightBDTMin(const double et) const
{
  return m_tightBDTMinIntercept + m_tightBDTMinSlope * et;
}

double RecoilJets::configuredNonTightBDTMin(const double et) const
{
  return m_nonTightBDTMinIntercept + m_nonTightBDTMinSlope * et;
}

double RecoilJets::configuredNonTightBDTMax(const double et) const
{
  return m_nonTightBDTMaxIntercept + m_nonTightBDTMaxSlope * et;
}

bool RecoilJets::configuredTightBDTPass(const double score, const double et) const
{
  const double min = configuredTightBDTMin(et);
  return std::isfinite(score) &&
         std::isfinite(min) &&
         std::isfinite(m_tightBDTMax) &&
         (score > min) &&
         (score < m_tightBDTMax);
}

bool RecoilJets::configuredNonTightBDTPass(const double score, const double et) const
{
  const double min = configuredNonTightBDTMin(et);
  const double max = configuredNonTightBDTMax(et);
  return std::isfinite(score) &&
         std::isfinite(min) &&
         std::isfinite(max) &&
         (score > min) &&
         (score < max);
}

RecoilJets::TightTag RecoilJets::configuredVariantABDTTag(const double score, const double et) const
{
  if (configuredTightBDTPass(score, et)) return TightTag::kTight;
  if (m_nonTightVariant == "newPPG12")
  {
    return configuredNonTightBDTPass(score, et) ? TightTag::kNonTight : TightTag::kNeither;
  }
  return TightTag::kNonTight;
}

bool RecoilJets::passesPPG12PhotonYieldCommon(const SSVars& v) const
{
  const double wr =
      (std::isfinite(v.wphi_cogx) && std::isfinite(v.weta_cogx) && v.weta_cogx != 0.0)
      ? (v.wphi_cogx / v.weta_cogx)
      : std::numeric_limits<double>::quiet_NaN();

  return
      in_open_interval(v.cluster_prob, kPPG12YieldCommonProbMin, kPPG12YieldCommonProbMax) &&
      in_open_interval(v.e11_over_e33, kPPG12YieldCommonE11E33Min, kPPG12YieldCommonE11E33Max) &&
      std::isfinite(wr) && (wr > kPPG12YieldCommonWrMin) &&
      std::isfinite(v.weta_cogx) && (v.weta_cogx < kPPG12YieldCommonWetaMax) &&
      std::isfinite(v.npb_score) && (v.npb_score > kPPG12YieldNpbMin);
}

RecoilJets::TightTag RecoilJets::classifyPPG12PhotonYieldTightness(const SSVars& v) const
{
  if (!passesPPG12PhotonYieldCommon(v))
  {
    return TightTag::kPreselectionFail;
  }

  const bool tightProb =
      in_open_interval(v.cluster_prob, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightWeta =
      in_open_interval(v.weta_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightWphi =
      in_open_interval(v.wphi_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightEt1 =
      in_open_interval(v.et1, kPPG12YieldTightEt1Min, kPPG12YieldTightEt1Max);
  const bool tightEt2 =
      in_open_interval(v.et2, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightEt3 =
      in_open_interval(v.et3, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightEt4 =
      in_open_interval(v.et4, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightE11E33 =
      in_open_interval(v.e11_over_e33, kPPG12YieldBroadMin, kPPG12YieldBroadMax);
  const bool tightE32E35 =
      in_open_interval(v.e32_over_e35, kPPG12YieldTightE32E35Min, kPPG12YieldTightE32E35Max);
  const bool tightBDT =
      configuredTightBDTPass(v.tight_bdt_score, v.pt_gamma);

  const bool tight =
      tightProb &&
      tightWeta &&
      tightWphi &&
      tightEt1 &&
      tightEt2 &&
      tightEt3 &&
      tightEt4 &&
      tightE11E33 &&
      tightE32E35 &&
      tightBDT;
  if (tight)
  {
    return TightTag::kTight;
  }

  const bool nonTightShape =
      in_open_interval(v.cluster_prob, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
      in_open_interval(v.weta_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
      in_open_interval(v.wphi_cogx, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
      in_open_interval(v.et1, kPPG12YieldNonTightEt1Min, kPPG12YieldNonTightEt1Max) &&
      in_open_interval(v.et4, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
      in_open_interval(v.e11_over_e33, kPPG12YieldBroadMin, kPPG12YieldBroadMax) &&
      in_open_interval(v.e32_over_e35, kPPG12YieldTightE32E35Min, kPPG12YieldTightE32E35Max);

  int nonTightFailCount = 0;
  if (!tightWeta)   nonTightFailCount += kPPG12YieldNonTightWetaOn;
  if (!tightWphi)   nonTightFailCount += kPPG12YieldNonTightWphiOn;
  if (!tightEt1)    nonTightFailCount += kPPG12YieldNonTightEt1On;
  if (!tightEt2)    nonTightFailCount += kPPG12YieldNonTightEt2On;
  if (!tightEt3)    nonTightFailCount += kPPG12YieldNonTightEt3On;
  if (!tightE11E33) nonTightFailCount += kPPG12YieldNonTightE11E33On;
  if (!tightE32E35) nonTightFailCount += kPPG12YieldNonTightE32E35On;
  if (!tightEt4)    nonTightFailCount += kPPG12YieldNonTightEt4On;
  if (!tightProb)   ++nonTightFailCount;
  if (!tightBDT)    nonTightFailCount += kPPG12YieldNonTightBDTOn;

  if (nonTightShape &&
      configuredNonTightBDTPass(v.tight_bdt_score, v.pt_gamma) &&
      nonTightFailCount > kPPG12YieldNonTightNFail)
  {
    return TightTag::kNonTight;
  }

  return TightTag::kNeither;
}


RecoilJets::TightTag RecoilJets::classifyPhotonTightness(const SSVars& v)
{
  // If preselection fails, short-circuit
  if (!passesPhotonPreselection(v))
  {
    if (Verbosity() >= 5)
      LOG(5, CLR_YELLOW, "  [classifyPhotonTightness] Preselection FAILED – returning kPreselectionFail");
    return TightTag::kPreselectionFail;
  }

  if (m_tightVariant == "newPPG12")
  {
    const double tight_min = configuredTightBDTMin(v.pt_gamma);
    const double non_tight_min = configuredNonTightBDTMin(v.pt_gamma);
    const double non_tight_max = configuredNonTightBDTMax(v.pt_gamma);
    const bool pass_tight_bdt = configuredTightBDTPass(v.tight_bdt_score, v.pt_gamma);
    const bool pass_non_tight_bdt = configuredNonTightBDTPass(v.tight_bdt_score, v.pt_gamma);

    if (Verbosity() >= 5)
    {
      LOG(5, CLR_BLUE,
          "  [classifyPhotonTightness] variant=newPPG12(PPG12 BDT)"
          << " | tight_bdt_score=" << v.tight_bdt_score
          << " | tight=(" << tight_min << ",+inf) → " << pass_tight_bdt
          << " | nonTight=(" << non_tight_min << "," << non_tight_max << ") → " << pass_non_tight_bdt
          << " | nonTightVariant=" << m_nonTightVariant);
    }

    const TightTag tag = configuredVariantABDTTag(v.tight_bdt_score, v.pt_gamma);

    if (Verbosity() >= 4)
    {
      const char* tagName = tightTagName(tag);
      const char* colour  = (tag == TightTag::kTight) ? CLR_RED :
                            (tag == TightTag::kNonTight ? CLR_GREEN : CLR_YELLOW);
      LOG(4, colour, "  [classifyPhotonTightness] newPPG12(PPG12 BDT)"
                      << " → tag=" << tagName);
    }

    return tag;
  }

  // Upper width cut is ET-dependent
  const double w_hi = m_phoid_tight_w_hi_intercept + m_phoid_tight_w_hi_slope * v.pt_gamma;
  if (!std::isfinite(w_hi) || !std::isfinite(v.pt_gamma) || v.pt_gamma <= 0.0)
  {
    LOG(2, CLR_YELLOW, "  [classifyPhotonTightness] non-finite tight_w_hi for pT^γ=" << v.pt_gamma
                        << " – treating as failure");
    return TightTag::kNeither;
  }

  const bool pass_weta   = in_open_interval(v.weta_cogx,  m_phoid_tight_w_lo, w_hi);
  const bool pass_wphi   = in_open_interval(v.wphi_cogx,  m_phoid_tight_w_lo, w_hi);
  const bool pass_e11e33 = in_open_interval(v.e11_over_e33, m_phoid_tight_e11e33_min, m_phoid_tight_e11e33_max);
  const bool pass_et1    = in_open_interval(v.et1,          m_phoid_tight_et1_min,    m_phoid_tight_et1_max);
  const bool pass_e32e35 = in_open_interval(v.e32_over_e35, m_phoid_tight_e32e35_min, m_phoid_tight_e32e35_max);

  if (Verbosity() >= 5)
  {
    LOG(5, CLR_BLUE,
        "  [classifyPhotonTightness] pT^γ=" << v.pt_gamma
        << " → w_hi=" << w_hi
        << " | weta=" << v.weta_cogx << " ok=" << pass_weta
        << " | wphi=" << v.wphi_cogx << " ok=" << pass_wphi
        << " | e11/e33=" << v.e11_over_e33 << " ok=" << pass_e11e33
        << " | et1=" << v.et1 << " ok=" << pass_et1
        << " | e32/e35=" << v.e32_over_e35 << " ok=" << pass_e32e35);
  }

  const int n_fail = (!pass_weta) + (!pass_wphi) + (!pass_e11e33) + (!pass_et1) + (!pass_e32e35);

  TightTag tag;
  if (n_fail == 0)      tag = TightTag::kTight;
  else if (n_fail >= 2) tag = TightTag::kNonTight;
  else                  tag = TightTag::kNeither;

  if (Verbosity() >= 4)
  {
    const char* tagName = tightTagName(tag);
    const char* colour  = (tag == TightTag::kTight) ? CLR_RED : CLR_GREEN;
    LOG(4, colour, "  [classifyPhotonTightness] n_fail=" << n_fail
                    << " → tag=" << tagName);
  }

  return tag;
}


void RecoilJets::setIsolationWP(double aGeV, double bPerGeV,
                                double sideGapGeV, double coneR, double towerMin,
                                double fixedGeV)
{
  // Keep original behavior (min floors), but report anything suspicious
  if (!std::isfinite(aGeV) || !std::isfinite(bPerGeV) ||
      !std::isfinite(sideGapGeV) || !std::isfinite(coneR) || !std::isfinite(towerMin) ||
      !std::isfinite(fixedGeV))
  {
    LOG(2, CLR_YELLOW,
        "  [setIsolationWP] Non-finite input(s): "
        << "A=" << aGeV << " B=" << bPerGeV << " gap=" << sideGapGeV
        << " fixedGeV=" << fixedGeV
        << " coneR=" << coneR << " towerMin=" << towerMin);
  }

  m_isoA      = aGeV;
  m_isoB      = bPerGeV;
  m_isoGap    = sideGapGeV;
  m_isoFixed  = (std::isfinite(fixedGeV) ? fixedGeV : 2.0);
  if (m_isoFixed < 0.0) m_isoFixed = 0.0;

  const double cone_before  = coneR;
  const double tower_before = towerMin;

  // PhotonClusterBuilder provides full calo isolation only for R=0.3 and R=0.4.
  // Allow YAML to select 0.30/0.40 (also accept shorthand .03/.04).
  int cone10 = 3;
  if (std::isfinite(coneR))
  {
      cone10 = static_cast<int>(std::lround(10.0 * coneR));
      if (!(cone10 == 3 || cone10 == 4))
      {
        const int cone100 = static_cast<int>(std::lround(100.0 * coneR));
        if (cone100 == 3 || cone100 == 4)
        {
          cone10 = cone100; // .03/.04 shorthand
        }
      }
    }

    if (!(cone10 == 3 || cone10 == 4))
    {
      if (Verbosity() >= 2)
      {
        LOG(2, CLR_YELLOW,
            "  [setIsolationWP] Requested coneR=" << coneR
            << " not supported (PhotonClusterBuilder supports 0.3 or 0.4). Forcing coneR=0.3.");
      }
      cone10 = 3;
  }

  m_isoConeR  = 0.1 * static_cast<double>(cone10);
  m_isoTowMin = std::max(0.0, towerMin);

  if (Verbosity() >= 4)
  {
    LOG(4, CLR_BLUE,
        "  [setIsolationWP] Isolation WP set:"
        << "  A=" << m_isoA
        << "  B=" << m_isoB
        << "  gap=" << m_isoGap
        << "  fixedGeV=" << m_isoFixed
        << "  coneR=" << m_isoConeR << (cone_before != m_isoConeR ? " (clamped)" : "")
        << "  towerMin=" << m_isoTowMin << (tower_before != m_isoTowMin ? " (clamped)" : ""));
  }
}

void RecoilJets::setPPIsoWPForCone(double coneR, double aGeV, double bPerGeV, double sideGapGeV)
{
  if (!std::isfinite(coneR) || !std::isfinite(aGeV) ||
      !std::isfinite(bPerGeV) || !std::isfinite(sideGapGeV))
  {
    LOG(2, CLR_YELLOW,
        "  [setPPIsoWPForCone] Non-finite input(s): coneR=" << coneR
        << " A=" << aGeV << " B=" << bPerGeV << " gap=" << sideGapGeV
        << " -> ignoring cone-specific pp isolation WP");
    return;
  }

  int cone10 = static_cast<int>(std::lround(10.0 * coneR));
  if (!(cone10 == 3 || cone10 == 4))
  {
    const int cone100 = static_cast<int>(std::lround(100.0 * coneR));
    if (cone100 == 3 || cone100 == 4) cone10 = cone100;
  }

  PPIsoWP* wp = nullptr;
  if (cone10 == 3) wp = &m_ppIsoWPR30;
  else if (cone10 == 4) wp = &m_ppIsoWPR40;

  if (!wp)
  {
    LOG(2, CLR_YELLOW,
        "  [setPPIsoWPForCone] Requested coneR=" << coneR
        << " is not supported for pp cone-specific isolation WP; expected R=0.3 or R=0.4");
    return;
  }

  wp->aGeV = aGeV;
  wp->bPerGeV = bPerGeV;
  wp->sideGapGeV = std::max(0.0, sideGapGeV);
  wp->enabled = true;

  std::cout << CLR_BLUE
            << "  [setPPIsoWPForCone] pp cone-specific isolation WP:"
            << " coneR=0." << cone10
            << " A=" << wp->aGeV
            << " B=" << wp->bPerGeV
            << " gap=" << wp->sideGapGeV
            << " thrReco(pT)=A+B*pT"
            << CLR_RESET << std::endl;
}

bool RecoilJets::getPPIsoParamsForCone(double coneR, double& aGeV, double& bPerGeV, double& sideGapGeV) const
{
  int cone10 = static_cast<int>(std::lround(10.0 * coneR));
  if (!(cone10 == 3 || cone10 == 4))
  {
    const int cone100 = static_cast<int>(std::lround(100.0 * coneR));
    if (cone100 == 3 || cone100 == 4) cone10 = cone100;
  }

  const PPIsoWP* wp = nullptr;
  if (cone10 == 3) wp = &m_ppIsoWPR30;
  else if (cone10 == 4) wp = &m_ppIsoWPR40;

  if (wp && wp->enabled)
  {
    aGeV = wp->aGeV;
    bPerGeV = wp->bPerGeV;
    sideGapGeV = wp->sideGapGeV;
    return true;
  }

  aGeV = m_isoA;
  bPerGeV = m_isoB;
  sideGapGeV = m_isoGap;
  return false;
}

void RecoilJets::getActiveIsoParams(double& aGeV, double& bPerGeV, double& sideGapGeV) const
{
  getPPIsoParamsForCone(m_isoConeR, aGeV, bPerGeV, sideGapGeV);
}

double RecoilJets::recoIsoThreshold(double ptGamma) const
{
  double aGeV = m_isoA;
  double bPerGeV = m_isoB;
  double sideGapGeV = m_isoGap;
  getActiveIsoParams(aGeV, bPerGeV, sideGapGeV);
  return m_isSlidingIso ? (aGeV + bPerGeV * ptGamma) : m_isoFixed;
}

double RecoilJets::recoNonIsoThreshold(double ptGamma) const
{
  double aGeV = m_isoA;
  double bPerGeV = m_isoB;
  double sideGapGeV = m_isoGap;
  getActiveIsoParams(aGeV, bPerGeV, sideGapGeV);
  return recoIsoThreshold(ptGamma) + sideGapGeV;
}


double RecoilJets::eiso(const RawCluster* clus, PHCompositeNode* /*topNode*/) const
{
  if (!clus)
  {
    if (Verbosity() >= 3)
      LOG(3, CLR_YELLOW, "  [eiso] clus==nullptr → return +inf (fail-safe)");
    return 1e9; // fail-safe: not isolated
  }

  // We require PhotonClusterBuilder-provided iso_* parameters stored on PhotonClusterv1.
  const auto* pho = dynamic_cast<const PhotonClusterv1*>(clus);
  if (!pho)
  {
    if (Verbosity() >= 2)
      LOG(2, CLR_YELLOW, "  [eiso] clus is not PhotonClusterv1 → return +inf (fail-safe)");
    return 1e9;
  }

  // PhotonClusterBuilder provides full (EMCal + HCALIN + HCALOUT) isolation for R=0.3 and R=0.4:
  //   iso_03_emcal (already subtracts ET^gamma), iso_03_hcalin, iso_03_hcalout
  //   iso_04_emcal (already subtracts ET^gamma), iso_04_hcalin, iso_04_hcalout
  const int cone10 = static_cast<int>(std::lround(10.0 * m_isoConeR));

  const char* k_em = nullptr;
  const char* k_hi = nullptr;
  const char* k_ho = nullptr;

  if (cone10 == 3)
  {
    k_em = "iso_03_emcal";
    k_hi = "iso_03_hcalin";
    k_ho = "iso_03_hcalout";
  }
  else if (cone10 == 4)
  {
    k_em = "iso_04_emcal";
    k_hi = "iso_04_hcalin";
    k_ho = "iso_04_hcalout";
  }
  else
  {
    if (Verbosity() >= 2)
      LOG(2, CLR_YELLOW,
          "  [eiso] m_isoConeR=" << m_isoConeR << " (cone10=" << cone10
          << ") not supported by PhotonClusterBuilder full calo iso → return +inf (fail-safe)");
    return 1e9;
  }

  const double em = pho->get_shower_shape_parameter(k_em);
  const double hi = pho->get_shower_shape_parameter(k_hi);
  const double ho = pho->get_shower_shape_parameter(k_ho);

  // Total isolation ET (PhotonClusterBuilder convention):
  //   iso_*_emcal already has (-ET^gamma) applied, HCAL terms are raw sums.
  const double iso = em + hi + ho;

  if (!std::isfinite(iso))
  {
    if (Verbosity() >= 2)
      LOG(2, CLR_YELLOW,
          "  [eiso] non-finite PhotonClusterBuilder iso: "
          << k_em << "=" << em << " " << k_hi << "=" << hi << " " << k_ho << "=" << ho
          << " → return +inf (fail-safe)");
    return 1e9;
  }

  if (Verbosity() >= 5)
  {
    LOG(5, CLR_BLUE,
        "  [eiso(builder)] cone10=" << cone10
        << "  " << k_em << "=" << em
        << "  " << k_hi << "=" << hi
        << "  " << k_ho << "=" << ho
        << "  total=" << iso);
  }

  return iso;
}

bool RecoilJets::loadPPG12PhotonYieldTowerMask()
{
  if (!(m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldApplyTowerMask && !m_isAuAu))
  {
    return true;
  }

  if (m_ppg12PhotonYieldTowerMask)
  {
    delete m_ppg12PhotonYieldTowerMask;
    m_ppg12PhotonYieldTowerMask = nullptr;
  }

  if (m_ppg12PhotonYieldTowerMaskFile.empty() || m_ppg12PhotonYieldTowerMaskName.empty())
  {
    LOG(0, CLR_RED,
        "[PPG12_PHOTON_YIELD_V1][tower-mask] empty file/name"
        << " file='" << m_ppg12PhotonYieldTowerMaskFile << "'"
        << " name='" << m_ppg12PhotonYieldTowerMaskName << "'");
    return false;
  }

  TFile* fMask = TFile::Open(m_ppg12PhotonYieldTowerMaskFile.c_str(), "READ");
  if (!fMask || fMask->IsZombie())
  {
    LOG(0, CLR_RED,
        "[PPG12_PHOTON_YIELD_V1][tower-mask] cannot open "
        << m_ppg12PhotonYieldTowerMaskFile);
    delete fMask;
    return false;
  }

  TH2* hMask = dynamic_cast<TH2*>(fMask->Get(m_ppg12PhotonYieldTowerMaskName.c_str()));
  if (!hMask)
  {
    LOG(0, CLR_RED,
        "[PPG12_PHOTON_YIELD_V1][tower-mask] histogram "
        << m_ppg12PhotonYieldTowerMaskName
        << " not found in " << m_ppg12PhotonYieldTowerMaskFile);
    fMask->Close();
    delete fMask;
    return false;
  }

  m_ppg12PhotonYieldTowerMask =
      dynamic_cast<TH2*>(hMask->Clone("ppg12_photon_yield_tower_mask_clone"));
  if (!m_ppg12PhotonYieldTowerMask)
  {
    LOG(0, CLR_RED,
        "[PPG12_PHOTON_YIELD_V1][tower-mask] clone failed for "
        << m_ppg12PhotonYieldTowerMaskName);
    fMask->Close();
    delete fMask;
    return false;
  }

  m_ppg12PhotonYieldTowerMask->SetDirectory(nullptr);
  const double nMasked = m_ppg12PhotonYieldTowerMask->Integral();
  LOG(1, CLR_GREEN,
      "[PPG12_PHOTON_YIELD_V1][tower-mask] loaded "
      << m_ppg12PhotonYieldTowerMaskName
      << " from " << m_ppg12PhotonYieldTowerMaskFile
      << " | masked towers=" << nMasked);

  fMask->Close();
  delete fMask;
  return true;
}

int RecoilJets::currentRunNumber() const
{
  if (m_evtHeader)
  {
    const int runNumber = m_evtHeader->get_RunNumber();
    if (runNumber > 0) return runNumber;
  }

  auto* rc = recoConsts::instance();
  if (!rc) return 0;

  uint64_t runNumber = rc->get_uint64Flag("RUNNUMBER", 0);
  if (runNumber == 0)
  {
    runNumber = rc->get_uint64Flag("TIMESTAMP", 0);
  }
  if (runNumber == 0 ||
      runNumber > static_cast<uint64_t>(std::numeric_limits<int>::max()))
  {
    return 0;
  }
  return static_cast<int>(runNumber);
}

bool RecoilJets::ppg12PeriodRunContains(int runNumber) const
{
  return (m_ppg12PeriodContractEnabled &&
          runNumber >= m_ppg12PeriodRunMin &&
          runNumber < m_ppg12PeriodRunMaxExclusive);
}

bool RecoilJets::configurePPG12SimEventWeight(const double sliceFactor,
                                              const int laneCode)
{
  m_ppg12SimWeightActive = false;
  m_ppg12SimWeightLaneCode = 0;
  m_ppg12SimWeightLaneComponentCode = 0;
  m_ppg12SimWeightFactorSlice = 1.0;
  m_ppg12SimWeightFactorVertex = 1.0;
  m_ppg12SimWeightFactorMix = 1.0;
  m_ppg12SimWeightFactorPeriod = 1.0;
  m_ppg12SimWeightFactorFinal = 1.0;
  m_mcEventWeight = 1.0;

  if (!(m_isSim && !m_isAuAu)) return true;
  if (!(laneCode == 1 || laneCode == 2) || !std::isfinite(sliceFactor) || sliceFactor <= 0.0)
  {
    LOG(0, CLR_RED,
        "[PPG12_SIM_WEIGHT][FATAL] invalid lane or slice factor"
        << " | lane=" << laneCode << " | slice=" << sliceFactor
        << " | outfile=" << Outfile);
    return false;
  }

  if (!m_ppg12PhotonYieldEnabled ||
      !m_ppg12PeriodContractEnabled ||
      !m_ppg12PeriodUseLumiWeight ||
      !m_vertexReweightOn ||
      !m_vertexReweightH)
  {
    LOG(0, CLR_RED,
        "[PPG12_SIM_WEIGHT][FATAL] incomplete canonical PPG12 SIM weighting contract"
        << " | photon_yield=" << m_ppg12PhotonYieldEnabled
        << " | period_contract=" << m_ppg12PeriodContractEnabled
        << " | period_lumi_weight=" << m_ppg12PeriodUseLumiWeight
        << " | vertex_reweight_on=" << m_vertexReweightOn
        << " | vertex_hist_loaded=" << (m_vertexReweightH != nullptr)
        << " | lane=" << laneCode
        << " | outfile=" << Outfile);
    return false;
  }

  const bool haveHardTruthVertex =
      std::isfinite(m_truthVz) && m_truthVz > kPPG12TruthVtxSentinelThreshold;
  const bool haveRequiredMBTruthVertex =
      !m_ppg12PhotonYieldDoubleInteraction ||
      (std::isfinite(m_truthVzMB) && m_truthVzMB > kPPG12TruthVtxSentinelThreshold);
  if (!haveHardTruthVertex || !haveRequiredMBTruthVertex)
  {
    LOG(0, CLR_RED,
        "[PPG12_SIM_WEIGHT][FATAL] missing truth vertex required by canonical SI/DI weight"
        << " | hard_truth_z=" << m_truthVz
        << " | mb_truth_z=" << m_truthVzMB
        << " | component=" << (m_ppg12PhotonYieldDoubleInteraction ? "DI" : "SI")
        << " | outfile=" << Outfile);
    return false;
  }

  const double mixFactor = m_ppg12PhotonYieldMixWeight;
  const double periodFactor = m_ppg12PeriodLumiWeight;
  PPG12SimWeight::Factors factors;
  if (!PPG12SimWeight::Build(sliceFactor,
                             m_mcVertexWeight,
                             mixFactor,
                             periodFactor,
                             factors))
  {
    LOG(0, CLR_RED,
        "[PPG12_SIM_WEIGHT][FATAL] non-finite or negative factor"
        << " | slice=" << sliceFactor
        << " | vertex=" << m_mcVertexWeight
        << " | mix=" << mixFactor
        << " | period=" << periodFactor);
    return false;
  }

  m_ppg12SimWeightActive = true;
  m_ppg12SimWeightLaneCode = laneCode;
  m_ppg12SimWeightLaneComponentCode =
      (laneCode == 1)
          ? (m_ppg12PhotonYieldDoubleInteraction ? 2 : 1)
          : (m_ppg12PhotonYieldDoubleInteraction ? 4 : 3);
  m_ppg12SimWeightFactorSlice = factors.slice;
  m_ppg12SimWeightFactorVertex = factors.vertex;
  m_ppg12SimWeightFactorMix = factors.mix;
  m_ppg12SimWeightFactorPeriod = factors.period;
  m_ppg12SimWeightFactorFinal = factors.final;
  m_mcEventWeight = factors.final;

  // From this point onward, every weighted RecoilJets histogram sees the
  // complete PPG12 event weight. Explicit Fill weights are extra physics
  // factors only; raw diagnostics must bypass the weighted wrapper.
  RJMCWeighting::CurrentLaneComponentCode() = m_ppg12SimWeightLaneComponentCode;
  RJMCWeighting::CurrentWeight() = factors.final;
  fillPPG12SimWeightAudit();
  if (auto* h = getOrBookPPG12EisoVertexContractAuditHist("SIM"))
  {
    h->Fill(7);
    if (m_replayFoundationEnabled)
    {
      ReplayPPG12DiagnosticOccurrence row;
      row.trigger = "SIM";
      row.occurrence_kind = "EISO_VERTEX_AUDIT";
      row.stage_code = 7;
      m_replayPPG12DiagnosticOccurrences.push_back(row);
    }
  }

  LOG(4, CLR_MAGENTA,
      "[PPG12_SIM_WEIGHT] canonical factors"
      << " | lane=" << (laneCode == 1 ? "photonjet" : "inclusivejet")
      << " | component=" << (m_ppg12PhotonYieldDoubleInteraction ? "DI" : "SI")
      << " | period=" << m_ppg12PeriodKey
      << " | slice=" << factors.slice
      << " | vertex=" << factors.vertex
      << " | mix=" << factors.mix
      << " | period_factor=" << factors.period
      << " | final=" << factors.final);
  return true;
}

void RecoilJets::fillPPG12SimWeightAudit()
{
  if (!m_ppg12SimWeightActive || !out || !out->IsOpen()) return;

  constexpr const char* kTrig = "SIM";
  HistMap& H = qaHistogramsByTrigger[kTrig];
  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(kTrig);
  if (!dir) dir = out->mkdir(kTrig);
  if (!dir)
  {
    if (prevDir) prevDir->cd();
    return;
  }
  dir->cd();

  auto book1D = [&](const std::string& name,
                    const std::string& title,
                    const int nbins,
                    const double xmin,
                    const double xmax) -> TH1D*
  {
    if (auto it = H.find(name); it != H.end()) return dynamic_cast<TH1D*>(it->second);
    auto* h = new TH1D(name.c_str(), title.c_str(), nbins, xmin, xmax);
    h->Sumw2();
    h->SetDirectory(dir);
    H[name] = h;
    return h;
  };

  auto book2D = [&](const std::string& name,
                    const std::string& title,
                    const int nx,
                    const double xmin,
                    const double xmax,
                    const int ny,
                    const double ymin,
                    const double ymax) -> TH2D*
  {
    if (auto it = H.find(name); it != H.end()) return dynamic_cast<TH2D*>(it->second);
    auto* h = new TH2D(name.c_str(), title.c_str(), nx, xmin, xmax, ny, ymin, ymax);
    h->Sumw2();
    h->SetDirectory(dir);
    H[name] = h;
    return h;
  };

  const auto logWeight = [](const double value)
  {
    return std::log10(std::max(value, 1.0e-12));
  };

  if (auto* h = book1D("h_ppg12_weight_audit_factor_slice",
                       "PPG12 SIM slice factor;log_{10}(w_{slice});events",
                       240, -4.0, 8.0))
    h->Fill(logWeight(m_ppg12SimWeightFactorSlice));
  if (auto* h = book1D("h_ppg12_weight_audit_factor_vertex",
                       "PPG12 SIM vertex factor;w_{vertex};events",
                       400, 0.0, 10.0))
    h->Fill(m_ppg12SimWeightFactorVertex);
  if (auto* h = book1D("h_ppg12_weight_audit_factor_mix",
                       "PPG12 SIM SI/DI mixture factor;w_{mix};events",
                       240, 0.0, 1.2))
    h->Fill(m_ppg12SimWeightFactorMix);
  if (auto* h = book1D("h_ppg12_weight_audit_factor_period",
                       "PPG12 SIM period exposure factor;w_{period};events",
                       240, 0.0, 1.2))
    h->Fill(m_ppg12SimWeightFactorPeriod);
  if (auto* h = book1D("h_ppg12_weight_audit_factor_final",
                       "PPG12 SIM final fill weight;log_{10}(w_{final});events",
                       400, -12.0, 8.0))
    h->Fill(logWeight(m_ppg12SimWeightFactorFinal));

  if (auto* h = book1D("h_ppg12_weight_audit_component_events",
                       "PPG12 SIM weighted events;lane/component;events",
                       4, 0.5, 4.5))
  {
    h->GetXaxis()->SetBinLabel(1, "photonjet_SI");
    h->GetXaxis()->SetBinLabel(2, "photonjet_DI");
    h->GetXaxis()->SetBinLabel(3, "inclusivejet_SI");
    h->GetXaxis()->SetBinLabel(4, "inclusivejet_DI");
    h->Fill(m_ppg12SimWeightLaneComponentCode);
  }

  if (auto* h2 = book2D("h2_ppg12_weight_audit_final_vs_vertex_z",
                        "PPG12 SIM final weight vs hard vertex;z_{truth} [cm];log_{10}(w_{final})",
                        400, -200.0, 200.0,
                        400, -12.0, 8.0))
  {
    if (std::isfinite(m_truthVz)) h2->Fill(m_truthVz, logWeight(m_ppg12SimWeightFactorFinal));
  }

  if (auto* h2 = book2D("h_ppg12_weight_audit_fill_mode",
                        "PPG12 SIM histogram fill modes;mode;lane/component",
                        2, 0.5, 2.5,
                        4, 0.5, 4.5))
  {
    h2->GetXaxis()->SetBinLabel(1, "full_weight");
    h2->GetXaxis()->SetBinLabel(2, "raw_opt_out");
    h2->GetYaxis()->SetBinLabel(1, "photonjet_SI");
    h2->GetYaxis()->SetBinLabel(2, "photonjet_DI");
    h2->GetYaxis()->SetBinLabel(3, "inclusivejet_SI");
    h2->GetYaxis()->SetBinLabel(4, "inclusivejet_DI");
  }

  if (prevDir) prevDir->cd();
}

void RecoilJets::finalizePPG12SimWeightAudit()
{
  auto trigIt = qaHistogramsByTrigger.find("SIM");
  if (trigIt == qaHistogramsByTrigger.end()) return;
  auto histIt = trigIt->second.find("h_ppg12_weight_audit_fill_mode");
  if (histIt == trigIt->second.end()) return;
  auto* h2 = dynamic_cast<TH2D*>(histIt->second);
  if (!h2) return;

  const auto& full = RJMCWeighting::FullFillCounts();
  const auto& raw = RJMCWeighting::RawFillCounts();
  unsigned long long total = 0;
  for (int code = 1; code <= 4; ++code)
  {
    h2->SetBinContent(1, code, static_cast<double>(full[static_cast<std::size_t>(code)]));
    h2->SetBinContent(2, code, static_cast<double>(raw[static_cast<std::size_t>(code)]));
    total += full[static_cast<std::size_t>(code)] + raw[static_cast<std::size_t>(code)];
  }
  h2->SetEntries(static_cast<double>(total));
}

void RecoilJets::fillPPG12VertexContractQA(const std::vector<std::string>& activeTrig,
                                           bool preVzCut)
{
  if (!m_ppg12PhotonYieldEnabled || m_isAuAu || activeTrig.empty()) return;

  const int runNumber = currentRunNumber();
  const std::string runPeriod = (!m_isSim && runNumber > 0)
                                    ? ppg12PeriodLabelForRun(runNumber)
                                    : m_ppg12PeriodKey;
  const bool runPass = (!m_ppg12PeriodFilterData || ppg12PeriodRunContains(runNumber));

  double vertexWeight = 1.0;
  double mbVertexWeight = 1.0;
  bool usedTruthWeight = false;
  const bool missingMBTruth =
      (m_isSim && !m_isAuAu && m_ppg12PhotonYieldDoubleInteraction &&
       (!std::isfinite(m_truthVzMB) || m_truthVzMB <= kPPG12TruthVtxSentinelThreshold));

  if (m_isSim && !m_isAuAu && m_vertexReweightOn && m_vertexReweightH)
  {
    vertexWeight = ppg12TruthVertexWeight(m_vertexReweightH, m_truthVz);
    if (m_ppg12PhotonYieldDoubleInteraction)
    {
      mbVertexWeight = ppg12TruthVertexWeight(m_vertexReweightH, m_truthVzMB);
      vertexWeight *= mbVertexWeight;
    }
    usedTruthWeight = true;
  }

  const double lumiWeight = (m_ppg12PeriodUseLumiWeight ? m_ppg12PeriodLumiWeight : 1.0);
  const double periodEventWeight =
      (m_isSim && !m_isAuAu) ? vertexWeight * m_ppg12PhotonYieldMixWeight * lumiWeight : 1.0;
  const std::string vzStage = preVzCut ? "pre_vzcut" : "post_vzcut";

  for (const auto& trigShort : activeTrig)
  {
    if (trigShort.empty()) continue;

    if (auto* h = getOrBookPPG12VertexQAAuditHist(trigShort))
    {
      auto fillAuditStage = [&](const int stage)
      {
        h->Fill(stage);
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "VERTEX_CONTRACT_AUDIT";
          row.stage_code = stage;
          row.occurrence_weight = RJMCWeighting::SafeWeight();
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      };
      fillAuditStage(1);
      if (m_ppg12PeriodContractEnabled) fillAuditStage(2);
      if (m_ppg12PeriodFilterData) fillAuditStage(3);
      if (runPeriod == "0mrad") fillAuditStage(4);
      else if (runPeriod == "1p5mrad") fillAuditStage(5);
      else fillAuditStage(6);
      if (m_isSim && !m_ppg12PhotonYieldDoubleInteraction) fillAuditStage(7);
      if (m_isSim && m_ppg12PhotonYieldDoubleInteraction) fillAuditStage(8);
      if (m_ppg12PeriodMixWeightAuto) fillAuditStage(9);
      else if (m_isSim) fillAuditStage(10);
      if (m_ppg12PeriodVertexFileAuto) fillAuditStage(11);
      else if (m_isSim) fillAuditStage(12);
      if (m_isSim && m_ppg12PeriodUseLumiWeight) fillAuditStage(13);
      if (usedTruthWeight) fillAuditStage(14);
      if (missingMBTruth) fillAuditStage(15);
      if (m_ppg12PeriodFilterData && runPass) fillAuditStage(16);
      if (m_ppg12PeriodFilterData && !runPass) fillAuditStage(17);
      fillAuditStage(preVzCut ? 18 : 19);
      if (!m_ppg12PeriodContractEnabled) fillAuditStage(20);
      bumpHistFill(trigShort, h->GetName());
    }

    if (auto* h = getOrBookPPG12PeriodContractValues(trigShort))
    {
      bumpHistFill(trigShort, h->GetName());
      if (m_replayFoundationEnabled)
      {
        const std::array<double, 13> values{{
            static_cast<double>(m_ppg12PeriodRunMin),
            static_cast<double>(m_ppg12PeriodRunMaxExclusive),
            m_ppg12PeriodLumi,
            m_ppg12PeriodLumiTarget,
            m_ppg12PeriodLumiWeight,
            m_ppg12PeriodFSingle,
            m_ppg12PeriodFDouble,
            m_ppg12PeriodClosureZCut,
            m_ppg12PhotonYieldDoubleInteraction ? 1.0 : 0.0,
            m_ppg12PhotonYieldMixWeight,
            m_ppg12PeriodMixWeightAuto ? 1.0 : 0.0,
            m_ppg12PeriodVertexFileAuto ? 1.0 : 0.0,
            m_ppg12PeriodFilterData ? 1.0 : 0.0}};
        for (std::size_t index = 0; index < values.size(); ++index)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "PERIOD_CONTRACT_VALUE";
          row.stage_code = static_cast<int>(index) + 1;
          row.flow_value = values[index];
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
    }

    if (m_replayFoundationEnabled)
    {
      ReplayPPG12DiagnosticOccurrence row;
      row.trigger = trigShort;
      row.occurrence_kind = "VERTEX_QA_STAGE";
      row.stage_code = preVzCut ? 18 : 19;
      row.reco_vertex_z = m_vz;
      row.hard_truth_vertex_z = m_truthVz;
      row.mb_truth_vertex_z = m_truthVzMB;
      row.vertex_weight = vertexWeight;
      row.period_event_weight = periodEventWeight;
      row.occurrence_weight = RJMCWeighting::SafeWeight();
      m_replayPPG12DiagnosticOccurrences.push_back(row);
    }

    if (m_isSim && !m_isAuAu)
    {
      if (std::isfinite(m_vz))
      {
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_reco_z_unweighted_" + vzStage,
                "PPG12 SIM reco vertex z (" + m_ppg12PeriodKey + ", unweighted, " + vzStage + ");v_{z}^{reco} [cm];events",
                400, -200.0, 200.0))
        {
          h->Fill(m_vz);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_reco_z_weighted_" + vzStage,
                "PPG12 SIM reco vertex z (" + m_ppg12PeriodKey + ", weighted, " + vzStage + ");v_{z}^{reco} [cm];weighted events",
                400, -200.0, 200.0))
        {
          h->Fill(m_vz, periodEventWeight);
          bumpHistFill(trigShort, h->GetName());
        }
      }
      if (std::isfinite(m_truthVz))
      {
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_truth_z_unweighted_" + vzStage,
                "PPG12 SIM hard-scatter truth vertex z (" + m_ppg12PeriodKey + ", unweighted, " + vzStage + ");z_{h}^{truth} [cm];events",
                400, -200.0, 200.0))
        {
          h->Fill(m_truthVz);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_truth_z_weighted_" + vzStage,
                "PPG12 SIM hard-scatter truth vertex z (" + m_ppg12PeriodKey + ", weighted, " + vzStage + ");z_{h}^{truth} [cm];weighted events",
                400, -200.0, 200.0))
        {
          h->Fill(m_truthVz, periodEventWeight);
          bumpHistFill(trigShort, h->GetName());
        }
      }
      if (m_ppg12PhotonYieldDoubleInteraction && std::isfinite(m_truthVzMB))
      {
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_truth_mb_z_unweighted_" + vzStage,
                "PPG12 SIM MB-overlay truth vertex z (" + m_ppg12PeriodKey + ", unweighted, " + vzStage + ");z_{mb}^{truth} [cm];events",
                400, -200.0, 200.0))
        {
          h->Fill(m_truthVzMB);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_sim_truth_mb_z_weighted_" + vzStage,
                "PPG12 SIM MB-overlay truth vertex z (" + m_ppg12PeriodKey + ", weighted, " + vzStage + ");z_{mb}^{truth} [cm];weighted events",
                400, -200.0, 200.0))
        {
          h->Fill(m_truthVzMB, periodEventWeight);
          bumpHistFill(trigShort, h->GetName());
        }
      }
      if (auto* h = getOrBookPPG12VertexQA1D(
              trigShort,
              "h_ppg12_vtxqa_sim_vertex_weight_" + vzStage,
              "PPG12 SIM vertex-reweight factor (" + m_ppg12PeriodKey + ", " + vzStage + ");w_{vtx};events",
              200, 0.0, 10.0))
      {
        h->Fill(vertexWeight);
        bumpHistFill(trigShort, h->GetName());
      }
      if (auto* h = getOrBookPPG12VertexQA1D(
              trigShort,
              "h_ppg12_vtxqa_sim_period_event_weight_" + vzStage,
              "PPG12 SIM period event weight (" + m_ppg12PeriodKey + ", " + vzStage + ");w_{vtx} #times f_{mix} #times L/L_{target};events",
              200, 0.0, 10.0))
      {
        h->Fill(periodEventWeight);
        bumpHistFill(trigShort, h->GetName());
      }
    }
    else if (std::isfinite(m_vz))
    {
      const std::string periodSuffix =
          (runPeriod == "0mrad" || runPeriod == "1p5mrad") ? runPeriod : "other";
      if (auto* h = getOrBookPPG12VertexQA1D(
              trigShort,
              "h_ppg12_vtxqa_data_reco_z_triggered_" + periodSuffix + "_" + vzStage,
              "PPG12 data triggered reco vertex z (" + periodSuffix + ", " + vzStage + ");v_{z}^{reco} [cm];events",
              400, -200.0, 200.0))
      {
        h->Fill(m_vz);
        bumpHistFill(trigShort, h->GetName());
      }
      if (runNumber > 0)
      {
        if (auto* h = getOrBookPPG12VertexQA1D(
                trigShort,
                "h_ppg12_vtxqa_data_run_triggered_" + periodSuffix + "_" + vzStage,
                "PPG12 data triggered run audit (" + periodSuffix + ", " + vzStage + ");run number;events",
                20000, 40000.0, 60000.0))
        {
          h->Fill(runNumber);
          bumpHistFill(trigShort, h->GetName());
        }
      }
    }
  }
}

void RecoilJets::fillPPG12Fig81DataHDReferenceVertexQA(PHCompositeNode* topNode)
{
  if (!m_ppg12PhotonYieldEnabled || m_isAuAu || m_isSim) return;
  if (!topNode || !out || !out->IsOpen()) return;

  auto& H = qaHistogramsByTrigger[kPPG12Fig13Bit30TriggerKey];

  auto ensureDir = [&]() -> TDirectory*
  {
    TDirectory* dir = out->GetDirectory(kPPG12Fig13Bit30TriggerKey);
    if (!dir) dir = out->mkdir(kPPG12Fig13Bit30TriggerKey);
    return dir;
  };

  auto getAudit = [&]() -> TH1I*
  {
    const std::string name = "h_ppg12_fig81_hD_reference_contract_audit";
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
      H.erase(it);
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = ensureDir();
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }
    dir->cd();

    auto* h = RJMCWeighting::RJNewTH1I(
        name.c_str(),
        "PPG12 Fig.81 data h_D reference contract audit;stage;events",
        16, 0.5, 16.5);
    if (h)
    {
      h->GetXaxis()->SetBinLabel(1, "seen_after_fetchNodes_pre_firstEventCuts");
      h->GetXaxis()->SetBinLabel(2, "gl1_present");
      h->GetXaxis()->SetBinLabel(3, "scaled_bit30");
      h->GetXaxis()->SetBinLabel(4, "mbd_vertex_map_present");
      h->GetXaxis()->SetBinLabel(5, "mbd_vertex_entry_present");
      h->GetXaxis()->SetBinLabel(6, "mbd_z_finite");
      h->GetXaxis()->SetBinLabel(7, "abs_mbd_z_le_200");
      h->GetXaxis()->SetBinLabel(8, "run_period_known");
      h->GetXaxis()->SetBinLabel(9, "filled");
      h->GetXaxis()->SetBinLabel(10, "reject_no_gl1");
      h->GetXaxis()->SetBinLabel(11, "reject_no_bit30");
      h->GetXaxis()->SetBinLabel(12, "reject_no_mbd_map");
      h->GetXaxis()->SetBinLabel(13, "reject_no_mbd_entry");
      h->GetXaxis()->SetBinLabel(14, "reject_bad_mbd_z");
      h->GetXaxis()->SetBinLabel(15, "reject_abs_mbd_z_gt_200");
      h->GetXaxis()->SetBinLabel(16, "reject_period_other");
      H[name] = h;
    }

    if (prevDir) prevDir->cd();
    return h;
  };

  auto book1F = [&](const std::string& name,
                    const std::string& title,
                    int nbins,
                    double xmin,
                    double xmax) -> TH1F*
  {
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
      H.erase(it);
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = ensureDir();
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }
    dir->cd();

    auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
    if (h)
    {
      h->Sumw2();
      H[name] = h;
    }
    if (prevDir) prevDir->cd();
    return h;
  };

  auto* audit = getAudit();
  auto fillAudit = [&](int bin)
  {
    if (audit) audit->Fill(bin);
  };
  auto finishAudit = [&]()
  {
    bumpHistFill(kPPG12Fig13Bit30TriggerKey,
                 audit ? audit->GetName() : "h_ppg12_fig81_hD_reference_contract_audit");
  };

  fillAudit(1);

  Gl1Packet* gl1 = findNode::getClass<Gl1Packet>(topNode, "14001");
  if (!gl1) gl1 = findNode::getClass<Gl1Packet>(topNode, "GL1Packet");
  if (!gl1)
  {
    fillAudit(10);
    finishAudit();
    return;
  }
  fillAudit(2);

  const uint64_t scaledVector = static_cast<uint64_t>(gl1->lValue(0, "ScaledVector"));
  const bool scaledBit30 = ((scaledVector & (1ULL << 30U)) != 0ULL);
  if (!scaledBit30)
  {
    fillAudit(11);
    finishAudit();
    return;
  }
  fillAudit(3);

  MbdVertexMap* mbdMap = findNode::getClass<MbdVertexMap>(topNode, "MbdVertexMap");
  if (!mbdMap || mbdMap->empty())
  {
    fillAudit(12);
    finishAudit();
    return;
  }
  fillAudit(4);

  MbdVertex* mbdVertex = mbdMap->begin()->second;
  if (!mbdVertex)
  {
    fillAudit(13);
    finishAudit();
    return;
  }
  fillAudit(5);

  const double mbdZ = mbdVertex->get_z();
  if (!std::isfinite(mbdZ))
  {
    fillAudit(14);
    finishAudit();
    return;
  }
  fillAudit(6);

  if (std::fabs(mbdZ) > 200.0)
  {
    fillAudit(15);
    finishAudit();
    return;
  }
  fillAudit(7);

  const int runNumber = currentRunNumber();
  const std::string period = ppg12PeriodLabelForRun(runNumber);
  if (!(period == "0mrad" || period == "1p5mrad"))
  {
    fillAudit(16);
    finishAudit();
    return;
  }
  fillAudit(8);

  if (auto* hAll = book1F(
          "h_ppg12_fig81_data_reco_z_hD_reference_contract_all",
          "PPG12 Fig.81 data reco vertex z, h_D reference contract;MBD z_{reco} [cm];events",
          80, -200.0, 200.0))
  {
    hAll->Fill(mbdZ);
    bumpHistFill(kPPG12Fig13Bit30TriggerKey, hAll->GetName());
  }

  if (auto* hPeriod = book1F(
          "h_ppg12_fig81_data_reco_z_hD_reference_contract_" + period,
          "PPG12 Fig.81 data reco vertex z, h_D reference contract (" + period + ");MBD z_{reco} [cm];events",
          80, -200.0, 200.0))
  {
    hPeriod->Fill(mbdZ);
    bumpHistFill(kPPG12Fig13Bit30TriggerKey, hPeriod->GetName());
  }

  if (std::isfinite(m_vz))
  {
    if (auto* hDelta = book1F(
            "h_ppg12_fig81_mbd_minus_recoiljets_vz_hD_reference_contract",
            "PPG12 Fig.81 h_D reference contract MBD - RecoilJets v_{z};MBD z - m_vz [cm];events",
            400, -2.0, 2.0))
    {
      hDelta->Fill(mbdZ - static_cast<double>(m_vz));
      bumpHistFill(kPPG12Fig13Bit30TriggerKey, hDelta->GetName());
    }
  }

  if (runNumber > 0)
  {
    if (auto* hRun = book1F(
            "h_ppg12_fig81_data_run_hD_reference_contract_" + period,
            "PPG12 Fig.81 data run audit, h_D reference contract (" + period + ");run number;events",
            20000, 40000.0, 60000.0))
    {
      hRun->Fill(runNumber);
      bumpHistFill(kPPG12Fig13Bit30TriggerKey, hRun->GetName());
    }
  }

  fillAudit(9);
  finishAudit();
}

void RecoilJets::fillPPG12Fig81SlimtreeVertexQA(PHCompositeNode* topNode)
{
  if (!m_ppg12PhotonYieldEnabled || m_isAuAu || m_isSim) return;
  if (!topNode || !out || !out->IsOpen()) return;

  auto& H = qaHistogramsByTrigger[kPPG12Fig13Bit30TriggerKey];

  auto ensureDir = [&]() -> TDirectory*
  {
    TDirectory* dir = out->GetDirectory(kPPG12Fig13Bit30TriggerKey);
    if (!dir) dir = out->mkdir(kPPG12Fig13Bit30TriggerKey);
    return dir;
  };

  auto getAudit = [&]() -> TH1I*
  {
    const std::string name = "h_ppg12_fig81_slimtree_vertex_contract_audit";
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
      H.erase(it);
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = ensureDir();
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }
    dir->cd();

    auto* h = RJMCWeighting::RJNewTH1I(
        name.c_str(),
        "PPG12 Fig.81 data slimtree vertex contract audit;stage;events",
        18, 0.5, 18.5);
    if (h)
    {
      h->GetXaxis()->SetBinLabel(1, "accepted_pp_event");
      h->GetXaxis()->SetBinLabel(2, "gl1_14001_present");
      h->GetXaxis()->SetBinLabel(3, "scaled_bit30");
      h->GetXaxis()->SetBinLabel(4, "mbd_vertex_map_present");
      h->GetXaxis()->SetBinLabel(5, "mbd_vertex_entry_present");
      h->GetXaxis()->SetBinLabel(6, "mbd_z_finite");
      h->GetXaxis()->SetBinLabel(7, "abs_mbd_z_le_200");
      h->GetXaxis()->SetBinLabel(8, "run_period_known");
      h->GetXaxis()->SetBinLabel(9, "saved_cluster_proxy");
      h->GetXaxis()->SetBinLabel(10, "filled");
      h->GetXaxis()->SetBinLabel(11, "reject_no_gl1_14001");
      h->GetXaxis()->SetBinLabel(12, "reject_no_bit30");
      h->GetXaxis()->SetBinLabel(13, "reject_no_mbd_map");
      h->GetXaxis()->SetBinLabel(14, "reject_no_mbd_entry");
      h->GetXaxis()->SetBinLabel(15, "reject_bad_mbd_z");
      h->GetXaxis()->SetBinLabel(16, "reject_abs_mbd_z_gt_200");
      h->GetXaxis()->SetBinLabel(17, "reject_period_other");
      h->GetXaxis()->SetBinLabel(18, "reject_no_saved_cluster");
      H[name] = h;
    }

    if (prevDir) prevDir->cd();
    return h;
  };

  auto book1F = [&](const std::string& name,
                    const std::string& title,
                    int nbins,
                    double xmin,
                    double xmax) -> TH1F*
  {
    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
      H.erase(it);
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = ensureDir();
    if (!dir)
    {
      if (prevDir) prevDir->cd();
      return nullptr;
    }
    dir->cd();

    auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
    if (h) h->Sumw2();
    H[name] = h;
    if (prevDir) prevDir->cd();
    return h;
  };

  auto countClusters = [](RawClusterContainer* container) -> std::size_t
  {
    if (!container) return 0;
    std::size_t n = 0;
    const auto range = container->getClusters();
    for (auto it = range.first; it != range.second; ++it)
    {
      if (it->second) ++n;
    }
    return n;
  };

  auto* audit = getAudit();
  auto fillAudit = [&](int bin)
  {
    if (audit) audit->Fill(bin);
  };

  fillAudit(1);

  Gl1Packet* gl1 = findNode::getClass<Gl1Packet>(topNode, "14001");
  if (!gl1)
  {
    fillAudit(11);
    return;
  }
  fillAudit(2);

  const uint64_t scaledVector = static_cast<uint64_t>(gl1->lValue(0, "ScaledVector"));
  const bool scaledBit30 = ((scaledVector & (1ULL << 30U)) != 0ULL);
  if (!scaledBit30)
  {
    fillAudit(12);
    return;
  }
  fillAudit(3);

  MbdVertexMap* mbdMap = findNode::getClass<MbdVertexMap>(topNode, "MbdVertexMap");
  if (!mbdMap || mbdMap->empty())
  {
    fillAudit(13);
    return;
  }
  fillAudit(4);

  MbdVertex* mbdVertex = mbdMap->begin()->second;
  if (!mbdVertex)
  {
    fillAudit(14);
    return;
  }
  fillAudit(5);

  const double mbdZ = mbdVertex->get_z();
  if (!std::isfinite(mbdZ))
  {
    fillAudit(15);
    return;
  }
  fillAudit(6);

  if (std::fabs(mbdZ) > 200.0)
  {
    fillAudit(16);
    return;
  }
  fillAudit(7);

  const int runNumber = currentRunNumber();
  const std::string period = ppg12PeriodLabelForRun(runNumber);
  if (!(period == "0mrad" || period == "1p5mrad"))
  {
    fillAudit(17);
    return;
  }
  fillAudit(8);

  std::set<RawClusterContainer*> clusterContainers;
  if (m_clus) clusterContainers.insert(m_clus);
  if (m_clus_nocorr) clusterContainers.insert(m_clus_nocorr);
  if (m_photons) clusterContainers.insert(m_photons);
  if (m_photons_npb) clusterContainers.insert(m_photons_npb);
  if (m_photons_tightbdt) clusterContainers.insert(m_photons_tightbdt);
  if (m_ppg12TopoClusters) clusterContainers.insert(m_ppg12TopoClusters);

  std::size_t savedClusterProxyCount = 0;
  for (auto* container : clusterContainers)
  {
    savedClusterProxyCount += countClusters(container);
  }

  if (auto* hCount = book1F(
          "h_ppg12_fig81_slimtree_saved_cluster_proxy_count",
          "PPG12 Fig.81 slimtree saved-cluster proxy multiplicity;unique persisted cluster entries;events",
          500, -0.5, 499.5))
  {
    hCount->Fill(static_cast<double>(std::min<std::size_t>(savedClusterProxyCount, 499)));
    bumpHistFill(kPPG12Fig13Bit30TriggerKey, hCount->GetName());
  }

  if (savedClusterProxyCount == 0)
  {
    fillAudit(18);
    return;
  }
  fillAudit(9);

  if (auto* hAll = book1F(
          "h_ppg12_fig81_data_reco_z_slimtree_contract_all",
          "PPG12 Fig.81 data reco vertex z, slimtree contract;MBD z_{reco} [cm];events",
          80, -200.0, 200.0))
  {
    hAll->Fill(mbdZ);
    bumpHistFill(kPPG12Fig13Bit30TriggerKey, hAll->GetName());
  }

  if (auto* hPeriod = book1F(
          "h_ppg12_fig81_data_reco_z_slimtree_contract_" + period,
          "PPG12 Fig.81 data reco vertex z, slimtree contract (" + period + ");MBD z_{reco} [cm];events",
          80, -200.0, 200.0))
  {
    hPeriod->Fill(mbdZ);
    bumpHistFill(kPPG12Fig13Bit30TriggerKey, hPeriod->GetName());
  }

  if (runNumber > 0)
  {
    if (auto* hRun = book1F(
            "h_ppg12_fig81_data_run_slimtree_contract_" + period,
            "PPG12 Fig.81 data run audit, slimtree contract (" + period + ");run number;events",
            20000, 40000.0, 60000.0))
    {
      hRun->Fill(runNumber);
      bumpHistFill(kPPG12Fig13Bit30TriggerKey, hRun->GetName());
    }
  }

  fillAudit(10);
  bumpHistFill(kPPG12Fig13Bit30TriggerKey, audit ? audit->GetName() : "h_ppg12_fig81_slimtree_vertex_contract_audit");
}

bool RecoilJets::ppg12PhotonYieldTowerMasked(const PhotonClusterv1* pho) const
{
  if (!(m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldApplyTowerMask && !m_isAuAu))
  {
    return false;
  }
  if (!pho || !m_ppg12PhotonYieldTowerMask) return false;

  double ietaRaw = pho->get_shower_shape_parameter("ppg12_cluster_ietacent_raw");
  double iphiRaw = pho->get_shower_shape_parameter("ppg12_cluster_iphicent_raw");
  if (!std::isfinite(ietaRaw) || !std::isfinite(iphiRaw))
  {
    ietaRaw = pho->get_shower_shape_parameter("cluster_ietacent");
    iphiRaw = pho->get_shower_shape_parameter("cluster_iphicent");
  }
  if (!std::isfinite(ietaRaw) || !std::isfinite(iphiRaw)) return false;

  const int ieta = static_cast<int>(ietaRaw);
  const int iphi = static_cast<int>(iphiRaw);
  if (ieta < 0 || ieta >= m_ppg12PhotonYieldTowerMask->GetNbinsX()) return false;
  if (iphi < 0 || iphi >= m_ppg12PhotonYieldTowerMask->GetNbinsY()) return false;

  return m_ppg12PhotonYieldTowerMask->GetBinContent(ieta + 1, iphi + 1) > 0.0;
}

double RecoilJets::ppg12PhotonYieldKinematicVertexZ() const
{
  // CaloAna24 uses the reconstructed MBD vertex for reconstructed cluster
  // kinematics and topocluster isolation in both data and photon-jet MC.
  // Truth vertices are used only by configurePPG12SimEventWeight().
  return m_vz;
}

double RecoilJets::ppg12PhotonYieldRawEiso(const RawCluster* clus, PHCompositeNode* topNode)
{
  return ppg12PhotonYieldRawEisoDetailed(clus, topNode, nullptr);
}

double RecoilJets::ppg12PhotonYieldRawEisoDetailed(const RawCluster* clus,
                                                   PHCompositeNode* topNode,
                                                   PPG12EisoPathAudit* audit)
{
  PPG12EisoPathAudit localAudit;
  PPG12EisoPathAudit& pathAudit = audit ? *audit : localAudit;
  pathAudit = PPG12EisoPathAudit{};
  if (!(m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldUseTopoIso && !m_isAuAu))
  {
    const double fallback = eiso(clus, topNode);
    pathAudit.recomputedRaw = fallback;
    pathAudit.finalRaw = fallback;
    pathAudit.pathCode = std::isfinite(fallback) && fallback < 1e8 ? 2 : 0;
    return fallback;
  }

  const auto* pho = dynamic_cast<const PhotonClusterv1*>(clus);
  if (!pho)
  {
    pathAudit.storedRejected = true;
    recordPPG12EisoVertexContractAudit(pathAudit);
    if (Verbosity() >= 2)
      LOG(2, CLR_YELLOW,
          "  [PPG12_PHOTON_YIELD_V1][topo-iso] cluster is not PhotonClusterv1 -> +inf");
    return 1e9;
  }

  const double storedTopoValid = pho->get_shower_shape_parameter("ppg12_topo_valid_04");
  const double storedTopoRawEiso = pho->get_shower_shape_parameter("ppg12_topo_raw_eiso_04");
  const double legacyPositiveOnlyRawEiso =
      pho->get_shower_shape_parameter("ppg12_topo_positive_only_raw_eiso_04");
  const double storedTopoSumEt =
      pho->get_shower_shape_parameter("ppg12_topo_sumet_04");
  const double storedPositiveOnlyTopoSumEt =
      pho->get_shower_shape_parameter("ppg12_topo_positive_only_sumet_04");
  const double expectedVertexZ = ppg12PhotonYieldKinematicVertexZ();
  const double storedVertexZ = pho->get_shower_shape_parameter("ppg12_topo_vertex_z");
  const bool vertexCompatible =
      !std::isfinite(expectedVertexZ) ||
      (std::isfinite(storedVertexZ) && std::fabs(storedVertexZ - expectedVertexZ) < 1.0e-3);
  const bool storedUsable =
      std::isfinite(storedTopoValid) && storedTopoValid > 0.5 &&
      std::isfinite(storedTopoRawEiso) && storedTopoRawEiso < 1.0e8;

  pathAudit.storedRaw = storedTopoRawEiso;
  pathAudit.legacyPositiveOnlyRaw = legacyPositiveOnlyRawEiso;
  pathAudit.storedTopoSumEt = storedTopoSumEt;
  pathAudit.storedPositiveOnlyTopoSumEt = storedPositiveOnlyTopoSumEt;
  pathAudit.storedValid = storedTopoValid;
  pathAudit.storedVertexZ = storedVertexZ;
  pathAudit.expectedVertexZ = expectedVertexZ;
  pathAudit.vertexCompatible = vertexCompatible;
  pathAudit.storedUsable = storedUsable;

  // A valid PhotonClusterBuilder value was already constructed with the
  // reconstructed MBD vertex. Never invalidate or recompute it because a
  // truth vertex differs from the reconstructed one.
  if (storedUsable)
  {
    pathAudit.storedAccepted = true;
    pathAudit.recoVertexUsedForEiso = std::isfinite(storedVertexZ);
    pathAudit.finalRaw = storedTopoRawEiso;
    pathAudit.pathCode = 1;
    if (!audit)
    {
      recordPPG12EisoVertexContractAudit(pathAudit);
      if (Verbosity() >= 5)
      {
        LOG(5, CLR_BLUE,
            "  [PPG12_PHOTON_YIELD_V1][topo-iso] using PhotonClusterBuilder stored raw eiso="
            << storedTopoRawEiso
            << " vertex_z=" << storedVertexZ);
      }
      return storedTopoRawEiso;
    }
  }
  else
  {
    pathAudit.storedRejected = true;
    pathAudit.recomputeFallbackUsed = true;
    if (Verbosity() >= 3)
    {
      LOG(3, CLR_YELLOW,
          "  [PPG12_PHOTON_YIELD_V1][topo-iso] stored PhotonClusterBuilder eiso is missing/invalid"
          << " stored_raw=" << storedTopoRawEiso
          << " -> recomputing in RecoilJets");
    }
  }

  auto recomputeRawEiso = [&]() -> double
  {
    if (!m_ppg12TopoClusters)
    {
      if (Verbosity() >= 1)
        LOG(1, CLR_RED,
            "  [PPG12_PHOTON_YIELD_V1][topo-iso] "
            << kPPG12YieldTopoClusterNode << " missing -> +inf");
      return 1e9;
    }

    double axisEta = pho->get_shower_shape_parameter("ppg12_iso_axis_eta");
    double axisPhi = TVector2::Phi_mpi_pi(pho->get_shower_shape_parameter("ppg12_iso_axis_phi"));
    if (!std::isfinite(axisEta) || !std::isfinite(axisPhi))
    {
      axisEta = pho->get_shower_shape_parameter("cluster_eta");
      axisPhi = TVector2::Phi_mpi_pi(pho->get_shower_shape_parameter("cluster_phi"));
    }
    if (!std::isfinite(axisEta) || !std::isfinite(axisPhi))
    {
      if (Verbosity() >= 2)
        LOG(2, CLR_YELLOW,
            "  [PPG12_PHOTON_YIELD_V1][topo-iso] non-finite iso axis -> +inf");
      return 1e9;
    }
    pathAudit.isoAxisEta = axisEta;
    pathAudit.isoAxisPhi = axisPhi;

    double candidateEt = pho->get_shower_shape_parameter("cluster_et");
    if (!std::isfinite(candidateEt)) candidateEt = pho->get_shower_shape_parameter("cluster_pt");
    pathAudit.candidateEt = candidateEt;
    if (!std::isfinite(candidateEt) || candidateEt <= 0.0)
    {
      if (Verbosity() >= 2)
        LOG(2, CLR_YELLOW,
            "  [PPG12_PHOTON_YIELD_V1][topo-iso] invalid candidate ET=" << candidateEt << " -> +inf");
      return 1e9;
    }

    double topoEt04 = 0.0;
    double positiveOnlyTopoEt04 = 0.0;
    const double recoVertexZ = ppg12PhotonYieldKinematicVertexZ();
    pathAudit.recoVertexUsedForEiso = std::isfinite(recoVertexZ);
    const CLHEP::Hep3Vector vertex(0.0, 0.0, recoVertexZ);
    const auto range = m_ppg12TopoClusters->getClusters();
    for (auto it = range.first; it != range.second; ++it)
    {
      ++pathAudit.topoNodeCount;
      const RawCluster* topo = it->second;
      if (!topo) continue;

      const double topoEta = RawClusterUtility::GetPseudorapidity(*topo, vertex);
      const double topoPhi = TVector2::Phi_mpi_pi(RawClusterUtility::GetAzimuthAngle(*topo, vertex));
      if (!std::isfinite(topoEta) || !std::isfinite(topoPhi)) continue;

      const double topoEt = topo->get_energy() / std::cosh(topoEta);
      if (!std::isfinite(topoEt)) continue;

      const double dEta = axisEta - topoEta;
      const double dPhi = TVector2::Phi_mpi_pi(axisPhi - topoPhi);
      const double dR = std::sqrt(dEta * dEta + dPhi * dPhi);
      if (dR < kPPG12YieldRecoIsoConeR)
      {
        ++pathAudit.inConeMemberCount;
        topoEt04 += topoEt;
        if (topoEt > 0.0) positiveOnlyTopoEt04 += topoEt;
        if (audit && m_ppg12EisoConeMemberCanaryOut.is_open())
        {
          PPG12EisoConeMemberAudit member;
          member.key = static_cast<std::uint64_t>(it->first);
          member.energy = topo->get_energy();
          member.eta = topoEta;
          member.phi = topoPhi;
          member.et = topoEt;
          member.dEta = dEta;
          member.dPhi = dPhi;
          member.dR = dR;
          pathAudit.coneMembers.push_back(member);
        }
      }
    }
    pathAudit.recomputedTopoSumEt = topoEt04;
    pathAudit.recomputedPositiveOnlyTopoSumEt = positiveOnlyTopoEt04;

    double iso = topoEt04 - candidateEt;
    double positiveOnlyIso = positiveOnlyTopoEt04 - candidateEt;
    if (m_ppg12PhotonYieldExcludeCandidateTopoCluster && m_isSim && !m_isAuAu)
    {
      // PPG12 Fig.29 final slimtree behaves like the photon topocluster is
      // excluded from the topo-cone residual before the final candidate-ET
      // subtraction. Our topo collection includes it, so remove it here only
      // for the pp-SIM PPG12 photon-yield compatibility path.
      iso -= candidateEt;
      positiveOnlyIso -= candidateEt;
    }
    if (!std::isfinite(pathAudit.legacyPositiveOnlyRaw))
    {
      pathAudit.legacyPositiveOnlyRaw = positiveOnlyIso;
    }
    if (Verbosity() >= 5)
    {
      LOG(5, CLR_BLUE,
          "  [PPG12_PHOTON_YIELD_V1][topo-iso] topoET04=" << topoEt04
          << " candidateET=" << candidateEt
          << " candidateExcluded=" << (m_ppg12PhotonYieldExcludeCandidateTopoCluster ? "true" : "false")
          << " iso=" << iso);
    }
    return std::isfinite(iso) ? iso : 1e9;
  };

  const double recomputedRawEiso = recomputeRawEiso();
  pathAudit.recomputedRaw = recomputedRawEiso;
  if (!storedUsable)
  {
    pathAudit.finalRaw = recomputedRawEiso;
    pathAudit.pathCode =
        (std::isfinite(recomputedRawEiso) && recomputedRawEiso < 1e8) ? 2 : 0;
  }
  recordPPG12EisoVertexContractAudit(pathAudit);
  return storedUsable ? storedTopoRawEiso : recomputedRawEiso;
}

void RecoilJets::recordPPG12EisoVertexContractAudit(const PPG12EisoPathAudit& audit)
{
  if (!(m_ppg12PhotonYieldEnabled && m_ppg12PhotonYieldUseTopoIso && !m_isAuAu)) return;

  const std::string auditDirectory = m_isSim ? "SIM" : kPPG12Fig13Bit30TriggerKey;
  TH1I* h = getOrBookPPG12EisoVertexContractAuditHist(auditDirectory);
  if (!h) return;

  auto fillAuditStage = [&](const int stage)
  {
    h->Fill(stage);
    if (m_replayFoundationEnabled)
    {
      ReplayPPG12DiagnosticOccurrence row;
      row.trigger = auditDirectory;
      row.occurrence_kind = "EISO_VERTEX_AUDIT";
      row.stage_code = stage;
      m_replayPPG12DiagnosticOccurrences.push_back(row);
    }
  };
  if (audit.storedUsable) fillAuditStage(1);
  if (audit.storedAccepted) fillAuditStage(2);
  if (audit.storedRejected) fillAuditStage(3);
  if (audit.recomputeFallbackUsed) fillAuditStage(4);
  if (audit.vertexMismatchRejected) fillAuditStage(5);
  if (audit.recoVertexUsedForEiso) fillAuditStage(6);
}

void RecoilJets::recordPPG12EisoPathCanary(const PPG12EisoPathAudit& audit,
                                           const int candidateIndex,
                                           const double recoEt,
                                           const double eta,
                                           const double phi,
                                           const bool isTruthSignal,
                                           const SSVars& vars,
                                           const double correctedEiso,
                                           const double isoThreshold,
                                           const double nonIsoLower,
                                           const TightTag tightTag)
{
  if (!m_ppg12EisoPathCanaryEnabled || !m_ppg12EisoPathCanaryOut.is_open()) return;
  if (m_ppg12EisoPathCanaryMaxRows > 0 &&
      m_ppg12EisoPathCanaryRowsWritten >= m_ppg12EisoPathCanaryMaxRows) return;
  if (!std::isfinite(recoEt) || recoEt < m_ppg12EisoPathCanaryMinEt ||
      recoEt >= m_ppg12EisoPathCanaryMaxEt) return;

  auto writeNumber = [&](const double value)
  {
    if (std::isfinite(value)) m_ppg12EisoPathCanaryOut << std::setprecision(17) << value;
  };
  const int ptBin = findPPG12Fig24RecoPtBin(recoEt);
  const int eisoBin = std::isfinite(correctedEiso)
      ? static_cast<int>(std::floor((correctedEiso + 10.0) / 0.1)) + 1
      : -1;
  const char* pathLabel = audit.pathCode == 1 ? "stored" :
                          audit.pathCode == 2 ? "recomputed" : "invalid";

  auto regionFor = [&](const double value) -> const char*
  {
    if (!std::isfinite(value) || value >= 1e8) return "invalid";
    if (value > kPPG12YieldRecoIsoMin && value < isoThreshold) return "isolated";
    if (value > nonIsoLower && value < kPPG12YieldRecoNonIsoMax) return "nonisolated";
    if (value >= kPPG12YieldRecoNonIsoMax) return "overflow";
    return "gap";
  };
  const double storedCorrected = ppg12PhotonYieldEiso(audit.storedRaw);
  const double legacyPositiveOnlyCorrected =
      ppg12PhotonYieldEiso(audit.legacyPositiveOnlyRaw);
  const double recomputedCorrected = ppg12PhotonYieldEiso(audit.recomputedRaw);
  const char* storedRegion = regionFor(storedCorrected);
  const char* legacyPositiveOnlyRegion = regionFor(legacyPositiveOnlyCorrected);
  const char* recomputedRegion = regionFor(recomputedCorrected);
  const char* currentRegion = regionFor(correctedEiso);
  const char* mismatchReason = "none";
  if (!audit.storedUsable) mismatchReason = "stored_invalid_fallback";
  else if (std::string(storedRegion) != std::string(recomputedRegion))
    mismatchReason = "stored_recomputed_region_disagree";

  const bool npbPass = std::isfinite(vars.npb_score) && vars.npb_score > kPPG12YieldNpbMin;
  const bool looseSSPass =
      std::isfinite(vars.e11_over_e33) && vars.e11_over_e33 < kPPG12YieldCommonE11E33Max &&
      in_open_interval(vars.et1, kPPG12YieldTightEt1Min, kPPG12YieldTightEt1Max) &&
      in_open_interval(vars.e32_over_e35, kPPG12YieldTightE32E35Min, kPPG12YieldTightE32E35Max);

  const long long eventSequence = m_evtHeader
      ? static_cast<long long>(m_evtHeader->get_EvtSequence())
      : -1;
  const long long memberRowsRequested =
      static_cast<long long>(audit.coneMembers.size());
  const bool memberVectorComplete =
      memberRowsRequested == audit.inConeMemberCount;
  const bool memberRowsFit =
      m_ppg12EisoConeMemberCanaryMaxRows <= 0 ||
      m_ppg12EisoConeMemberCanaryRowsWritten + memberRowsRequested <=
          m_ppg12EisoConeMemberCanaryMaxRows;
  const bool memberCaptureComplete =
      m_ppg12EisoConeMemberCanaryOut.is_open() && memberVectorComplete && memberRowsFit;
  long long memberRowsCaptured = 0;
  if (memberCaptureComplete)
  {
    auto writeMemberNumber = [&](const double value)
    {
      if (std::isfinite(value))
      {
        m_ppg12EisoConeMemberCanaryOut << std::setprecision(17) << value;
      }
    };
    for (std::size_t memberIndex = 0; memberIndex < audit.coneMembers.size(); ++memberIndex)
    {
      const auto& member = audit.coneMembers[memberIndex];
      m_ppg12EisoConeMemberCanaryOut
          << currentRunNumber() << ',' << event_count << ',' << eventSequence << ','
          << candidateIndex << ',';
      writeMemberNumber(recoEt); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(eta); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(phi); m_ppg12EisoConeMemberCanaryOut << ','
          << (isTruthSignal ? 1 : 0) << ',';
      writeMemberNumber(vars.tight_bdt_score); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(vars.npb_score); m_ppg12EisoConeMemberCanaryOut << ','
          << tightTagName(tightTag) << ',' << m_ppg12EisoVertexSource << ',';
      writeMemberNumber(audit.expectedVertexZ); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(audit.isoAxisEta); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(audit.isoAxisPhi); m_ppg12EisoConeMemberCanaryOut << ','
          << audit.topoNodeCount << ',' << audit.inConeMemberCount << ','
          << memberIndex << ',' << member.key << ',';
      writeMemberNumber(member.energy); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.eta); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.phi); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.et); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.dEta); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.dPhi); m_ppg12EisoConeMemberCanaryOut << ',';
      writeMemberNumber(member.dR);
      m_ppg12EisoConeMemberCanaryOut << '\n';
      ++memberRowsCaptured;
      ++m_ppg12EisoConeMemberCanaryRowsWritten;
    }
  }

  m_ppg12EisoPathCanaryOut
      << currentRunNumber() << ',' << event_count << ',' << eventSequence << ','
      << candidateIndex << ',';
  writeNumber(recoEt); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(eta); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(phi); m_ppg12EisoPathCanaryOut << ','
      << (isTruthSignal ? 1 : 0) << ',';
  writeNumber(vars.tight_bdt_score); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(vars.npb_score); m_ppg12EisoPathCanaryOut << ','
      << (npbPass ? 1 : 0) << ','
      << (looseSSPass ? 1 : 0) << ','
      << (passesPPG12PhotonYieldCommon(vars) ? 1 : 0) << ','
      << tightTagName(tightTag) << ',' << m_ppg12EisoVertexSource << ',';
  writeNumber(audit.storedRaw); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.legacyPositiveOnlyRaw); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.storedTopoSumEt); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.storedPositiveOnlyTopoSumEt); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.storedValid); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.storedVertexZ); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.expectedVertexZ); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.isoAxisEta); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.isoAxisPhi); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.candidateEt); m_ppg12EisoPathCanaryOut << ','
      << (audit.vertexCompatible ? 1 : 0) << ','
      << (audit.storedAccepted ? 1 : 0) << ','
      << (audit.storedRejected ? 1 : 0) << ','
      << (audit.recomputeFallbackUsed ? 1 : 0) << ','
      << (audit.vertexMismatchRejected ? 1 : 0) << ','
      << (audit.recoVertexUsedForEiso ? 1 : 0) << ','
      << audit.topoNodeCount << ',' << audit.inConeMemberCount << ',';
  writeNumber(audit.recomputedTopoSumEt); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.recomputedPositiveOnlyTopoSumEt); m_ppg12EisoPathCanaryOut << ',';
  writeNumber(audit.recomputedRaw); m_ppg12EisoPathCanaryOut << ',';
  m_ppg12EisoPathCanaryOut
      << memberRowsCaptured << ',' << (memberCaptureComplete ? 1 : 0) << ',';
  writeNumber(audit.finalRaw); m_ppg12EisoPathCanaryOut << ','
      << audit.pathCode << ',' << pathLabel << ',';
  writeNumber(correctedEiso); m_ppg12EisoPathCanaryOut << ','
      << isoThreshold << ',' << nonIsoLower << ',' << kPPG12YieldRecoNonIsoMax << ','
      << storedRegion << ',' << legacyPositiveOnlyRegion << ','
      << recomputedRegion << ',' << currentRegion << ','
      << mismatchReason << ','
      << ptBin << ',' << eisoBin << ',';
  writeNumber(m_ppg12SimWeightFactorFinal);
  m_ppg12EisoPathCanaryOut << '\n';
  ++m_ppg12EisoPathCanaryRowsWritten;
}

double RecoilJets::ppg12PhotonYieldEiso(double eisoEt) const
{
  if (!(m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu))
  {
    return eisoEt;
  }

  if (!std::isfinite(eisoEt) || eisoEt >= 1e8)
  {
    return eisoEt;
  }

  return m_ppg12PhotonYieldMcIsoScale * eisoEt + m_ppg12PhotonYieldMcIsoShift;
}

double RecoilJets::ppg12PhotonYieldClusterEtForCuts(double ptGamma, int candidateIndex) const
{
  (void) candidateIndex;
  // RecoEffCalculator_TTreeReader.C uses the calibrated, unsmeared cluster ET
  // for every analysis cut, ID/iso decision, and ABCD yield.  Do not couple
  // those physics selections to the response-only resolution model below.
  return ptGamma;
}

double RecoilJets::ppg12PhotonYieldClusterEtForResponse(double recoEt,
                                                        double truthPt,
                                                        int candidateIndex) const
{
  if (!(m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu)) return recoEt;
  if (!std::isfinite(recoEt) || recoEt <= 0.0 ||
      !std::isfinite(truthPt) || truthPt <= 0.0)
  {
    return recoEt;
  }

  const double dataSigma2 =
      (kPPG12YieldResponseEResDataP0 * kPPG12YieldResponseEResDataP0) / truthPt +
      (kPPG12YieldResponseEResDataP1 * kPPG12YieldResponseEResDataP1) /
          (truthPt * truthPt) +
      kPPG12YieldResponseEResDataP2 * kPPG12YieldResponseEResDataP2;
  const double mcSigma2 =
      (kPPG12YieldResponseEResMcP0 * kPPG12YieldResponseEResMcP0) / truthPt +
      (kPPG12YieldResponseEResMcP1 * kPPG12YieldResponseEResMcP1) /
          (truthPt * truthPt) +
      kPPG12YieldResponseEResMcP2 * kPPG12YieldResponseEResMcP2;
  const double sigmaExtraGeV =
      std::sqrt(std::max(0.0, dataSigma2 - mcSigma2)) * truthPt;
  if (!(sigmaExtraGeV > 0.0) || !std::isfinite(sigmaExtraGeV)) return recoEt;

  // PPG12 uses a fixed seed but a stateful draw sequence.  Distributed jobs
  // cannot preserve that monolithic entry ordering, so derive one stable draw
  // per physical event/candidate while retaining the same Gaussian model.
  std::uint64_t key = static_cast<std::uint64_t>(std::max(currentRunNumber(), 0));
  auto mixKey = [&key](const std::uint64_t value)
  {
    key ^= value + 0x9e3779b97f4a7c15ULL + (key << 6U) + (key >> 2U);
  };
  const std::uint64_t eventKey = m_evtHeader
      ? static_cast<std::uint64_t>(static_cast<std::uint32_t>(m_evtHeader->get_EvtSequence()))
      : static_cast<std::uint64_t>(event_count);
  mixKey(eventKey);
  mixKey(static_cast<std::uint64_t>(event_count));
  mixKey(static_cast<std::uint64_t>(std::max(candidateIndex, 0)));
  // Event sequence and candidate indices can restart at DST/file boundaries.
  // Mixing the exact reco/truth kinematics avoids correlated repeated draws
  // across independently chunked jobs while remaining reproducible when the
  // same physical candidate is replayed.
  mixKey(std::bit_cast<std::uint64_t>(recoEt));
  mixKey(std::bit_cast<std::uint64_t>(truthPt));
  key += 0x9e3779b97f4a7c15ULL;
  key = (key ^ (key >> 30U)) * 0xbf58476d1ce4e5b9ULL;
  key = (key ^ (key >> 27U)) * 0x94d049bb133111ebULL;
  key ^= key >> 31U;
  unsigned int seed = static_cast<unsigned int>((key ^ (key >> 32U)) & 0xffffffffULL);
  if (seed == 0U) seed = 42U;

  TRandom3 rng(seed);
  const double smeared = recoEt + rng.Gaus(0.0, sigmaExtraGeV);
  return (std::isfinite(smeared) && smeared > 0.0) ? smeared : recoEt;
}

bool RecoilJets::ppg12PhotonYieldInResponseWindow(double recoPt, double truthPt) const
{
  return std::isfinite(recoPt) && std::isfinite(truthPt) &&
         !m_ppg12PhotonYieldRecoPtBins.empty() &&
         !m_ppg12PhotonYieldTruthPtBins.empty() &&
         recoPt > m_ppg12PhotonYieldRecoPtBins.front() &&
         recoPt < m_ppg12PhotonYieldRecoPtBins.back() &&
         truthPt > m_ppg12PhotonYieldTruthPtBins.front() &&
         truthPt < m_ppg12PhotonYieldTruthPtBins.back();
}

double RecoilJets::ppg12Fig36TruthPriorWeight(double truthPt) const
{
  if (!std::isfinite(truthPt)) return 1.0;

  // PPG12 config_bdt_nom.yaml analysis.unfold.truth_reweight:
  // ([0] + [1]x + [3]x^2) / (1 + [2]x + [4]x^2), clamped to 10-30 GeV.
  const double x = std::min(30.0, std::max(10.0, truthPt));
  constexpr double p0 = 4.05592;
  constexpr double p1 = -0.984728;
  constexpr double p2 = -0.478818;
  constexpr double p3 = 0.0723232;
  constexpr double p4 = 0.0522681;

  const double den = 1.0 + p2 * x + p4 * x * x;
  if (!std::isfinite(den) || den == 0.0) return 1.0;

  const double num = p0 + p1 * x + p3 * x * x;
  const double w = num / den;
  return std::isfinite(w) ? w : 1.0;
}

bool RecoilJets::isIsolated(const RawCluster* clus, double et_gamma, PHCompositeNode* topNode)
{
  if (!std::isfinite(et_gamma) || et_gamma <= 0.0)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW, "  [isIsolated] invalid ET^γ=" << et_gamma << " → false");
    return false;
  }

    const double thr = recoIsoThreshold(et_gamma);
    const double eiso_val =
        (m_ppg12PhotonYieldEnabled && !m_isAuAu)
            ? ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(clus, topNode))
            : this->eiso(clus, topNode);
    const bool passIso = (eiso_val < thr);

    if (Verbosity() >= 5)
        LOG(5, (passIso ? CLR_RED : CLR_YELLOW),
            "  [isIsolated] ET^γ=" << et_gamma << "  thr=" << thr << "  eiso=" << eiso_val
            << "  pass=" << (passIso ? 1 : 0));

    return passIso;
}


bool RecoilJets::isNonIsolated(const RawCluster* clus, double et_gamma, PHCompositeNode* topNode)
{
  if (!std::isfinite(et_gamma) || et_gamma <= 0.0)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW, "  [isNonIsolated] invalid ET^γ=" << et_gamma << " → false");
    return false;
  }

  const double thr = recoNonIsoThreshold(et_gamma);
  const double eiso_val =
      (m_ppg12PhotonYieldEnabled && !m_isAuAu)
          ? ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(clus, topNode))
          : this->eiso(clus, topNode);

  if (Verbosity() >= 5)
    LOG(5, CLR_BLUE, "  [isNonIsolated] ET^γ=" << et_gamma << "  thr=" << thr << "  eiso=" << eiso_val
                        << "  pass=" << (eiso_val > thr));

  return (eiso_val > thr);
}


// -----------------------------------------------------------------------------
// Unified truth-MC signal definition: isolated prompt photon (CaloAna-matching)
// -----------------------------------------------------------------------------




RecoilJets::TruthSignalPhotonMap
RecoilJets::buildPPG12TruthPhotonWitnessMap(
    PHCompositeNode* topNode,
    RJReplayFoundationV1::TruthPhotonInventoryV1* inventory) const
{
  TruthSignalPhotonMap truthPhotonByTrackId;
  if(inventory)
  {
    *inventory=RJReplayFoundationV1::TruthPhotonInventoryV1{};
    inventory->capture_state=0;
  }
  if (!topNode || !m_truthInfo) return truthPhotonByTrackId;
  if(inventory)inventory->capture_state=1;

  PHHepMCGenEventMap* hepmcmap = findNode::getClass<PHHepMCGenEventMap>(topNode, "PHHepMCGenEventMap");
  std::map<int, const HepMC::GenEvent*> hepmcEventByEmbedId;
  if (hepmcmap)
  {
    for (auto it = hepmcmap->begin(); it != hepmcmap->end(); ++it)
    {
      PHHepMCGenEvent* genevt = it->second;
      if (!genevt) continue;
      const HepMC::GenEvent* evt = genevt->getEvent();
      if (!evt) continue;
      const auto inserted = hepmcEventByEmbedId.emplace(genevt->get_embedding_id(), evt);
      if (!inserted.second && inserted.first->second != evt)
        throw std::runtime_error("truth embedding ID maps to multiple HepMC events");
    }
  }

  std::vector<const PHG4Particle*> embeddedPrimaryParticles;
  {
    auto primaryRange = m_truthInfo->GetPrimaryParticleRange();
    for (auto truthIt = primaryRange.first; truthIt != primaryRange.second; ++truthIt)
    {
      const PHG4Particle* truth = truthIt->second;
      if (!truth) continue;
      if (m_truthInfo->isEmbeded(truth->get_track_id()) < 1) continue;
      embeddedPrimaryParticles.push_back(truth);
    }
  }

  constexpr double kMergerDR = 0.001;

  for (const PHG4Particle* truthPho : embeddedPrimaryParticles)
  {
    if (!truthPho) continue;
    if (truthPho->get_pid() != 22) continue;
    if(inventory)++inventory->native_embedded_primary_pid22_count;

    const int trackId = truthPho->get_track_id();
    const int embedId = m_truthInfo->isEmbeded(trackId);
    const int barcode = truthPho->get_barcode();
    const auto evtIt = hepmcEventByEmbedId.find(embedId);
    const HepMC::GenEvent* evt = (evtIt != hepmcEventByEmbedId.end()) ? evtIt->second : nullptr;
    const HepMC::GenParticle* hepPhoton = findHepMCParticleByBarcode(evt, barcode);
    const bool hepmcAssociationValid = hepPhoton && hepPhoton->pdg_id() == 22;
    const int photonClass = hepmcAssociationValid ? ppg12Fig2PhotonClass(hepPhoton) : -1;

    TLorentzVector p1(truthPho->get_px(), truthPho->get_py(), truthPho->get_pz(), truthPho->get_e());
    const double etaPho = p1.Eta();
    const double phiPho = p1.Phi();
    const double ptPho = p1.Pt();
    if (!std::isfinite(ptPho) || !std::isfinite(etaPho) || !std::isfinite(phiPho) || ptPho <= 0.0)
    {
      if(inventory)inventory->rejectInvalidKinematics();
      continue;
    }

    double isoSumEtR03 = 0.0;
    double isoSumEtR04 = 0.0;
    double clusterEt = 0.0;
    for (const PHG4Particle* truth : embeddedPrimaryParticles)
    {
      if (!truth) continue;

      TLorentzVector p2(truth->get_px(), truth->get_py(), truth->get_pz(), truth->get_e());
      const double qEt = p2.Et();
      if (!std::isfinite(qEt) || qEt <= 0.0)
      {
        if(inventory && (!std::isfinite(qEt) || qEt<0.0))
          ++inventory->isolation_input_incomplete_count;
        continue;
      }

      const double dr = p1.DeltaR(p2);
      if (!std::isfinite(dr))
      {
        if(inventory)++inventory->isolation_input_incomplete_count;
        continue;
      }
      if (dr < 0.3) isoSumEtR03 += qEt;
      if (dr < 0.4) isoSumEtR04 += qEt;
      if (dr < kMergerDR) clusterEt += qEt;
    }

    const double isoEtR03 = isoSumEtR03 - clusterEt;
    const double isoEtR04 = isoSumEtR04 - clusterEt;
    if (!std::isfinite(isoEtR03) || !std::isfinite(isoEtR04))
    {
      if(inventory)inventory->rejectNonfiniteIsolation();
      continue;
    }

    TruthSignalPhotonInfo info;
    info.trackId = trackId;
    info.barcode = barcode;
    info.pt = ptPho;
    info.eta = etaPho;
    info.phi = TVector2::Phi_mpi_pi(phiPho);
    info.isoEt = isoEtR03;
    info.isoEtR03 = isoEtR03;
    info.isoEtR04 = isoEtR04;
    info.truthIsolationValid = true;
    info.g4PhotonValid = true;
    info.hepmcAssociationValid = hepmcAssociationValid;
    info.photonClass = photonClass;
    info.embedId = embedId;
    info.hep = hepPhoton;
    info.g4 = truthPho;

    auto existing = truthPhotonByTrackId.find(info.trackId);
    if(existing!=truthPhotonByTrackId.end() && inventory)
      inventory->rejectDuplicateTrack();
    if (existing == truthPhotonByTrackId.end() || info.pt > existing->second.pt)
    {
      truthPhotonByTrackId[info.trackId] = info;
    }
  }

  return truthPhotonByTrackId;
}

RecoilJets::TruthSignalPhotonMap
RecoilJets::buildPPG12TruthSignalPhotonMap(PHCompositeNode* topNode) const
{
  TruthSignalPhotonMap truthSignalByTrackId;
  const TruthSignalPhotonMap truthPhotonByTrackId =
      buildPPG12TruthPhotonWitnessMap(topNode);
  for (const auto& entry : truthPhotonByTrackId)
  {
    const TruthSignalPhotonInfo& info = entry.second;
    // Exact PPG12 RecoEff denominator: a valid embedded G4 photon, class < 3
    // (including 0 and -1), |eta| < 0.7 and nominal R=0.3 isolation < 4 GeV.
    if (!info.g4PhotonValid || !(info.photonClass < 3)) continue;
    if (!std::isfinite(info.eta) || std::fabs(info.eta) >= 0.7) continue;
    if (!info.truthIsolationValid || !(info.isoEtR03 < m_truthIsoMaxGeV)) continue;
    truthSignalByTrackId.emplace(entry.first, info);
  }
  return truthSignalByTrackId;
}

bool RecoilJets::classifyRecoPhotonWithPPG12TruthTrack(const RawCluster* rc,
                                                       CaloRawClusterEval& clustereval,
                                                       const TruthSignalPhotonMap& truthSignalByTrackId,
                                                       TruthSignalPhotonInfo& matchedTruth,
                                                       int& clusterTruthTrackId,
                                                       float& eContrib) const
{
  matchedTruth = TruthSignalPhotonInfo{};
  clusterTruthTrackId = -1;
  eContrib = std::numeric_limits<float>::lowest();
  if (!rc || truthSignalByTrackId.empty()) return false;

  RawCluster* rc_nc = const_cast<RawCluster*>(rc);
  PHG4Particle* primary = clustereval.max_truth_primary_particle_by_energy(rc_nc);
  if (!primary) return false;

  clusterTruthTrackId = primary->get_track_id();
  eContrib = clustereval.get_energy_contribution(rc_nc, primary);

  const auto found = truthSignalByTrackId.find(clusterTruthTrackId);
  if (found == truthSignalByTrackId.end()) return false;

  matchedTruth = found->second;
  return true;
}

// -----------------------------------------------------------------------------
// Unified truth→reco photon matching using the PPG12 cluster_truthtrkID convention
// -----------------------------------------------------------------------------
bool RecoilJets::findRecoPhotonMatchedToTruthSignal(const TruthSignalPhotonMap& truthSignalByTrackId,
                                                    int targetTrackId,
                                                    CaloRawClusterEval& clustereval,
                                                    const RawCluster*& recoPho,
                                                    double& recoPt,
                                                    double& recoEta,
                                                    double& recoPhi,
                                                    double& drBest,
                                                    float& eContribBest) const
{
  recoPho       = nullptr;
  recoPt        = std::numeric_limits<double>::quiet_NaN();
  recoEta       = std::numeric_limits<double>::quiet_NaN();
  recoPhi       = std::numeric_limits<double>::quiet_NaN();
  drBest        = std::numeric_limits<double>::infinity();
  eContribBest  = std::numeric_limits<float>::lowest();

  if (!m_photons) return false;
  constexpr double kRecoEtaAbsMax = 0.7;
  constexpr double kRecoPtMinGeV = 5.0;
  const auto found = truthSignalByTrackId.find(targetTrackId);
  if (found == truthSignalByTrackId.end()) return false;
  const TruthSignalPhotonInfo& targetTruth = found->second;

  const auto prange = m_photons->getClusters();
  for (auto pit = prange.first; pit != prange.second; ++pit)
  {
    const auto* pho = dynamic_cast<const PhotonClusterv1*>(pit->second);
    if (!pho) continue;

    const RawCluster* rc = pho;

    double eta = pho->get_shower_shape_parameter("cluster_eta");
    double phi = TVector2::Phi_mpi_pi(pho->get_shower_shape_parameter("cluster_phi"));
    double pt  = pho->get_shower_shape_parameter("cluster_pt");

    if (!std::isfinite(eta) || !std::isfinite(phi) || !std::isfinite(pt)) continue;
    if (std::fabs(eta) >= kRecoEtaAbsMax) continue;
    if (pt <= kRecoPtMinGeV) continue;

    TruthSignalPhotonInfo matchedTruth;
    int clusterTruthTrackId = -1;
    float econtrib = std::numeric_limits<float>::lowest();
    if (!classifyRecoPhotonWithPPG12TruthTrack(rc, clustereval, truthSignalByTrackId,
                                               matchedTruth, clusterTruthTrackId, econtrib)) continue;
    if (clusterTruthTrackId != targetTrackId) continue;

    const double dphi = TVector2::Phi_mpi_pi(targetTruth.phi - phi);
    const double deta = targetTruth.eta - eta;
    const double dr   = std::sqrt(deta*deta + dphi*dphi);

    // Choose by largest energy contribution, tie-break by smallest ΔR
    bool take = false;
    if (!recoPho) take = true;
    else if (econtrib > eContribBest) take = true;
    else if (econtrib == eContribBest && dr < drBest) take = true;

    if (take)
    {
      recoPho       = rc;
      recoPt        = pt;
      recoEta       = eta;
      recoPhi       = phi;
      drBest        = dr;
      eContribBest  = econtrib;
    }
  }

  return (recoPho != nullptr);
}


const HepMC::GenParticle* RecoilJets::findHepMCParticleByBarcode(const HepMC::GenEvent* evt, int bc) const
{
    if (!evt) return nullptr;

    for (auto it = evt->particles_begin(); it != evt->particles_end(); ++it)
    {
      const HepMC::GenParticle* p = *it;
      if (p && p->barcode() == bc) return p;
    }

    return nullptr;
}




// ---------- E_T / centrality bin helpers ----------
int RecoilJets::findPtBin(double pt) const
{
  if (m_gammaPtBins.size() < 2)
  {
    if (Verbosity() >= 3)
      LOG(3, CLR_YELLOW, "  [findPtBin] pT bin edges vector has size < 2 – returning -1");
    return -1;
  }

  // Optional monotonicity check (diagnostic only)
  if (Verbosity() >= 6)
  {
    bool mono = std::is_sorted(m_gammaPtBins.begin(), m_gammaPtBins.end());
    if (!mono)
      LOG(6, CLR_YELLOW, "  [findPtBin] pT bin edges are NOT monotonic");
  }

  if (!std::isfinite(pt))
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW, "  [findPtBin] non-finite pT=" << pt << " – returning -1");
    return -1;
  }

  for (size_t i = 0; i + 1 < m_gammaPtBins.size(); ++i)
  {
    if (pt >= m_gammaPtBins[i] && pt < m_gammaPtBins[i + 1])
      return static_cast<int>(i);
  }

  if (Verbosity() >= 5)
    LOG(5, CLR_BLUE, "  [findPtBin] pT=" << pt << " out of configured range – returning -1");
  return -1;
}


int RecoilJets::findCentBin(int cent) const
{
  if (m_centEdges.size() < 2)
  {
    if (Verbosity() >= 3)
      LOG(3, CLR_YELLOW, "  [findCentBin] centrality edges vector has size < 2 – returning -1");
    return -1;
  }

  // Optional monotonicity check (diagnostic only)
  if (Verbosity() >= 6)
  {
    bool mono = std::is_sorted(m_centEdges.begin(), m_centEdges.end());
    if (!mono)
      LOG(6, CLR_YELLOW, "  [findCentBin] centrality edges are NOT monotonic");
  }

  for (size_t i = 0; i + 1 < m_centEdges.size(); ++i)
  {
    if (cent >= m_centEdges[i] && cent < m_centEdges[i + 1])
      return static_cast<int>(i);
  }

  if (Verbosity() >= 5)
    LOG(5, CLR_BLUE, "  [findCentBin] cent=" << cent << " out of configured range – returning -1");
  return -1;
}


// suffix: _ET_lo_hi  [ _cent_clo_chi only if isAuAu & centIdx>=0 ]
std::string RecoilJets::suffixForBins(int ptIdx, int centIdx) const
{
  std::ostringstream s;

  // Photon pT slicing (uses m_gammaPtBins as the configured pT bin edges)
  if (ptIdx >= 0) {
    const double lo = m_gammaPtBins[ptIdx];
    const double hi = m_gammaPtBins[ptIdx+1];
    s << "_pT_" << std::fixed << std::setprecision(0) << lo << '_' << hi;
  }

  // Centrality slicing (Au+Au only, and only if centIdx>=0)
  if (m_isAuAu && centIdx >= 0) {
    const int clo = m_centEdges[centIdx];
    const int chi = m_centEdges[centIdx+1];
    s << "_cent_" << clo << '_' << chi;
  }

  return s.str();
}

void RecoilJets::initEventDisplayDiagnosticsTree()
{
  if (!m_evtDiagEnabled)
  {
    if (Verbosity() >= 4)
    {
      LOG(4, CLR_CYAN, "[EventDisplayTree][init] skipped: m_evtDiagEnabled=false");
    }
    return;
  }

  if (m_evtDiagTree)
  {
    if (Verbosity() >= 5)
    {
      LOG(5, CLR_CYAN, "[EventDisplayTree][init] already exists: entries=" << m_evtDiagTree->GetEntries());
    }
    return;
  }

  if (!out)
  {
    LOG(1, CLR_YELLOW, "[EventDisplayTree][init] cannot create tree: output TFile pointer is null");
    m_evtDiagEnabled = false;
    return;
  }

  if (!out->IsOpen())
  {
    LOG(1, CLR_YELLOW, "[EventDisplayTree][init] cannot create tree: output file is not open (" << out->GetName() << ")");
    m_evtDiagEnabled = false;
    return;
  }

  if (!out->cd())
  {
    LOG(1, CLR_YELLOW, "[EventDisplayTree][init] cannot create tree: out->cd() failed (" << out->GetName() << ")");
    m_evtDiagEnabled = false;
    return;
  }

  if (Verbosity() >= 2)
  {
    LOG(2, CLR_CYAN, "[EventDisplayTree][init] creating EventDisplayTree in file: " << out->GetName());
  }

  m_evtDiagTree = new TTree("EventDisplayTree",
                            "EventDisplay diagnostics per event per jet radius (offline rendering)");

  if (!m_evtDiagTree)
  {
    LOG(1, CLR_YELLOW, "[EventDisplayTree][init] failed to allocate TTree (nullptr)");
    m_evtDiagEnabled = false;
    return;
  }

  m_evtDiagTree->SetDirectory(out);

  bool ok = true;

  auto AddLeaf = [&](const char* name, void* addr, const char* leaflist)
  {
    TBranch* br = m_evtDiagTree->Branch(name, addr, leaflist);
    if (!br)
    {
      ok = false;
      LOG(1, CLR_YELLOW, "[EventDisplayTree][init] Branch FAILED: \"" << name << "\" leaflist=\"" << leaflist << "\"");
    }
    else if (Verbosity() >= 6)
    {
      LOG(6, CLR_GREEN, "[EventDisplayTree][init] Branch OK: \"" << name << "\" title=\"" << br->GetTitle() << "\"");
    }
  };

  auto AddObj = [&](const char* name, auto* addr)
  {
    TBranch* br = m_evtDiagTree->Branch(name, addr);
    if (!br)
    {
      ok = false;
      LOG(1, CLR_YELLOW, "[EventDisplayTree][init] Branch FAILED: \"" << name << "\" (object)");
    }
    else if (Verbosity() >= 6)
    {
      LOG(6, CLR_GREEN, "[EventDisplayTree][init] Branch OK: \"" << name << "\" class=\"" << br->GetClassName() << "\"");
    }
  };

  AddLeaf("run", &m_evtDiag_run, "run/I");
  AddLeaf("evt", &m_evtDiag_evt, "evt/I");
  AddLeaf("event_count", &m_evtDiag_eventCount, "event_count/L");
  AddLeaf("vz", &m_evtDiag_vz, "vz/F");

  AddObj("rKey", &m_evtDiag_rKey);
  AddLeaf("ptBin", &m_evtDiag_ptBin, "ptBin/I");
  AddLeaf("cat", &m_evtDiag_cat, "cat/I");
  AddLeaf("isSim", &m_evtDiag_isSim, "isSim/I");

  AddLeaf("ptGammaTruth", &m_evtDiag_ptGammaTruth, "ptGammaTruth/F");
  AddLeaf("phiGammaTruth", &m_evtDiag_phiGammaTruth, "phiGammaTruth/F");
  AddLeaf("ptGammaReco", &m_evtDiag_ptGammaReco, "ptGammaReco/F");
  AddLeaf("etaGammaReco", &m_evtDiag_etaGammaReco, "etaGammaReco/F");
  AddLeaf("phiGammaReco", &m_evtDiag_phiGammaReco, "phiGammaReco/F");

  AddLeaf("sel_pt", &m_evtDiag_sel_pt, "sel_pt/F");
  AddLeaf("sel_eta", &m_evtDiag_sel_eta, "sel_eta/F");
  AddLeaf("sel_phi", &m_evtDiag_sel_phi, "sel_phi/F");

  AddLeaf("best_pt", &m_evtDiag_best_pt, "best_pt/F");
  AddLeaf("best_eta", &m_evtDiag_best_eta, "best_eta/F");
  AddLeaf("best_phi", &m_evtDiag_best_phi, "best_phi/F");

  AddLeaf("truthLead_pt", &m_evtDiag_truthLead_pt, "truthLead_pt/F");
  AddLeaf("truthLead_eta", &m_evtDiag_truthLead_eta, "truthLead_eta/F");
  AddLeaf("truthLead_phi", &m_evtDiag_truthLead_phi, "truthLead_phi/F");

  AddLeaf("drSelToTruthLead", &m_evtDiag_drSelToTruthLead, "drSelToTruthLead/F");
  AddLeaf("drBestToTruthLead", &m_evtDiag_drBestToTruthLead, "drBestToTruthLead/F");

  AddObj("sel_calo", &m_evtDiag_sel_calo);
  AddObj("sel_ieta", &m_evtDiag_sel_ieta);
  AddObj("sel_iphi", &m_evtDiag_sel_iphi);
  AddObj("sel_etaTower", &m_evtDiag_sel_etaTower);
  AddObj("sel_phiTower", &m_evtDiag_sel_phiTower);
  AddObj("sel_etTower", &m_evtDiag_sel_etTower);
  AddObj("sel_eTower", &m_evtDiag_sel_eTower);

  AddObj("best_calo", &m_evtDiag_best_calo);
  AddObj("best_ieta", &m_evtDiag_best_ieta);
  AddObj("best_iphi", &m_evtDiag_best_iphi);
  AddObj("best_etaTower", &m_evtDiag_best_etaTower);
  AddObj("best_phiTower", &m_evtDiag_best_phiTower);
  AddObj("best_etTower", &m_evtDiag_best_etTower);
  AddObj("best_eTower", &m_evtDiag_best_eTower);

  if (!ok)
  {
    LOG(1, CLR_YELLOW, "[EventDisplayTree][init] one or more Branch() calls failed; disabling EventDisplayTree (physics unaffected)");
    delete m_evtDiagTree;
    m_evtDiagTree = nullptr;
    m_evtDiagEnabled = false;
    return;
  }

  if (Verbosity() >= 2)
  {
    const int nBr = (m_evtDiagTree->GetListOfBranches() ? m_evtDiagTree->GetListOfBranches()->GetEntries() : -1);
    LOG(2, CLR_GREEN, "[EventDisplayTree][init] OK: booked EventDisplayTree with nBranches=" << nBr);
  }
}




void RecoilJets::resetEventDisplayDiagnosticsBuffers()
{
  m_evtDiag_run        = 0;
  m_evtDiag_evt        = 0;
  m_evtDiag_eventCount = 0;
  m_evtDiag_vz         = 0.0f;

  m_evtDiag_rKey.clear();
  m_evtDiag_ptBin = -1;
  m_evtDiag_cat   = -1;

  m_evtDiag_isSim = 0;

  m_evtDiag_ptGammaTruth  = -9999.0f;
  m_evtDiag_phiGammaTruth = -9999.0f;
  m_evtDiag_ptGammaReco   = -9999.0f;
  m_evtDiag_etaGammaReco  = -9999.0f;
  m_evtDiag_phiGammaReco  = -9999.0f;

  m_evtDiag_sel_pt  = -9999.0f;
  m_evtDiag_sel_eta = -9999.0f;
  m_evtDiag_sel_phi = -9999.0f;

  m_evtDiag_best_pt  = -9999.0f;
  m_evtDiag_best_eta = -9999.0f;
  m_evtDiag_best_phi = -9999.0f;

  m_evtDiag_truthLead_pt  = -9999.0f;
  m_evtDiag_truthLead_eta = -9999.0f;
  m_evtDiag_truthLead_phi = -9999.0f;

  m_evtDiag_drSelToTruthLead  = -1.0f;
  m_evtDiag_drBestToTruthLead = -1.0f;

  m_evtDiag_sel_calo.clear();
  m_evtDiag_sel_ieta.clear();
  m_evtDiag_sel_iphi.clear();
  m_evtDiag_sel_etaTower.clear();
  m_evtDiag_sel_phiTower.clear();
  m_evtDiag_sel_etTower.clear();
  m_evtDiag_sel_eTower.clear();

  m_evtDiag_best_calo.clear();
  m_evtDiag_best_ieta.clear();
  m_evtDiag_best_iphi.clear();
  m_evtDiag_best_etaTower.clear();
  m_evtDiag_best_phiTower.clear();
  m_evtDiag_best_etTower.clear();
  m_evtDiag_best_eTower.clear();
}

bool RecoilJets::eventDisplayDiagnosticsNeed(const std::string& rKey, int ptBin, EventDisplayCat cat)
{
  if (m_evtDiagMaxPerBin <= 0)
  {
    return true;
  }

  std::ostringstream oss;
  oss << rKey << "_ptBin" << ptBin << "_cat" << static_cast<int>(cat);
  const std::string key = oss.str();

  int& n = m_evtDiagSavedPerBin[key];
  if (n >= m_evtDiagMaxPerBin)
  {
    return false;
  }
  ++n;
  return true;
}

void RecoilJets::appendEventDisplayDiagnosticsFromJet(const Jet* jet,
                                                      std::vector<int>& calo,
                                                      std::vector<int>& ieta,
                                                      std::vector<int>& iphi,
                                                      std::vector<float>& eta,
                                                      std::vector<float>& phi,
                                                      std::vector<float>& et,
                                                      std::vector<float>& e) const
{
  if (!jet)
  {
    return;
  }

    auto handleComp = [&](const Jet::SRC src, const unsigned int idx)
    {
      TowerInfoContainer* towers = nullptr;
      RawTowerGeomContainer* geom = nullptr;
      RawTowerDefs::CalorimeterId caloId = RawTowerDefs::CalorimeterId::CEMC;
      int caloCode = -1;

      if (src == Jet::CEMC_TOWERINFO || src == Jet::CEMC_TOWERINFO_RETOWER)
      {
        towers = m_evtDispTowersCEMC;
        geom   = m_evtDispGeomCEMC;
        caloId = RawTowerDefs::CalorimeterId::CEMC;
        caloCode = 0;
      }
      else if (src == Jet::HCALIN_TOWERINFO)
      {
        towers = m_evtDispTowersIHCal;
        geom   = m_evtDispGeomIHCal;
        caloId = RawTowerDefs::CalorimeterId::HCALIN;
        caloCode = 1;
      }
      else if (src == Jet::HCALOUT_TOWERINFO)
      {
        towers = m_evtDispTowersOHCal;
        geom   = m_evtDispGeomOHCal;
        caloId = RawTowerDefs::CalorimeterId::HCALOUT;
        caloCode = 2;
      }
      else
      {
        return;
      }

      if (!towers || !geom)
      {
        return;
      }

      const auto nTowers = towers->size();
      if (nTowers == 0)
      {
        return;
      }

      // TowerJetInput stores TowerInfo constituents as CHANNEL indices.
      // Treat compid as channel only; never decode_key here (can segfault if misused).
      if (idx >= nTowers)
      {
        return;
      }

      TowerInfo* tower = towers->get_tower_at_channel(idx);
      if (!tower)
      {
        return;
      }

      const unsigned int calokey = towers->encode_key(idx);
      const int twr_ieta = towers->getTowerEtaBin(calokey);
      const int twr_iphi = towers->getTowerPhiBin(calokey);
      if (twr_ieta < 0 || twr_iphi < 0 || twr_ieta >= 4095 || twr_iphi >= 4095)
      {
        return;
      }

      RawTowerDefs::keytype key = RawTowerDefs::encode_towerid(caloId, twr_ieta, twr_iphi);
      RawTowerGeom* tower_geom = geom->get_tower_geometry(key);
      if (!tower_geom)
      {
        return;
      }

      const double x = tower_geom->get_center_x();
      const double y = tower_geom->get_center_y();
      const double r = std::sqrt(x * x + y * y);
      if (!(r > 0))
      {
        return;
      }

      const double tower_phi = std::atan2(y, x);

      const double eta0 = tower_geom->get_eta();
      const double z0 = std::sinh(eta0) * r;
      const double z = z0 - m_vz;
      const double tower_eta = std::asinh(z / r);

      const double E = tower->get_energy();
      const double Et = E / std::cosh(tower_eta);

      if (!std::isfinite(Et))
      {
        return;
      }

      calo.push_back(caloCode);
      ieta.push_back(twr_ieta);
      iphi.push_back(twr_iphi);
      eta.push_back(static_cast<float>(tower_eta));
      phi.push_back(static_cast<float>(tower_phi));
      et.push_back(static_cast<float>(Et));
      e.push_back(static_cast<float>(E));
    };

    Jet* jetNC = const_cast<Jet*>(jet);
    Jet::TYPE_comp_vec& compVec = jetNC->get_comp_vec();

    if (!compVec.empty())
    {
      for (const auto& comp : compVec)
      {
        handleComp(comp.first, comp.second);
      }
    }
    else
    {
      for (auto it = jet->begin_comp(); it != jet->end_comp(); ++it)
      {
        handleComp(it->first, it->second);
      }
    }
}

void RecoilJets::fillEventDisplayDiagnostics(const std::string& rKey,
                                             int ptBin,
                                             EventDisplayCat cat,
                                             double truthGammaPt,
                                             double truthGammaPhi,
                                             double recoGammaPt,
                                             double recoGammaEta,
                                             double recoGammaPhi,
                                             const Jet* selectedRecoilJet,
                                             const Jet* recoTruthBest,
                                             const Jet* truthLeadRecoilJet)
{
    if (!m_evtDiagEnabled || !m_evtDiagNodesReady)
    {
        return;
    }

    initEventDisplayDiagnosticsTree();
    if (!m_evtDiagTree)
    {
        return;
    }

    resetEventDisplayDiagnosticsBuffers();

    if (m_evtHeader)
    {
        m_evtDiag_run = currentRunNumber();
        m_evtDiag_evt = m_evtHeader->get_EvtSequence();
    }
    m_evtDiag_eventCount = event_count;
    m_evtDiag_vz = static_cast<float>(m_vz);

    m_evtDiag_rKey   = rKey;
    m_evtDiag_ptBin  = ptBin;
    m_evtDiag_cat    = static_cast<int>(cat);
    m_evtDiag_isSim  = (m_isSim ? 1 : 0);

    m_evtDiag_ptGammaReco   = static_cast<float>(recoGammaPt);
    m_evtDiag_etaGammaReco  = static_cast<float>(recoGammaEta);
    m_evtDiag_phiGammaReco  = static_cast<float>(recoGammaPhi);

    if (m_isSim)
    {
        m_evtDiag_ptGammaTruth  = static_cast<float>(truthGammaPt);
        m_evtDiag_phiGammaTruth = static_cast<float>(truthGammaPhi);
    }
    else
    {
        m_evtDiag_ptGammaTruth  = -9999.0f;
        m_evtDiag_phiGammaTruth = -9999.0f;
    }

    if (selectedRecoilJet)
    {
        m_evtDiag_sel_pt  = static_cast<float>(selectedRecoilJet->get_pt());
        m_evtDiag_sel_eta = static_cast<float>(selectedRecoilJet->get_eta());
        m_evtDiag_sel_phi = static_cast<float>(selectedRecoilJet->get_phi());
    }

    if (m_isSim && recoTruthBest)
    {
        m_evtDiag_best_pt  = static_cast<float>(recoTruthBest->get_pt());
        m_evtDiag_best_eta = static_cast<float>(recoTruthBest->get_eta());
        m_evtDiag_best_phi = static_cast<float>(recoTruthBest->get_phi());
    }

    if (m_isSim && truthLeadRecoilJet)
    {
        m_evtDiag_truthLead_pt  = static_cast<float>(truthLeadRecoilJet->get_pt());
        m_evtDiag_truthLead_eta = static_cast<float>(truthLeadRecoilJet->get_eta());
        m_evtDiag_truthLead_phi = static_cast<float>(truthLeadRecoilJet->get_phi());
    }

    auto dR = [](double eta1, double phi1, double eta2, double phi2)
    {
        const double dphi = TVector2::Phi_mpi_pi(phi1 - phi2);
        const double deta = eta1 - eta2;
        return std::sqrt(deta * deta + dphi * dphi);
    };

    if (m_isSim && selectedRecoilJet && truthLeadRecoilJet)
    {
        m_evtDiag_drSelToTruthLead = static_cast<float>(dR(selectedRecoilJet->get_eta(),
                                                           selectedRecoilJet->get_phi(),
                                                           truthLeadRecoilJet->get_eta(),
                                                           truthLeadRecoilJet->get_phi()));
    }

    if (m_isSim && recoTruthBest && truthLeadRecoilJet)
    {
        m_evtDiag_drBestToTruthLead = static_cast<float>(dR(recoTruthBest->get_eta(),
                                                            recoTruthBest->get_phi(),
                                                            truthLeadRecoilJet->get_eta(),
                                                            truthLeadRecoilJet->get_phi()));
    }

    const Jet* selForTowers  = selectedRecoilJet;
    const Jet* bestForTowers = recoTruthBest;

    auto mapCalibToRawForTowers = [&](const Jet* calibJet) -> const Jet*
    {
        if (!calibJet) return nullptr;

        const std::string jetRKey = baseRKeyFromDphiHistKey(rKey);
        auto itCal = m_jets.find(jetRKey);
        auto itRaw = m_jetsRaw.find(jetRKey);
        if (itCal == m_jets.end() || !itCal->second) return nullptr;
        if (itRaw == m_jetsRaw.end() || !itRaw->second) return nullptr;

        JetContainer* calib = itCal->second;
        JetContainer* raw   = itRaw->second;

        // Require RAW constituents; otherwise tower payload will be empty.
        auto hasConstituents = [&](const Jet* j) -> bool
        {
            return (j && (j->size_comp() > 0));
        };

        // 1) Primary: ID-based mapping (JetCalib sets calibrated jet id in the same loop as raw jets).
        const int idC = static_cast<int>(calibJet->get_id());
        if (idC >= 0)
        {
            for (const Jet* jr : *raw)
            {
                if (!jr) continue;
                if (static_cast<int>(jr->get_id()) != idC) continue;
                if (!hasConstituents(jr)) continue;
                return jr;
            }
        }

        // 2) Secondary: index-preserving mapping (if id is not reliable in this container).
        int idx = -1;
        int i = 0;
        for (const Jet* jc : *calib)
        {
            if (jc == calibJet)
            {
                idx = i;
                break;
            }
            ++i;
        }

        if (idx >= 0)
        {
            int j = 0;
            for (const Jet* jr : *raw)
            {
                if (j == idx)
                {
                    if (hasConstituents(jr))
                    {
                        return jr;
                    }
                    break;
                }
                ++j;
            }
        }

        // 3) Fallback: closest-in-ΔR match in RAW container (only if ordering/id differ).
        const double etaC = calibJet->get_eta();
        const double phiC = calibJet->get_phi();

        const Jet* best = nullptr;
        double bestDR2  = 1e9;

        for (const Jet* jr : *raw)
        {
            if (!hasConstituents(jr)) continue;

            const double deta = (jr->get_eta() - etaC);
            const double dphi = TVector2::Phi_mpi_pi(jr->get_phi() - phiC);
            const double dr2  = deta*deta + dphi*dphi;

            if (dr2 < bestDR2)
            {
                bestDR2 = dr2;
                best = jr;
            }
        }

        return best;
    };

    if (const Jet* jr = mapCalibToRawForTowers(selectedRecoilJet)) selForTowers = jr;
    if (const Jet* jr = mapCalibToRawForTowers(recoTruthBest))     bestForTowers = jr;

    appendEventDisplayDiagnosticsFromJet(selForTowers,
                                         m_evtDiag_sel_calo,
                                         m_evtDiag_sel_ieta,
                                         m_evtDiag_sel_iphi,
                                         m_evtDiag_sel_etaTower,
                                         m_evtDiag_sel_phiTower,
                                         m_evtDiag_sel_etTower,
                                         m_evtDiag_sel_eTower);

    appendEventDisplayDiagnosticsFromJet(bestForTowers,
                                         m_evtDiag_best_calo,
                                         m_evtDiag_best_ieta,
                                         m_evtDiag_best_iphi,
                                         m_evtDiag_best_etaTower,
                                         m_evtDiag_best_phiTower,
                                         m_evtDiag_best_etTower,
                                         m_evtDiag_best_eTower);
    const bool hasSelTowers  = !m_evtDiag_sel_etTower.empty();
    const bool hasBestTowers = !m_evtDiag_best_etTower.empty();
    const bool hasAnyTowers  = (hasSelTowers || hasBestTowers);

    // If we failed to capture tower constituents, do NOT write a diagnostics entry.
    // This prevents blank/empty event display PNGs.
    if (!hasAnyTowers)
    {
        if (Verbosity() >= 1)
        {
            LOG(1, CLR_YELLOW,
                "[EventDisplayTree][skip] empty tower payload (no constituents) "
                << "(event_count=" << event_count
                << " rKey=" << rKey
                << " ptBin=" << ptBin
                << " cat=" << static_cast<int>(cat) << ")");
        }
        return;
    }

    ++m_evtDiagNFill;

    const int icat = static_cast<int>(cat);
    if (icat >= 0 && icat < 3)
    {
        ++m_evtDiagNFillByCat[icat];
        if (hasAnyTowers) ++m_evtDiagNFillWithAnyTowersByCat[icat];
    }

    if (hasSelTowers)  ++m_evtDiagNFillWithSelTowers;
    if (hasBestTowers) ++m_evtDiagNFillWithBestTowers;
    if (hasAnyTowers)  ++m_evtDiagNFillWithAnyTowers;

    if (Verbosity() >= 1)
    {
        LOG(1, CLR_CYAN,
            "[EventDisplayTree][Fill][PHASE A] about to Fill() "
            << "(event_count=" << event_count
            << " rKey=" << rKey
            << " ptBin=" << ptBin
            << " cat=" << static_cast<int>(cat)
            << " nSelTowers=" << m_evtDiag_sel_etTower.size()
            << " nBestTowers=" << m_evtDiag_best_etTower.size() << ")");
    }

    m_evtDiagTree->Fill();

    if (Verbosity() >= 1)
    {
        LOG(1, CLR_GREEN,
            "[EventDisplayTree][Fill][PHASE B] returned from Fill()");
    }
}



TH1I* RecoilJets::getOrBookCountHist(const std::string& trig,
                                     const std::string& base,
                                     int etIdx, int centIdx,
                                     HistViewScope scope)
{
    const std::string suffix = suffixForBins(etIdx, centIdx);
    const std::string name   = histBaseForScope(base, scope) + suffix;

    if (Verbosity() >= 5)
        LOG(5, CLR_BLUE, "  [getOrBookCountHist] trig=\"" << trig << "\" base=\"" << base
            << "\" etIdx=" << etIdx << " centIdx=" << centIdx
            << " → name=\"" << name << "\"");

    if (trig.empty() || base.empty())
    {
        LOG(2, CLR_YELLOW, "  [getOrBookCountHist] empty trig/base (trig=\"" << trig
            << "\", base=\"" << base << "\") – returning nullptr");
        return nullptr;
    }

    // Map slot
    auto& H = qaHistogramsByTrigger[trig];

    // If already booked, verify type and return
    if (auto it = H.find(name); it != H.end())
    {
        if (auto* h = dynamic_cast<TH1I*>(it->second))
        {
            if (Verbosity() >= 6)
                LOG(6, CLR_GREEN, "    [getOrBookCountHist] reusing existing TH1I \"" << name << "\"");
            return h;
        }
        LOG(2, CLR_YELLOW, "    [getOrBookCountHist] name clash: object \"" << name
            << "\" exists but is not TH1I – replacing it");
        H.erase(it);
    }

    // Safety: output file & directory
    if (!out || !out->IsOpen())
    {
        LOG(1, CLR_YELLOW, "  [getOrBookCountHist] output TFile invalid/null – returning nullptr");
        return nullptr;
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir)
    {
        if (Verbosity() >= 4) LOG(4, CLR_BLUE, "    [getOrBookCountHist] creating directory \"" << trig << '"');
        dir = out->mkdir(trig.c_str());
    }
    if (!dir)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookCountHist] failed to create/access directory \"" << trig << "\"");
        if (prevDir) prevDir->cd();
        return nullptr;
    }

    dir->cd();

    // This booking helper serves both physics counts and diagnostic counters.
    // ABCD/purity/xJ counts remain weighted; finite/missing and cut-failure
    // diagnostics are explicitly raw so they cannot be mistaken for PPG12
    // weighted observables.
    const bool rawDiagnostic =
        base.rfind("h_npbScore_", 0) == 0 ||
        base.rfind("h_tightBDTScore_", 0) == 0 ||
        base.rfind("h_preRefFail", 0) == 0 ||
        base.rfind("h_preRefMatrix_", 0) == 0 ||
        base.rfind("h_preFail", 0) == 0 ||
        base.rfind("h_tightFail", 0) == 0;

    auto bookCount = [&](const char* title, int nbins, double xmin, double xmax) -> TH1I*
    {
        return rawDiagnostic
            ? RJMCWeighting::RJNewRawTH1I(name.c_str(), title, nbins, xmin, xmax)
            : RJMCWeighting::RJNewTH1I(name.c_str(), title, nbins, xmin, xmax);
    };

    if (base == "h_preFailMask" || base.rfind("h_preRefFailMask_", 0) == 0)
    {
        const std::string title = name + ";preselection fail mask;entries";

        if (Verbosity() >= 5)
            LOG(5, CLR_BLUE, "    [getOrBookCountHist] booking TH1I name=\"" << name << "\" title=\"" << title << '"');

        auto* h = bookCount(title.c_str(), 16, -0.5, 15.5);
        if (!h)
        {
            LOG(1, CLR_YELLOW, "  [getOrBookCountHist] new TH1I failed for \"" << name << '"');
            if (prevDir) prevDir->cd();
            return nullptr;
        }

        const char* labels[16] = {
            "pass",
            "e11",
            "et1",
            "e11+et1",
            "e32",
            "e11+e32",
            "et1+e32",
            "e11+et1+e32",
            "weta",
            "e11+weta",
            "et1+weta",
            "e11+et1+weta",
            "e32+weta",
            "e11+e32+weta",
            "et1+e32+weta",
            "all4"
        };

        for (int ib = 0; ib < 16; ++ib)
            h->GetXaxis()->SetBinLabel(ib + 1, labels[ib]);

        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
    }

    if (base.rfind("h_tightFailMask_", 0) == 0)
    {
        const std::string title = name + ";tight fail mask;entries";

        if (Verbosity() >= 5)
            LOG(5, CLR_BLUE, "    [getOrBookCountHist] booking TH1I name=\"" << name << "\" title=\"" << title << '"');

        auto* h = bookCount(title.c_str(), 32, -0.5, 31.5);
        if (!h)
        {
            LOG(1, CLR_YELLOW, "  [getOrBookCountHist] new TH1I failed for \"" << name << '"');
            if (prevDir) prevDir->cd();
            return nullptr;
        }

        const char* labels[32] = {
            "pass",
            "weta",
            "wphi",
            "weta+wphi",
            "e11",
            "weta+e11",
            "wphi+e11",
            "weta+wphi+e11",
            "et1",
            "weta+et1",
            "wphi+et1",
            "weta+wphi+et1",
            "e11+et1",
            "weta+e11+et1",
            "wphi+e11+et1",
            "weta+wphi+e11+et1",
            "e32",
            "weta+e32",
            "wphi+e32",
            "weta+wphi+e32",
            "e11+e32",
            "weta+e11+e32",
            "wphi+e11+e32",
            "weta+wphi+e11+e32",
            "et1+e32",
            "weta+et1+e32",
            "wphi+et1+e32",
            "weta+wphi+et1+e32",
            "e11+et1+e32",
            "weta+e11+et1+e32",
            "wphi+e11+et1+e32",
            "all5"
        };

        for (int ib = 0; ib < 32; ++ib)
            h->GetXaxis()->SetBinLabel(ib + 1, labels[ib]);

        H[name] = h;

        if (prevDir) prevDir->cd();
        return h;
    }

    const std::string title = name + ";count;entries";
    if (Verbosity() >= 5)
        LOG(5, CLR_BLUE, "    [getOrBookCountHist] booking TH1I name=\"" << name << "\" title=\"" << title << '"');

    auto* h = bookCount(title.c_str(), 1, 0.5, 1.5);
    if (!h)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookCountHist] new TH1I failed for \"" << name << '"');
        if (prevDir) prevDir->cd();
        return nullptr;
    }
    h->GetXaxis()->SetBinLabel(1,"count");
    H[name] = h;

    if (prevDir) prevDir->cd();
    return h;
}

TH1F* RecoilJets::getOrBookBDTScoreHist(const std::string& trig,
                                        const std::string& base,
                                        int etIdx, int centIdx)
{
  const std::string suffix = suffixForBins(etIdx, centIdx);
  const std::string name = histBaseForScope(base, HistViewScope::Canonical) + suffix;

  if (trig.empty() || base.empty()) return nullptr;

  auto& H = qaHistogramsByTrigger[trig];
  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir)
  {
    if (prevDir) prevDir->cd();
    return nullptr;
  }

  dir->cd();
  const std::string title = name + ";BDT score;Entries";
  const bool rawDiagnostic =
      base.rfind("h_npbScore_", 0) == 0 ||
      base.rfind("h_tightBDTScore_", 0) == 0;
  auto* h = rawDiagnostic
      ? RJMCWeighting::RJNewRawTH1F(name.c_str(), title.c_str(), 120, -1.05, 1.05)
      : RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), 120, -1.05, 1.05);
  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}


