void RecoilJets::bookPPG12PhotonYieldSchema(const std::vector<std::string>& activeTrig)
{
    if (!m_ppg12PhotonYieldEnabled) return;
    if (!out || !out->IsOpen()) return;

    static const char* recoObjects[] = {
        "h_all_cluster_0",
        "h_common_cluster_0",
        "h_all_cluster_signal_0",
        "h_all_cluster_notmatch_0",
        "h_common_cluster_signal_0",
        "h_common_cluster_notmatch_0",
        "h_tight_cluster_0",
        "h_tight_cluster_signal_0",
        "h_tight_cluster_notmatch_0",
        "h_tight_iso_cluster_0",
        "h_tight_iso_cluster_signal_0",
        "h_tight_iso_cluster_notmatch_0",
        "h_tight_noniso_cluster_0",
        "h_tight_noniso_cluster_signal_0",
        "h_tight_noniso_cluster_notmatch_0",
        "h_nontight_iso_cluster_0",
        "h_nontight_iso_cluster_signal_0",
        "h_nontight_iso_cluster_notmatch_0",
        "h_nontight_noniso_cluster_0",
        "h_nontight_noniso_cluster_signal_0",
        "h_nontight_noniso_cluster_notmatch_0",
        "h_pT_reco_response_0",
        "h_pT_reco_half_response_0",
        "h_pT_reco_secondhalf_response_0",
        "h_pT_reco_fake_0",
        "h_ppg12_fig36_pT_reco_response_prior_0",
        "h_ppg12_fig37_input_reco_pT_0",
        "h_ppg12_fig37_input_reco_half_pT_0",
        "h_ppg12_fig37_input_reco_secondhalf_pT_0",
        "h_ppg12_fig37_input_fake_pT_0"
    };

    static const char* truthObjects[] = {
        "h_truth_pT_0",
        "h_truth_pT_novtx_0",
        "h_truth_pT_vertexcut_0",
        "h_truth_pT_vertexcut_mbd_cut_0",
        "h_truth_pT_vertexcut_mbd_north_cut_0",
        "h_truth_pT_vertexcut_mbd_south_cut_0",
        "h_photonEffTruthDen_pTgamma_0",
        "h_photonEffReco_pTgamma_0",
        "h_photonEffRecoTight_pTgamma_0",
        "h_photonEffRecoIso_pTgamma_0",
        "h_photonEffRecoTightIso_pTgamma_0",
        "h_photonEffPpg12Fig6TruthDen_pTgamma_0",
        "h_photonEffPpg12Fig6Reco_pTgamma_0",
        "h_photonEffPpg12Fig6RecoTight_pTgamma_0",
        "h_photonEffPpg12Fig6RecoIso_pTgamma_0",
        "h_photonEffPpg12Fig6RecoTightIso_pTgamma_0",
        "h_pT_truth_response_0",
        "h_pT_truth_half_response_0",
        "h_pT_truth_secondhalf_response_0",
        "h_ppg12_fig36_pT_truth_response_prior_0",
        "h_ppg12_fig37_input_truth_pT_0",
        "h_ppg12_fig37_input_truth_half_pT_0",
        "h_ppg12_fig37_input_truth_secondhalf_pT_0"
    };

    // Keep the response contracts separated:
    //   h_response_*                         : current inclusive-yield response, no PPG12 truth-prior multiplier.
    //   h2_ppg12_fig36_*_prior_*             : PPG12 Fig.36 reproduction, truth-prior applied during fill.
    //   h2_ppg12_fig37_input_*               : current analysis / xJgamma normalization response inputs.
    static const char* responseObjects[] = {
        "h_response_full_0",
        "h_response_half_0",
        "h2_ppg12_fig36_response_reco_truth_prior_0",
        "h2_ppg12_fig36_response_half_reco_truth_prior_0",
        "h2_ppg12_fig37_input_response_reco_truth_0",
        "h2_ppg12_fig37_input_response_half_reco_truth_0"
    };

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;
        if (!m_ppg12PhotonYieldSchemaBookedTriggers.insert(trigShort).second) continue;

        getOrBookPPG12VertexQAAuditHist(trigShort);
        getOrBookPPG12PeriodContractValues(trigShort);

        for (const char* name : recoObjects)
        {
            getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                        "p_{T}^{#gamma,reco} [GeV]", "Entries");
        }
        for (const char* name : truthObjects)
        {
            getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldTruthPtBins,
                                        "p_{T}^{#gamma,truth} [GeV]", "Entries");
        }
        for (const char* name : responseObjects)
        {
            getOrBookPPG12PhotonYieldResponse2D(trigShort, name);
        }
        if (m_isSim && !m_isAuAu)
        {
            getOrBookPPG12Fig37LeadTagInput1D(trigShort,
                                              "h_ppg12_fig37_input_leadtag_reco_pT_0",
                                              m_unfoldRecoPhotonPtBins,
                                              "p_{T}^{#gamma,reco} [GeV]",
                                              "Reco photons");
            getOrBookPPG12Fig37LeadTagInput1D(trigShort,
                                              "h_ppg12_fig37_input_leadtag_fake_pT_0",
                                              m_unfoldRecoPhotonPtBins,
                                              "p_{T}^{#gamma,reco} [GeV]",
                                              "Reco fakes");
            getOrBookPPG12Fig37LeadTagInput1D(trigShort,
                                              "h_ppg12_fig37_input_leadtag_truth_pT_0",
                                              m_unfoldTruthPhotonPtBins,
                                              "p_{T}^{#gamma,truth} [GeV]",
                                              "Truth photons");
            getOrBookPPG12Fig37LeadTagInput1D(trigShort,
                                              "h_ppg12_fig37_input_leadtag_miss_pT_0",
                                              m_unfoldTruthPhotonPtBins,
                                              "p_{T}^{#gamma,truth} [GeV]",
                                              "Truth misses");
            getOrBookPPG12Fig37LeadTagResponse2D(trigShort,
                                                 "h2_ppg12_fig37_input_leadtag_response_truth_reco_0");
            getOrBookPPG12Fig8Response2D(trigShort,
                                         "h2_ppg12_fig8_respET_vs_truthET_reco_vz30_eta07",
                                         "E_{T}^{cluster} / E_{T}^{#gamma,truth}");
            getOrBookPPG12Fig8Response2D(trigShort,
                                         "h2_ppg12_fig8_respE_vs_truthET_reco_vz30_eta07",
                                         "E^{cluster} / E^{#gamma,truth}");
            getOrBookPPG12Fig8Primitive2D(trigShort,
                                          "h2_ppg12_fig8_Etruth_Ecluster_reco_vz30_eta07",
                                          "E^{#gamma,truth} [GeV]",
                                          "E^{cluster} [GeV]");
            getOrBookPPG12Fig8Primitive2D(trigShort,
                                          "h2_ppg12_fig8_Ettruth_Etcluster_reco_vz30_eta07",
                                          "E_{T}^{#gamma,truth} [GeV]",
                                          "E_{T}^{cluster} [GeV]");
            getOrBookPPG12Fig8AuditHist(trigShort);
        }
    }
}

void RecoilJets::fillPPG12Fig8ResponseTargets(const std::vector<std::string>& activeTrig,
                                              CaloRawClusterEval& clustereval,
                                              const TruthSignalPhotonMap& truthSignalByTrackId)
{
    if (!m_ppg12PhotonYieldEnabled || !m_isSim || m_isAuAu) return;
    if (activeTrig.empty()) return;

    bookPPG12PhotonYieldSchema(activeTrig);

    auto fillAudit = [&](int bin)
    {
      for (const auto& trigShort : activeTrig)
      {
        if (auto* h = getOrBookPPG12Fig8AuditHist(trigShort))
        {
          h->Fill(bin);
          bumpHistFill(trigShort, h->GetName());
          if (m_replayFoundationEnabled)
          {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = trigShort;
            row.occurrence_kind = "FIG8_AUDIT";
            row.stage_code = bin;
            row.occurrence_weight = RJMCWeighting::SafeWeight();
            m_replayPPG12DiagnosticOccurrences.push_back(row);
          }
        }
      }
    };

    fillAudit(1);

    if (!std::isfinite(m_vz) || std::fabs(m_vz) >= kPPG12Fig8VertexAbsMax) return;
    fillAudit(2);

    RawClusterContainer* fig8Clusters = m_ppg12Fig8Clusters;
    bool usingFallbackSplitNode = false;
    if (!fig8Clusters && m_ppg12Fig8UseFallbackClusterNode)
    {
      fig8Clusters = m_clus;
      usingFallbackSplitNode = (fig8Clusters != nullptr);
    }
    if (fig8Clusters == m_clus && m_ppg12Fig8ClusterNode != kPPG12Fig8FallbackClusterNode)
    {
      usingFallbackSplitNode = true;
    }

    if (!fig8Clusters)
    {
      fillAudit(10);
      return;
    }
    fillAudit(3);
    fillAudit(usingFallbackSplitNode ? 5 : 4);

    constexpr double fillWeight = 1.0;
    const CLHEP::Hep3Vector clusterVertex(0.0, 0.0, ppg12PhotonYieldKinematicVertexZ());
    const auto crange = fig8Clusters->getClusters();
    int clusterOrdinal = 0;
    for (auto cit = crange.first; cit != crange.second; ++cit)
    {
      const RawCluster* rc = cit->second;
      if (!rc) continue;
      const int currentClusterOrdinal = clusterOrdinal++;
      fillAudit(6);

      TruthSignalPhotonInfo matchedTruth;
      int clusterTruthTrackId = -1;
      float eContrib = std::numeric_limits<float>::lowest();
      if (!classifyRecoPhotonWithPPG12TruthTrack(rc, clustereval,
                                                 truthSignalByTrackId,
                                                 matchedTruth,
                                                 clusterTruthTrackId,
                                                 eContrib))
      {
        continue;
      }
      fillAudit(7);

      if (!std::isfinite(matchedTruth.pt) || matchedTruth.pt <= 0.0 ||
          !std::isfinite(matchedTruth.eta) ||
          std::fabs(matchedTruth.eta) >= kPPG12Fig8TruthEtaAbsMax)
      {
        continue;
      }

      const double clusterEnergy = rc->get_energy();
      const double clusterEta = RawClusterUtility::GetPseudorapidity(*rc, clusterVertex);
      const double clusterEt =
          (std::isfinite(clusterEnergy) && std::isfinite(clusterEta))
              ? clusterEnergy / std::cosh(clusterEta)
              : std::numeric_limits<double>::quiet_NaN();
      if (!std::isfinite(clusterEt) || clusterEt < kPPG12Fig8RecoEtMin) continue;
      fillAudit(8);

      const double truthEt = matchedTruth.pt;
      double truthEnergy = std::numeric_limits<double>::quiet_NaN();
      if (matchedTruth.g4)
      {
        truthEnergy = matchedTruth.g4->get_e();
      }
      if ((!std::isfinite(truthEnergy) || truthEnergy <= 0.0) && matchedTruth.hep)
      {
        truthEnergy = matchedTruth.hep->momentum().e();
      }
      if (!std::isfinite(truthEnergy) || truthEnergy <= 0.0)
      {
        truthEnergy = truthEt * std::cosh(matchedTruth.eta);
      }

      const double respEt = clusterEt / truthEt;
      const double respE = clusterEnergy / truthEnergy;
      if (!std::isfinite(respEt) || !std::isfinite(respE) ||
          !std::isfinite(truthEt) || !std::isfinite(truthEnergy) ||
          !std::isfinite(clusterEnergy))
      {
        continue;
      }

      for (const auto& trigShort : activeTrig)
      {
        if (auto* h = getOrBookPPG12Fig8Response2D(trigShort,
                                                   "h2_ppg12_fig8_respET_vs_truthET_reco_vz30_eta07",
                                                   "E_{T}^{cluster} / E_{T}^{#gamma,truth}"))
        {
          h->Fill(truthEt, respEt, fillWeight);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12Fig8Response2D(trigShort,
                                                   "h2_ppg12_fig8_respE_vs_truthET_reco_vz30_eta07",
                                                   "E^{cluster} / E^{#gamma,truth}"))
        {
          h->Fill(truthEt, respE, fillWeight);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12Fig8Primitive2D(trigShort,
                                                    "h2_ppg12_fig8_Etruth_Ecluster_reco_vz30_eta07",
                                                    "E^{#gamma,truth} [GeV]",
                                                    "E^{cluster} [GeV]"))
        {
          h->Fill(truthEnergy, clusterEnergy, fillWeight);
          bumpHistFill(trigShort, h->GetName());
        }
        if (auto* h = getOrBookPPG12Fig8Primitive2D(trigShort,
                                                    "h2_ppg12_fig8_Ettruth_Etcluster_reco_vz30_eta07",
                                                    "E_{T}^{#gamma,truth} [GeV]",
                                                    "E_{T}^{cluster} [GeV]"))
        {
          h->Fill(truthEt, clusterEt, fillWeight);
          bumpHistFill(trigShort, h->GetName());
        }
        if (m_replayFoundationEnabled)
        {
          ReplayPPG12DiagnosticOccurrence row;
          row.trigger = trigShort;
          row.occurrence_kind = "FIG8_CLUSTER";
          row.cluster_ordinal = currentClusterOrdinal;
          row.truth_track_id = clusterTruthTrackId;
          row.generator_barcode = matchedTruth.barcode;
          row.cluster_energy = clusterEnergy;
          row.cluster_eta = clusterEta;
          row.cluster_et = clusterEt;
          row.truth_energy = truthEnergy;
          row.truth_eta = matchedTruth.eta;
          row.truth_et = truthEt;
          row.energy_contribution = static_cast<double>(eContrib);
          row.occurrence_weight = fillWeight * RJMCWeighting::SafeWeight();
          m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
      }
      fillAudit(9);
    }
}

void RecoilJets::fillPPG12PhotonYieldAllCommon(const std::vector<std::string>& activeTrig,
                                               double ptGamma,
                                               bool commonPass,
                                              bool haveTruthClass,
                                              bool isTruthSignal,
                                              double weight,
                                              bool signalResponseWindow,
                                              bool fillInclusive)
{
    if (!m_ppg12PhotonYieldEnabled) return;
    bookPPG12PhotonYieldSchema(activeTrig);
    if (!std::isfinite(ptGamma) || ptGamma <= 0.0) return;

    auto fillOne = [&](const std::string& trigShort, const std::string& name)
    {
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                                  "p_{T}^{#gamma,reco} [GeV]", "Entries"))
        {
            h->Fill(ptGamma, weight);
            bumpHistFill(trigShort, name);
        }
    };

    for (const auto& trigShort : activeTrig)
    {
        if (m_replayFoundationEnabled)
        {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = trigShort;
            row.occurrence_kind = "PHOTON_ALL_COMMON";
            row.reco_photon_pt = ptGamma;
            row.occurrence_weight = weight * RJMCWeighting::SafeWeight();
            row.selection_bitmask =
                (commonPass ? 1ULL : 0ULL) |
                (haveTruthClass ? 2ULL : 0ULL) |
                (isTruthSignal ? 4ULL : 0ULL) |
                (signalResponseWindow ? 8ULL : 0ULL) |
                (fillInclusive ? 16ULL : 0ULL);
            m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
        if (fillInclusive)
        {
            fillOne(trigShort, "h_all_cluster_0");
            if (commonPass) fillOne(trigShort, "h_common_cluster_0");
        }

        if (haveTruthClass)
        {
            if (!isTruthSignal || signalResponseWindow)
            {
                fillOne(trigShort, isTruthSignal ? "h_all_cluster_signal_0" : "h_all_cluster_notmatch_0");
                if (commonPass) fillOne(trigShort, isTruthSignal ? "h_common_cluster_signal_0" : "h_common_cluster_notmatch_0");
            }
        }
    }
}

void RecoilJets::fillPPG12PhotonYieldTightAndABCD(const std::vector<std::string>& activeTrig,
                                                  double ptGamma,
                                                  double responsePtGamma,
                                                  double truthPt,
                                                  RecoilJets::TightTag tightTag,
                                                  bool iso,
                                                  bool nonIso,
                                                  bool haveTruthClass,
                                                  bool isTruthSignal,
                                                  double weight,
                                                  bool fillInclusive)
{
    if (!m_ppg12PhotonYieldEnabled) return;
    bookPPG12PhotonYieldSchema(activeTrig);
    if (!std::isfinite(ptGamma) || ptGamma <= 0.0) return;

    auto fillReco = [&](const std::string& trigShort, const std::string& name)
    {
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                                  "p_{T}^{#gamma,reco} [GeV]", "Entries"))
        {
            h->Fill(ptGamma, weight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillTruth = [&](const std::string& trigShort, const std::string& name)
    {
        if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldTruthPtBins,
                                                  "p_{T}^{#gamma,truth} [GeV]", "Entries"))
        {
            h->Fill(truthPt, weight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillTruthWithExtraWeight = [&](const std::string& trigShort,
                                        const std::string& name,
                                        const double extraWeight)
    {
        if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
        if (!std::isfinite(extraWeight)) return;
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldTruthPtBins,
                                                  "p_{T}^{#gamma,truth} [GeV]", "Entries"))
        {
            h->Fill(truthPt, weight * extraWeight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillRecoWithExtraWeight = [&](const std::string& trigShort,
                                       const std::string& name,
                                       const double extraWeight)
    {
        if (!std::isfinite(responsePtGamma) || responsePtGamma <= 0.0) return;
        if (!std::isfinite(extraWeight)) return;
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                                  "p_{T}^{#gamma,reco} [GeV]", "Entries"))
        {
            h->Fill(responsePtGamma, weight * extraWeight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillResponseReco = [&](const std::string& trigShort, const std::string& name)
    {
        if (!std::isfinite(responsePtGamma) || responsePtGamma <= 0.0) return;
        if (auto* h = getOrBookPPG12PhotonYield1D(trigShort, name, m_ppg12PhotonYieldRecoPtBins,
                                                  "p_{T}^{#gamma,reco} [GeV]", "Entries"))
        {
            h->Fill(responsePtGamma, weight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillResponse = [&](const std::string& trigShort)
    {
        if (!std::isfinite(responsePtGamma) || responsePtGamma <= 0.0) return;
        if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
        if (auto* h = getOrBookPPG12PhotonYieldResponse2D(trigShort, "h_response_full_0"))
        {
            h->Fill(responsePtGamma, truthPt, weight);
            bumpHistFill(trigShort, "h_response_full_0");
        }
    };

    auto fillResponseNamedWithExtraWeight = [&](const std::string& trigShort,
                                                const std::string& name,
                                                const double extraWeight)
    {
        if (!std::isfinite(responsePtGamma) || responsePtGamma <= 0.0) return;
        if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
        if (!std::isfinite(extraWeight)) return;
        if (auto* h = getOrBookPPG12PhotonYieldResponse2D(trigShort, name))
        {
            h->Fill(responsePtGamma, truthPt, weight * extraWeight);
            bumpHistFill(trigShort, name);
        }
    };

    auto fillResponseNamed = [&](const std::string& trigShort, const std::string& name)
    {
        if (!std::isfinite(responsePtGamma) || responsePtGamma <= 0.0) return;
        if (!std::isfinite(truthPt) || truthPt <= 0.0) return;
        if (auto* h = getOrBookPPG12PhotonYieldResponse2D(trigShort, name))
        {
            h->Fill(responsePtGamma, truthPt, weight);
            bumpHistFill(trigShort, name);
        }
    };

    const bool tight = (tightTag == TightTag::kTight);
    const bool nontight = (tightTag == TightTag::kNonTight);
    if (!tight && !nontight) return;
    const bool inAnalysisWindow = ppg12PhotonYieldInResponseWindow(ptGamma, truthPt);
    const bool inResponseWindow = ppg12PhotonYieldInResponseWindow(responsePtGamma, truthPt);

    for (const auto& trigShort : activeTrig)
    {
        if (m_replayFoundationEnabled)
        {
            ReplayPPG12DiagnosticOccurrence row;
            row.trigger = trigShort;
            row.occurrence_kind = "PHOTON_TIGHT_ABCD";
            row.reco_photon_pt = ptGamma;
            row.response_photon_pt = responsePtGamma;
            row.truth_photon_pt = truthPt;
            if (std::isfinite(truthPt) && truthPt > 0.0)
              row.truth_prior_weight = ppg12Fig36TruthPriorWeight(truthPt);
            row.occurrence_weight = weight * RJMCWeighting::SafeWeight();
            row.selection_bitmask =
                (tight ? 1ULL : 0ULL) |
                (nontight ? 2ULL : 0ULL) |
                (iso ? 4ULL : 0ULL) |
                (nonIso ? 8ULL : 0ULL) |
                (haveTruthClass ? 16ULL : 0ULL) |
                (isTruthSignal ? 32ULL : 0ULL) |
                (inAnalysisWindow ? 64ULL : 0ULL) |
                (inResponseWindow ? 128ULL : 0ULL) |
                (fillInclusive ? 256ULL : 0ULL);
            m_replayPPG12DiagnosticOccurrences.push_back(row);
        }
        if (fillInclusive && tight)
        {
            fillReco(trigShort, "h_tight_cluster_0");
        }
        if (tight && haveTruthClass && (!isTruthSignal || inAnalysisWindow))
        {
            fillReco(trigShort, isTruthSignal ? "h_tight_cluster_signal_0" : "h_tight_cluster_notmatch_0");
        }
    }

    const char* regionBase = nullptr;
    if      (tight    && iso)    regionBase = "h_tight_iso_cluster";
    else if (tight    && nonIso) regionBase = "h_tight_noniso_cluster";
    else if (nontight && iso)    regionBase = "h_nontight_iso_cluster";
    else if (nontight && nonIso) regionBase = "h_nontight_noniso_cluster";
    else return;

    for (const auto& trigShort : activeTrig)
    {
        if (fillInclusive)
        {
            fillReco(trigShort, std::string(regionBase) + "_0");
        }

        if (haveTruthClass)
        {
            const std::string suffix = isTruthSignal ? "_signal_0" : "_notmatch_0";
            const bool isTightIsoSignal =
                isTruthSignal && tight && iso &&
                (std::string(regionBase) == "h_tight_iso_cluster");
            if (!isTightIsoSignal || inAnalysisWindow)
            {
                fillReco(trigShort, std::string(regionBase) + suffix);
            }
        }

        if (haveTruthClass && isTruthSignal && tight && iso && inResponseWindow)
        {
            const double fig36PriorWeight = ppg12Fig36TruthPriorWeight(truthPt);
            fillTruth(trigShort, "h_pT_truth_response_0");
            fillResponseReco(trigShort, "h_pT_reco_response_0");
            fillResponse(trigShort);
            fillTruthWithExtraWeight(trigShort,
                                      "h_ppg12_fig36_pT_truth_response_prior_0",
                                      fig36PriorWeight);
            fillRecoWithExtraWeight(trigShort,
                                     "h_ppg12_fig36_pT_reco_response_prior_0",
                                     fig36PriorWeight);
            fillResponseNamedWithExtraWeight(trigShort,
                                             "h2_ppg12_fig36_response_reco_truth_prior_0",
                                             fig36PriorWeight);
            fillTruth(trigShort, "h_ppg12_fig37_input_truth_pT_0");
            fillResponseReco(trigShort, "h_ppg12_fig37_input_reco_pT_0");
            fillResponseNamed(trigShort, "h2_ppg12_fig37_input_response_reco_truth_0");
            if ((m_bk.evt_seen % 2) == 0)
            {
                fillTruth(trigShort, "h_pT_truth_half_response_0");
                fillResponseReco(trigShort, "h_pT_reco_half_response_0");
                fillResponseNamed(trigShort, "h_response_half_0");
                fillResponseNamedWithExtraWeight(trigShort,
                                                 "h2_ppg12_fig36_response_half_reco_truth_prior_0",
                                                 fig36PriorWeight);
                fillTruth(trigShort, "h_ppg12_fig37_input_truth_half_pT_0");
                fillResponseReco(trigShort, "h_ppg12_fig37_input_reco_half_pT_0");
                fillResponseNamed(trigShort, "h2_ppg12_fig37_input_response_half_reco_truth_0");
            }
            else
            {
                fillTruth(trigShort, "h_pT_truth_secondhalf_response_0");
                fillResponseReco(trigShort, "h_pT_reco_secondhalf_response_0");
                fillTruth(trigShort, "h_ppg12_fig37_input_truth_secondhalf_pT_0");
                fillResponseReco(trigShort, "h_ppg12_fig37_input_reco_secondhalf_pT_0");
            }
        }
        else if (haveTruthClass && !isTruthSignal && tight && iso)
        {
            fillReco(trigShort, "h_pT_reco_fake_0");
            fillReco(trigShort, "h_ppg12_fig37_input_fake_pT_0");
        }
    }
}


// ------------------------------------------------------------------
//  isolation PASS/FAIL counter histogram (2 bins), same slicing rules.
//   bin 1 = PASS  (Eiso < thr)
//   bin 2 = FAIL  (Eiso >= thr)
// ------------------------------------------------------------------
TH1I* RecoilJets::getOrBookIsoDecisionHist(const std::string& trig, int ptIdx, int centIdx)
{
  const std::string base   = "h_isoDecision";
  const std::string suffix = suffixForBins(ptIdx, centIdx);
  const std::string name   = withIsoViewSuffix(base) + suffix;

  if (Verbosity() >= 5)
    LOG(5, CLR_BLUE, "  [getOrBookIsoDecisionHist] trig=\"" << trig
           << "\" ptIdx=" << ptIdx << " centIdx=" << centIdx
           << " → name=\"" << name << "\"");

  if (trig.empty())
  {
    LOG(2, CLR_YELLOW, "  [getOrBookIsoDecisionHist] empty trig – returning nullptr");
    return nullptr;
  }

  auto& H = qaHistogramsByTrigger[trig];

  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
    LOG(2, CLR_YELLOW, "    [getOrBookIsoDecisionHist] name clash: object \"" << name
                       << "\" exists but is not TH1I – replacing it");
    H.erase(it);
  }

  if (!out || !out->IsOpen())
  {
    LOG(1, CLR_YELLOW, "  [getOrBookIsoDecisionHist] output TFile invalid/null – returning nullptr");
    return nullptr;
  }

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir)
  {
    LOG(1, CLR_YELLOW, "  [getOrBookIsoDecisionHist] failed to create/access directory \"" << trig << "\"");
    if (prevDir) prevDir->cd();
    return nullptr;
  }

  dir->cd();

  auto* h = RJMCWeighting::RJNewTH1I(name.c_str(), (name + ";Isolation decision;Entries").c_str(), 2, 0.5, 2.5);
  if (!h)
  {
    LOG(1, CLR_YELLOW, "  [getOrBookIsoDecisionHist] new TH1I failed for \"" << name << '"');
    if (prevDir) prevDir->cd();
    return nullptr;
  }

  h->GetXaxis()->SetBinLabel(1, "PASS");
  h->GetXaxis()->SetBinLabel(2, "FAIL");
  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}

// Event-level reco-photon multiplicity diagnostic:
//   N = number of reco photon candidates passing the SAME iso∧tight gate used
//       for the event-leading photon selection (filled once per event; binned
//       by the selected leading-photon pT bin via suffixForBins()).
TH1I* RecoilJets::getOrBookNIsoTightPhoCandHist(const std::string& trig, int ptIdx, int centIdx)
{
  const std::string base   = "h_nIsoTightPhoCand";
  const std::string suffix = suffixForBins(ptIdx, centIdx);
  const std::string name   = withIsoViewSuffix(base) + suffix;

  if (Verbosity() >= 5)
    LOG(5, CLR_BLUE, "  [getOrBookNIsoTightPhoCandHist] trig=\"" << trig
           << "\" ptIdx=" << ptIdx << " centIdx=" << centIdx
           << " → name=\"" << name << "\"");

  if (trig.empty())
  {
    LOG(2, CLR_YELLOW, "  [getOrBookNIsoTightPhoCandHist] empty trig – returning nullptr");
    return nullptr;
  }

  auto& H = qaHistogramsByTrigger[trig];

  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
    LOG(2, CLR_YELLOW, "    [getOrBookNIsoTightPhoCandHist] name clash: object \"" << name
                       << "\" exists but is not TH1I – replacing it");
    H.erase(it);
  }

  if (!out || !out->IsOpen())
  {
    LOG(1, CLR_YELLOW, "  [getOrBookNIsoTightPhoCandHist] output TFile invalid/null – returning nullptr");
    return nullptr;
  }

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir)
  {
    LOG(1, CLR_YELLOW, "  [getOrBookNIsoTightPhoCandHist] failed to create/access directory \"" << trig << "\"");
    if (prevDir) prevDir->cd();
    return nullptr;
  }

  dir->cd();

  // Integer multiplicity diagnostic: raw events, not a PPG12 weighted yield.
  auto* h = RJMCWeighting::RJNewRawTH1I(name.c_str(),
                                        (name + ";N_{#gamma}^{iso+tight} candidates;Entries").c_str(),
                                        11, -0.5, 10.5);
  if (!h)
  {
    LOG(1, CLR_YELLOW, "  [getOrBookNIsoTightPhoCandHist] new TH1I failed for \"" << name << '"');
    if (prevDir) prevDir->cd();
    return nullptr;
  }

  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}


// ============================================================================
//  SIM-only truth isolation QA bookers
//    - stored directly in the trigger directory (SIM => /SIM/)
//    - NOT sliced by pT/centrality (these are global truth QA histograms)
// ============================================================================
TH1F* RecoilJets::getOrBookTruthIsoHist(const std::string& trig,
                                       const std::string& name,
                                       int nbins, double xmin, double xmax)
{
  if (trig.empty() || name.empty()) return nullptr;
  const std::string viewName = name;

  auto& H = qaHistogramsByTrigger[trig];
  if (auto it = H.find(viewName); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }
  dir->cd();

  const std::string title = viewName + ";E_{T}^{iso,truth} [GeV];Entries";
  auto* h = RJMCWeighting::RJNewTH1F(viewName.c_str(), title.c_str(), nbins, xmin, xmax);
  h->Sumw2();
  H[viewName] = h;

  if (prevDir) prevDir->cd();
  return h;
}

TH1I* RecoilJets::getOrBookTruthIsoDecisionHist(const std::string& trig,
                                               const std::string& name)
{
  if (trig.empty() || name.empty()) return nullptr;
  const std::string viewName = name;

  auto& H = qaHistogramsByTrigger[trig];
  if (auto it = H.find(viewName); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }
  dir->cd();

  const std::string title = viewName + ";Truth isolation cut decision;Entries";
  auto* h = RJMCWeighting::RJNewTH1I(viewName.c_str(), title.c_str(), 2, 0.5, 2.5);
  h->GetXaxis()->SetBinLabel(1, "PASS");
  h->GetXaxis()->SetBinLabel(2, "FAIL");
  H[viewName] = h;

  if (prevDir) prevDir->cd();
  return h;
}

// ------------------------------------------------------------------
//  matched truth-signal -> reco ABCD leakage histogram
//   - one histogram per (pT[/cent]) slice
//   - bins: 1=A, 2=B, 3=C, 4=D
// ------------------------------------------------------------------
TH1* RecoilJets::getOrBookSigABCDLeakageHist(const std::string& trig, int ptIdx, int centIdx,
                                             const std::string& base)
{
    const std::string suffix = suffixForBins(ptIdx, centIdx);
    const std::string name   = withIsoViewSuffix(base) + suffix;
    const bool useFloatHist = (m_ppg12PhotonYieldEnabled && m_isSim && !m_isAuAu);

    if (trig.empty()) return nullptr;

    auto& H = qaHistogramsByTrigger[trig];

    if (auto it = H.find(name); it != H.end())
    {
      if (auto* h = dynamic_cast<TH1*>(it->second)) return h;
      H.erase(it);
    }

    if (!out || !out->IsOpen()) return nullptr;

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }

    dir->cd();

    const std::string title =
      name + ";Reco ABCD region for matched truth-signal photons;Entries";

    TH1* h = useFloatHist
      ? static_cast<TH1*>(RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), 4, 0.5, 4.5))
      : static_cast<TH1*>(RJMCWeighting::RJNewTH1I(name.c_str(), title.c_str(), 4, 0.5, 4.5));
    h->GetXaxis()->SetBinLabel(1, "A");
    h->GetXaxis()->SetBinLabel(2, "B");
    h->GetXaxis()->SetBinLabel(3, "C");
    h->GetXaxis()->SetBinLabel(4, "D");

    H[name] = h;

    if (prevDir) prevDir->cd();
    return h;
}



// ============================================================================
//  Jet QA helpers (generic bookers + fillers)
//  - Naming:  <base>_<rKey> + suffixForBins(ptIdx,centIdx)
//  - Pure jet QA uses ptIdx = -1 (centrality-only suffix in AuAu)
// ============================================================================

bool RecoilJets::fillPPG12InclusiveJetTruthSpectrumQA(PHCompositeNode* topNode)
{
  if (!m_isSim || m_isAuAu) return false;

  const PPG12InclusiveJetSlice slice = ppg12InclusiveJetSliceFromContext(Outfile);
  if (slice == PPG12InclusiveJetSlice::kNone) return false;

  double stitchLo = -999.0;
  double stitchHi = -999.0;
  if (!ppg12InclusiveJetSliceWindow(slice, stitchLo, stitchHi)) return false;

  JetContainer* truthJetsR04 = nullptr;
  std::string truthJetsNode = "cached";
  if (topNode)
  {
    if (auto* truth = findNode::getClass<PHG4TruthInfoContainer>(topNode, "G4TruthInfo"))
    {
      m_truthInfo = truth;
      m_truthVz = std::numeric_limits<double>::quiet_NaN();
      m_truthVzMB = std::numeric_limits<double>::quiet_NaN();

      const int primaryvtxid = truth->GetPrimaryVertexIndex();
      if (const PHG4VtxPoint* vtx = truth->GetVtx(primaryvtxid))
      {
        const double z = vtx->get_z();
        if (std::isfinite(z)) m_truthVz = z;
      }

      auto vtxRange = truth->GetPrimaryVtxRange();
      for (auto vit = vtxRange.first; vit != vtxRange.second; ++vit)
      {
        if (vit->first == primaryvtxid) continue;
        const PHG4VtxPoint* vtxMB = vit->second;
        if (!vtxMB) continue;
        const double mbz = vtxMB->get_z();
        if (std::isfinite(mbz))
        {
          m_truthVzMB = mbz;
          break;
        }
      }
    }

    const auto truthJetLookup = ppg12FindTruthJetsR04(topNode);
    truthJetsR04 = truthJetLookup.first;
    if (!truthJetLookup.second.empty()) truthJetsNode = truthJetLookup.second;
  }
  else
  {
    auto itR04 = m_truthJetsByRKey.find("r04");
    if (itR04 != m_truthJetsByRKey.end()) truthJetsR04 = itR04->second;
    if (auto itNode = m_truthJetsNodeByRKey.find("r04"); itNode != m_truthJetsNodeByRKey.end())
    {
      truthJetsNode = itNode->second.empty() ? "cached" : itNode->second;
    }
  }

  const bool haveR04Container = (truthJetsR04 != nullptr);

  double fig6VertexWeight = 1.0;
  bool fig6WeightOK = true;
  if (m_vertexReweightOn)
  {
    if (!m_vertexReweightH)
    {
      LOG(0, CLR_RED,
          "[PPG12_FIG6_CONTRACT][FATAL] vertex reweight requested but h_w_iterative is not loaded"
          << " | sample=" << ppg12InclusiveJetSliceName(slice)
          << " | period=" << m_ppg12PeriodKey
          << " | file=" << m_vertexReweightFile);
      fig6WeightOK = false;
    }
    else
    {
      if (!std::isfinite(m_truthVz))
      {
        LOG(0, CLR_RED,
            "[PPG12_FIG6_CONTRACT][FATAL] truth-vertex reweight requested but hard truth z is not finite"
            << " | sample=" << ppg12InclusiveJetSliceName(slice)
            << " | period=" << m_ppg12PeriodKey);
        fig6WeightOK = false;
      }
      else
      {
        fig6VertexWeight *= ppg12TruthVertexWeight(m_vertexReweightH, m_truthVz);
      }
      if (fig6WeightOK && m_ppg12PhotonYieldDoubleInteraction)
      {
        if (m_ppg12PeriodStrictDoubleMB &&
            (!std::isfinite(m_truthVzMB) || m_truthVzMB <= kPPG12TruthVtxSentinelThreshold))
        {
          LOG(1, CLR_RED,
              "    [PPG12_FIG6_CONTRACT][REJECT] double-interaction PPG12 SIM event lacks a usable "
              "MB-overlay truth vertex for the second w(z) factor"
              << " | truthVz=" << m_truthVz
              << " | truthVzMB=" << m_truthVzMB
              << " | period=" << m_ppg12PeriodKey);
          fig6WeightOK = false;
        }
        else
        {
          fig6VertexWeight *= ppg12TruthVertexWeight(m_vertexReweightH, m_truthVzMB);
        }
      }
    }
  }

  if (!fig6WeightOK || !std::isfinite(fig6VertexWeight) || fig6VertexWeight < 0.0)
  {
    return true;
  }

  double maxTruthJetPtR04 = -1.0;
  if (haveR04Container)
  {
    for (const Jet* tj : *truthJetsR04)
    {
      if (!tj) continue;
      const double pt = tj->get_pt();
      if (std::isfinite(pt) && pt > maxTruthJetPtR04) maxTruthJetPtR04 = pt;
    }
  }

  const bool haveTruthJet = (maxTruthJetPtR04 >= 0.0);
  const bool passWindow = haveTruthJet &&
                          ppg12WindowContains(maxTruthJetPtR04, stitchLo, stitchHi);
  const double xsecPb = ppg12InclusiveJetSliceXsecPb(slice);
  const double sliceWeight = (kPPG12Jet50CrossPb > 0.0) ? (xsecPb / kPPG12Jet50CrossPb) : 0.0;
  if (sliceWeight <= 0.0 || !std::isfinite(sliceWeight)) return false;
  const double lumiFactor = m_ppg12PeriodUseLumiWeight ? m_ppg12PeriodLumiWeight : 1.0;
  const double mixFactor = m_ppg12PhotonYieldMixWeight;
  PPG12SimWeight::Factors fig6Factors;
  if (!PPG12SimWeight::Build(sliceWeight,
                             fig6VertexWeight,
                             mixFactor,
                             lumiFactor,
                             fig6Factors))
  {
    LOG(0, CLR_RED,
        "[PPG12_FIG6_CONTRACT][FATAL] invalid canonical SIM weight factors"
        << " | slice=" << sliceWeight
        << " | vertex=" << fig6VertexWeight
        << " | mix=" << mixFactor
        << " | period=" << lumiFactor);
    return true;
  }
  if (m_replayFoundationEnabled)
  {
    ReplayPPG12DiagnosticOccurrence row;
    row.trigger = "SIM";
    row.occurrence_kind = "PP_FIG6_WEIGHTED_SOURCE";
    row.sample_code = ppg12InclusiveJetSliceBin(slice);
    row.decision = passWindow ? 1 : (haveTruthJet ? 2 : 3);
    if (haveTruthJet) row.flow_value = maxTruthJetPtR04;
    row.occurrence_weight = fig6Factors.final;
    m_replayPPG12DiagnosticOccurrences.push_back(row);
  }

  if (m_ppg12Fig6EventCanaryEnabled)
  {
    const double currentWeight = fig6Factors.vertex * fig6Factors.mix * fig6Factors.period;
    const double hardVertexWeight =
        (m_vertexReweightOn && m_vertexReweightH && std::isfinite(m_truthVz))
        ? ppg12TruthVertexWeight(m_vertexReweightH, m_truthVz)
        : 1.0;
    const double mbVertexWeight =
        (m_ppg12PhotonYieldDoubleInteraction &&
         m_vertexReweightOn && m_vertexReweightH &&
         std::isfinite(m_truthVzMB) && m_truthVzMB > kPPG12TruthVtxSentinelThreshold)
        ? ppg12TruthVertexWeight(m_vertexReweightH, m_truthVzMB)
        : 1.0;
    const double combinedVertexWeight = hardVertexWeight * mbVertexWeight;
    const double ppg12FormulaWeight = fig6Factors.final;
    const double finalFillWeight = fig6Factors.final;

    ++m_ppg12Fig6CanaryEventsSeen;
    if (haveTruthJet) ++m_ppg12Fig6CanaryValidTruthJets;
    if (passWindow)
    {
      ++m_ppg12Fig6CanaryOwnedWindowEvents;
      ++m_ppg12Fig6CanaryRawOwnedEntries;
      m_ppg12Fig6CanaryWeightedOwnedIntegral += finalFillWeight;
    }
    m_ppg12Fig6CanarySumXsecFactor += sliceWeight;
    m_ppg12Fig6CanarySumLumiFactor += lumiFactor;
    m_ppg12Fig6CanarySumMixFactor += mixFactor;
    m_ppg12Fig6CanarySumVertexWeight += combinedVertexWeight;
    m_ppg12Fig6CanarySumFinalFillWeight += (passWindow ? finalFillWeight : 0.0);

    auto envFirstNonEmpty = [](std::initializer_list<const char*> keys,
                               const std::string& fallback) -> std::string
    {
      for (const char* key : keys)
      {
        const char* raw = std::getenv(key);
        if (raw && raw[0] != '\0') return std::string(raw);
      }
      return fallback;
    };
    auto csv = [](const std::string& value) -> std::string
    {
      std::string out = "\"";
      for (char c : value)
      {
        if (c == '"') out += "\"\"";
        else out += c;
      }
      out += "\"";
      return out;
    };
    auto writeNum = [&](double value)
    {
      if (std::isfinite(value))
      {
        m_ppg12Fig6EventCanaryOut << std::setprecision(17) << value;
      }
    };
    auto reasonFor = [&](const char* target, bool shouldFill) -> std::string
    {
      if (shouldFill) return "filled";
      if (!haveR04Container) return "missing_r04_truth_jet_container";
      if (!haveTruthJet) return "no_valid_truth_jet";
      const std::string targetName(target);
      if (targetName == "kept" && !passWindow) return "outside_owned_window";
      if (targetName == "rejected" && passWindow) return "inside_owned_window";
      return "not_selected_for_target";
    };
    auto writeTargetRow = [&](const char* target, bool shouldFill)
    {
      if (!m_ppg12Fig6EventCanaryOut.is_open()) return;
      if (m_ppg12Fig6EventCanaryMaxRows > 0 &&
          m_ppg12Fig6EventCanaryRowsWritten >= m_ppg12Fig6EventCanaryMaxRows)
      {
        return;
      }
      const std::string inputPath = envFirstNonEmpty(
          {"RJ_PPG12_FIG6_EVENT_CANARY_INPUT", "RJ_CURRENT_INPUT_FILE",
           "RJ_INPUT_FILE", "INPUT_FILE", "DST_FILE"},
          truthJetsNode.empty() ? (Outfile.empty() ? std::string("unset") : Outfile) : truthJetsNode);
      const int rawFillCount = shouldFill ? 1 : 0;
      const double rowFinalWeight = shouldFill ? finalFillWeight : 0.0;
      const double rowRatio =
          (std::isfinite(ppg12FormulaWeight) && ppg12FormulaWeight != 0.0)
          ? (rowFinalWeight / ppg12FormulaWeight)
          : std::numeric_limits<double>::quiet_NaN();

      m_ppg12Fig6EventCanaryOut
          << csv(ppg12InclusiveJetSliceName(slice)) << ','
          << csv(inputPath) << ','
          << csv(m_ppg12PeriodKey) << ','
          << csv(m_ppg12PhotonYieldDoubleInteraction ? "DI" : "SI") << ','
          << event_count << ',';
      writeNum(maxTruthJetPtR04); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(stitchLo); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(stitchHi); m_ppg12Fig6EventCanaryOut << ','
          << (passWindow ? 1 : 0) << ','
          << csv("h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_r04_maxTruthJetPt") << ','
          << csv(target) << ','
          << rawFillCount << ',';
      writeNum(xsecPb); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(kPPG12Jet50CrossPb); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(sliceWeight); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(lumiFactor); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(mixFactor); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(m_truthVz); m_ppg12Fig6EventCanaryOut << ',';
      if (m_ppg12PhotonYieldDoubleInteraction) writeNum(m_truthVzMB);
      m_ppg12Fig6EventCanaryOut << ',';
      writeNum(hardVertexWeight); m_ppg12Fig6EventCanaryOut << ',';
      if (m_ppg12PhotonYieldDoubleInteraction) writeNum(mbVertexWeight);
      m_ppg12Fig6EventCanaryOut << ',';
      writeNum(currentWeight); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(rowFinalWeight); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(ppg12FormulaWeight); m_ppg12Fig6EventCanaryOut << ',';
      writeNum(rowRatio); m_ppg12Fig6EventCanaryOut << ','
          << csv(reasonFor(target, shouldFill)) << '\n';
      ++m_ppg12Fig6EventCanaryRowsWritten;
    };

    writeTargetRow("all", haveTruthJet);
    writeTargetRow("kept", passWindow);
    writeTargetRow("rejected", haveTruthJet && !passWindow);
  }

  if (!haveR04Container) return true;

  constexpr const char* kTrig = "SIM";
  HistMap& H = qaHistogramsByTrigger[kTrig];

  if (!out || !out->IsOpen()) return true;
  TDirectory* prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(kTrig);
  if (!dir) dir = out->mkdir(kTrig);
  if (!dir)
  {
    if (prevDir) prevDir->cd();
    return true;
  }
  dir->cd();

  auto bookWeighted1F = [&](const std::string& name,
                            const std::string& title,
                            int nbins,
                            double xmin,
                            double xmax) -> TH1F*
  {
    if (auto it = H.find(name); it != H.end())
    {
      return dynamic_cast<TH1F*>(it->second);
    }
    auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
    if (!h) return nullptr;
    h->Sumw2();
    h->SetDirectory(dir);
    H[name] = h;
    return h;
  };

  auto bookMetadata = [&](const std::string& name,
                          const std::string& title) -> TH1F*
  {
    if (auto it = H.find(name); it != H.end())
    {
      return dynamic_cast<TH1F*>(it->second);
    }
    auto* h = new TH1F(name.c_str(), title.c_str(), 12, 0.5, 12.5);
    if (!h) return nullptr;
    h->SetDirectory(dir);
    H[name] = h;
    h->GetXaxis()->SetBinLabel(1, "events_seen_raw");
    h->GetXaxis()->SetBinLabel(2, "window_low_GeV");
    h->GetXaxis()->SetBinLabel(3, "window_high_GeV");
    h->GetXaxis()->SetBinLabel(4, "upper_edge_inclusive");
    h->GetXaxis()->SetBinLabel(5, "bin_width_GeV");
    h->GetXaxis()->SetBinLabel(6, "xsec_pb");
    h->GetXaxis()->SetBinLabel(7, "xsec_over_jet50");
    h->GetXaxis()->SetBinLabel(8, "sample_bin");
    h->GetXaxis()->SetBinLabel(9, "truth_def_code");
    h->GetXaxis()->SetBinLabel(10, "includes_current_weight");
    h->GetXaxis()->SetBinLabel(11, "includes_slice_weight");
    h->GetXaxis()->SetBinLabel(12, "value_mode_code");
    return h;
  };

  constexpr int kPPG12Fig6JetPtBins = 100;
  constexpr double kPPG12Fig6JetPtMin = 0.0;
  constexpr double kPPG12Fig6JetPtMax = 100.0;
  constexpr double kPPG12Fig6BinWidth = (kPPG12Fig6JetPtMax - kPPG12Fig6JetPtMin) /
                                        static_cast<double>(kPPG12Fig6JetPtBins);

  auto fillHist = [&](const std::string& suffix, const bool shouldFill)
  {
    auto* h = bookWeighted1F(
        std::string("h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_r04_maxTruthJetPt_") + suffix,
        std::string("h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_r04_maxTruthJetPt_") + suffix +
            ";max R=0.4 truth jet p_{T} [GeV];PPG12 weighted counts",
        kPPG12Fig6JetPtBins,
        kPPG12Fig6JetPtMin,
        kPPG12Fig6JetPtMax);
    if (!h || !shouldFill) return;
    h->Fill(maxTruthJetPtR04);
    bumpHistFill(kTrig, h->GetName());
  };

  const double savedWeight = RJMCWeighting::CurrentWeight();
  const int savedLaneComponentCode = RJMCWeighting::CurrentLaneComponentCode();
  RJMCWeighting::CurrentLaneComponentCode() = m_ppg12PhotonYieldDoubleInteraction ? 4 : 3;
  RJMCWeighting::CurrentWeight() = fig6Factors.final;
  fillHist("all", haveTruthJet);
  fillHist("kept", passWindow);
  fillHist("rejected", haveTruthJet && !passWindow);
  RJMCWeighting::CurrentWeight() = savedWeight;
  RJMCWeighting::CurrentLaneComponentCode() = savedLaneComponentCode;

  if (auto* hMeta = bookMetadata("h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_metadata",
                                 "h_ppInclusiveJetStitch_ppg12Fig6EventWeighted_metadata;metadata;value"))
  {
    hMeta->Fill(1.0);
    hMeta->SetBinContent(2, stitchLo);
    hMeta->SetBinContent(3, stitchHi);
    hMeta->SetBinContent(4, 1.0);
    hMeta->SetBinContent(5, kPPG12Fig6BinWidth);
    hMeta->SetBinContent(6, xsecPb);
    hMeta->SetBinContent(7, sliceWeight);
    hMeta->SetBinContent(8, static_cast<double>(ppg12InclusiveJetSliceBin(slice)));
    hMeta->SetBinContent(9, 20.0);
    hMeta->SetBinContent(10, 1.0);
    hMeta->SetBinContent(11, 1.0);
    hMeta->SetBinContent(12, 2.0);
    bumpHistFill(kTrig, hMeta->GetName());
  }

  if (prevDir) prevDir->cd();
  return true;
}

TH1I* RecoilJets::getOrBookJetQA1I(const std::string& trig,
                                  const std::string& base,
                                  const std::string& xAxisTitle,
                                  const std::string& rKey,
                                  int ptIdx, int centIdx,
                                  int nbins, double xmin, double xmax)
{
  const std::string suffix = suffixForBins(ptIdx, centIdx);
  const std::string name   = base + "_" + rKey + suffix;

  if (trig.empty() || base.empty() || rKey.empty()) return nullptr;

  auto& H = qaHistogramsByTrigger[trig];

  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1I*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }

  dir->cd();

  const std::string xlab  = (xAxisTitle.empty() ? base : xAxisTitle);
  const std::string title = name + ";" + xlab + ";Entries";

  auto* h = RJMCWeighting::RJNewTH1I(name.c_str(), title.c_str(), nbins, xmin, xmax);
  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}


TH1F* RecoilJets::getOrBookJetQA1F(const std::string& trig,
                                  const std::string& base,
                                  const std::string& xAxisTitle,
                                  const std::string& rKey,
                                  int ptIdx, int centIdx,
                                  int nbins, double xmin, double xmax)
{
  const std::string suffix = suffixForBins(ptIdx, centIdx);
  const std::string name   = base + "_" + rKey + suffix;

  if (trig.empty() || base.empty() || rKey.empty()) return nullptr;

  auto& H = qaHistogramsByTrigger[trig];

  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }

  dir->cd();

  const std::string xlab  = (xAxisTitle.empty() ? base : xAxisTitle);
  const std::string title = name + ";" + xlab + ";Entries";

  auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), nbins, xmin, xmax);
  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}


TH2F* RecoilJets::getOrBookJetQA2F(const std::string& trig,
                                  const std::string& base,
                                  const std::string& xAxisTitle,
                                  const std::string& yAxisTitle,
                                  const std::string& rKey,
                                  int ptIdx, int centIdx,
                                  int nxbins, double xmin, double xmax,
                                  int nybins, double ymin, double ymax)
{
  const std::string suffix = suffixForBins(ptIdx, centIdx);
  const std::string name   = base + "_" + rKey + suffix;

  if (trig.empty() || base.empty() || rKey.empty()) return nullptr;

  auto& H = qaHistogramsByTrigger[trig];

  if (auto it = H.find(name); it != H.end())
  {
    if (auto* h = dynamic_cast<TH2F*>(it->second)) return h;
    H.erase(it);
  }

  if (!out || !out->IsOpen()) return nullptr;

  TDirectory* const prevDir = gDirectory;
  TDirectory* dir = out->GetDirectory(trig.c_str());
  if (!dir) dir = out->mkdir(trig.c_str());
  if (!dir) { if (prevDir) prevDir->cd(); return nullptr; }

  dir->cd();

  const std::string xlab  = (xAxisTitle.empty() ? "x" : xAxisTitle);
  const std::string ylab  = (yAxisTitle.empty() ? "y" : yAxisTitle);
  const std::string title = name + ";" + xlab + ";" + ylab;

  auto* h = RJMCWeighting::RJNewTH2F(name.c_str(), title.c_str(),
                     nxbins, xmin, xmax,
                     nybins, ymin, ymax);
  H[name] = h;

  if (prevDir) prevDir->cd();
  return h;
}


// ---------------------------- Pure jet QA filler ----------------------------
void RecoilJets::fillInclusiveJetQA(const std::vector<std::string>& activeTrig,
                                   int centIdx,
                                   const std::string& rKey)
{
  if (activeTrig.empty()) return;

  JetContainer* jets = nullptr;
  if (auto it = m_jets.find(rKey); it != m_jets.end()) jets = it->second;
  if (!jets) return;

  const int effCentIdx = (m_isAuAu ? centIdx : -1);

  // Fiducial/containment cut depends on jet radius key:
  //   |eta_jet| < 1.1 - R
  const double etaAbsMaxUse = jetEtaAbsMaxForRKey(rKey);

  // Event-level (fiducial jets only)
  int    nJetsFid = 0;
  double HT       = 0.0;
  double leadPt   = -1.0;
  double leadEta  = 0.0;
  double leadPhi  = 0.0;
  double subPt    = -1.0;

  constexpr int    nbPt  = 200;  constexpr double ptLo  = 0.0;   constexpr double ptHi  = 100.0;
  constexpr int    nbEta = 120;  constexpr double etaLo = -1.2;  constexpr double etaHi =  1.2;
  constexpr int    nbPhi = 128;  constexpr double phiLo = -M_PI; constexpr double phiHi =  M_PI;

  constexpr int    nbMass = 120; constexpr double mLo = 0.0;     constexpr double mHi = 30.0;

  // 2D occupancy and mass-vs-pt
  constexpr int    nbEta2 = 60;
  constexpr int    nbPhi2 = 64;
  constexpr int    nbPt2  = 100;
  constexpr int    nbM2   = 80;
  constexpr double m2Hi   = 20.0;

  // Loop over jets once; fill "all" first (pT cut only), then "incl" (fiducial)
  for (const Jet* j : *jets)
  {
    if (!j) continue;

    const double pt  = j->get_pt();
    const double eta = j->get_eta();

    if (!std::isfinite(pt) || !std::isfinite(eta)) continue;
    if (pt < m_minJetPt) continue;

    const double phi = TVector2::Phi_mpi_pi(j->get_phi());
    const double mass = j->get_mass();

    // ----------------- "all": pT cut only (no eta acceptance) -----------------
    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetPt_all", "p_{T}^{jet} [GeV]", rKey, -1, effCentIdx, nbPt, ptLo, ptHi))
      { h->Fill(pt); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetEta_all", "#eta^{jet}", rKey, -1, effCentIdx, nbEta, etaLo, etaHi))
      { h->Fill(eta); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetPhi_all", "#phi^{jet} [rad]", rKey, -1, effCentIdx, nbPhi, phiLo, phiHi))
      { h->Fill(phi); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h2 = getOrBookJetQA2F(trigShort, "h_jetEtaPhi_all", "#eta^{jet}", "#phi^{jet} [rad]",
                                      rKey, -1, effCentIdx, nbEta2, etaLo, etaHi, nbPhi2, phiLo, phiHi))
      { h2->Fill(eta, phi); bumpHistFill(trigShort, h2->GetName()); }

      if (std::isfinite(mass) && mass >= 0.0)
      {
        if (auto* hm = getOrBookJetQA1F(trigShort, "h_jetMass_all", "m^{jet} [GeV]", rKey, -1, effCentIdx, nbMass, mLo, mHi))
        { hm->Fill(mass); bumpHistFill(trigShort, hm->GetName()); }

        if (auto* h2m = getOrBookJetQA2F(trigShort, "h_jetMassVsPt_all", "p_{T}^{jet} [GeV]", "m^{jet} [GeV]",
                                         rKey, -1, effCentIdx, nbPt2, ptLo, ptHi, nbM2, mLo, m2Hi))
        { h2m->Fill(pt, mass); bumpHistFill(trigShort, h2m->GetName()); }
      }
    }

    // ----------------- "incl": fiducial jets used for analysis ----------------
    // Fiducial/containment cut depends on jet radius key:
    //   |eta_jet| < 1.1 - R
    if (std::fabs(eta) >= etaAbsMaxUse) continue;

    ++nJetsFid;
    HT += pt;

    if (pt > leadPt)
    {
      subPt   = leadPt;
      leadPt  = pt;
      leadEta = eta;
      leadPhi = phi;
    }
    else if (pt > subPt)
    {
      subPt = pt;
    }

    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetPt_incl", "p_{T}^{jet} [GeV]", rKey, -1, effCentIdx, nbPt, ptLo, ptHi))
      { h->Fill(pt); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetEta_incl", "#eta^{jet}", rKey, -1, effCentIdx, nbEta, etaLo, etaHi))
      { h->Fill(eta); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jetPhi_incl", "#phi^{jet} [rad]", rKey, -1, effCentIdx, nbPhi, phiLo, phiHi))
      { h->Fill(phi); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h2 = getOrBookJetQA2F(trigShort, "h_jetEtaPhi_incl", "#eta^{jet}", "#phi^{jet} [rad]",
                                      rKey, -1, effCentIdx, nbEta2, etaLo, etaHi, nbPhi2, phiLo, phiHi))
      { h2->Fill(eta, phi); bumpHistFill(trigShort, h2->GetName()); }

      if (std::isfinite(mass) && mass >= 0.0)
      {
        if (auto* hm = getOrBookJetQA1F(trigShort, "h_jetMass_incl", "m^{jet} [GeV]", rKey, -1, effCentIdx, nbMass, mLo, mHi))
        { hm->Fill(mass); bumpHistFill(trigShort, hm->GetName()); }

        if (auto* h2m = getOrBookJetQA2F(trigShort, "h_jetMassVsPt_incl", "p_{T}^{jet} [GeV]", "m^{jet} [GeV]",
                                         rKey, -1, effCentIdx, nbPt2, ptLo, ptHi, nbM2, mLo, m2Hi))
        { h2m->Fill(pt, mass); bumpHistFill(trigShort, h2m->GetName()); }
      }
    }
  }

    // Per-event jet summary (printed once per rKey, not once per trigger)
    if (Verbosity() >= 6)
    {
      std::ostringstream os;
      os << "    [jetQA:event] rKey=" << rKey
         << " | jets(container)=" << jets->size()
         << " | fiducial jets (pT>" << m_minJetPt
         << ", |eta|<" << std::fixed << std::setprecision(2) << etaAbsMaxUse
         << ")=" << nJetsFid
         << " | HT=" << std::fixed << std::setprecision(2) << HT;

      if (leadPt >= 0.0)
      {
        os << " | lead=(pT=" << std::fixed << std::setprecision(2) << leadPt
           << ", eta=" << std::fixed << std::setprecision(3) << leadEta
           << ", phi=" << std::fixed << std::setprecision(3) << leadPhi << ")";
      }
      if (subPt >= 0.0)
      {
        os << " | sublead pT=" << std::fixed << std::setprecision(2) << subPt;
      }

      LOG(6, CLR_CYAN, os.str());
    }

    // Event-level histograms (fiducial jets only)
    for (const auto& trigShort : activeTrig)
    {
      if (auto* h = getOrBookJetQA1I(trigShort, "h_nJets", "N_{jets}", rKey, -1, effCentIdx, 100, 0.0, 100.0))
      { h->Fill(nJetsFid); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_HT", "H_{T} [GeV]", rKey, -1, effCentIdx, 300, 0.0, 150.0))
      { h->Fill(HT); bumpHistFill(trigShort, h->GetName()); }

      if (leadPt >= 0.0)
      {
        if (auto* h = getOrBookJetQA1F(trigShort, "h_leadJetPt", "p_{T}^{lead jet} [GeV]", rKey, -1, effCentIdx, 200, 0.0, 100.0))
        { h->Fill(leadPt); bumpHistFill(trigShort, h->GetName()); }

        if (auto* h = getOrBookJetQA1F(trigShort, "h_leadJetEta", "#eta^{lead jet}", rKey, -1, effCentIdx, 120, -1.2, 1.2))
        { h->Fill(leadEta); bumpHistFill(trigShort, h->GetName()); }

        if (auto* h = getOrBookJetQA1F(trigShort, "h_leadJetPhi", "#phi^{lead jet} [rad]", rKey, -1, effCentIdx, 128, -M_PI, M_PI))
        { h->Fill(leadPhi); bumpHistFill(trigShort, h->GetName()); }
      }

      if (subPt >= 0.0)
      {
        if (auto* h = getOrBookJetQA1F(trigShort, "h_subleadJetPt", "p_{T}^{sublead jet} [GeV]", rKey, -1, effCentIdx, 200, 0.0, 100.0))
        { h->Fill(subPt); bumpHistFill(trigShort, h->GetName()); }
      }
    }
}


// ----------------------- Selected jet QA (gamma+jet jets) -----------------------
void RecoilJets::fillSelectedJetQA(const std::vector<std::string>& activeTrig,
                                  int ptIdx, int centIdx,
                                  const std::string& rKey,
                                  const Jet* jet1,
                                  const Jet* jet2)
{
  if (activeTrig.empty() || !jet1) return;

  const int effCentIdx = (m_isAuAu ? centIdx : -1);

  const double eta1 = jet1->get_eta();
  const double phi1 = TVector2::Phi_mpi_pi(jet1->get_phi());
  const double m1   = jet1->get_mass();

  for (const auto& trigShort : activeTrig)
  {
    if (auto* h = getOrBookJetQA1F(trigShort, "h_jet1Eta_sel", "#eta^{jet1}", rKey, ptIdx, effCentIdx, 120, -1.2, 1.2))
    { h->Fill(eta1); bumpHistFill(trigShort, h->GetName()); }

    if (auto* h = getOrBookJetQA1F(trigShort, "h_jet1Phi_sel", "#phi^{jet1} [rad]", rKey, ptIdx, effCentIdx, 128, -M_PI, M_PI))
    { h->Fill(phi1); bumpHistFill(trigShort, h->GetName()); }

    if (std::isfinite(m1) && m1 >= 0.0)
    {
      if (auto* h = getOrBookJetQA1F(trigShort, "h_jet1Mass_sel", "m^{jet1} [GeV]", rKey, ptIdx, effCentIdx, 120, 0.0, 30.0))
      { h->Fill(m1); bumpHistFill(trigShort, h->GetName()); }
    }

    if (jet2)
    {
      const double eta2 = jet2->get_eta();
      const double phi2 = TVector2::Phi_mpi_pi(jet2->get_phi());

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jet2Eta_sel", "#eta^{jet2}", rKey, ptIdx, effCentIdx, 120, -1.2, 1.2))
      { h->Fill(eta2); bumpHistFill(trigShort, h->GetName()); }

      if (auto* h = getOrBookJetQA1F(trigShort, "h_jet2Phi_sel", "#phi^{jet2} [rad]", rKey, ptIdx, effCentIdx, 128, -M_PI, M_PI))
      { h->Fill(phi2); bumpHistFill(trigShort, h->GetName()); }
    }
  }
}


// Record a histogram fill (for end-of-job diagnostics)
void RecoilJets::bumpHistFill(const std::string& trig, const std::string& hnameWithSuffix)
{
  if (trig.empty() || hnameWithSuffix.empty())
  {
    LOG(2, CLR_YELLOW, "  [bumpHistFill] empty trig or hist name (\"" << trig
           << "\", \"" << hnameWithSuffix << "\") – ignoring");
    return;
  }

  // ------------------------------------------------------------------
  // (A) Job-wide fill counter (used by your End() summary)
  // ------------------------------------------------------------------
  const std::string key = trig + "::" + hnameWithSuffix;

  bool firstThisHist = false;
  long long jobCount = 0;

  auto it = m_histFill.find(key);
  if (it == m_histFill.end())
  {
    m_histFill.emplace(key, 1);
    firstThisHist = true;
    jobCount = 1;

    // Keep your old "first fill" behavior (useful at medium verbosity)
    if (Verbosity() >= 6)
      LOG(6, CLR_BLUE, "    [bumpHistFill] first fill → \"" << key << "\" = 1");
  }
  else
  {
    ++(it->second);
    jobCount = it->second;
  }

  // ------------------------------------------------------------------
  // (B) Per-fill logging (ONLY at high verbosity), rate-limited per event
  //
  //  Verbosity() >= 7: prints fill lines
  //  Verbosity() >= 8: larger budget (more lines per event)
  //  Verbosity() >= 9: essentially unlimited
  //
  //  Optional filter:
  //    export RJ_HIST_VERBOSE_REGEX='h_ss_|h_Eiso|h_xJ'
  //  ------------------------------------------------------------------
  const int v = static_cast<int>(Verbosity());
  if (v < 7) return;

  // ---- optional regex filter (match on "trig::hist") -----------------
  static bool cfgInit = false;
  static bool useFilter = false;
  static std::regex filter;

  if (!cfgInit)
  {
    cfgInit = true;
    if (gSystem)
    {
      const char* re = gSystem->Getenv("RJ_HIST_VERBOSE_REGEX");
      if (re && std::string(re).size() > 0)
      {
        try
        {
          filter = std::regex(re);
          useFilter = true;
          std::cout << CLR_CYAN
                    << "[RecoilJets] RJ_HIST_VERBOSE_REGEX enabled: \"" << re << "\""
                    << CLR_RESET << std::endl;
        }
        catch (...)
        {
          useFilter = false;
          std::cout << CLR_YELLOW
                    << "[RecoilJets] RJ_HIST_VERBOSE_REGEX is invalid — ignoring filter"
                    << CLR_RESET << std::endl;
        }
      }
    }
  }

  if (useFilter)
  {
    if (!std::regex_search(key, filter) && !std::regex_search(hnameWithSuffix, filter))
      return;
  }

  // ---- per-event print budget ---------------------------------------
  const long long evt = static_cast<long long>(event_count);

  static long long lastEvt = -1;
  static int linesThisEvt = 0;
  static bool warnedThisEvt = false;

  if (evt != lastEvt)
  {
    lastEvt = evt;
    linesThisEvt = 0;
    warnedThisEvt = false;
  }

  int cap = 200;
  if (v >= 9) cap = 100000000;   // effectively unlimited
  else if (v >= 8) cap = 2000;   // heavy but still bounded
  else             cap = 200;    // safe default

  if (linesThisEvt >= cap)
  {
    if (!warnedThisEvt)
    {
      warnedThisEvt = true;
      LOG(6, CLR_YELLOW,
          "    [HFill] (evt=" << evt << ") print budget reached (cap=" << cap
          << "). Suppressing further histogram-fill prints this event. "
          << "Raise Verbosity() to >=9 for unlimited, or set RJ_HIST_VERBOSE_REGEX to narrow output.");
    }
    return;
  }
  ++linesThisEvt;

  // ---- resolve TObject for type + entries (best-effort) --------------
  TObject* obj = nullptr;
  auto itTrig = qaHistogramsByTrigger.find(trig);
  if (itTrig != qaHistogramsByTrigger.end())
  {
    auto itObj = itTrig->second.find(hnameWithSuffix);
    if (itObj != itTrig->second.end()) obj = itObj->second;
  }

  const char* cls = obj ? obj->ClassName() : "unresolved";
  long long entries = -1;
  if (auto* h = dynamic_cast<TH1*>(obj)) entries = static_cast<long long>(h->GetEntries());

  std::ostringstream os;
  os << "    [HFill] evt=" << evt
     << " trig=\"" << trig << "\""
     << " hist=\"" << hnameWithSuffix << "\""
     << " type=" << cls;

  if (entries >= 0) os << " entries=" << entries;
  os << " jobCount=" << jobCount;

  if (firstThisHist) os << " (first-time)";

  const char* col = firstThisHist ? CLR_GREEN : CLR_CYAN;
  LOG(7, col, os.str());
}


TH1F* RecoilJets::getOrBookSSHist(const std::string& trig,
                                  const std::string& varKey,
                                  const std::string& tagKey,
                                  int etIdx, int centIdx,
                                  HistViewScope scope)
{
    const std::string base   = "h_ss_" + varKey + "_" + tagKey;
    const std::string suffix = suffixForBins(etIdx, centIdx);
    const std::string name   = histBaseForScope(base, scope) + suffix;

    if (Verbosity() >= 5)
        LOG(5, CLR_BLUE, "  [getOrBookSSHist] trig=\"" << trig << "\" varKey=\"" << varKey
            << "\" tagKey=\"" << tagKey << "\" etIdx=" << etIdx << " centIdx=" << centIdx
            << " → name=\"" << name << "\"");

    if (trig.empty() || varKey.empty() || tagKey.empty())
    {
        LOG(2, CLR_YELLOW, "  [getOrBookSSHist] empty trig/varKey/tagKey – returning nullptr");
        return nullptr;
    }

    auto& H = qaHistogramsByTrigger[trig];

    if (auto it = H.find(name); it != H.end())
    {
        if (auto* h = dynamic_cast<TH1F*>(it->second))
        {
            if (Verbosity() >= 6)
                LOG(6, CLR_GREEN, "    [getOrBookSSHist] reusing existing TH1F \"" << name << "\"");
            return h;
        }
        LOG(2, CLR_YELLOW, "    [getOrBookSSHist] name clash: object \"" << name
            << "\" exists but is not TH1F – replacing it");
        H.erase(it);
    }

    if (!out || !out->IsOpen())
    {
        LOG(1, CLR_YELLOW, "  [getOrBookSSHist] output TFile invalid/null – returning nullptr");
        return nullptr;
    }

    // Choose sane, variable-specific ranges (matches your previous defaults)
    int    nb = 120;
    double lo = 0.0, hi = 1.2;
    if (varKey == "weta" || varKey == "wphi") { nb = 120; lo = 0.0; hi = 1.2; }
    else if (varKey == "et1")                 { nb = 120; lo = 0.0; hi = 1.2; }
    else if (varKey == "e11e33" || varKey == "e32e35") { nb = 120; lo = 0.0; hi = 1.2; }
    else if (varKey == "npbScore")            { nb = 120; lo = -1.0; hi = 1.2; }
    else
    {
        LOG(3, CLR_YELLOW, "  [getOrBookSSHist] unknown varKey \"" << varKey
            << "\" – using default nb=" << nb << " range=[" << lo << "," << hi << "]");
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookSSHist] failed to create/access directory \"" << trig << "\"");
        if (prevDir) prevDir->cd();
        return nullptr;
    }

    dir->cd();

    const std::string title = base + ";" + varKey + ";Entries";

    if (Verbosity() >= 5)
        LOG(5, CLR_BLUE, "    [getOrBookSSHist] booking TH1F name=\"" << name
            << "\" bins=" << nb << " range=[" << lo << "," << hi
            << "] title=\"" << title << '"');

    auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(), nb, lo, hi);
    if (!h)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookSSHist] new TH1F failed for \"" << name << '"');
        if (prevDir) prevDir->cd();
        return nullptr;
    }
    H[name] = h;

    if (prevDir) prevDir->cd();
    return h;
}


TH1F* RecoilJets::getOrBookPPG12TableQA1DHist(const std::string& trig,
                                              const std::string& varKey,
                                              const std::string& ptToken,
                                              const std::string& centToken,
                                              int cutIdx)
{
    if (!m_ppg12TableQAEnabled) return nullptr;
    if (trig.empty() || varKey.empty() || ptToken.empty() || cutIdx < 0 || cutIdx > 4)
    {
        LOG(2, CLR_YELLOW, "  [getOrBookPPG12TableQA1DHist] invalid key request");
        return nullptr;
    }
    const PPG12TableQAVarDef* def = findPPG12TableQAVar(varKey);
    if (!def)
    {
        LOG(2, CLR_YELLOW, "  [getOrBookPPG12TableQA1DHist] unknown varKey \"" << varKey << '"');
        return nullptr;
    }

    std::string name = "h1d_" + varKey + "_eta0_pt" + ptToken;
    if (!centToken.empty()) name += "_" + centToken;
    name += "_cut" + std::to_string(cutIdx);

    auto& H = qaHistogramsByTrigger[trig];
    if (auto it = H.find(name); it != H.end())
    {
        if (auto* h = dynamic_cast<TH1F*>(it->second)) return h;
        LOG(2, CLR_YELLOW, "    [getOrBookPPG12TableQA1DHist] replacing non-TH1F object \"" << name << '"');
        H.erase(it);
    }
    if (!out || !out->IsOpen())
    {
        LOG(1, CLR_YELLOW, "  [getOrBookPPG12TableQA1DHist] output TFile invalid/null");
        return nullptr;
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookPPG12TableQA1DHist] failed to create/access directory \"" << trig << "\"");
        if (prevDir) prevDir->cd();
        return nullptr;
    }
    dir->cd();

    const std::string title =
        std::string("PPG12_TABLE_QA_V1;") + def->axis + ";Weighted counts";
    auto* h = RJMCWeighting::RJNewTH1F(name.c_str(), title.c_str(),
                                       def->nbins, def->xmin, def->xmax);
    if (h) H[name] = h;
    if (prevDir) prevDir->cd();
    return h;
}


TH2F* RecoilJets::getOrBookPPG12TableQAHist(const std::string& trig,
                                            const std::string& varKey,
                                            const std::string& ptToken,
                                            const std::string& centToken,
                                            int cutIdx)
{
    if (!m_ppg12TableQAEnabled) return nullptr;
    if (trig.empty() || varKey.empty() || ptToken.empty() || cutIdx < 0 || cutIdx > 4)
    {
        LOG(2, CLR_YELLOW, "  [getOrBookPPG12TableQAHist] invalid key request");
        return nullptr;
    }
    const PPG12TableQAVarDef* def = findPPG12TableQAVar(varKey);
    if (!def)
    {
        LOG(2, CLR_YELLOW, "  [getOrBookPPG12TableQAHist] unknown varKey \"" << varKey << '"');
        return nullptr;
    }

    std::string name = "h2d_" + varKey + "_eta0_pt" + ptToken;
    if (!centToken.empty()) name += "_" + centToken;
    name += "_cut" + std::to_string(cutIdx);

    auto& H = qaHistogramsByTrigger[trig];
    if (auto it = H.find(name); it != H.end())
    {
        if (auto* h = dynamic_cast<TH2F*>(it->second)) return h;
        LOG(2, CLR_YELLOW, "    [getOrBookPPG12TableQAHist] replacing non-TH2F object \"" << name << '"');
        H.erase(it);
    }
    if (!out || !out->IsOpen())
    {
        LOG(1, CLR_YELLOW, "  [getOrBookPPG12TableQAHist] output TFile invalid/null");
        return nullptr;
    }

    TDirectory* const prevDir = gDirectory;
    TDirectory* dir = out->GetDirectory(trig.c_str());
    if (!dir) dir = out->mkdir(trig.c_str());
    if (!dir)
    {
        LOG(1, CLR_YELLOW, "  [getOrBookPPG12TableQAHist] failed to create/access directory \"" << trig << "\"");
        if (prevDir) prevDir->cd();
        return nullptr;
    }
    dir->cd();

    const PPG12TableQA2DXAxisDef xAxis = ppg12TableQA2DXAxis(varKey);
    const std::string title =
        std::string("PPG12_TABLE_QA_V1;") + def->axis + ";E_{T}^{iso} [GeV]";
    auto* h = RJMCWeighting::RJNewTH2F(name.c_str(), title.c_str(),
                                       xAxis.nbins, xAxis.xmin, xAxis.xmax,
                                       200, -10.0, 30.0);
    if (h) H[name] = h;
    if (prevDir) prevDir->cd();
    return h;
}

