void RecoilJets::fillPPG12Fig13E11E33(const std::vector<std::string>& activeTrig,
                                      const SSVars& v,
                                      double eisoEt,
                                      const std::string& sampleKey,
                                      int cutIdx,
                                      double ptForBinning)
{
    if (!m_ppg12Fig13ParityQA) return;
    if (sampleKey.empty()) return;
    if (!std::isfinite(v.pt_gamma) || !std::isfinite(v.e11_over_e33)) return;
    if (!std::isfinite(eisoEt) || eisoEt > 1e8) return;

    const double tokenPt = std::isfinite(ptForBinning) ? ptForBinning : v.pt_gamma;
    const std::vector<std::string> ptTokens = ppg12TableQAPtTokens(tokenPt);
    if (ptTokens.empty()) return;

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;
        for (const std::string& ptToken : ptTokens)
        {
            if (auto* h = getOrBookPPG12Fig13E11E33Hist(trigShort, sampleKey, ptToken, cutIdx))
            {
                h->Fill(v.e11_over_e33);
                bumpHistFill(trigShort, h->GetName());
            }
            if (auto* h2 = getOrBookPPG12Fig13E11E33IsoHist(trigShort, sampleKey, ptToken, cutIdx))
            {
                h2->Fill(v.e11_over_e33, eisoEt);
                bumpHistFill(trigShort, h2->GetName());
            }
        }
    }
}

void RecoilJets::fillPPG12IsoStackQA(const std::vector<std::string>& activeTrig,
                                     double ptGamma,
                                     double eisoEt,
                                     RecoilJets::TightTag tightTag,
                                     double weight)
{
    if (!m_ppg12PhotonYieldEnabled || m_isAuAu) return;
    if (activeTrig.empty()) return;
    if (!std::isfinite(ptGamma) || !std::isfinite(eisoEt) || eisoEt > 1e8) return;

    std::string tightness;
    if (tightTag == TightTag::kTight) tightness = "tight";
    else if (tightTag == TightTag::kNonTight) tightness = "nontight";
    else return;

    int ptIdx = -1;
    for (int i = 0; i + 1 < static_cast<int>(m_ppg12PhotonYieldRecoPtBins.size()); ++i)
    {
        if (ptGamma > m_ppg12PhotonYieldRecoPtBins[i] &&
            ptGamma < m_ppg12PhotonYieldRecoPtBins[i + 1])
        {
            ptIdx = i;
            break;
        }
    }
    if (ptIdx < 0) return;

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;
        if (auto* h = getOrBookPPG12IsoStackHist(trigShort, tightness, ptIdx))
        {
            h->Fill(eisoEt, weight);
            bumpHistFill(trigShort, h->GetName());
            if (m_replayFoundationEnabled)
            {
                ReplayPPG12DiagnosticOccurrence row;
                row.trigger = trigShort;
                row.occurrence_kind = "PP_ISOLATION_STACK_FILL";
                row.sample_code = ptIdx + 1;
                row.decision = (tightness == "tight") ? 1 : 2;
                row.flow_value = eisoEt;
                row.occurrence_weight = RJMCWeighting::SafeWeight() * weight;
                m_replayPPG12DiagnosticOccurrences.push_back(row);
            }
        }
    }
}


double RecoilJets::ppg12DataTriggerEfficiencyWeight(double recoEt) const
{
    if (m_isSim || m_isAuAu || !m_ppg12PhotonYieldEnabled) return 1.0;
    if (!std::isfinite(recoEt)) return 0.0;

    // PPG12 efficiencytool/config_bdt_nom.yaml and
    // RecoEffCalculator_TTreeReader.C use this bit-30 Gumbel-CDF correction
    // for data yield/isolation histograms. Keep it local to those explicit
    // RecoEff-style families so raw counters and TableQA remain unweighted.
    constexpr double p0 = 1.0;
    constexpr double mu = -2.04;
    constexpr double beta = 3.33;
    const double efficiency = p0 * std::exp(-std::exp(-(recoEt - mu) / beta));
    if (!std::isfinite(efficiency) || efficiency <= 1e-6) return 0.0;
    return 1.0 / efficiency;
}


void RecoilJets::fillPPG12DataTriggerEfficiencyAudit(
    const std::vector<std::string>& activeTrig,
    double recoEt,
    double correctionWeight)
{
    if (m_isSim || m_isAuAu || !m_ppg12PhotonYieldEnabled) return;
    if (!std::isfinite(recoEt) || !std::isfinite(correctionWeight) || correctionWeight <= 0.0) return;

    static const std::vector<double> correctionBins = []()
    {
        std::vector<double> bins;
        bins.reserve(201);
        for (int i = 0; i <= 200; ++i) bins.push_back(0.5 + 0.01 * i);
        return bins;
    }();

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;
        if (auto* h = getOrBookPPG12PhotonYield1D(
                trigShort,
                "h_ppg12_data_trigger_efficiency_correction",
                correctionBins,
                "1/#epsilon_{L1,bit30}(E_{T}^{reco})",
                "raw candidate count"))
        {
            h->Fill(correctionWeight);
            bumpHistFill(trigShort, h->GetName());
        }
    }
}


void RecoilJets::bookPPG12TableQASchema(const std::vector<std::string>& activeTrig)
{
    if (!m_ppg12TableQAEnabled) return;

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;
        if (!m_ppg12TableQASchemaBookedTriggers.insert(trigShort).second) continue;

        for (const char* ptToken : ppg12TableQAAllPtTokens())
        {
            for (int cutIdx = 0; cutIdx <= 4; ++cutIdx)
            {
                for (const auto& var : ppg12TableQAVars())
                {
                    getOrBookPPG12TableQA1DHist(trigShort, var.key, ptToken, "", cutIdx);
                    getOrBookPPG12TableQAHist(trigShort, var.key, ptToken, "", cutIdx);
                }
            }
        }
    }
}


double RecoilJets::ppg12TableQABDTScore(const SSVars& v) const
{
    if (std::isfinite(v.tight_bdt_score)) return v.tight_bdt_score;
    return std::numeric_limits<double>::quiet_NaN();
}


void RecoilJets::fillPPG12TableQA(const std::vector<std::string>& activeTrig,
                                  const SSVars& v,
                                  double eisoEt,
                                  int centIdx,
                                  int cutIdx,
                                  double rowWeight,
                                  double ptForBinning)
{
    (void) centIdx;
    if (!m_ppg12TableQAEnabled) return;
    bookPPG12TableQASchema(activeTrig);
    if (!std::isfinite(eisoEt) || eisoEt > 1e8) return;

    const double tokenPt = std::isfinite(ptForBinning) ? ptForBinning : v.pt_gamma;
    const std::vector<std::string> ptTokens = ppg12TableQAPtTokens(tokenPt);
    if (ptTokens.empty()) return;

    const double wr = (std::isfinite(v.wphi_cogx) && std::isfinite(v.weta_cogx) &&
                       std::fabs(v.weta_cogx) > 1e-12)
        ? (v.wphi_cogx / v.weta_cogx)
        : std::numeric_limits<double>::quiet_NaN();
    const double bdtScore = ppg12TableQABDTScore(v);

    auto valueFor = [&](const std::string& key) -> double
    {
        if (key == "weta_cogx")  return v.weta_cogx;
        if (key == "wphi_cogx")  return v.wphi_cogx;
        if (key == "wr")         return wr;
        if (key == "et1")        return v.et1;
        if (key == "et2")        return v.et2;
        if (key == "et3")        return v.et3;
        if (key == "et4")        return v.et4;
        if (key == "e11_to_e33") return v.e11_over_e33;
        if (key == "e17_to_e77") return v.e17_over_e77;
        if (key == "e32_to_e35") return v.e32_over_e35;
        if (key == "bdt")        return bdtScore;
        if (key == "npb_score")  return v.npb_score;
        return std::numeric_limits<double>::quiet_NaN();
    };

    for (const auto& trigShort : activeTrig)
    {
        for (const std::string& ptToken : ptTokens)
        {
            for (const auto& var : ppg12TableQAVars())
            {
                const double value = valueFor(var.key);
                if (!std::isfinite(value)) continue;
                if (auto* h1 = getOrBookPPG12TableQA1DHist(trigShort, var.key, ptToken, "", cutIdx))
                {
                    h1->Fill(value, rowWeight);
                    bumpHistFill(trigShort, h1->GetName());
                }
                if (auto* h = getOrBookPPG12TableQAHist(trigShort, var.key, ptToken, "", cutIdx))
                {
                    h->Fill(value, eisoEt, rowWeight);
                    bumpHistFill(trigShort, h->GetName());
                }
            }
        }
    }
}

bool RecoilJets::computePPG12ClusterMbdTiming(const SSVars& v,
                                              double& clusterMbdDeltaT,
                                              double& clusterTime,
                                              double& mbdTime) const
{
    clusterMbdDeltaT = std::numeric_limits<double>::quiet_NaN();
    clusterTime = std::numeric_limits<double>::quiet_NaN();
    mbdTime = std::numeric_limits<double>::quiet_NaN();

    if (m_isSim || m_isAuAu) return false;
    if (!m_mbdout || m_mbdout->isValid() == 0) return false;
    if (m_mbdout->get_npmt(0) < 1 || m_mbdout->get_npmt(1) < 1) return false;
    if (!std::isfinite(v.mean_time)) return false;

    const double rawMbdT0 = static_cast<double>(m_mbdout->get_t0());
    if (!std::isfinite(rawMbdT0)) return false;

    mbdTime = rawMbdT0 - ppg12TableQAMbdT0OffsetForRun(currentRunNumber());
    clusterTime = v.mean_time * m_ppg12TableQANPBTagTimeSampleNs;
    clusterMbdDeltaT = clusterTime - mbdTime;

    return std::isfinite(clusterTime) &&
           std::isfinite(mbdTime) &&
           std::isfinite(clusterMbdDeltaT);
}

bool RecoilJets::passPPG12Fig14NpbMbdTimingSelection(const SSVars& v,
                                                     double phi) const
{
    if (!std::isfinite(v.weta_cogx) || v.weta_cogx < m_ppg12Fig14NPBMbdWetaMin) return false;
    if (!std::isfinite(phi)) return false;

    // PPG12 efficiencytool/plot_cluster_time.C defines the MBD-timing NPB
    // selection as !otherside_jet && weta_cogx >= 0.6. The otherside flag is
    // any reconstructed jet with |Delta phi(cluster, jet)| > pi/2, with no
    // jet-pT threshold in that flag.
    for (const auto& [rKey, jets] : m_jets)
    {
        (void) rKey;
        if (!jets) continue;
        for (auto it = jets->begin(); it != jets->end(); ++it)
        {
            const Jet* jet = *it;
            if (!jet) continue;
            const double jetPhi = jet->get_phi();
            if (!std::isfinite(jetPhi)) continue;
            const double dphi = std::fabs(TVector2::Phi_mpi_pi(phi - jetPhi));
            if (dphi > M_PI / 2.0) return false;
        }
    }

    return true;
}

void RecoilJets::fillPPG12Fig14Fig15TimingQA(const std::vector<std::string>& activeTrig,
                                             const SSVars& v,
                                             double eta,
                                             double phi,
                                             double ptForBinning,
                                             double rowWeight)
{
    if (!m_ppg12TableQAEnabled) return;
    if (m_isSim || m_isAuAu) return;
    if (activeTrig.empty()) return;

    const double tokenPt = std::isfinite(ptForBinning) ? ptForBinning : v.pt_gamma;
    if (!std::isfinite(tokenPt) || !std::isfinite(eta)) return;

    double clusterMbdDeltaT = std::numeric_limits<double>::quiet_NaN();
    double clusterTime = std::numeric_limits<double>::quiet_NaN();
    double mbdTime = std::numeric_limits<double>::quiet_NaN();
    if (!computePPG12ClusterMbdTiming(v, clusterMbdDeltaT, clusterTime, mbdTime)) return;

    const double w = std::isfinite(rowWeight) ? rowWeight : 1.0;
    const bool fillFig14 = (tokenPt > 10.0);
    const bool fillFig14Npb = fillFig14 && passPPG12Fig14NpbMbdTimingSelection(v, phi);
    const std::vector<std::string> ptTokens = ppg12TableQAPtTokens(tokenPt);

    auto ptBinTitle = [](const std::string& token) -> std::string
    {
        if (token == "0") return "10 < p_{T} < 14 GeV";
        if (token == "1") return "14 < p_{T} < 18 GeV";
        if (token == "2") return "18 < p_{T} < 22 GeV";
        if (token == "3") return "22 < p_{T} < 28 GeV";
        if (token == "4") return "28 < p_{T} < 30 GeV";
        return "";
    };

    for (const auto& trigShort : activeTrig)
    {
        if (trigShort.empty()) continue;

        if (fillFig14)
        {
            if (auto* h = getOrBookPPG12TimingHist(
                    trigShort,
                    "h_all_delta_t_mbd_vs_eta",
                    "Cluster-MBD Time vs Eta (All Clusters, pT>10 GeV);Cluster #eta;Cluster-MBD Time (ns)",
                    50, -1.0, 1.0,
                    160, -40.0, 40.0))
            {
                h->Fill(eta, clusterMbdDeltaT, w);
                bumpHistFill(trigShort, h->GetName());
            }
            if (auto* h = getOrBookPPG12TimingHist(
                    trigShort,
                    "h_all_cluster_t_vs_eta",
                    "Cluster Time vs Eta (All Clusters, pT>10 GeV);Cluster #eta;Cluster Time (ns)",
                    50, -1.0, 1.0,
                    160, -40.0, 40.0))
            {
                h->Fill(eta, clusterTime, w);
                bumpHistFill(trigShort, h->GetName());
            }
        }

        if (fillFig14Npb)
        {
            if (auto* h = getOrBookPPG12TimingHist(
                    trigShort,
                    "h_npb_delta_t_mbd_vs_eta",
                    "Cluster-MBD Time vs Eta (NPB Selection, pT>10 GeV);Cluster #eta;Cluster-MBD Time (ns)",
                    50, -1.0, 1.0,
                    160, -40.0, 40.0))
            {
                h->Fill(eta, clusterMbdDeltaT, w);
                bumpHistFill(trigShort, h->GetName());
            }
            if (auto* h = getOrBookPPG12TimingHist(
                    trigShort,
                    "h_npb_cluster_t_vs_eta",
                    "Cluster Time vs Eta (NPB Selection, pT>10 GeV);Cluster #eta;Cluster Time (ns)",
                    50, -1.0, 1.0,
                    160, -40.0, 40.0))
            {
                h->Fill(eta, clusterTime, w);
                bumpHistFill(trigShort, h->GetName());
            }
        }

        if (!std::isfinite(v.npb_score)) continue;
        if (std::fabs(eta) >= 0.7) continue;
        for (const std::string& ptToken : ptTokens)
        {
            if (ptToken != "0" && ptToken != "1" && ptToken != "2" &&
                ptToken != "3" && ptToken != "4")
            {
                continue;
            }
            const std::string ptTitle = ptBinTitle(ptToken);
            if (ptTitle.empty()) continue;
            const std::string name = "h_npb_score_vs_time_eta0_pt" + ptToken;
            const std::string title =
                "NPB Score vs Cluster-MBD Time -0.7 < eta < 0.7, " +
                ptTitle +
                ";Cluster-MBD Time [ns];NPB Score";
            if (auto* h = getOrBookPPG12TimingHist(
                    trigShort,
                    name,
                    title,
                    40, -20.0, 20.0,
                    100, 0.0, 1.0))
            {
                h->Fill(clusterMbdDeltaT, v.npb_score, w);
                bumpHistFill(trigShort, h->GetName());
            }
        }
    }
}


void RecoilJets::loadPPG12TableQAMbdT0Corrections(const std::string& path)
{
    m_ppg12TableQAMbdT0Correction.clear();
    if (path.empty()) return;

    std::ifstream in(path);
    if (!in)
    {
        LOG(1, CLR_YELLOW, "[PPG12_TABLE_QA_V1] could not open MBD t0 correction file: " << path);
        return;
    }
    std::string line;
    while (std::getline(in, line))
    {
        const auto hash = line.find('#');
        if (hash != std::string::npos) line = line.substr(0, hash);
        std::istringstream ss(line);
        int run = 0;
        double correction = 0.0;
        if (ss >> run >> correction) m_ppg12TableQAMbdT0Correction[run] = correction;
    }
    LOG(1, CLR_MAGENTA,
        "[PPG12_TABLE_QA_V1] loaded " << m_ppg12TableQAMbdT0Correction.size()
        << " MBD t0 correction rows from " << path);
}


double RecoilJets::ppg12TableQAMbdT0OffsetForRun(int runNumber) const
{
    const auto it = m_ppg12TableQAMbdT0Correction.find(runNumber);
    return (it != m_ppg12TableQAMbdT0Correction.end()) ? it->second : 0.0;
}


bool RecoilJets::isPPG12TableQADataNPBTaggedCluster(const SSVars& v,
                                                    double phi,
                                                    double& clusterMbdDeltaT,
                                                    double& mbdTime,
                                                    bool& hasAwayJet,
                                                    bool requireTaggingEnabled) const
{
    clusterMbdDeltaT = std::numeric_limits<double>::quiet_NaN();
    mbdTime = std::numeric_limits<double>::quiet_NaN();
    hasAwayJet = false;

    if (m_isSim || m_isAuAu) return false;
    if (requireTaggingEnabled && !m_ppg12TableQANPBDataTaggingEnabled) return false;
    if (!m_mbdout || m_mbdout->isValid() == 0) return false;
    if (m_mbdout->get_npmt(0) < 1 || m_mbdout->get_npmt(1) < 1) return false;
    if (!std::isfinite(v.mean_time) || !std::isfinite(phi)) return false;

    const double rawMbdT0 = static_cast<double>(m_mbdout->get_t0());
    if (!std::isfinite(rawMbdT0)) return false;

    const int runNumber = currentRunNumber();
    mbdTime = rawMbdT0 - ppg12TableQAMbdT0OffsetForRun(runNumber);
    const double clusterTime = v.mean_time * m_ppg12TableQANPBTagTimeSampleNs;
    if (!std::isfinite(clusterTime) || !std::isfinite(mbdTime)) return false;

    clusterMbdDeltaT = clusterTime - mbdTime;
    if (!std::isfinite(v.pt_gamma) || v.pt_gamma < 6.0 || v.pt_gamma > 40.0) return false;
    if (!std::isfinite(v.weta_cogx) || v.weta_cogx < m_ppg12TableQANPBWetaMin) return false;
    if (!(clusterMbdDeltaT < m_ppg12TableQANPBDeltaTCut)) return false;

    for (const auto& [rKey, jets] : m_jets)
    {
        (void) rKey;
        if (!jets) continue;
        for (auto it = jets->begin(); it != jets->end(); ++it)
        {
            const Jet* jet = *it;
            if (!jet) continue;
            const double jetPt = jet->get_pt();
            const double jetPhi = jet->get_phi();
            if (!std::isfinite(jetPt) || !std::isfinite(jetPhi)) continue;
            if (jetPt < m_ppg12TableQANPBAwayJetPtMin) continue;
            const double dphi = std::fabs(TVector2::Phi_mpi_pi(phi - jetPhi));
            if (dphi > m_ppg12TableQANPBAwayJetDPhiMin)
            {
                hasAwayJet = true;
                return false;
            }
        }
    }
    return true;
}




void RecoilJets::fillIsoSSTagCounters(const std::string& trig,
                                      const RawCluster* clus,
                                      const SSVars& v,
                                      const TightTag tightTag,
                                      double pt_gamma,
                                      int centIdx,
                                      PHCompositeNode* topNode)
{
  if (!clus)
  {
    LOG(3, CLR_YELLOW, "  [fillIsoSSTagCounters] clus==nullptr – abort slice fill");
    return;
  }

  const int ptIdx = findPtBin(pt_gamma);
  if (ptIdx < 0)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW,
          "  [fillIsoSSTagCounters] pT bin not found for pT^γ=" << pt_gamma
          << " – skipping fills");
    return;
  }

  const int effCentIdx = (m_isAuAu ? centIdx : -1);
  const std::string slice = suffixForBins(ptIdx, effCentIdx) + m_activeIsoViewSuffix;

  // -------------------------------------------------------------------------
  // Isolation region definition for purity. In pp PPG12 photon-yield mode,
  // use the PPG12 topo-cluster R=0.4 scalar; otherwise keep the generic
  // PhotonClusterBuilder tower-cone scalar used by legacy/default analyses.
  //
  //   ISO region:      Eiso < (A + B * pT)
  //   NONISO sideband: Eiso > (A + B * pT + configured gap)
  //   GAP region:      [thrIso, thrIso+gap] is excluded from A–B–C–D
  // -------------------------------------------------------------------------
  const double eiso_et =
      (m_ppg12PhotonYieldEnabled && !m_isAuAu)
          ? ppg12PhotonYieldEiso(ppg12PhotonYieldRawEiso(clus, topNode))
          : eiso(clus, topNode);

  // Missing/non-finite isolation returns a huge fail-safe. Do NOT treat that as
  // "non-isolated sideband" — skip purity classification entirely.
  if (!std::isfinite(eiso_et) || eiso_et > 1e8)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW,
          "  [fillIsoSSTagCounters] invalid/missing Eiso=" << eiso_et
          << " → skip A–B–C–D fill (purity regions require valid iso)");
    return;
  }

  const double thrIso    = recoIsoThreshold(pt_gamma);
  const double thrNonIso = recoNonIsoThreshold(pt_gamma);

  const bool iso    = (eiso_et < thrIso);
  const bool nonIso = (eiso_et > thrNonIso);

  // Exclude the gap region from A–B–C–D (PPG12 definition)
  if (!iso && !nonIso)
  {
    if (Verbosity() >= 5)
    {
      std::ostringstream os;
      os << "    [SS+Iso] trig=\"" << trig << "\" slice=\"" << slice << "\""
         << " pT^γ=" << std::fixed << std::setprecision(2) << pt_gamma
         << " | Eiso=" << std::setprecision(3) << eiso_et
         << " in GAP: [" << std::setprecision(3) << thrIso
         << ", " << std::setprecision(3) << thrNonIso << "]"
         << " → excluded from A–B–C–D";
      LOG(5, CLR_YELLOW, os.str());
    }
    return;
  }

  // -------------------------------------------------------------------------
  // ABCD tight axis
  //
  // The caller already resolved tight/non-tight with the active configured
  // tightVariant and nonTightVariant. Use that exact tag here so the raw ABCD
  // purity histograms, leakage histograms, and signal-region logic all share
  // the same photon-ID definition.
  // -------------------------------------------------------------------------
  const TightTag tag = tightTag;

  if (tag == TightTag::kNeither)
  {
    if (Verbosity() >= 5)
    {
      std::ostringstream os;
      os << "    [SS+Iso] trig=\"" << trig << "\" slice=\"" << slice << "\""
         << " pT^γ=" << std::fixed << std::setprecision(2) << pt_gamma
         << " | Eiso=" << std::setprecision(3) << eiso_et
         << " thrIso=" << std::setprecision(3) << thrIso
         << " thrNonIso=" << std::setprecision(3) << thrNonIso
         << " → region=" << (iso ? "ISO" : "NONISO")
         << " | tight=" << tightTagName(tag)
         << " | NOTE: active variant assigns neither tight nor non-tight → excluded from ABCD";
      LOG(5, CLR_YELLOW, os.str());
    }
    return;
  }

  // If this ever happens, it indicates the caller violated the expected control flow
  // (this function assumes preselection already passed).
  if (tag == TightTag::kPreselectionFail)
  {
    if (Verbosity() >= 4)
      LOG(4, CLR_YELLOW,
          "  [fillIsoSSTagCounters] tag==kPreselectionFail (unexpected here) → skip ABCD fill");
    return;
  }

  const double ref_w_hi = tight_w_hi(pt_gamma);
  const bool ref_pass_weta   = in_open_interval(v.weta_cogx,    TIGHT_W_LO,       ref_w_hi);
  const bool ref_pass_wphi   = in_open_interval(v.wphi_cogx,    TIGHT_W_LO,       ref_w_hi);
  const bool ref_pass_e11e33 = in_open_interval(v.e11_over_e33, TIGHT_E11E33_MIN, TIGHT_E11E33_MAX);
  const bool ref_pass_et1    = in_open_interval(v.et1,          TIGHT_ET1_MIN,    TIGHT_ET1_MAX);
  const bool ref_pass_e32e35 = in_open_interval(v.e32_over_e35, TIGHT_E32E35_MIN, TIGHT_E32E35_MAX);
  const int ref_tight_fails =
      (!ref_pass_weta) + (!ref_pass_wphi) + (!ref_pass_e11e33) + (!ref_pass_et1) + (!ref_pass_e32e35);

  // -------------------------------------------------------------------------
  // Update per-slice counters (only for candidates that ACTUALLY enter ABCD)
  // -------------------------------------------------------------------------
  auto& S = m_catByTrig[trig][slice];
  S.seen += 1;

  // -------------------------------------------------------------------------
  // Choose A–B–C–D category using ISO vs NONISO sideband and the active
  // tight/non-tight definition.
  //
  // Keep histogram names for backward compatibility:
  //   - "notTight" means the configured non-tight sideband.
  // -------------------------------------------------------------------------
  const char* comboBase  = nullptr;
  const char* comboKeySS = nullptr;
  char        region     = '?';

  if (iso && tag == TightTag::kTight)
  {
    // Region A: tight, isolated
    region    = 'A';
    comboBase = "h_isIsolated_isTight";
    comboKeySS= "isIsolated_isTight";
    ++S.n_iso_tight;
  }
  else if (nonIso && tag == TightTag::kTight)
  {
    // Region B: tight, non-isolated (strict NONISO sideband)
    region    = 'B';
    comboBase = "h_notIsolated_isTight";
    comboKeySS= "notIsolated_isTight";
    ++S.n_nonIso_tight;
  }
  else if (iso && tag == TightTag::kNonTight)
  {
    // Region C: configured non-tight, isolated
    region    = 'C';
    comboBase = "h_isIsolated_notTight";     // legacy name retained
    comboKeySS= "isIsolated_notTight";       // legacy key retained
    ++S.n_iso_nonTight;
  }
  else if (nonIso && tag == TightTag::kNonTight)
  {
    // Region D: configured non-tight, non-isolated (strict NONISO sideband)
    region    = 'D';
    comboBase = "h_notIsolated_notTight";    // legacy name retained
    comboKeySS= "notIsolated_notTight";      // legacy key retained
    ++S.n_nonIso_nonTight;
  }
  else
  {
    // Should be unreachable because:
    //   - gap removed earlier
    //   - kNeither removed earlier
    //   - tag must now be either kTight or kNonTight
    if (Verbosity() >= 4)
    {
      std::ostringstream os;
      os << "  [fillIsoSSTagCounters] UNREACHABLE mapping hit:"
         << " iso=" << iso << " nonIso=" << nonIso
         << " tag=" << tightTagName(tag)
         << " | Eiso=" << eiso_et
         << " thrIso=" << thrIso
         << " thrNonIso=" << thrNonIso
         << " → skip fills to be safe";
      LOG(4, CLR_YELLOW, os.str());
    }
    return;
  }

    // -------------------------------------------------------------------------
    // Count histogram for this ABCD region (per pT/cent slice)
    // -------------------------------------------------------------------------
    if (auto* hc = getOrBookCountHist(trig, comboBase, ptIdx, effCentIdx))
    {
      hc->Fill(1);
      bumpHistFill(trig, hc->GetName());
    }
    else
    {
      LOG(2, CLR_YELLOW,
          "  [fillIsoSSTagCounters] getOrBookCountHist returned nullptr for \""
          << comboBase << "\" slice=\"" << slice << '"');
    }

    // -------------------------------------------------------------------------
    // Isolation-energy distribution for each ABCD region (per pT/cent slice)
    // -------------------------------------------------------------------------
    {
      const std::string hBase = std::string("h_Eiso_ABCD_") + std::string(1, region);
      if (auto* hIsoReg = getOrBookIsoPartHist(trig, hBase, "E_{T}^{iso} [GeV]",
                                               ptIdx, effCentIdx, HistViewScope::IsoView))
      {
        hIsoReg->Fill(eiso_et);
        bumpHistFill(trig, hIsoReg->GetName());
      }
    }

    // -------------------------------------------------------------------------
    // Photon pT distribution for each ABCD region (per cent slice)
    // -------------------------------------------------------------------------
    {
      const std::string hBase = std::string("h_pTgamma_ABCD_") + std::string(1, region);
      if (auto* hPtReg = getOrBookPtGammaHist(trig, hBase, effCentIdx))
      {
        hPtReg->Fill(pt_gamma);
        bumpHistFill(trig, hPtReg->GetName());
      }
  }

  // -------------------------------------------------------------------------
  // Verbose diagnostics (optional)
  // -------------------------------------------------------------------------
  if (Verbosity() >= 5)
  {
    // Optional: break isolation into PhotonClusterBuilder components (best-effort)
    double iso_em = std::numeric_limits<double>::quiet_NaN();
    double iso_hi = std::numeric_limits<double>::quiet_NaN();
    double iso_ho = std::numeric_limits<double>::quiet_NaN();

    const int cone10 = static_cast<int>(std::lround(10.0 * m_isoConeR));
    const char* k_em = nullptr;
    const char* k_hi = nullptr;
    const char* k_ho = nullptr;

    if (cone10 == 3)      { k_em = "iso_03_emcal"; k_hi = "iso_03_hcalin"; k_ho = "iso_03_hcalout"; }
    else if (cone10 == 4) { k_em = "iso_04_emcal"; k_hi = "iso_04_hcalin"; k_ho = "iso_04_hcalout"; }

    if (k_em && k_hi && k_ho)
    {
      if (auto* pho = dynamic_cast<const PhotonClusterv1*>(clus))
      {
        iso_em = pho->get_shower_shape_parameter(k_em);
        iso_hi = pho->get_shower_shape_parameter(k_hi);
        iso_ho = pho->get_shower_shape_parameter(k_ho);
      }
    }

    // (1) Compact summary line
    {
      std::ostringstream os;
      os << "    [SS+Iso] trig=\"" << trig << "\" slice=\"" << slice << "\""
         << " pT^γ=" << std::fixed << std::setprecision(2) << pt_gamma
         << " | Eiso=" << std::setprecision(3) << eiso_et
         << " thrIso=" << std::setprecision(3) << thrIso
         << " thrNonIso=" << std::setprecision(3) << thrNonIso
         << " → region=" << region << "(" << (iso ? "ISO" : "NONISO") << ")"
         << " | tight=" << tightTagName(tag);
      if (m_tightVariant == "reference")
      {
        os << " (refFails=" << ref_tight_fails << ")";
      }
      else if (m_tightVariant == "newPPG12")
      {
        os << " | tightBDT=" << std::setprecision(4) << v.tight_bdt_score;
      }
      os << " | ref_w_hi=" << std::setprecision(3) << ref_w_hi;

      // Highlight the true signal region A in red; others cyan
      const char* colour = (region == 'A') ? CLR_RED : CLR_CYAN;
      LOG(5, colour, os.str());
    }

    // (2) Structured details
    if (Verbosity() >= 6)
    {
      // Isolation breakdown
      {
        std::ostringstream os;
        os << "      [iso parts] coneR=" << std::fixed << std::setprecision(2) << m_isoConeR
           << " : ";
        if (std::isfinite(iso_em) && std::isfinite(iso_hi) && std::isfinite(iso_ho))
        {
          os << k_em << "=" << std::setprecision(3) << iso_em
             << " " << k_hi << "=" << std::setprecision(3) << iso_hi
             << " " << k_ho << "=" << std::setprecision(3) << iso_ho
             << " → total=" << std::setprecision(3) << (iso_em + iso_hi + iso_ho);
        }
        else
        {
          os << "(components unavailable) total(Eiso)=" << std::setprecision(3) << eiso_et;
        }
        os << " | thrIso=" << std::setprecision(3) << thrIso
           << " | thrNonIso=" << std::setprecision(3) << thrNonIso;
        LOG(6, CLR_BLUE, os.str());
      }

      // Shower-shape values + cut windows (tight)
      {
        std::ostringstream os;
        os << "      [SS vars] "
           << "weta=" << std::fixed << std::setprecision(3) << v.weta_cogx
           << " ∈ (" << TIGHT_W_LO << "," << std::setprecision(3) << ref_w_hi << ") → " << (ref_pass_weta ? "PASS" : "FAIL")
           << " | wphi=" << std::setprecision(3) << v.wphi_cogx
           << " ∈ (" << TIGHT_W_LO << "," << std::setprecision(3) << ref_w_hi << ") → " << (ref_pass_wphi ? "PASS" : "FAIL")
           << " | et1=" << std::setprecision(3) << v.et1
           << " ∈ (" << TIGHT_ET1_MIN << "," << TIGHT_ET1_MAX << ") → " << (ref_pass_et1 ? "PASS" : "FAIL")
           << " | e11/e33=" << std::setprecision(3) << v.e11_over_e33
           << " ∈ (" << TIGHT_E11E33_MIN << "," << TIGHT_E11E33_MAX << ") → " << (ref_pass_e11e33 ? "PASS" : "FAIL")
           << " | e32/e35=" << std::setprecision(3) << v.e32_over_e35
           << " ∈ (" << TIGHT_E32E35_MIN << "," << TIGHT_E32E35_MAX << ") → " << (ref_pass_e32e35 ? "PASS" : "FAIL");
        LOG(6, CLR_BLUE, os.str());
      }
    }
  }

  // -------------------------------------------------------------------------
  // SS variable histograms for THIS ABCD category (only for ISO or NONISO sideband)
  // -------------------------------------------------------------------------
  auto fillSS = [&](const std::string& key, double val)
  {
    if (auto* h = getOrBookSSHist(trig, key, comboKeySS, ptIdx, effCentIdx))
    {
      h->Fill(val);
      bumpHistFill(trig, h->GetName());
    }
    else
    {
      LOG(2, CLR_YELLOW,
          "    [fillSS] getOrBookSSHist returned nullptr for key=\"" << key
          << "\" tagKey=\"" << comboKeySS << "\" slice=\"" << slice << '"');
    }
  };

  fillSS("weta",   v.weta_cogx);
  fillSS("wphi",   v.wphi_cogx);
  fillSS("et1",    v.et1);
  fillSS("e11e33", v.e11_over_e33);
  fillSS("e32e35", v.e32_over_e35);

  // -------------------------------------------------------------------------
  // No additional counting histograms beyond the four ABCD regions:
  //   A: h_isIsolated_isTight
  //   B: h_notIsolated_isTight
  //   C: h_isIsolated_notTight
  //   D: h_notIsolated_notTight
  // -------------------------------------------------------------------------
}




void RecoilJets::printCutSummary() const
{
  using std::cout; using std::endl; using std::setw; using std::left; using std::right;

  cout << "\n\033[1mJob-wide cutflow summary\033[0m\n";

  // Events
  cout << "\n\033[1mEvents\033[0m\n";
  cout << "metric              | value\n"
          "--------------------+-------\n";
  cout << left << setw(20) << "seen"            << " | " << right << setw(7) << m_bk.evt_seen         << '\n';
  cout << left << setw(20) << "fail(trigger)"   << " | " << right << setw(7) << m_bk.evt_fail_trigger << '\n';
  cout << left << setw(20) << "fail(|vz|)"      << " | " << right << setw(7) << m_bk.evt_fail_vz      << '\n';
  cout << left << setw(20) << "accepted"        << " | " << right << setw(7) << m_bk.evt_accepted     << '\n';

  // Photon candidates: high-level
  cout << "\n\033[1mPhoton candidates (PHOTONCLUSTER_CEMC)\033[0m\n";
  cout << "metric                         | value\n"
          "-------------------------------+-------\n";
  cout << left << setw(31) << "total (container)"          << " | " << right << setw(7) << m_bk.pho_total           << '\n';
  cout << left << setw(31) << "early reject: pT^#gamma<5"  << " | " << right << setw(7) << m_bk.pho_early_E         << '\n';
  cout << left << setw(31) << "fail |eta| fiducial"        << " | " << right << setw(7) << m_bk.pho_eta_fail        << '\n';
  cout << left << setw(31) << "fail ET bin (out of range)" << " | " << right << setw(7) << m_bk.pho_etbin_out       << '\n';
  cout << left << setw(31) << "no RawCluster ptr"          << " | " << right << setw(7) << m_bk.pho_noRC            << '\n';
  cout << left << setw(31) << "reached pre+iso step"       << " | " << right << setw(7) << m_bk.pho_reached_pre_iso << '\n';

  // Preselection breakdown
  cout << "\n\033[1mPreselection (among reached pre+iso)\033[0m\n";
  cout << "outcome/criterion              | count\n"
          "-------------------------------+-------\n";
  cout << left << setw(31) << "pass preselection"          << " | " << right << setw(7) << m_bk.pre_pass             << '\n';
  cout << left << setw(31) << "fail weta >= 0.60"          << " | " << right << setw(7) << m_bk.pre_fail_weta        << '\n';
  cout << left << setw(31) << "fail et1 < 0.60"            << " | " << right << setw(7) << m_bk.pre_fail_et1_low     << '\n';
  cout << left << setw(31) << "fail et1 > 1.00"            << " | " << right << setw(7) << m_bk.pre_fail_et1_high    << '\n';
  cout << left << setw(31) << "fail e11/e33 >= 0.98"       << " | " << right << setw(7) << m_bk.pre_fail_e11e33_high << '\n';
  cout << left << setw(31) << "fail e32/e35 < 0.80"        << " | " << right << setw(7) << m_bk.pre_fail_e32e35_low  << '\n';
  cout << left << setw(31) << "fail e32/e35 > 1.00"        << " | " << right << setw(7) << m_bk.pre_fail_e32e35_high << '\n';

  // Tight classification (for preselection-passed)
  cout << "\n\033[1mTight classification (preselection-passed)\033[0m\n";
  cout << "category                       | count\n"
          "-------------------------------+-------\n";
  cout << left << setw(31) << "Tight (all 5 pass)"         << " | " << right << setw(7) << m_bk.tight_tight     << '\n';
  cout << left << setw(31) << "Neither (exactly 1 fail)"   << " | " << right << setw(7) << m_bk.tight_neither   << '\n';
  cout << left << setw(31) << "Non-Tight (>=2 fail)"       << " | " << right << setw(7) << m_bk.tight_nonTight  << '\n';

  cout << "— per-cut fails —\n";
  cout << left << setw(31) << "fail weta tight"            << " | " << right << setw(7) << m_bk.tight_fail_weta   << '\n';
  cout << left << setw(31) << "fail wphi tight"            << " | " << right << setw(7) << m_bk.tight_fail_wphi   << '\n';
  cout << left << setw(31) << "fail et1 tight"             << " | " << right << setw(7) << m_bk.tight_fail_et1    << '\n';
  cout << left << setw(31) << "fail e11/e33 tight"         << " | " << right << setw(7) << m_bk.tight_fail_e11e33 << '\n';
  cout << left << setw(31) << "fail e32/e35 tight"         << " | " << right << setw(7) << m_bk.tight_fail_e32e35 << '\n';

  // Isolation
  cout << "\n\033[1mIsolation (preselection-passed)\033[0m\n";
  cout << "outcome                        | count\n"
          "-------------------------------+-------\n";
  cout << left << setw(31) << "isolated (canonical view)"     << " | " << right << setw(7) << m_bk.iso_pass         << '\n';
  cout << left << setw(31) << "non-isolated (canonical view)" << " | " << right << setw(7) << m_bk.iso_fail         << '\n';
}
